DG.put("sasatr-naam-maalaa/5",{"n":5,"title":"ਅਥ ਤੁਪਕ ਕੇ ਨਾਮ","title_roman":"Ath tupak ke naam","page":955,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":955,"meaning_status":"draft"},{"type":"verse","number":[461],"number_text":"੪੬੧।","page":955,"lines":[{"gurmukhi":"ਬਾਹਿਨਿ ਆਦਿ ਉਚਾਰੀਐ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Baahini aadi uchaareeai ripu pad anti uchaari |","meaning_en":"First say 'bahini' (army), then at the end say the word 'ripu' (enemy);","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੪੬੧।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 461 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[462],"number_text":"੪੬੨।","page":955,"lines":[{"gurmukhi":"ਸਿੰਧਵਨੀ ਪਦ ਪ੍ਰਿਥਮ ਕਹਿ ਰਿਪਣੀ ਅੰਤ ਉਚਾਰਿ।","roman":"Sindhavnee pad pritham kahi ripnee ant uchaari |","meaning_en":"First say the word 'sindhavani' (army of horses), then at the end say 'ripani' (enemy);","page":955,"meaning_status":"draft","note":"ਰਿਪਣੀ: printed so; read as ripu with the feminine ending (ripuni)."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੪੬੨।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 462 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[463],"number_text":"੪੬੩।","page":955,"lines":[{"gurmukhi":"ਤੁਰੰਗਨਿ ਪ੍ਰਿਥਮ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Turangni pritham uchaari kai ripu ari anti uchaari |","meaning_en":"First say 'turangani' (army of horses), then at the end say 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੪੬੩।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 463 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[464],"number_text":"੪੬੪।","page":955,"lines":[{"gurmukhi":"ਹਯਨੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਹਾ ਅਰਿ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Haynee aadi uchaari kai haa ari pad anti bakhaan |","meaning_en":"First say 'hayani' (army of horses), then at the end say the words 'ha' and 'ari';","page":955,"meaning_status":"draft","note":"ਹਾ ਅਰਿ: 'ha' (slayer) and 'ari' (enemy); reading of ਹਾ uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਬੁਧਿਵਾਨ। ੪੬੪।","roman":"Naam tupak ke hot hai cheen lehu budhivaan | 464 |","meaning_en":"these become names of the tupak (gun); intelligent ones, recognise them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[465],"number_text":"੪੬੫।","page":955,"lines":[{"gurmukhi":"ਅਰਬਨਿ ਆਦਿ ਬਖਾਨੀਐ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Arabni aadi bakhaaneeai ripu ari anti uchaari |","meaning_en":"First say 'arabani' (army of Arab horses), then at the end say 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੪੬੫।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 465 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[466],"number_text":"੪੬੬।","page":955,"lines":[{"gurmukhi":"ਕਿੰਕਾਣੀ ਪ੍ਰਥਮੋਚਰਿ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤ ਉਚਾਰਿ।","roman":"Kinkaanee prathmochri kai ripu pad ant uchaari |","meaning_en":"First say 'kinkani' (army of horses), then at the end say the word 'ripu' (enemy);","page":955,"meaning_status":"draft","note":"ਕਿੰਕਾਣੀ: read as an army of horses (kinkan = horse); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰਿ। ੪੬੬।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaari | 466 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[467],"number_text":"੪੬੭।","page":955,"lines":[{"gurmukhi":"ਅਸੁਨੀ ਆਦਿ ਉਚਾਰੀਐ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੀਨ।","roman":"Asunee aadi uchaareeai anti sabad ari deen |","meaning_en":"First say 'asuni' (army of horses), and at the end add the word 'ari' (enemy);","page":955,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਤੁਪਕ ਕੇ ਨਾਮ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੪੬੭।","roman":"Satru tupak ke naam hai leejhu samajh prabeen | 467 |","meaning_en":"these are the names of the tupak (gun), the enemy; skilled ones, grasp them.","page":955,"meaning_status":"draft","note":"Printed so: ਸਤ੍ਰੁ ('enemy') stands in this closing line where the others have ਨਾਮ; read as 'names of the gun, the enemy'; uncertain."}]},{"type":"verse","number":[468],"number_text":"੪੬੮।","page":955,"lines":[{"gurmukhi":"ਸੁਆਸਨਿ ਆਦਿ ਬਖਾਨੀਐ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Suaasni aadi bakhaaneeai ripu ari pad kai deen |","meaning_en":"First say 'suasani', then add 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft","note":"ਸੁਆਸਨਿ: base word unclear (perhaps an army of horses, from ashva); left unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੪੬੮।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 468 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[469],"number_text":"੪੬੯।","page":955,"lines":[{"gurmukhi":"ਆਧਿਨਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadhini aadi uchaari kai ripu pad anti bakhaan |","meaning_en":"First say 'adhini', then at the end say the word 'ripu' (enemy);","page":955,"meaning_status":"draft","note":"ਆਧਿਨਿ: base word unclear (perhaps 'army of lords', from adhip); left unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੪੬੯।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 469 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[470],"number_text":"੪੭੦।","page":955,"lines":[{"gurmukhi":"ਪ੍ਰਭੁਣੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Prabhunee aadi uchaari kai ripu pad anti bakhaan |","meaning_en":"First say 'prabhuni' (army of lords), then at the end say the word 'ripu' (enemy);","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੪੭੦।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 470 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[471],"number_text":"੪੭੧।","page":955,"lines":[{"gurmukhi":"ਆਦਿ ਭੂਪਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Aadi bhoopnee sabad kahi ripu ari anti uchaar |","meaning_en":"First say the word 'bhupani' (army of kings), then at the end say 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰਿ। ੪੭੧।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaari | 471 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[472],"number_text":"੪੭੨।","page":955,"lines":[{"gurmukhi":"ਆਦਿ ਈਸਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੇ ਦੀਨ।","roman":"Aadi eesnee sabad kahi ripu ari pad ke deen |","meaning_en":"First say the word 'isani' (army of lords), then add 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੪੭੨।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 472 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[473],"number_text":"੪੭੩।","page":955,"lines":[{"gurmukhi":"ਆਦਿ ਸੰਉਡਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Aadi sanudnee sabad kahi ripu ari bahuri uchaar |","meaning_en":"First say the word 'saundani' (army of elephants), then say 'ripu' and 'ari' (both 'enemy') after it;","page":955,"meaning_status":"draft","note":"ਸੰਉਡਣੀ: read as army of trunked ones (elephants); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੪੭੩।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 473 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[474],"number_text":"੪੭੪।","page":955,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਸਤ੍ਰੁਣੀ ਉਚਰੀਐ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Pratham satrunee uchreeai ripu ari anti uchaar |","meaning_en":"First say 'satruni' (army of enemies), then at the end say 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੪੭੪।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 474 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[475],"number_text":"੪੭੫।","page":955,"lines":[{"gurmukhi":"ਸਕਲ ਛਤ੍ਰ ਕੇ ਨਾਮ ਲੈ ਨੀ ਕਹਿ ਰਿਪੁਹਿ ਬਖਾਨ।","roman":"Sakal chhatr ke naam lai nee kahi ripuhi bakhaan |","meaning_en":"Take all the names of the chhatra (royal canopy), say 'ni', and then speak the word 'ripu' (enemy);","page":955,"meaning_status":"draft","note":"ਛਤ੍ਰ: 'royal canopy' or 'kshatriya'; uncertain. ਨੀ is the feminine/army ending to be added."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੪੭੫।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 475 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[476],"number_text":"੪੭੬।","page":955,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਛਤ੍ਰਨੀ ਸਬਦ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Pratham chhatranee sabad uchri ripu ari anti bakhaan |","meaning_en":"First say the word 'chhatrani' (army with royal canopies), then at the end say 'ripu' and 'ari' (both 'enemy');","page":955,"meaning_status":"draft","note":"ਛਤ੍ਰਨੀ: 'army with canopies' or 'army of kshatriyas'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੪੭੬।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 476 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":955,"meaning_status":"draft"}]},{"type":"verse","number":[477],"number_text":"੪੭੭।","page":956,"lines":[{"gurmukhi":"ਆਤਪਤ੍ਰਣੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Aataptranee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'atapatrani' (army with parasols), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰਿ। ੪੭੭।","roman":"Naam tupak ke hot hai cheen chatur nirdhaari | 477 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[478],"number_text":"੪੭੮।","page":956,"lines":[{"gurmukhi":"ਆਦਿ ਪਤਾਕਨਿ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Aadi pataakni sabad kahi ripu ari pad kai deen |","meaning_en":"First say the word 'patakani' (army with banners), then add 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੪੭੮।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 478 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[479],"number_text":"੪੭੯।","page":956,"lines":[{"gurmukhi":"ਛਿਤਪਤਾਢਿ ਪ੍ਰਿਥਮੋਚਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Chhitaptaadhi prithmochri kai ripu ari anti uchaar |","meaning_en":"First say 'chhitpatadhi', then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft","note":"ਛਿਤਪਤਾਢਿ: printed so; perhaps from chhitpati (lord of the earth, king); unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੪੭੯।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 479 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[480],"number_text":"੪੮੦।","page":956,"lines":[{"gurmukhi":"ਰਉਦਨਿ ਆਦਿ ਉਚਾਰੀਐ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Raudni aadi uchaareeai ripu ari anti bakhaan |","meaning_en":"First say 'raudani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft","note":"ਰਉਦਨਿ: base word unclear (perhaps 'fierce army'); left unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੪੮੦।","roman":"Naam tupak ke hot hai leejhu chatur pachhaan | 480 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[481],"number_text":"੪੮੧।","page":956,"lines":[{"gurmukhi":"ਸਸਤ੍ਰਨਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Sastrani aadi bakhaani kai ripu ari pad kai deen |","meaning_en":"First say 'sastrani' (army with weapons), then add 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੪੮੧।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 481 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[482],"number_text":"੪੮੨।","page":956,"lines":[{"gurmukhi":"ਸਬਦ ਸਿੰਧੁਰਣਿ ਉਚਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Sabad sindhurni uchri kai ripu ari pad kai deen |","meaning_en":"First say the word 'sindhurani' (army of elephants), then add 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੪੮੨।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 482 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[483],"number_text":"੪੮੩।","page":956,"lines":[{"gurmukhi":"ਆਦਿ ਸੁਭਟਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi subhatnee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'subhatani' (army of warriors), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੪੮੩।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 483 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[484],"number_text":"੪੮੪।","page":956,"lines":[{"gurmukhi":"ਰਥਿਨੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਮਥਨੀ ਮਥਨ ਬਖਾਨ।","roman":"Rathinee aadi uchaari kai mathnee mathan bakhaan |","meaning_en":"First say 'rathini' (army of chariots), then say 'mathani' and 'mathan' (crusher, destroyer);","page":956,"meaning_status":"draft","note":"ਮਥਨੀ ਮਥਨ: read as two words meaning 'crusher/destroyer' given in place of ripu; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੪੮੪।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 484 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[485],"number_text":"੪੮੫।","page":956,"lines":[{"gurmukhi":"ਸਬਦ ਸ੍ਯੰਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Sabad syandnee aadi kahi ripu ari bahuri bakhaan |","meaning_en":"First say the word 'syandani' (army of chariots), then say 'ripu' and 'ari' (both 'enemy') after it;","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੪੮੫।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 485 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[486],"number_text":"੪੮੬।","page":956,"lines":[{"gurmukhi":"ਆਦਿ ਸਕਟਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi sakatnee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'sakatani' (army of carts/chariots), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸਮਝ ਲੇਹੁ ਮਤਿਵਾਨ। ੪੮੬।","roman":"Naam tupak ke hot hai samajh lehu mativaan | 486 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, understand them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[487],"number_text":"੪੮੭।","page":956,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਸਤ੍ਰੂਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Pratham satroonee sabad kahi ripu ari anti uchaar |","meaning_en":"First say the word 'satruni' (army of enemies), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਕਬਿ ਸੁਧਾਰ। ੪੮੭।","roman":"Naam tupak ke hot hai leejhu sukbi sudhaar | 487 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[488],"number_text":"੪੮੮।","page":956,"lines":[{"gurmukhi":"ਆਦਿ ਦੁਸਟਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi dusatnee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'dustani' (army of the wicked), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੪੮੮।","roman":"Naam tupak ke hot hai leejhu chatur pachhaan | 488 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[489],"number_text":"੪੮੯।","page":956,"lines":[{"gurmukhi":"ਅਸੁ ਕਵਚਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Asu kavachnee aadi kahi ripu ari anti uchaari |","meaning_en":"First say 'asu kavachani' (army of armoured horses), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft","note":"ਅਸੁ ਕਵਚਨੀ: read as 'horse-armour army'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੪੮੯।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 489 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[490],"number_text":"੪੯੦।","page":956,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਬਰਮਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Pratham baramnee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'barmani' (army with armour), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਬੁਧਿਵਾਨ। ੪੯੦।","roman":"Naam tupak ke hot hai cheen lehu budhivaan | 490 |","meaning_en":"these become names of the tupak (gun); intelligent ones, recognise them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[491],"number_text":"੪੯੧।","page":956,"lines":[{"gurmukhi":"ਤਨੁਤ੍ਰਾਣਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Tanutraannee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'tanutranani' (army with body-armour), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੪੯੧।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 491 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[492],"number_text":"੪੯੨।","page":956,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਚਰਮਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Pratham charamnee sabad kahi ripu ari anti uchaari |","meaning_en":"First say the word 'charmani' (army with shields), then at the end say 'ripu' and 'ari' (both 'enemy');","page":956,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁਧਾਰ। ੪੯੨।","roman":"Naam tupak ke hot hai leejhu su kabi sudhaar | 492 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":956,"meaning_status":"draft"}]},{"type":"verse","number":[493],"number_text":"੪੯੩।","page":957,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਸਿਪਰਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਉਚਰਹੁ ਅੰਤਿ।","roman":"Pratham siparnee sabad kahi ripu ari ucharhu anti |","meaning_en":"First say the word 'siparani' (army with shields), then say 'ripu' and 'ari' (both 'enemy') at the end;","page":957,"meaning_status":"draft","note":"ਸਿਪਰ: Persian 'shield'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਜੂ ਕੇ ਸਕਲ ਨਿਕਸਤ ਚਲਤ ਅਨੰਤ। ੪੯੩।","roman":"Naam tupak joo ke sakal niksat chalat anant | 493 |","meaning_en":"all the names of the tupak (gun) go on coming forth without end.","page":957,"meaning_status":"draft","note":"ਨਿਕਸਤ ਚਲਤ ਅਨੰਤ: read as 'go on emerging endlessly'; uncertain."}]},{"type":"verse","number":[494],"number_text":"੪੯੪।","page":957,"lines":[{"gurmukhi":"ਸਬ ਸਲਣੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Sab salnee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'sab salani', then add 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft","note":"ਸਬ ਸਲਣੀ: printed so; perhaps 'army with spears (sal)'; unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੪੯੪।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 494 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[495],"number_text":"੪੯੫।","page":957,"lines":[{"gurmukhi":"ਪ੍ਰਥਮੈ ਚਕ੍ਰਣਿ ਸਬਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੇ ਦੀਨ।","roman":"Prathmai chakrani sabdi kahi ripu ari pad ke deen |","meaning_en":"First say the word 'chakrani' (army with discuses), then add 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੪੯੫।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 495 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[496],"number_text":"੪੯੬।","page":957,"lines":[{"gurmukhi":"ਆਦਿ ਖੜਗਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Aadi kharagnee sabad kahi ripu ari anti uchaar |","meaning_en":"First say the word 'kharagani' (army with swords), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁਧਾਰ। ੪੯੬।","roman":"Naam tupak ke hot hai leejhu su kabi sudhaar | 496 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[497],"number_text":"੪੯੭।","page":957,"lines":[{"gurmukhi":"ਅਸਿਨੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Asinee aadi uchaari kai ripu ari anti bakhaan |","meaning_en":"First say 'asini' (army with swords), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੪੯੭।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 497 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[498],"number_text":"੪੯੮।","page":957,"lines":[{"gurmukhi":"ਨਿਸਤ੍ਰਿਸਨੀ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Nistrisnee uchaari kai ripu ari anti bakhaan |","meaning_en":"Say 'nistrisani' (army with swords), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਨਿਕਸਤ ਚਲਤ ਪ੍ਰਮਾਨ। ੪੯੮।","roman":"Naam tupak ke hot hai niksat chalat pramaan | 498 |","meaning_en":"these become names of the tupak (gun); they go on coming forth, as is established.","page":957,"meaning_status":"draft","note":"ਨਿਕਸਤ ਚਲਤ ਪ੍ਰਮਾਨ: read as 'go on emerging, as established'; uncertain."}]},{"type":"verse","number":[499],"number_text":"੪੯੯।","page":957,"lines":[{"gurmukhi":"ਖਗਨੀ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Khagnee aadi bakhaani kai ripu ari pad kai deen |","meaning_en":"First say 'khagani' (army with swords), then add 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft","note":"ਖਗ: here read as 'sword' (it can also mean 'bird' or 'arrow'); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੪੯੯।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 499 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[500],"number_text":"੫੦੦।","page":957,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਏਸ੍ਰਣੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Sasatr esranee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'sastra esrani' (army of the lord of weapons), then add 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੦੦।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 500 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[501],"number_text":"੫੦੧।","page":957,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਰਾਜਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Sasatr raajnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'sastra rajani' (army of the king of weapons), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੦੧।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 501 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[502],"number_text":"੫੦੨।","page":957,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਰਾਟਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Sasatr raatnee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'sastra ratani' (army of the sovereign of weapons), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪ੍ਰਮਾਨ। ੫੦੨।","roman":"Naam tupak ke hot hai leejhu chatur pramaan | 502 |","meaning_en":"these become names of the tupak (gun); clever ones, accept them as valid.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[503],"number_text":"੫੦੩।","page":957,"lines":[{"gurmukhi":"ਆਦਿ ਸੈਫਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi saiphnee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'saifani' (army with swords), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft","note":"ਸੈਫ: Arabic 'sword'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੦੩।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 503 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[504],"number_text":"੫੦੪।","page":957,"lines":[{"gurmukhi":"ਆਦਿ ਤੇਗਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Aadi tegnee sabad kahi ripu ari pad kai deen |","meaning_en":"First say the word 'tegani' (army with swords), then add 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft","note":"ਤੇਗ: Persian 'sword'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੦੪।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 504 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[505],"number_text":"੫੦੫।","page":957,"lines":[{"gurmukhi":"ਆਦਿ ਕ੍ਰਿਪਾਨਨਿ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi kripaanni sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'kripanani' (army with swords), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪ੍ਰਮਾਨ। ੫੦੫।","roman":"Naam tupak hot hai leejhu chatur pramaan | 505 |","meaning_en":"these become names of the tupak (gun); clever ones, accept them as valid.","page":957,"meaning_status":"draft","note":"Printed so, without ਕੇ ('of') found in the other closing lines."}]},{"type":"verse","number":[506],"number_text":"੫੦੬।","page":957,"lines":[{"gurmukhi":"ਸਮਸੇਰਣੀ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Samsernee uchaari kai ripu ari anti bakhaan |","meaning_en":"Say 'samsherani' (army with swords), then at the end say 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft","note":"ਸਮਸੇਰ: Persian 'sword'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਚਿਤ ਮਹਿ ਜਾਨ। ੫੦੬।","roman":"Naam tupak ke hot hai chatur chit mahi jaan | 506 |","meaning_en":"these become names of the tupak (gun); clever ones, know them in your mind.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[507],"number_text":"੫੦੭।","page":957,"lines":[{"gurmukhi":"ਆਦਿ ਖੰਡਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰਿ।","roman":"Aadi khandnee sabad kahi ripu ari bahuri uchaari |","meaning_en":"First say the word 'khandani' (army of destroyers / with double-edged swords), then say 'ripu' and 'ari' (both 'enemy') after it;","page":957,"meaning_status":"draft","note":"ਖੰਡਨੀ: 'destroying' or 'with khandas'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁਧਾਰ। ੫੦੭।","roman":"Naam tupak ke hot hai leejhu su kabi sudhaar | 507 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[508],"number_text":"੫੦੮।","page":957,"lines":[{"gurmukhi":"ਖਲਖੰਡਨ ਪਦ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Khalkhandan pad aadi kahi ripu ari pad kai deen |","meaning_en":"First say the word 'khalkhandan' (destroyer of the wicked), then add 'ripu' and 'ari' (both 'enemy');","page":957,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੦੮।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 508 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":957,"meaning_status":"draft"}]},{"type":"verse","number":[509],"number_text":"੫੦੯।","page":958,"lines":[{"gurmukhi":"ਕਵਚਾਂਤਕਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Kavchaantaknee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'kavachantakani' (army that ends armour), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੦੯।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 509 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[510],"number_text":"੫੧੦।","page":958,"lines":[{"gurmukhi":"ਧਾਰਾਧਰਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੇ ਦੀਨ।","roman":"Dhaaraadharnee aadi kahi ripu ari pad ke deen |","meaning_en":"First say 'dharadharani', then add 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft","note":"ਧਾਰਾਧਰਨੀ: 'bearing a sharp edge' (sword) or 'cloud'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੧੦।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 510 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[511],"number_text":"੫੧੧।","page":958,"lines":[{"gurmukhi":"ਕਵਚ ਤਾਪਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Kavach taapnee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'kavach tapani' (army that torments armour), then add 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft","note":"ਤਾਪਨੀ: read as 'tormenting/burning'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੫੧੧।","roman":"Naam tupak ke hot hai chatur leejeeahu cheen | 511 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[512],"number_text":"੫੧੨।","page":958,"lines":[{"gurmukhi":"ਤਨੁ ਤ੍ਰਾਣਿ ਅਰਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Tanu traani ari aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'tanu tran ari' (enemy of body-armour), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਲੀਜੀਅਹੁ ਜਾਨ। ੫੧੨।","roman":"Naam tupak ke hot hai chatur leejeeahu jaan | 512 |","meaning_en":"these become names of the tupak (gun); clever ones, know them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[513],"number_text":"੫੧੩।","page":958,"lines":[{"gurmukhi":"ਕਵਚ ਘਾਤਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Kavach ghaatnee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'kavach ghatani' (army that smashes armour), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪ੍ਰਮਾਨ। ੫੧੩।","roman":"Naam tupak ke hot hai leejhu chatur pramaan | 513 |","meaning_en":"these become names of the tupak (gun); clever ones, accept them as valid.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[514],"number_text":"੫੧੪।","page":958,"lines":[{"gurmukhi":"ਦੁਸਟ ਦਾਹਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Dusat daahnee aadi kahi ripu ari sabad bakhaan |","meaning_en":"First say 'dust dahani' (burner of the wicked), then say the words 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੧੪।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 514 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[515],"number_text":"੫੧੫।","page":958,"lines":[{"gurmukhi":"ਦੁਰਜਨ ਦਰਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Durjan darnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'durjan darani' (tearer of the wicked), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਜਾਨੁ ਚਤੁਰ ਨਿਰਧਾਰ। ੫੧੫।","roman":"Naam tupak ke hot hai jaanu chatur nirdhaar | 515 |","meaning_en":"these become names of the tupak (gun); clever ones, know them and settle on them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[516],"number_text":"੫੧੬।","page":958,"lines":[{"gurmukhi":"ਦੁਰਜਨ ਦਬਕਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Durjan dabaknee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'durjan dabakani' (that cows the wicked), then add 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft","note":"ਦਬਕਨੀ: read as 'frightening/subduing'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੧੬।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 516 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[517],"number_text":"੫੧੭।","page":958,"lines":[{"gurmukhi":"ਦੁਸਟ ਚਰਬਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Dusat charabnee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'dust charabani' (chewer of the wicked), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੫੧੭।","roman":"Naam tupak ke hot hai leejhu chatur pachhaan | 517 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[518],"number_text":"੫੧੮।","page":958,"lines":[{"gurmukhi":"ਬੀਰ ਬਰਜਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Beer barajnee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'bir barajani' (that holds back warriors), then add 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੧੮।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 518 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[519],"number_text":"੫੧੯।","page":958,"lines":[{"gurmukhi":"ਬਾਰ ਬਰਜਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁਣੀ ਅੰਤ ਖਾਨ।","roman":"Baar barajnee aadi kahi ripunee ant khaan |","meaning_en":"First say 'bar barajani', then at the end say 'ripuni' (enemy);","page":958,"meaning_status":"draft","note":"ਬਾਰ ਬਰਜਨੀ: perhaps 'that wards off blows'; uncertain. ਅੰਤ ਖਾਨ: printed so; read as ਅੰਤ ਬਖਾਨ ('say at the end')."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੫੧੯।","roman":"Naam tupak ke hot hai leejhu chatur pachhaan | 519 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[520],"number_text":"੫੨੦।","page":958,"lines":[{"gurmukhi":"ਬਿਸਿਖ ਬਰਖਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Bisikh barakhnee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'bisikh barakhani' (rainer of arrows), then add 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੫੨੦।","roman":"Naam tupak ke hot hai chatur leejeeahu cheen | 520 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[521],"number_text":"੫੨੧।","page":958,"lines":[{"gurmukhi":"ਬਾਨ ਦਾਇਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Baan daainee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'ban daini' (giver of arrows), then add 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੨੧।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 521 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[522],"number_text":"੫੨੨।","page":958,"lines":[{"gurmukhi":"ਬਿਸਿਖ ਬ੍ਰਿਸਟਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Bisikh brisatnee aadi kahi ripu ari anti uchaari |","meaning_en":"First say 'bisikh bristani' (rainer of arrows), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰਿ। ੫੨੨।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaari | 522 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[523],"number_text":"੫੨੩।","page":958,"lines":[{"gurmukhi":"ਪਨਜ ਪ੍ਰਹਾਰਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Panaj prahaarni aadi kahi ripu ari anti uchaari |","meaning_en":"First say 'panaj praharani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft","note":"ਪਨਜ: perhaps 'arrow'; ਪ੍ਰਹਾਰਨਿ 'striker'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੨੩।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 523 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[524],"number_text":"੫੨੪।","page":958,"lines":[{"gurmukhi":"ਧਨੁਨੀ ਆਦਿ ਉਚਾਰੀਐ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Dhanunee aadi uchaareeai ripu ari anti uchaari |","meaning_en":"First say 'dhanuni' (army with bows), then at the end say 'ripu' and 'ari' (both 'enemy');","page":958,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੨੪।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 524 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":958,"meaning_status":"draft"}]},{"type":"verse","number":[525],"number_text":"੫੨੫।","page":959,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਧਨੁਖਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Pratham dhanukhnee sabad kahi ripu ari pad kai deen |","meaning_en":"First say the word 'dhanukhani' (army with bows), then add 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੫੨੫।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 525 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[526],"number_text":"੫੨੬।","page":959,"lines":[{"gurmukhi":"ਕੋਅੰਡਨੀ ਆਦਿ ਉਚਾਰੀਐ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Koandnee aadi uchaareeai ripu ari pad kai deen |","meaning_en":"First say 'koandani' (army with bows), then add 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft","note":"ਕੋਅੰਡ: read as kodand, 'bow'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੨੬।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 526 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[527],"number_text":"੫੨੭।","page":959,"lines":[{"gurmukhi":"ਬਾਣਾਗ੍ਰਜਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੌ ਦੇਹੁ।","roman":"Baanaagrajnee aadi kahi ripu ari pad kau dehu |","meaning_en":"First say 'banagrajani', then add 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft","note":"ਬਾਣਾਗ੍ਰਜਨੀ: perhaps 'arrow-tip' (ban + agra) or 'bow'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤ ਲੇਹੁ। ੫੨੭।","roman":"Naam tupak ke hot hai cheen chatur chit lehu | 527 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[528],"number_text":"੫੨੮।","page":959,"lines":[{"gurmukhi":"ਬਾਣ ਪ੍ਰਹਰਣੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Baan praharnee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'ban praharani' (striker of arrows), then add 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੫੨੮।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 528 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[529],"number_text":"੫੨੯।","page":959,"lines":[{"gurmukhi":"ਆਦਿ ਉਚਰਿ ਪਦ ਬਾਣਨੀ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Aadi uchri pad baannee ripu ari anti uchaar |","meaning_en":"First say the word 'banani' (army with arrows), then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੨੯।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 529 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[530],"number_text":"੫੩੦।","page":959,"lines":[{"gurmukhi":"ਬਿਸਿਖ ਪਰਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Bisikh parannee aadi kahi ripu pad anti bakhaan |","meaning_en":"First say 'bisikh paranani', then at the end say the word 'ripu' (enemy);","page":959,"meaning_status":"draft","note":"ਬਿਸਿਖ ਪਰਨਨੀ: perhaps 'feathered arrows'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਪ੍ਰਮਾਨ। ੫੩੦।","roman":"Naam tupak ke hot hai cheenhu chatur pramaan | 530 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them as valid.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[531],"number_text":"੫੩੧।","page":959,"lines":[{"gurmukhi":"ਬਿਸਿਖਨਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Bisikhni aadi bakhaani kai ripu pad anti uchaar |","meaning_en":"First say 'bisikhani' (army with arrows), then at the end say the word 'ripu' (enemy);","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਅਪਾਰ। ੫੩੧।","roman":"Naam tupak ke hot hai cheenhu chatur apaar | 531 |","meaning_en":"these become names of the tupak (gun); recognise them, you who are greatly clever.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[532],"number_text":"੫੩੨।","page":959,"lines":[{"gurmukhi":"ਸੁਭਟ ਘਾਇਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Subhat ghaainee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'subhat ghaini' (wounder of warriors), then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਸੁ ਧਾਰ। ੫੩੨।","roman":"Naam tupak ke hot hai leejhu chatur su dhaar | 532 |","meaning_en":"these become names of the tupak (gun); clever ones, take them up with care.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[533],"number_text":"੫੩੩।","page":959,"lines":[{"gurmukhi":"ਸਤ੍ਰੁ ਸੰਘਰਣੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Satru sangharnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'satru sangharani' (destroyer of enemies), then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੩੩।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 533 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[534],"number_text":"੫੩੪।","page":959,"lines":[{"gurmukhi":"ਪਨਜ ਪ੍ਰਹਰਣੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Panaj praharnee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'panaj praharani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft","note":"ਪਨਜ: perhaps 'arrow'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੩੪।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 534 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[535],"number_text":"੫੩੫।","page":959,"lines":[{"gurmukhi":"ਕੋਅੰਡਜ ਦਾਇਨਿ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Koandaj daaini uchri ripu ari bahuri bakhaan |","meaning_en":"Say 'koandaj daini' (giver of what is born of the bow, i.e. arrows), then say 'ripu' and 'ari' (both 'enemy') after it;","page":959,"flags":[{"code":"ੇੋ","reason":"ੇ and ੋ typed on one letter; one covers the other, printed as ੋ"}],"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੩੫।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 535 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[536],"number_text":"੫੩੬।","page":959,"lines":[{"gurmukhi":"ਆਦਿ ਨਿਖੰਗਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi nikhangnee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'nikhangani' (army with quivers), then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਪਛਾਨ। ੫੩੬।","roman":"Naam tupak ke hot hai leejhu sughar pachhaan | 536 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[537],"number_text":"੫੩੭।","page":959,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਪਤ੍ਰਣੀ ਪਦ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Pratham patranee pad uchri ripu ari anti uchaar |","meaning_en":"First say the word 'patrani' (army with feathered arrows), then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft","note":"ਪਤ੍ਰਣੀ: patra = feather/leaf; read as feathered arrows; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੩੭।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 537 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[538],"number_text":"੫੩੮।","page":959,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਪਛਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੌ ਦੇਹੁ।","roman":"Pratham pachhnee sabad kahi ripu ari pad kau dehu |","meaning_en":"First say the word 'pachhani' (army with winged arrows), then add 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft","note":"ਪਛਣੀ: from paksh, 'wing'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੫੩੮।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 538 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[539],"number_text":"੫੩੯।","page":959,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਪਤ੍ਰਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Pratham patranee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'patrani' (army with feathered arrows), then at the end say 'ripu' and 'ari' (both 'enemy');","page":959,"meaning_status":"draft","note":"ਪਤ੍ਰਣੀ: patra = feather/leaf; read as feathered arrows; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜੀਅਹੁ ਸੁਘਰ ਪਛਾਨ। ੫੩੯।","roman":"Naam tupak ke hot hai leejeeahu sughar pachhaan | 539 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":959,"meaning_status":"draft"}]},{"type":"verse","number":[540],"number_text":"੫੪੦।","page":960,"lines":[{"gurmukhi":"ਪਰਿਣੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Parinee aadi uchaari kai ripu ari bahuri bakhaan |","meaning_en":"First say 'parini' (army with feathered arrows), then say 'ripu' and 'ari' (both 'enemy') after it;","page":960,"meaning_status":"draft","note":"ਪਰਿਣੀ: read from par, 'feather'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਪ੍ਰਮਾਨ। ੫੪੦।","roman":"Naam tupak ke hot hai cheenhu chatur pramaan | 540 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them as valid.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[541],"number_text":"੫੪੧।","page":960,"lines":[{"gurmukhi":"ਪੰਖਣਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰਿ।","roman":"Pankhni aadi uchaari kai ripu ari bahuri uchaari |","meaning_en":"First say 'pankhani' (army with feathered arrows), then say 'ripu' and 'ari' (both 'enemy') after it;","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੪੧।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 541 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[542],"number_text":"੫੪੨।","page":960,"lines":[{"gurmukhi":"ਪਤ੍ਰਣਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Patrani aadi bakhaani kai ripu ari anti uchaari |","meaning_en":"First say 'patrani' (army with feathered arrows), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft","note":"ਪਤ੍ਰਣਿ: patra = feather/leaf; read as feathered arrows; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੫੪੨।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 542 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[543],"number_text":"੫੪੩।","page":960,"lines":[{"gurmukhi":"ਨਭਚਰਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Nabhachri aadi bakhaani kai ripu ari anti uchaari |","meaning_en":"First say 'nabhchari' (sky-goer), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰਿ। ੫੪੩।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaari | 543 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[544],"number_text":"੫੪੪।","page":960,"lines":[{"gurmukhi":"ਰਥਨੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Rathnee aadi uchaari kai ripu ari anti uchaari |","meaning_en":"First say 'rathani' (army of chariots), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੫੪੪।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 544 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[545],"number_text":"੫੪੫।","page":960,"lines":[{"gurmukhi":"ਸਕਟਨਿ ਆਦਿ ਉਚਾਰੀਐ ਰਿਪੁ ਅਰਿ ਪਦ ਕੇ ਦੀਨ।","roman":"Sakatni aadi uchaareeai ripu ari pad ke deen |","meaning_en":"First say 'sakatani' (army of carts/chariots), then add 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੪੫।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 545 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[546],"number_text":"੫੪੬।","page":960,"lines":[{"gurmukhi":"ਰਥਣੀ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Rathnee aadi bakhaani kai ripu ari anti uchaari |","meaning_en":"First say 'rathani' (army of chariots), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੪੬।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 546 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[547],"number_text":"੫੪੭।","page":960,"lines":[{"gurmukhi":"ਆਦਿ ਸਬਦ ਕਹਿ ਸ੍ਯੰਦਨੀ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Aadi sabad kahi syandnee ripu ari anti uchaar |","meaning_en":"First say the word 'syandani' (army of chariots), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੪੭।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 547 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[548],"number_text":"੫੪੮।","page":960,"lines":[{"gurmukhi":"ਪਟਨੀ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤ ਉਚਾਰ।","roman":"Patnee aadi bakhaani kai ripu ari ant uchaar |","meaning_en":"First say 'patani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft","note":"ਪਟਨੀ: perhaps 'army with cloth/banners'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੫੪੮।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 548 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[549],"number_text":"੫੪੯।","page":960,"lines":[{"gurmukhi":"ਆਦਿ ਬਸਤ੍ਰਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi bastranee sabad kahi ripu ari anti bakhaan |","meaning_en":"First say the word 'bastrani' (army with garments), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft","note":"ਬਸਤ੍ਰਣੀ: 'garments' (perhaps armour coats); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੫੪੯।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 549 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[550],"number_text":"੫੫੦।","page":960,"lines":[{"gurmukhi":"ਬਿਯੂਹਨਿ ਆਦਿ ਬਖਾਨੀਐ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Biyoohni aadi bakhaaneeai ripu ari anti uchaar |","meaning_en":"First say 'biyuhani' (army in battle-array), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੫੫੦।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 550 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[551],"number_text":"੫੫੧।","page":960,"lines":[{"gurmukhi":"ਬਜ੍ਰਣਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Bajrani aadi bakhaani kai ripu ari anti uchaar |","meaning_en":"First say 'bajrani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft","note":"ਬਜ੍ਰਣਿ: from vajra (thunderbolt / hard weapon); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੫੧।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 551 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[552],"number_text":"੫੫੨।","page":960,"lines":[{"gurmukhi":"ਬਲਣੀ ਆਦਿ ਬਖਾਨੀਐ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Balnee aadi bakhaaneeai ripu ari anti uchaar |","meaning_en":"First say 'balani' (army of strength), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੫੨।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 552 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[553],"number_text":"੫੫੩।","page":960,"lines":[{"gurmukhi":"ਦਲਣੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਮਲਣੀ ਪਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Dalnee aadi uchaari kai malnee pad puni dehu |","meaning_en":"First say 'dalani' (army), and then add the word 'malani' (crusher);","page":960,"meaning_status":"draft","note":"ਦਲਣੀ/ਮਲਣੀ: 'army' or 'crusher' / 'crusher'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੫੫੩।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 553 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[554],"number_text":"੫੫੪।","page":960,"lines":[{"gurmukhi":"ਬਾਦਿਤ੍ਰਣੀ ਬਖਾਨਿ ਕੈ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Baaditranee bakhaani kai anti sabad ari dehu |","meaning_en":"Say 'baditrani' (army with musical instruments), and at the end add the word 'ari' (enemy);","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੫੫੪।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 554 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[555],"number_text":"੫੫੫।","page":960,"lines":[{"gurmukhi":"ਆਦਿ ਨਾਦਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Aadi naadnee sabad kahi ripu ari anti uchaar |","meaning_en":"First say the word 'nadani' (army that sounds), then at the end say 'ripu' and 'ari' (both 'enemy');","page":960,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਅਪਾਰ। ੫੫੫।","roman":"Naam tupak ke hot hai cheenhu chatur apaar | 555 |","meaning_en":"these become names of the tupak (gun); recognise them, you who are greatly clever.","page":960,"meaning_status":"draft"}]},{"type":"verse","number":[556],"number_text":"੫੫੬।","page":961,"lines":[{"gurmukhi":"ਦੁੰਦਭਿ ਧਰਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Dundbhi dharnee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'dundabhi dharani' (bearer of war-drums), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੫੬।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 556 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[557],"number_text":"੫੫੭।","page":961,"lines":[{"gurmukhi":"ਦੁੰਦਭਨੀ ਪਦ ਪ੍ਰਥਮ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Dundabhnee pad pratham kahi ripu ari anti uchaar |","meaning_en":"First say the word 'dundabhani' (army with war-drums), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੫੭।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 557 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[558],"number_text":"੫੫੮।","page":961,"lines":[{"gurmukhi":"ਨਾਦ ਨਾਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Naad naadnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'nad nadani' (army that sounds the sound), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੫੮।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 558 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[559],"number_text":"੫੫੯।","page":961,"lines":[{"gurmukhi":"ਦੁੰਦਭਿ ਧੁਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Dundbhi dhunnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'dundabhi dhunani' (army sounding war-drums), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸਮਝਹੁ ਸੁਘਰ ਅਪਾਰ। ੫੫੯।","roman":"Naam tupak ke hot hai samajhhu sughar apaar | 559 |","meaning_en":"these become names of the tupak (gun); understand them, you who are greatly skilful.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[560],"number_text":"੫੬੦।","page":961,"lines":[{"gurmukhi":"ਆਦਿ ਭੇਰਣੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Aadi bhernee sabad kahi ripu pad bahuri bakhaan |","meaning_en":"First say the word 'bherani' (army with kettledrums), then say the word 'ripu' (enemy) after it;","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਬੁਧਿਵਾਨ। ੫੬੦।","roman":"Naam tupak ke hot hai cheen lehu budhivaan | 560 |","meaning_en":"these become names of the tupak (gun); intelligent ones, recognise them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[561],"number_text":"੫੬੧।","page":961,"lines":[{"gurmukhi":"ਦੁੰਦਭਿ ਘੋਖਨ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Dundbhi ghokhan aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'dundabhi ghokhan' (roar of war-drums), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੫੬੧।","roman":"Naam tupak ke hot hai cheen chatur nirdhaar | 561 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[562],"number_text":"੫੬੨।","page":961,"lines":[{"gurmukhi":"ਨਾਦਾਨਿਸਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Naadaanisnee aadi kahi ripu ari bahuri bakhaan |","meaning_en":"First say 'nadanisani', then say 'ripu' and 'ari' (both 'enemy') after it;","page":961,"meaning_status":"draft","note":"ਨਾਦਾਨਿਸਨੀ: perhaps nad (sound) + nisan (drum); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਕਰੀਅਹੁ ਚਤੁਰ ਪ੍ਰਮਾਨ। ੫੬੨।","roman":"Naam tupak ke hot hai kareeahu chatur pramaan | 562 |","meaning_en":"these become names of the tupak (gun); clever ones, accept them as valid.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[563],"number_text":"੫੬੩।","page":961,"lines":[{"gurmukhi":"ਆਨਿਕਨੀ ਪਦ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Aaniknee pad aadi kahi ripu pad bahuri bakhaan |","meaning_en":"First say the word 'anikani', then say the word 'ripu' (enemy) after it;","page":961,"meaning_status":"draft","note":"ਆਨਿਕਨੀ: from anak (war-drum) or anik (army); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੬੩।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 563 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[564],"number_text":"੫੬੪।","page":961,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਢਾਲਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Pratham dhaalnee sabad kahi ripu ari anti uchaar |","meaning_en":"First say the word 'dhalani' (army with shields), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft","note":"ਢਾਲਨੀ: read as 'with shields'; amid drum and conch words it may name a drum; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਬਿਚਾਰ। ੫੬੪।","roman":"Naam tupak ke hot hai leejhu samajh bichaar | 564 |","meaning_en":"these become names of the tupak (gun); take them, understanding and weighing them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[565],"number_text":"੫੬੫।","page":961,"lines":[{"gurmukhi":"ਢਢਨੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪਦ ਬਹੁਰੋ ਦੇਹੁ।","roman":"Dhadhnee aadi uchaari kai ripu pad bahuro dehu |","meaning_en":"First say 'dhadhani' (army with dhadh drums), then add the word 'ripu' (enemy) after it;","page":961,"meaning_status":"draft","note":"ਢਢਨੀ: read as from dhadh, a small drum; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੫੬੫।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 565 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[566],"number_text":"੫੬੬।","page":961,"lines":[{"gurmukhi":"ਸੰਖਨਿਸਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Sankhnisnee aadi kahi ripu ari bahuri uchaar |","meaning_en":"First say 'sankhanisani', then say 'ripu' and 'ari' (both 'enemy') after it;","page":961,"meaning_status":"draft","note":"ਸੰਖਨਿਸਨੀ: perhaps sankh (conch) + nisan (drum); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੫੬੬।","roman":"Naam tupak ke hot hai cheen chatur nirdhaar | 566 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[567],"number_text":"੫੬੭।","page":961,"lines":[{"gurmukhi":"ਸੰਖ ਸਬਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Sankh sabadnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'sankh sabadani' (army sounding conches), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਸੁ ਧਾਰ।੫੬੭।","roman":"Naam tupak ke hot hai leejhu chatur su dhaar | 567 |","meaning_en":"these become names of the tupak (gun); clever ones, take them up with care.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[568],"number_text":"੫੬੮।","page":961,"lines":[{"gurmukhi":"ਸੰਖ ਨਾਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Sankh naadnee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'sankh nadani' (army sounding conches), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੬੮।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 568 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[569],"number_text":"੫੬੯।","page":961,"lines":[{"gurmukhi":"ਸਿੰਘ ਨਾਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Singh naadnee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'singh nadani' (army with a lion's roar), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੬੯।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 569 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[570],"number_text":"੫੭੦।","page":961,"lines":[{"gurmukhi":"ਪਲ ਭਛਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Pal bhachhi naadni aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'pal bhachh nadani' (army with the roar of the flesh-eater), then at the end say 'ripu' and 'ari' (both 'enemy');","page":961,"meaning_status":"draft","note":"ਪਲ ਭਛਿ: 'flesh-eater' (lion or tiger)."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਚਿਤ ਪਹਿਚਾਨ। ੫੭੦।","roman":"Naam tupak ke hot hai chatur chit pahichaan | 570 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":961,"meaning_status":"draft"}]},{"type":"verse","number":[571],"number_text":"੫੭੧।","page":962,"lines":[{"gurmukhi":"ਬਿਆਘ੍ਰ ਨਾਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Biaaghr naadnee aadi kahi ripu ari bahuri bakhaan |","meaning_en":"First say 'biaghr nadani' (army with a tiger's roar), then say 'ripu' and 'ari' (both 'enemy') after it;","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੭੧।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 571 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[572],"number_text":"੫੭੨।","page":962,"lines":[{"gurmukhi":"ਹਰਿ ਜਛਨਿ ਨਾਦਨਿ ਉਚਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Hari jachhni naadni uchri kai ripu ari anti bakhaan |","meaning_en":"Say 'hari jachhani nadani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft","note":"ਹਰਿ ਜਛਨਿ: perhaps 'lion'; unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੫੭੨।","roman":"Naam tupak ke hot hai leejhu chatur pachhaan | 572 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[573],"number_text":"੫੭੩।","page":962,"lines":[{"gurmukhi":"ਪੁੰਡਰੀਕ ਨਾਦਨਿ ਉਚਰਿ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Pundreek naadni uchri kai ripu pad anti bakhaan |","meaning_en":"Say 'pundarik nadani' (army with a tiger's roar), then at the end say the word 'ripu' (enemy);","page":962,"meaning_status":"draft","note":"ਪੁੰਡਰੀਕ: read here as 'tiger'; it can also mean 'lotus'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਬੁਧਿਵਾਨ। ੫੭੩।","roman":"Naam tupak ke hot hai cheen lehu budhivaan | 573 |","meaning_en":"these become names of the tupak (gun); intelligent ones, recognise them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[574],"number_text":"੫੭੪।","page":962,"lines":[{"gurmukhi":"ਹਰ ਨਾਦਨਿ ਪਦ ਪ੍ਰਿਥਮ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Har naadni pad pritham kahi ripu ari anti uchaar |","meaning_en":"First say the word 'har nadani' (army with a lion's roar), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft","note":"ਹਰ: read as hari, 'lion'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੫੭੪।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 574 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[575],"number_text":"੫੭੫।","page":962,"lines":[{"gurmukhi":"ਪੰਚਾਨਨਿ ਘੋਖਨਿ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Panchaanni ghokhni uchri ripu ari anti bakhaan |","meaning_en":"Say 'panchanani ghokhani' (army with a lion's roar), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft","note":"ਪੰਚਾਨਨ: 'five-faced', the lion."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਚਿਤ ਪਹਚਿਾਨ। ੫੭੫।","roman":"Naam tupak ke hot hai chatur chit pahchaan | 575 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":962,"meaning_status":"draft","note":"ਪਹਚਿਾਨ: printed so; read as ਪਹਿਚਾਨ ('recognise')."}]},{"type":"verse","number":[576],"number_text":"੫੭੬।","page":962,"lines":[{"gurmukhi":"ਸੇਰ ਸਬਦਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤ ਉਚਾਰ।","roman":"Ser sabadnee aadi kahi ripu ari ant uchaar |","meaning_en":"First say 'ser sabadani' (army with a lion's sound), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੭੬।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 576 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[577],"number_text":"੫੭੭।","page":962,"lines":[{"gurmukhi":"ਮ੍ਰਿਗਅਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰ ਬਖਾਨ।","roman":"Mriga'ari naadni aadi kahi ripu ari bahur bakhaan |","meaning_en":"First say 'mrigari nadani' (army with the roar of the deer's enemy, the lion), then say 'ripu' and 'ari' (both 'enemy') after it;","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਪ੍ਰਗਿਆਵਾਨ। ੫੭੭।","roman":"Naam tupak ke hot hai cheenhu pragiaavaan | 577 |","meaning_en":"these become names of the tupak (gun); men of understanding, recognise them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[578],"number_text":"੫੭੮।","page":962,"lines":[{"gurmukhi":"ਪਸੁਪਤਾਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Pasuptaari dhvannee uchri ripu pad anti uchaar |","meaning_en":"Say 'pasupatari dhvanani', then at the end say the word 'ripu' (enemy);","page":962,"meaning_status":"draft","note":"ਪਸੁਪਤਾਰਿ: perhaps 'lord of beasts' (lion); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੫੭੮।","roman":"Naam tupak ke hot hai cheen chatur nirdhaar | 578 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[579],"number_text":"੫੭੯।","page":962,"lines":[{"gurmukhi":"ਮ੍ਰਿਗਪਤਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Mrigapti naadni aadi kahi ripu ari bahuri bakhaan |","meaning_en":"First say 'mrigpati nadani' (army with the roar of the lord of deer, the lion), then say 'ripu' and 'ari' (both 'enemy') after it;","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਪ੍ਰਗਿਆਵਾਨ। ੫੭੯।","roman":"Naam tupak ke hot hai cheenhu pragiaavaan | 579 |","meaning_en":"these become names of the tupak (gun); men of understanding, recognise them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[580],"number_text":"੫੮੦।","page":962,"lines":[{"gurmukhi":"ਪਸੁ ਏਸ੍ਰਣ ਨਾਦਨਿ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Pasu esran naadni uchri ripu ari anti uchaar |","meaning_en":"Say 'pasu esran nadani' (army with the roar of the lord of beasts), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਸੁ ਧਾਰ। ੫੮੦।","roman":"Naam tupak ke hot hai leejhu chatur su dhaar | 580 |","meaning_en":"these become names of the tupak (gun); clever ones, take them up with care.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[581],"number_text":"੫੮੧।","page":962,"lines":[{"gurmukhi":"ਗਜਰਿ ਨਾਦਿਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Gajri naadinee aadi kahi ripu pad anti bakhaan |","meaning_en":"First say 'gajari nadini' (army with the roar of the elephant's enemy), then at the end say the word 'ripu' (enemy);","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਜਾਨ। ੫੮੧।","roman":"Naam tupak ke hot hai sughar leejeeahu jaan | 581 |","meaning_en":"these become names of the tupak (gun); skilful ones, know them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[582],"number_text":"੫੮੨।","page":962,"lines":[{"gurmukhi":"ਸਊਡਿਯਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Saoodiyri dhvannee aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'saundiyari dhvanani' (army with the roar of the elephant's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੮੨।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 582 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[583],"number_text":"੫੮੩।","page":962,"lines":[{"gurmukhi":"ਦੰਤਿਯਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Dantiyri naadni aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'dantiyari nadani' (army with the roar of the tusker's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੮੩।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 583 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[584],"number_text":"੫੮੪।","page":962,"lines":[{"gurmukhi":"ਅਨਕਪਿਯਰਿ ਨਾਦਨਿ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Anakpiyri naadni uchri ripu ari anti uchaar |","meaning_en":"Say 'anakapiyari nadani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft","note":"ਅਨਕਪਿਯਰਿ: perhaps 'enemy of the elephant' (anekap = elephant); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੫੮੪।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 584 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[585],"number_text":"੫੮੫।","page":962,"lines":[{"gurmukhi":"ਸਿੰਧੁਰਾਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Sindhuraari dhvannee uchri ripu ari anti uchaar |","meaning_en":"Say 'sindhurari dhvanani' (army with the roar of the elephant's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":962,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਬਿਚਾਰ। ੫੮੫।","roman":"Naam tupak ke hot hai leejhu sumti bichaar | 585 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them with thought.","page":962,"meaning_status":"draft"}]},{"type":"verse","number":[586],"number_text":"੫੮੬।","page":963,"lines":[{"gurmukhi":"ਮਾਤੰਗਰਿ ਨਾਦਨਿ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Maatangri naadni uchri ripu ari anti uchaar |","meaning_en":"Say 'matangari nadani' (army with the roar of the elephant's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":963,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰਿ ਸੰਭਾਰਿ। ੫੮੬।","roman":"Naam tupak ke hot hai leejhu sughri sanbhaari | 586 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and keep them with care.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[587],"number_text":"੫੮੭।","page":963,"lines":[{"gurmukhi":"ਸਾਵਿਜਾਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਸੁ ਭਾਖੁ।","roman":"Saavijaari dhvannee uchri ripu pad anti su bhaakhu |","meaning_en":"Say 'savijari dhvanani', then speak the word 'ripu' (enemy) at the end;","page":963,"meaning_status":"draft","note":"ਸਾਵਿਜਾਰਿ: base word unclear (perhaps 'enemy of beasts'); unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਚਿਤਿ ਰਾਖੁ। ੫੮੭।","roman":"Naam tupak ke hot hai cheeni chatur chiti raakhu | 587 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and keep them in mind.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[588],"number_text":"੫੮੮।","page":963,"lines":[{"gurmukhi":"ਗਜਨਿਯਾਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਬਖਾਨ।","roman":"Gajniyaari naadni aadi kahi ripu ari anti bakhaan |","meaning_en":"First say 'gajaniyari nadani' (army with the roar of the elephant-host's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":963,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੫੮੮।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 588 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[589],"number_text":"੫੮੯।","page":963,"lines":[{"gurmukhi":"ਨਾਗਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Naagri dhvannee aadi kahi ripu ari bahuri bakhaan |","meaning_en":"First say 'nagari dhvanani' (army with the roar of the elephant's enemy), then say 'ripu' and 'ari' (both 'enemy') after it;","page":963,"meaning_status":"draft","note":"ਨਾਗ: here read as 'elephant' (it can also mean 'serpent'); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਉਚਰਤ ਚਲੋ ਸੁਜਾਨ। ੫੮੯।","roman":"Naam tupak ke hot hai uchrat chalo sujaan | 589 |","meaning_en":"these become names of the tupak (gun); wise ones, go on speaking them.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[590],"number_text":"੫੯੦।","page":963,"lines":[{"gurmukhi":"ਹਸਤਿਯਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Hastiyri dhvannee aadi kahi ripu ari puni pad dehu |","meaning_en":"First say 'hastiyari dhvanani' (army with the roar of the elephant's enemy), then add the words 'ripu' and 'ari' (both 'enemy');","page":963,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੫੯੦।","roman":"Naam tupak ke hot hai cheeni chatur chiti lehu | 590 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[591],"number_text":"੫੯੧।","page":963,"lines":[{"gurmukhi":"ਹਰਿਨਿਅਰਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪਦ ਬਹੁਰੋ ਦੇਹੁ।","roman":"Hariniari aadi uchaari kai ripu pad bahuro dehu |","meaning_en":"First say 'haraniari', then add the word 'ripu' (enemy) after it;","page":963,"meaning_status":"draft","note":"ਹਰਿਨਿਅਰਿ: 'enemy of deer' (harini) or 'enemy of the lion-host'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤ ਲੇਹੁ। ੫੯੧।","roman":"Naam tupak ke hot hai cheen chatur chit lehu | 591 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[592],"number_text":"੫੯੨।","page":963,"lines":[{"gurmukhi":"ਕਰਨਿਯਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Karniyri dhvannee aadi kahi ripu pad anti uchaar |","meaning_en":"First say 'karaniyari dhvanani' (army with the roar of the elephant's enemy), then at the end say the word 'ripu' (enemy);","page":963,"meaning_status":"draft","note":"ਕਰਨਿ: read as karini, 'elephant'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੫੯੨।","roman":"Naam tupak ke hot hai cheen chatur nirdhaar | 592 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[593],"number_text":"੫੯੩।","page":963,"lines":[{"gurmukhi":"ਬਰਿਯਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Bariyri dhvannee aadi kahi ripu ari bahuri uchaar |","meaning_en":"First say 'bariyari dhvanani', then say 'ripu' and 'ari' (both 'enemy') after it;","page":963,"meaning_status":"draft","note":"ਬਰਿਯਰਿ: base word unclear (perhaps 'enemy of elephants'); unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੫੯੩।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 593 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[594],"number_text":"੫੯੪।","page":963,"lines":[{"gurmukhi":"ਦੰਤੀਯਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੋ ਦੇਹੁ।","roman":"Danteeyri dhvannee aadi kahi ripu ari pad ko dehu |","meaning_en":"First say 'dantiyari dhvanani' (army with the roar of the tusker's enemy), then add the words 'ripu' and 'ari' (both 'enemy');","page":963,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੫੯੪।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 594 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[595],"number_text":"੫੯੫।","page":963,"lines":[{"gurmukhi":"ਦ੍ਵਿਪਿ ਰਿਪੁ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Dvipi ripu dhvannee aadi kahi ripu ari bahuri uchaar |","meaning_en":"First say 'dvipi ripu dhvanani' (army with the roar of the elephant's enemy), then say 'ripu' and 'ari' (both 'enemy') after it;","page":963,"meaning_status":"draft","note":"ਦ੍ਵਿਪ: 'elephant'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੰਭਾਰ। ੫੯੫।","roman":"Naam tupak ke hot hai leejhu su kabi sanbhaar | 595 |","meaning_en":"these become names of the tupak (gun); good poets, take them and keep them with care.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[596],"number_text":"੫੯੬।","page":963,"lines":[{"gurmukhi":"ਪਦਮਿਯਰਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Padmiyri aadi bakhaani kai ripu ari bahuri bakhaan |","meaning_en":"First say 'padamiyari', then say 'ripu' and 'ari' (both 'enemy') after it;","page":963,"meaning_status":"draft","note":"ਪਦਮਿਯਰਿ: perhaps 'enemy of elephants' (padmi); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੫੯੬।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 596 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[597],"number_text":"੫੯੭।","page":963,"lines":[{"gurmukhi":"ਬਲਿਯਰਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਪਦ ਪੁਨਿ ਕੈ ਦੀਨ।","roman":"Baliyri aadi bakhaani kai ripu pad puni kai deen |","meaning_en":"First say 'baliyari', then add the word 'ripu' (enemy);","page":963,"meaning_status":"draft","note":"ਬਲਿਯਰਿ: base word unclear; unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੯੭।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 597 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[598],"number_text":"੫੯੮।","page":963,"lines":[{"gurmukhi":"ਇੰਭਿਅਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Inbhiari dhvannee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'ibhiari dhvanani' (army with the roar of the elephant's enemy), then add 'ripu' and 'ari' (both 'enemy');","page":963,"meaning_status":"draft","note":"ਇੰਭ: read as ibh, 'elephant'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਮਤਿ ਲੀਜੀਅਹੁ ਬੀਨ। ੫੯੮।","roman":"Naam tupak ke hot hai sumti leejeeahu been | 598 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, pick them out.","page":963,"meaning_status":"draft","note":"ਬੀਨ: read as 'pick out / discern'; uncertain."}]},{"type":"verse","number":[599],"number_text":"੫੯੯।","page":963,"lines":[{"gurmukhi":"ਕੁੰਭਿਯਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਖਿਪ ਪਦ ਕੈ ਦੀਨ।","roman":"Kunbhiyri naadni aadi kahi ripu khip pad kai deen |","meaning_en":"First say 'kumbhiyari nadani' (army with the roar of the elephant's enemy), then add the words 'ripu khip';","page":963,"meaning_status":"draft","note":"ਰਿਪੁ ਖਿਪ: printed so; 'khip' perhaps 'destroyer' (kshep); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੫੯੯।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 599 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":963,"meaning_status":"draft"}]},{"type":"verse","number":[600],"number_text":"੬੦੦।","page":964,"lines":[{"gurmukhi":"ਕੁੰਜਰਿਯਰਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪੁਨਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Kunjriyri aadi uchaari kai ripu puni anti uchaari |","meaning_en":"First say 'kunjariyari' (enemy of the elephant), then at the end say the word 'ripu' (enemy);","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸੰਭਾਰ। ੬੦੦।","roman":"Naam tupak ke hot hai leejhu sumti sanbhaar | 600 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and keep them with care.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[601],"number_text":"੬੦੧।","page":964,"lines":[{"gurmukhi":"ਪਤ੍ਰਿਯਰਿ ਅਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪੁਨਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Patriyri ari dhvannee uchri ripu puni pad kai deen |","meaning_en":"Say 'patriyari ari dhvanani', then add the word 'ripu' (enemy);","page":964,"meaning_status":"draft","note":"ਪਤ੍ਰਿਯਰਿ: base word unclear (patri may be 'tree' or 'bird'); unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੬੦੧।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 601 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[602],"number_text":"੬੦੨।","page":964,"lines":[{"gurmukhi":"ਤਰੁਰਿਪੁ ਅਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Taruripu ari dhvannee uchri ripu pad bahuri bakhaan |","meaning_en":"Say 'taruripu ari dhvanani' (army with the roar of the enemy of the tree's enemy), then say the word 'ripu' (enemy) after it;","page":964,"meaning_status":"draft","note":"ਤਰੁਰਿਪੁ: 'enemy of trees' (elephant); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਨਿਧਾਨ। ੬੦੨।","roman":"Naam tupak ke hot hai cheenhu chatur nidhaan | 602 |","meaning_en":"these become names of the tupak (gun); recognise them, you treasure-houses of cleverness.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[603],"number_text":"੬੦੩।","page":964,"lines":[{"gurmukhi":"ਸਊਡਿਯਾਂਤਕ ਧ੍ਵਨਨਿ ਉਚਰਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Saoodiyaantak dhvanni uchri ripu ari bahuri bakhaan |","meaning_en":"Say 'saundiyantak dhvanani' (army with the roar of the elephant's destroyer), then say 'ripu' and 'ari' (both 'enemy') after it;","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੬੦੩।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 603 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[604],"number_text":"੬੦੪।","page":964,"lines":[{"gurmukhi":"ਹਯਨਿਅਰਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Hayniari aadi uchaari kai ripu ari anti uchaar |","meaning_en":"First say 'hayaniari' (enemy of the horse-host), then at the end say 'ripu' and 'ari' (both 'enemy');","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੬੦੪।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 604 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[605],"number_text":"੬੦੫।","page":964,"lines":[{"gurmukhi":"ਹਯਨਿਅਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Hayniari dhvannee aadi kahi ripu pad bahuri bakhaan |","meaning_en":"First say 'hayaniari dhvanani' (army with the roar of the horse-host's enemy), then say the word 'ripu' (enemy) after it;","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਬੁਧਿਵਾਨ। ੬੦੫।","roman":"Naam tupak ke hot hai cheen lehu budhivaan | 605 |","meaning_en":"these become names of the tupak (gun); intelligent ones, recognise them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[606],"number_text":"੬੦੬।","page":964,"lines":[{"gurmukhi":"ਹਯਨਿਯਾਂਤਕ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Hayniyaantak dhvannee uchri ripu pad bahuri bakhaan |","meaning_en":"Say 'hayaniyantak dhvanani' (army with the roar of the horse-host's destroyer), then say the word 'ripu' (enemy) after it;","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੬੦੬।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 606 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[607],"number_text":"੬੦੭।","page":964,"lines":[{"gurmukhi":"ਅਸੁਅਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Asuari dhvannee aadi kahi ripu ari pad kai deen |","meaning_en":"First say 'asuari dhvanani' (army with the roar of the horse's enemy), then add 'ripu' and 'ari' (both 'enemy');","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਸੁਘਰ ਲੀਜੀਅਹੁ ਚੀਨ। ੬੦੭।","roman":"Naam tupak ke hot hai sughar leejeeahu cheen | 607 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[608],"number_text":"੬੦੮।","page":964,"lines":[{"gurmukhi":"ਤੁਰਯਾਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤ ਉਚਾਰ।","roman":"Turyaari naadni aadi kahi ripu ari ant uchaar |","meaning_en":"First say 'turyari nadani' (army with the roar of the horse's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸੁ ਧਾਰ। ੬੦੮।","roman":"Naam tupak ke hot hai leejhu sumti su dhaar | 608 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them up with care.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[609],"number_text":"੬੦੯।","page":964,"lines":[{"gurmukhi":"ਤੁਰੰਗਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪੁਨਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Turangri dhvannee aadi kahi ripu puni pad kai deen |","meaning_en":"First say 'turangari dhvanani' (army with the roar of the horse's enemy), then add the word 'ripu' (enemy);","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੬੦੯।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 609 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[610],"number_text":"੬੧੦।","page":964,"lines":[{"gurmukhi":"ਘੋਰਾਂਤਕਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Ghoraantaknee aadi kahi ripu pad anti uchaar |","meaning_en":"First say 'ghorantakani' (destroyer of horses), then at the end say the word 'ripu' (enemy);","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸੁ ਧਾਰ। ੬੧੦।","roman":"Naam tupak ke hot hai leejhu sumti su dhaar | 610 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them up with care.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[611],"number_text":"੬੧੧।","page":964,"lines":[{"gurmukhi":"ਬਾਜਾਂਤਕਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Baajaantaknee aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'bajantakani' (destroyer of horses), then at the end say 'ripu' and 'ari' (both 'enemy');","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੧੧।","roman":"Naam tupak ke hot hai cheen chatur nirdhaar | 611 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[612],"number_text":"੬੧੨।","page":964,"lines":[{"gurmukhi":"ਬਾਹਨਾਂਤਕੀ ਆਦਿ ਕਹਿ ਪੁਨਿ ਰਿਪੁ ਨਾਦਨਿ ਭਾਖੁ।","roman":"Baahnaantkee aadi kahi puni ripu naadni bhaakhu |","meaning_en":"First say 'bahanantaki' (destroyer of mounts), then say 'ripu nadani';","page":964,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਚਿਤ ਰਾਖੁ। ੬੧੨।","roman":"Naam tupak ke hot hai cheeni chatur chit raakhu | 612 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and keep them in mind.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[613],"number_text":"੬੧੩।","page":964,"lines":[{"gurmukhi":"ਸੂਰਜਜ ਅਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Soorjaj ari dhvannee uchri ripu pad bahuri bakhaan |","meaning_en":"Say 'surajaj ari dhvanani' (army with the roar of the enemy of the sun-born horse), then say the word 'ripu' (enemy) after it;","page":964,"meaning_status":"draft","note":"ਸੂਰਜਜ: 'born of the sun', read as the horse; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਲੇਹੁ ਮਤਿਵਾਨ। ੬੧੩।","roman":"Naam tupak ke hot hai cheen lehu mativaan | 613 |","meaning_en":"these become names of the tupak (gun); thoughtful ones, recognise them.","page":964,"meaning_status":"draft"}]},{"type":"verse","number":[614],"number_text":"੬੧੪।","page":965,"lines":[{"gurmukhi":"ਬਾਜ ਅਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਅੰਤ੍ਯਾਂਤਕ ਪਦ ਦੀਨ।","roman":"Baaj ari dhvannee aadi kahi antyaantak pad deen |","meaning_en":"First say 'baj ari dhvanani' (army with the roar of the horse's enemy), then add the word 'antyantak' (destroyer);","page":965,"meaning_status":"draft","note":"ਅੰਤ੍ਯਾਂਤਕ: read as 'ender, destroyer'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੬੧੪।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 614 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[615],"number_text":"੬੧੫।","page":965,"lines":[{"gurmukhi":"ਸਿੰਧੁਰਰਿ ਪ੍ਰਥਮ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Sindhurri pratham uchaari kai ripu pad anti uchaar |","meaning_en":"First say 'sindhurari' (enemy of the elephant), then at the end say the word 'ripu' (enemy);","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੧੫।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 615 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[616],"number_text":"੬੧੬।","page":965,"lines":[{"gurmukhi":"ਬਾਹਨਿ ਨਾਦਿਨ ਆਦਿ ਕਹਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Baahni naadin aadi kahi ripu pad anti uchaar |","meaning_en":"First say 'bahani nadin' (army sounding of mounts), then at the end say the word 'ripu' (enemy);","page":965,"meaning_status":"draft","note":"ਬਾਹਨਿ ਨਾਦਿਨ: printed so; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰਿ। ੬੧੬।","roman":"Naam tupak ke hot hai leejhu sughar su dhaari | 616 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[617],"number_text":"੬੧੭।","page":965,"lines":[{"gurmukhi":"ਤੁਰੰਗਰਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਧ੍ਵਨਨੀ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Turangri aadi bakhaani kai dhvannee bahuri uchaar |","meaning_en":"First say 'turangari' (enemy of the horse), then say 'dhvanani' (the sounding one) after it;","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰਿ। ੬੧੭।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaari | 617 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[618],"number_text":"੬੧੮।","page":965,"lines":[{"gurmukhi":"ਅਰਬਯਰਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰਿ।","roman":"Arbayri aadi uchaari kai ripu ari bahuri uchaari |","meaning_en":"First say 'arabayari' (enemy of the Arab horse), then say 'ripu' and 'ari' (both 'enemy') after it;","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸਵਾਰਿ। ੬੧੮।","roman":"Naam tupak ke hot hai leejhu su kabi savaari | 618 |","meaning_en":"these become names of the tupak (gun); good poets, take them and polish them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[619],"number_text":"੬੧੯।","page":965,"lines":[{"gurmukhi":"ਤੁਰੰਗਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Turangri dhvannee aadi kahi ripu ari puni pad dehu |","meaning_en":"First say 'turangari dhvanani' (army with the roar of the horse's enemy), then add the words 'ripu' and 'ari' (both 'enemy');","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੬੧੯।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 619 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[620],"number_text":"੬੨੦।","page":965,"lines":[{"gurmukhi":"ਕਿੰਕਨ ਅਰਿ ਧ੍ਵਨਨੀ ਉਚਰਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Kinkan ari dhvannee uchri ripu pad anti uchaar |","meaning_en":"Say 'kinkan ari dhvanani', then at the end say the word 'ripu' (enemy);","page":965,"meaning_status":"draft","note":"ਕਿੰਕਨ: read as 'horse'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੬੨੦।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 620 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[621],"number_text":"੬੨੧।","page":965,"lines":[{"gurmukhi":"ਘੁਰਅਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Ghura'ari naadni aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'ghurari nadani', then at the end say 'ripu' and 'ari' (both 'enemy');","page":965,"meaning_status":"draft","note":"ਘੁਰਅਰਿ: perhaps 'enemy of the horse' (ghur from ghora); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸੁ ਧਾਰ। ੬੨੧।","roman":"Naam tupak ke hot hai leejhu sumti su dhaar | 621 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them up with care.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[622],"number_text":"੬੨੨।","page":965,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਅਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Mrig ari naadni aadi kahi ripu ari anti uchaar |","meaning_en":"First say 'mrig ari nadani' (army with the roar of the deer's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰਿ। ੬੨੨।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaari | 622 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[623],"number_text":"੬੨੩।","page":965,"lines":[{"gurmukhi":"ਸਿੰਗੀ ਅਰਿ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Singee ari dhvannee aadi kahi ripu ari anti uchaari |","meaning_en":"First say 'singi ari dhvanani' (army with the roar of the horned deer's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੨੩।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 623 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[624],"number_text":"੬੨੪।","page":965,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਅਰਿ ਨਾਦਨਿ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰਿ।","roman":"Mrigee ari naadni aadi kahi ripu ari anti uchaari |","meaning_en":"First say 'mrigi ari nadani' (army with the roar of the doe's enemy), then at the end say 'ripu' and 'ari' (both 'enemy');","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸਵਾਰਿ। ੬੨੪।","roman":"Naam tupak ke hot hai leejhu su kabi savaari | 624 |","meaning_en":"these become names of the tupak (gun); good poets, take them and polish them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[625],"number_text":"੬੨੫।","page":965,"lines":[{"gurmukhi":"ਤ੍ਰਿਣ ਅਰਿ ਨਾਦਨਿ ਉਚਰਿ ਕੈ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Trin ari naadni uchri kai ripu pad bahuri bakhaan |","meaning_en":"Say 'trin ari nadani' (army with the roar of the enemy of the grass-[eater]), then say the word 'ripu' (enemy) after it;","page":965,"meaning_status":"draft","note":"ਤ੍ਰਿਣ ਅਰਿ: literally 'enemy of grass' (the deer, a grazer); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚਤੁਰ ਚਿਤ ਪਹਿਚਾਨ। ੬੨੫।","roman":"Naam tupak ke hot hai chatur chit pahichaan | 625 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[626],"number_text":"੬੨੬।","page":965,"lines":[{"gurmukhi":"ਭੂਚਰਿ ਆਦਿ ਬਖਾਨਿ ਕੈ ਰਿਪੁ ਅਰਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Bhoochri aadi bakhaani kai ripu ari anti uchaar |","meaning_en":"First say 'bhuchari' (earth-goers), then at the end say 'ripu' and 'ari' (both 'enemy');","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ।੬੨੬।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 626 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[627],"number_text":"੬੨੭।","page":965,"lines":[{"gurmukhi":"ਸੁਭਟ ਆਦਿ ਸਬਦ ਉਚਰਿ ਕੈ ਅੰਤਿ ਸਤ੍ਰੁ ਪਦ ਦੀਨ।","roman":"Subhat aadi sabad uchri kai anti satru pad deen |","meaning_en":"First say the word 'subhat' (warrior), and at the end add the word 'satru' (enemy);","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਚੀਨ। ੬੨੭।","roman":"Naam tupak ke hot hai leejhu sughar su cheen | 627 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[628],"number_text":"੬੨੮।","page":965,"lines":[{"gurmukhi":"ਆਦਿ ਸਤ੍ਰੁ ਸਬਦ ਉਚਰਿ ਕੈ ਅੰਤ੍ਯਾਂਤਕ ਪਦ ਭਾਖੁ।","roman":"Aadi satru sabad uchri kai antyaantak pad bhaakhu |","meaning_en":"First say the word 'satru' (enemy), then say the word 'antyantak' (destroyer);","page":965,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਚਿਤਿ ਰਾਖੁ। ੬੨੮।","roman":"Naam tupak ke hot hai cheeni chatur chiti raakhu | 628 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and keep them in mind.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[629],"number_text":"੬੨੯।","page":965,"lines":[{"gurmukhi":"ਸਤ੍ਰੁ ਆਦਿ ਸਬਦ ਉਚਰੀਐ ਸੂਲਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Satru aadi sabad uchreeai soolni anti uchaar |","meaning_en":"First say the word 'satru' (enemy), then at the end say 'sulani' (piercer);","page":965,"meaning_status":"draft","note":"ਸੂਲਨਿ: from sul, 'pain / spike'; read as 'one who pierces'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੨੯।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 629 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":965,"meaning_status":"draft"}]},{"type":"verse","number":[630],"number_text":"੬੩੦।","page":966,"lines":[{"gurmukhi":"ਆਦਿ ਜੁਧਨੀ ਭਾਖੀਐ ਅੰਤਕਨੀ ਪਦ ਭਾਖੁ।","roman":"Aadi judhnee bhaakheeai antaknee pad bhaakhu |","meaning_en":"First say 'judhani' (army of battle), then say the word 'antakani' (ender);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਚਿਤਿ ਰਾਖੁ। ੬੩੦।","roman":"Naam tupak ke hot hai cheeni chatur chiti raakhu | 630 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and keep them in mind.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[631],"number_text":"੬੩੧।","page":966,"lines":[{"gurmukhi":"ਬਰਮ ਆਦਿ ਸਬਦ ਉਚਰਿ ਕੈ ਬੇਧਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Baram aadi sabad uchri kai bedhni anti uchaar |","meaning_en":"First say the word 'barm' (armour), then at the end say 'bedhani' (piercer);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਬਰਮ ਬੇਧਨਿ ਤੁਪਕ ਕੋ ਲੀਜਹੁ ਨਾਮ ਸੁ ਧਾਰ। ੬੩੧।","roman":"Baram bedhni tupak ko leejhu naam su dhaar | 631 |","meaning_en":"take up with care 'barm bedhani' (piercer of armour) as a name of the tupak (gun).","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[632],"number_text":"੬੩੨।","page":966,"lines":[{"gurmukhi":"ਚਰਮ ਆਦਿ ਪਦ ਭਾਖਿ ਕੈ ਘਾਇਨਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Charam aadi pad bhaakhi kai ghaaini pad kai deen |","meaning_en":"First say the word 'charm' (shield / skin), then add the word 'ghaini' (wounder);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਚਰਮ ਘਾਇਨੀ ਤੁਪਕ ਕੇ ਨਾਮ ਲੀਜੀਅਹੁ ਚੀਨ। ੬੩੨।","roman":"Charam ghaainee tupak ke naam leejeeahu cheen | 632 |","meaning_en":"recognise 'charm ghaini' (wounder of shields) as a name of the tupak (gun).","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[633],"number_text":"੬੩੩।","page":966,"lines":[{"gurmukhi":"ਦ੍ਰੂਜਨ ਆਦਿ ਸਬਦ ਉਚਰਿ ਕੈ ਭਛਨੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Droojan aadi sabad uchri kai bhachhnee anti uchaar |","meaning_en":"First say the word 'drujan' (the wicked), then at the end say 'bhachhani' (devourer);","page":966,"meaning_status":"draft","note":"ਦ੍ਰੂਜਨ: printed so; read as durjan, 'the wicked'."},{"gurmukhi":"ਦ੍ਰੂਜਨ ਭਛਨੀ ਤੁਪਕ ਕੋ ਲੀਜਹੁ ਨਾਮ ਸੁ ਧਾਰ। ੬੩੩।","roman":"Droojan bhachhnee tupak ko leejhu naam su dhaar | 633 |","meaning_en":"take up with care 'drujan bhachhani' (devourer of the wicked) as a name of the tupak (gun).","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[634],"number_text":"੬੩੪।","page":966,"lines":[{"gurmukhi":"ਖਲ ਪਦ ਆਦਿ ਬਖਾਨਿ ਕੈ ਹਾ ਪਦ ਪੁਨਿ ਕੈ ਦੀਨ।","roman":"Khal pad aadi bakhaani kai haa pad puni kai deen |","meaning_en":"First say the word 'khal' (the wicked), then add the word 'ha' (slayer);","page":966,"meaning_status":"draft","note":"ਹਾ: read as 'slayer'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੬੩੪।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 634 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[635],"number_text":"੬੩੫।","page":966,"lines":[{"gurmukhi":"ਦੁਸਟਨ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁਣੀ ਅੰਤਿ ਬਖਾਨ।","roman":"Dustan aadi uchaari kai ripunee anti bakhaan |","meaning_en":"First say 'dustan' (the wicked), then at the end say 'ripuni' (enemy);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੇਹੁ ਪ੍ਰਬੀਨ ਪਛਾਨ। ੬੩੫।","roman":"Naam tupak ke hot hai lehu prabeen pachhaan | 635 |","meaning_en":"these become names of the tupak (gun); skilled ones, recognise them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[636],"number_text":"੬੩੬।","page":966,"lines":[{"gurmukhi":"ਰਿਪੁਣੀ ਆਦਿ ਉਚਾਰਿ ਕੈ ਖਿਪਣੀ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Ripunee aadi uchaari kai khipnee bahuri bakhaan |","meaning_en":"First say 'ripuni' (of enemies), then say 'khipani' (destroyer) after it;","page":966,"meaning_status":"draft","note":"ਖਿਪਣੀ: read as 'destroyer / hurler'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸਯਾਨ। ੬੩੬।","roman":"Naam tupak ke hot hai leejhu samajh sayaan | 636 |","meaning_en":"these become names of the tupak (gun); wise ones, grasp them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[637],"number_text":"੬੩੭।","page":966,"lines":[{"gurmukhi":"ਨਾਲ ਸੈਫਨੀ ਤੁਪਕ ਭਨਿ ਜਬਰਜੰਗ ਹਥ ਨਾਲ।","roman":"Naal saiphnee tupak bhani jabarjang hath naal |","meaning_en":"Say 'nal', 'saifani', 'tupak', 'jabarjang', 'hath nal',","page":966,"meaning_status":"draft","note":"A plain list of names of the gun; transliterated. Some may combine differently (e.g. 'nal saifani'); uncertain."},{"gurmukhi":"ਸੁਤਰ ਨਾਲ ਘੁੜ ਨਾਲ ਭਨਿ ਚੂਰਣਿ ਪੁਨਿ ਪਰ ਜੁਆਲ। ੬੩੭।","roman":"Sutar naal ghur naal bhani choorni puni par juaal | 637 |","meaning_en":"'sutar nal', 'ghur nal', and then 'churani' and 'par jual'.","page":966,"meaning_status":"draft","note":"ਸੁਤਰ ਨਾਲ: camel-gun; ਘੁੜ ਨਾਲ: horse-gun; ਚੂਰਣਿ, ਪਰ ਜੁਆਲ: meanings uncertain (perhaps 'crusher', 'flame-bearer')."}]},{"type":"verse","number":[638],"number_text":"੬੩੮।","page":966,"lines":[{"gurmukhi":"ਜੁਆਲ ਆਦਿ ਸਬਦੁਚਰਿ ਕੈ ਧਰਣੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Juaal aadi sabduchri kai dharnee anti uchaar |","meaning_en":"First say the word 'jual' (flame), then at the end say 'dharani' (holder);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸੁ ਧਾਰ। ੬੩੮।","roman":"Naam tupak ke hot hai leejhu sumti su dhaar | 638 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them up with care.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[639],"number_text":"੬੩੯।","page":966,"lines":[{"gurmukhi":"ਅਨਲੁ ਆਦਿ ਸਬਦੁਚਰਿ ਕੈ ਛੋਡਣਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Anlu aadi sabduchri kai chhodni anti uchaar |","meaning_en":"First say the word 'analu' (fire), then at the end say 'chhodani' (releaser);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੩੯।","roman":"Naam tupak ke hot hai cheen chatur nirdhaar | 639 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[640],"number_text":"੬੪੦।","page":966,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਬਮਨੀ ਆਦਿ ਕਹਿ ਮਨ ਮੈ ਸੁਘਰ ਬਿਚਾਰ।","roman":"Juaalaa bamnee aadi kahi man mai sughar bichaar |","meaning_en":"First say 'juala bamani' (spewer of flame); skilful ones, consider it in your mind;","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਜਾਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੪੦।","roman":"Naam tupak ke hot hai jaani chatur nirdhaar | 640 |","meaning_en":"these become names of the tupak (gun); clever ones, know them and settle on them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[641],"number_text":"੬੪੧।","page":966,"lines":[{"gurmukhi":"ਘਨ ਪਦ ਆਦਿ ਬਖਾਨਿ ਕੈ ਧ੍ਵਨਨੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Ghan pad aadi bakhaani kai dhvannee anti uchaar |","meaning_en":"First say the word 'ghan' (cloud), then at the end say 'dhvanani' (that thunders);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਅਪਾਰ। ੬੪੧।","roman":"Naam tupak ke hot hai cheenhu chatur apaar | 641 |","meaning_en":"these become names of the tupak (gun); recognise them, you who are greatly clever.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[642],"number_text":"੬੪੨।","page":966,"lines":[{"gurmukhi":"ਘਨ ਪਦ ਆਦਿ ਉਚਾਰਿ ਕੈ ਨਾਦਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Ghan pad aadi uchaari kai naadni anti uchaar |","meaning_en":"First say the word 'ghan' (cloud), then at the end say 'nadani' (that roars);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੪੨।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 642 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[643],"number_text":"੬੪੩।","page":966,"lines":[{"gurmukhi":"ਬਾਰਿਦ ਆਦਿ ਬਖਾਨਿ ਕੈ ਸਬਦਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Baarid aadi bakhaani kai sabadni anti uchaar |","meaning_en":"First say 'barid' (cloud), then at the end say 'sabadani' (that sounds);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੪੩।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 643 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[644],"number_text":"੬੪੪।","page":966,"lines":[{"gurmukhi":"ਮੇਘਨ ਧ੍ਵਨਨੀ ਆਦਿ ਕਹਿ ਰਿਪੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Meghan dhvannee aadi kahi ripu ari bahuri uchaar |","meaning_en":"First say 'meghan dhvanani' (that thunders like clouds), then say 'ripu' and 'ari' (both 'enemy') after it;","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਹੁ ਚਤੁਰ ਅਪਾਰ। ੬੪੪।","roman":"Naam tupak ke hot hai cheenhu chatur apaar | 644 |","meaning_en":"these become names of the tupak (gun); recognise them, you who are greatly clever.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[645],"number_text":"੬੪੫।","page":966,"lines":[{"gurmukhi":"ਮੇਘਨ ਸਬਦਨੀ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਸਬਦ ਉਚਾਰ।","roman":"Meghan sabadnee bakatr te prathmai sabad uchaar |","meaning_en":"First speak with your mouth the word 'meghan sabadani' (that sounds like clouds);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੬੪੫।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 645 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[646],"number_text":"੬੪੬।","page":966,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਆਲਯ ਅੰਤ ਉਚਾਰ।","roman":"Golaa aadi uchaari kai aalay ant uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'alay' (abode);","page":966,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੪੬।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 646 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":966,"meaning_status":"draft"}]},{"type":"verse","number":[647],"number_text":"੬੪੭।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਧਰਨੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi uchaari kai dharnee anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'dharani' (holder);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੬੪੭।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 647 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[648],"number_text":"੬੪੮।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਅਸਤ੍ਰਣਿ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Golaa aadi uchaari kai astrani puni pad dehu |","meaning_en":"First say 'gola' (ball), then add the word 'astrani' (thrower);","page":967,"meaning_status":"draft","note":"ਅਸਤ੍ਰਣਿ: read as 'that hurls (as a missile)'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤ ਲੇਹੁ। ੬੪੮।","roman":"Naam tupak ke hot hai cheen chatur chit lehu | 648 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[649],"number_text":"੬੪੯।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾਲਯਣੀ ਆਦਿ ਕਹਿ ਮੁਖ ਤੇ ਸਬਦ ਉਚਾਰ।","roman":"Golaalaynee aadi kahi mukh te sabad uchaar |","meaning_en":"First say with your mouth the word 'golalayani' (abode of the ball);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੬੪੯।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 649 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[650],"number_text":"੬੫੦।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਆਲਯਣੀ ਪੁਨਿ ਭਾਖੁ।","roman":"Golaa aadi uchaari kai aalaynee puni bhaakhu |","meaning_en":"First say 'gola' (ball), then say 'alayani' (abode);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਚਿਤਿ ਰਾਖੁ। ੬੫੦।","roman":"Naam tupak ke hot hai cheeni chatur chiti raakhu | 650 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and keep them in mind.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[651],"number_text":"੬੫੧।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਬਖਾਨਿ ਕੈ ਸਦਨਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi bakhaani kai sadanni anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'sadanani' (house);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਬਿਚਾਰ। ੬੫੧।","roman":"Naam tupak ke hot hai leejhu su kabi bichaar | 651 |","meaning_en":"these become names of the tupak (gun); good poets, take them with thought.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[652],"number_text":"੬੫੨।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਪਦ ਪ੍ਰਥਮੈ ਉਚਰਿ ਕੈ ਕੇਤਨਿ ਪਦ ਕਹੁ ਅੰਤਿ।","roman":"Golaa pad prathmai uchri kai ketni pad kahu anti |","meaning_en":"First say the word 'gola' (ball), then say the word 'ketani' (dwelling) at the end;","page":967,"meaning_status":"draft","note":"ਕੇਤਨਿ: read as 'abode/home' (ketan); uncertain."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਤੁਪਕ ਕੇ ਨਿਕਸਤ ਚਲਤ ਅਨੰਤ। ੬੫੨।","roman":"Naam sakal sree tupak ke niksat chalat anant | 652 |","meaning_en":"all the names of the revered tupak (gun) go on coming forth without end.","page":967,"meaning_status":"draft","note":"ਨਿਕਸਤ ਚਲਤ ਅਨੰਤ: read as 'go on emerging endlessly'; uncertain."}]},{"type":"verse","number":[653],"number_text":"੬੫੩।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਕੇਤਨਿ ਪਦ ਕੈ ਦੀਨ।","roman":"Golaa aadi uchaari kai ketni pad kai deen |","meaning_en":"First say 'gola' (ball), then add the word 'ketani' (dwelling);","page":967,"meaning_status":"draft","note":"ਕੇਤਨਿ: read as 'abode/home' (ketan); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੬੫੩।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 653 |","meaning_en":"these become names of the tupak (gun); skilled ones, grasp them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[654],"number_text":"੬੫੪।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਸਦਨੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi uchaari kai sadnee anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'sadani' (house);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੫੪।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 654 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[655],"number_text":"੬੫੫।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰੀਐ ਧਾਮਿਨ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi uchaareeai dhaamin anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'dhamin' (home);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤ ਸਵਾਰ। ੬੫੫।","roman":"Naam tupak ke hot hai leejhu sumat savaar | 655 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[656],"number_text":"੬੫੬।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਨਈਵਾਸਨ ਕਹਿ ਅੰਤਿ।","roman":"Golaa aadi uchaari kai naeevaasan kahi anti |","meaning_en":"First say 'gola' (ball), then say 'naivasan' (dwelling) at the end;","page":967,"meaning_status":"draft","note":"ਨਈਵਾਸਨ: printed so; read as nivasan, 'dwelling'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਨਿਕਸਤ ਚਲਤ ਬਿਅੰਤ। ੬੫੬।","roman":"Naam tupak ke hot hai niksat chalat biant | 656 |","meaning_en":"these become names of the tupak (gun); they go on coming forth without limit.","page":967,"meaning_status":"draft","note":"ਨਿਕਸਤ ਚਲਤ: read as 'go on emerging'; uncertain."}]},{"type":"verse","number":[657],"number_text":"੬੫੭।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਲਿਆਲੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi uchaari kai liaalee anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'liali';","page":967,"meaning_status":"draft","note":"ਲਿਆਲੀ: unclear; perhaps from alay ('abode'); unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸਵਾਰ। ੬੫੭।","roman":"Naam tupak ke hot hai leejhu sughar savaar | 657 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and polish them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[658],"number_text":"੬੫੮।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਮੁਕਤਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi uchaari kai mukatni anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'muktani' (releaser);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਕਹਿ ਕਬੋ ਲੀਜਹੁ ਸਕਲ ਬੀਚਾਰ। ੬੫੮।","roman":"Naam tupak ke kahi kabo leejhu sakal beechaar | 658 |","meaning_en":"poets, call these names of the tupak (gun); take them all with thought.","page":967,"meaning_status":"draft","note":"ਕਹਿ ਕਬੋ: read as 'say, O poets'; uncertain."}]},{"type":"verse","number":[659],"number_text":"੬੫੯।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਦਾਤੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Golaa aadi uchaari kai daatee anti uchaar |","meaning_en":"First say 'gola' (ball), then at the end say 'dati' (giver);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੬੫੯।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 659 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[660],"number_text":"੬੬੦।","page":967,"lines":[{"gurmukhi":"ਗੋਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਤਜਨੀ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Golaa aadi uchaari kai tajnee puni pad dehu |","meaning_en":"First say 'gola' (ball), then add the word 'tajani' (that casts off);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੬੬੦।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 660 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[661],"number_text":"੬੬੧।","page":967,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਛਡਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Juaalaa aadi uchaari kai chhadni anti uchaar |","meaning_en":"First say 'juala' (flame), then at the end say 'chhadani' (releaser);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੬੬੧।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 661 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[662],"number_text":"੬੬੨।","page":967,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਸਕਤਨੀ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਕਰੋ ਬਖਿਆਨ।","roman":"Juaalaa sakatnee bakatr te prathmai karo bakhiaan |","meaning_en":"First speak out with your mouth 'juala saktani' (flame-power);","page":967,"meaning_status":"draft","note":"ਸਕਤਨੀ: read as 'with power / spear-like'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਪਛਾਨ। ੬੬੨।","roman":"Naam tupak ke hot hai leejhu sughar pachhaan | 662 |","meaning_en":"these become names of the tupak (gun); skilful ones, recognise them.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[663],"number_text":"੬੬੩।","page":967,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਤਜਣੀ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Juaalaa tajnee bakatr te prathmai karo uchaar |","meaning_en":"First speak out with your mouth 'juala tajani' (casting forth flame);","page":967,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਬਿਚਾਰ। ੬੬੩।","roman":"Naam tupak ke hot hai leejhu chatur bichaar | 663 |","meaning_en":"these become names of the tupak (gun); clever ones, take them with thought.","page":967,"meaning_status":"draft"}]},{"type":"verse","number":[664],"number_text":"੬੬੪।","page":968,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਛਾਡਣਿ ਪ੍ਰਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Juaalaa chhaadni pratham hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'juala chhadani' (releasing flame);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰ। ੬੬੪।","roman":"Naam tupak ke hot hai leejhu sughar su dhaar | 664 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[665],"number_text":"੬੬੫।","page":968,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਦਾਇਨਿ ਪ੍ਰਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Juaalaa daaini pratham hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'juala daini' (giver of flame);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰ। ੬੬੫।","roman":"Naam tupak ke hot hai leejhu sughar su dhaar | 665 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[666],"number_text":"੬੬੬।","page":968,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਬਕਤ੍ਰਣਿ ਪ੍ਰਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Juaalaa baktrani pratham hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'juala bakatrani' (flame-mouthed);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸਵਾਰ। ੬੬੬।","roman":"Naam tupak ke hot hai leejhu sughar savaar | 666 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and polish them.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[667],"number_text":"੬੬੭।","page":968,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਪ੍ਰਗਟਾਇਨਿ ਪਦ ਦੇਹੁ।","roman":"Juaalaa aadi uchaari kai pragtaaini pad dehu |","meaning_en":"First say 'juala' (flame), then add the word 'pragtaini' (that brings forth);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੬੬੭।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 667 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[668],"number_text":"੬੬੮।","page":968,"lines":[{"gurmukhi":"ਜੁਆਲਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਧਰਣੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Juaalaa aadi uchaari kai dharnee anti uchaar |","meaning_en":"First say 'juala' (flame), then at the end say 'dharani' (holder);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸਵਾਰ। ੬੬੮।","roman":"Naam tupak ke hot hai leejhu sughar savaar | 668 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and polish them.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[669],"number_text":"੬੬੯।","page":968,"lines":[{"gurmukhi":"ਦੁਰਜਨ ਆਦਿ ਉਚਾਰਿ ਕੈ ਦਾਹਨਿ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Durjan aadi uchaari kai daahni puni pad dehu |","meaning_en":"First say 'durjan' (the wicked), then add the word 'dahani' (burner);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤ ਲੇਹੁ। ੬੬੯।","roman":"Naam tupak ke hot hai cheen chatur chit lehu | 669 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[670],"number_text":"੬੭੦।","page":968,"lines":[{"gurmukhi":"ਦ੍ਰੂਜਨ ਆਦਿ ਸਬਦ ਉਚਾਰਿ ਕੈ ਦਰਰਨਿ ਅੰਤਿ ਉਚਾਰ।","roman":"Droojan aadi sabad uchaari kai dararni anti uchaar |","meaning_en":"First say the word 'drujan' (the wicked), then at the end say 'dararani' (tearer);","page":968,"meaning_status":"draft","note":"ਦ੍ਰੂਜਨ: printed so; read as durjan. ਦਰਰਨਿ: printed so; read as darani, 'tearer'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰ। ੬੭੦।","roman":"Naam tupak ke hot hai leejhu sughar su dhaar | 670 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[671],"number_text":"੬੭੧।","page":968,"lines":[{"gurmukhi":"ਗੋਲੀ ਧਰਣੀ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Golee dharnee bakatr te prathmai karo uchaar |","meaning_en":"First speak out with your mouth 'goli dharani' (holder of the bullet);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰ। ੬੭੧।","roman":"Naam tupak ke hot hai leejhu sughar su dhaar | 671 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[672],"number_text":"੬੭੨।","page":968,"lines":[{"gurmukhi":"ਦੁਸਟ ਆਦਿ ਸਬਦ ਉਚਾਰਿ ਕੈ ਦਾਹਨਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Dusat aadi sabad uchaari kai daahni bahuri uchaar |","meaning_en":"First say the word 'dust' (the wicked), then say 'dahani' (burner);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰ। ੬੭੨।","roman":"Naam tupak ke hot hai leejhu sughar su dhaar | 672 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈੋ","gurmukhi":"ਚੌਪਈੋ","roman":"Chaupao","meaning_en":"Chaupai.","page":968,"meaning_status":"draft","note":"Printed so: ਚੌਪਈੋ (with an extra vowel sign); read as ਚੌਪਈ."},{"type":"verse","number":[673],"number_text":"੬੭੩।","page":968,"lines":[{"gurmukhi":"ਕਾਸਟ ਪ੍ਰਿਸਠਣੀ ਆਦਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰਹੁ।","roman":"Kaasat prisathnee aadi uchaarhu | naam tupak ke sakal bichaarhu |","meaning_en":"Say 'kasat prisathani' (with a wooden back) first; consider all these as names of the tupak (gun).","page":968,"meaning_status":"draft"},{"gurmukhi":"ਭੂਮਿਜ ਪ੍ਰਿਸਠਨਿ ਪੁਨਿ ਪਦ ਦੀਜੈ। ਨਾਮ ਚੀਨ ਤੁਪਕ ਕੋ ਲੀਜੈ। ੬੭੩।","roman":"Bhoomij prisathni puni pad deejai | naam cheen tupak ko leejai | 673 |","meaning_en":"Then give the word 'bhumij prisathani' (backed with what is born of the earth); recognise it as a name of the tupak (gun).","page":968,"meaning_status":"draft","note":"ਭੂਮਿਜ: 'earth-born', read as tree/wood."}]},{"type":"verse","number":[674],"number_text":"੬੭੪।","page":968,"lines":[{"gurmukhi":"ਕਾਸਠਿ ਪ੍ਰਿਸਠਣੀ ਆਦਿ ਉਚਾਰ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰ।","roman":"Kaasthi prisathnee aadi uchaar | naam tupak ke sakal bichaar |","meaning_en":"Say 'kasathi prisathani' (with a wooden back) first; consider all these as names of the tupak (gun).","page":968,"meaning_status":"draft"},{"gurmukhi":"ਦ੍ਰੁਮਜ ਬਾਸਨੀ ਪੁਨਿ ਪਦ ਦੀਜੈ। ਚੀਨ ਨਾਮ ਨਾਲੀ ਕੋ ਲੀਜੈ। ੬੭੪।","roman":"Drumaj baasnee puni pad deejai | cheen naam naalee ko leejai | 674 |","meaning_en":"Then give the word 'drumaj basani' (dwelling in what is born of trees); recognise it as a name of the nali (gun barrel).","page":968,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਦ੍ਰੁਮਜ ਬਾਸਨੀ: read as 'housed in wood'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":968,"meaning_status":"draft"},{"type":"verse","number":[675],"number_text":"੬੭੫।","page":968,"lines":[{"gurmukhi":"ਕਾਸਠਿ ਪ੍ਰਿਸਠਣੀ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Kaasthi prisathnee bakatr te prathmai karo uchaar |","meaning_en":"First speak out with your mouth 'kasathi prisathani' (with a wooden back);","page":968,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਜਨ ਸਵਾਰ। ੬੭੫।","roman":"Naam tupak ke hot hai leejhu sujan savaar | 675 |","meaning_en":"these become names of the tupak (gun); good people, take them and polish them.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[676],"number_text":"੬੭੬।","page":968,"lines":[{"gurmukhi":"ਜਲਜ ਪ੍ਰਿਸਠਣੀ ਪ੍ਰਿਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Jalaj prisathnee pritham hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'jalaj prisathani' (backed with the water-born);","page":968,"meaning_status":"draft","note":"ਜਲਜ: 'born of water'; here read as tree/wood (nourished by water); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸੁ ਧਾਰ। ੬੭੬।","roman":"Naam tupak ke hot hai leejhu sughar su dhaar | 676 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[677],"number_text":"੬੭੭।","page":968,"lines":[{"gurmukhi":"ਬਾਰਜ ਪ੍ਰਿਸਠਣ ਆਦਿ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Baaraj pristhan aadi hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'baraj prisathan' (backed with the water-born);","page":968,"meaning_status":"draft","note":"ਬਾਰਜ: 'born of water'; read as tree/wood; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੬੭੭।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 677 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[678],"number_text":"੬੭੮।","page":968,"lines":[{"gurmukhi":"ਨੀਰਜਾਲਯਣਿ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਿਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Neerjaalayni bakatr te prithmai karo uchaar |","meaning_en":"First speak out with your mouth 'nirajalayani' (housed in the water-born);","page":968,"meaning_status":"draft","note":"ਨੀਰਜਾਲਯਣਿ: read as niraj (water-born, wood) + alay (abode); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੬੭੮।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 678 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":968,"meaning_status":"draft"}]},{"type":"verse","number":[679],"number_text":"੬੭੯।","page":969,"lines":[{"gurmukhi":"ਅੰਬੁਜ ਪ੍ਰਿਸਠਣੀ ਪ੍ਰਿਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Anbuj prisathnee pritham hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'ambuj prisathani' (backed with the water-born);","page":969,"meaning_status":"draft","note":"ਅੰਬੁਜ: 'water-born' (usually 'lotus'); here read as wood; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੬੭੯।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 679 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[680],"number_text":"੬੮੦।","page":969,"lines":[{"gurmukhi":"ਘਨਜਜ ਪ੍ਰਿਸਠਣ ਪ੍ਰਿਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Ghanjaj pristhan pritham hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'ghanjaj prisathan' (backed with what is born of the cloud-born);","page":969,"meaning_status":"draft","note":"ਘਨਜਜ: cloud-born (water) -> born of water (tree); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸਵਾਰ। ੬੮੦।","roman":"Naam tupak ke hot hai leejhu sughar savaar | 680 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and polish them.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[681],"number_text":"੬੮੧।","page":969,"lines":[{"gurmukhi":"ਜਲ ਤਰ ਆਦਿ ਉਚਾਰਿ ਕੈ ਪ੍ਰਿਸਠਣਿ ਧਰ ਪਦ ਦੇਹੁ।","roman":"Jal tar aadi uchaari kai prisathni dhar pad dehu |","meaning_en":"First say 'jal tar' (water, tree), then add the words 'prisathani dhar' (bearing a back);","page":969,"meaning_status":"draft","note":"ਜਲ ਤਰ ... ਧਰ: reading of the compound uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੬੮੧।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 681 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[682],"number_text":"੬੮੨।","page":969,"lines":[{"gurmukhi":"ਬਾਰ ਆਦਿ ਸਬਦ ਉਚਰਿ ਕੈ ਤਰ ਪ੍ਰਿਸਠਣ ਪੁਨਿ ਭਾਖੁ।","roman":"Baar aadi sabad uchri kai tar pristhan puni bhaakhu |","meaning_en":"First say the word 'bar' (water), then say 'tar prisathan' (tree-backed);","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਰਾਖੁ। ੬੮੨।","roman":"Naam tupak ke hot hai cheen chatur chiti raakhu | 682 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and keep them in mind.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[683],"number_text":"੬੮੩।","page":969,"lines":[{"gurmukhi":"ਨੀਰ ਆਦਿ ਸਬਦ ਉਚਰਿ ਕੈ ਤਰ ਪਦ ਪ੍ਰਿਸਠਣ ਦੇਹੁ।","roman":"Neer aadi sabad uchri kai tar pad pristhan dehu |","meaning_en":"First say the word 'nir' (water), then add the words 'tar' (tree) and 'prisathan' (back);","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੬੮੩।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 683 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[684],"number_text":"੬੮੪।","page":969,"lines":[{"gurmukhi":"ਹਰਜ ਪ੍ਰਿਸਠਣੀ ਆਦਿ ਹੀ ਮੁਖ ਤੇ ਕਰੋ ਉਚਾਰ।","roman":"Haraj prisathnee aadi hee mukh te karo uchaar |","meaning_en":"First speak out with your mouth 'haraj prisathani';","page":969,"meaning_status":"draft","note":"ਹਰਜ: unclear (perhaps 'born of water' or 'born of green'); unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸਵਾਰ। ੬੮੪।","roman":"Naam tupak ke hot hai leejhu sughar savaar | 684 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and polish them.","page":969,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":969,"meaning_status":"draft"},{"type":"verse","number":[685],"number_text":"੬੮੫।","page":969,"lines":[{"gurmukhi":"ਬਾਰਿਜ ਪ੍ਰਿਸਠਣੀ ਆਦਿ ਉਚਾਰ। ਨਾਮ ਨਾਲਿ ਕੇ ਸਕਲ ਬਿਚਾਰ।","roman":"Baarij prisathnee aadi uchaar | naam naali ke sakal bichaar |","meaning_en":"Say 'barij prisathani' (backed with the water-born) first; consider all these as names of the nal (gun).","page":969,"meaning_status":"draft"},{"gurmukhi":"ਭੂਰਹ ਪ੍ਰਿਸਠਣਿ ਪੁਨਿ ਪਦ ਦੀਜੈ। ਨਾਮ ਜਾਨ ਤੁਪਕ ਕੋ ਲੀਜੈ। ੬੮੫।","roman":"Bhoorah prisathni puni pad deejai | naam jaan tupak ko leejai | 685 |","meaning_en":"Then give the word 'bhurah prisathani' (backed with what grows from the earth); know it as a name of the tupak (gun).","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[686],"number_text":"੬੮੬।","page":969,"lines":[{"gurmukhi":"ਭੂਮਿ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਰੁਹ ਪ੍ਰਿਸਠਣਿ ਤੁਮ ਬਹੁਰਿ ਸਵਾਰੋ।","roman":"Bhoomi sabad ko aadi uchaaro | ruh prisathni tum bahuri savaaro |","meaning_en":"Say the word 'bhumi' (earth) first, then set the words 'ruh prisathani' (grown, backed) after it;","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਹੀ ਹੋਹੀ। ਜੋ ਕੋਊ ਚਤੁਰ ਚੀਨ ਕਰ ਜੋਹੀ। ੬੮੬।","roman":"Naam tupak ke sabh hee hohee | jo ko'oo chatur cheen kar johee | 686 |","meaning_en":"all these become names of the tupak (gun), for any clever one who looks and recognises them.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[687],"number_text":"੬੮੭।","page":969,"lines":[{"gurmukhi":"ਤਰੁ ਰੁਹ ਪ੍ਰਿਸਠਨਿ ਆਦਿ ਉਚਰੀਅਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਰੀਅਹੁ।","roman":"Taru ruh prisathni aadi uchreeahu | naam tupak ke sakal bichreeahu |","meaning_en":"Say 'taru ruh prisathani' (backed with what grows as a tree) first; consider all these as names of the tupak (gun).","page":969,"meaning_status":"draft"},{"gurmukhi":"ਕਾਸਠ ਕੁੰਦਨੀ ਆਦਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ੬੮੭।","roman":"Kaasath kundnee aadi bakhaano | naam tupak ke sabh jeea jaano | 687 |","meaning_en":"Say 'kasath kundani' (with a wooden stock) first; know all these in your heart as names of the tupak (gun).","page":969,"meaning_status":"draft","note":"ਕੁੰਦਾ: the stock/butt of a gun."}]},{"type":"verse","number":[688],"number_text":"੬੮੮।","page":969,"lines":[{"gurmukhi":"ਭੂਮਿ ਸਬਦ ਕਹੁ ਆਦਿ ਉਚਾਰਹੁ। ਰੁਹ ਸੁ ਸਬਦ ਕੋ ਬਹੁਰ ਬਿਚਾਰਹੁ।","roman":"Bhoomi sabad kahu aadi uchaarhu | ruh su sabad ko bahur bichaarhu |","meaning_en":"Say the word 'bhumi' (earth) first, then consider the word 'ruh' (grown) after it;","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਜੂ ਕੇ ਸਭ ਮਾਨਹੁ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਜਾਨਹੁ। ੬੮੮।","roman":"Naam tupak joo ke sabh maanhu | yaa mai kachhoo bhed nahee jaanhu | 688 |","meaning_en":"accept all these as names of the revered tupak (gun); know that there is no difference in this.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[689],"number_text":"੬੮੯।","page":969,"lines":[{"gurmukhi":"ਪ੍ਰਿਥੀ ਸਬਦ ਕੋ ਪ੍ਰਿਥਮੈ ਦੀਜੈ। ਰੁਹ ਪਦ ਬਹੁਰਿ ਉਚਾਰਨ ਕੀਜੈ।","roman":"Prithee sabad ko prithmai deejai | ruh pad bahuri uchaaran keejai |","meaning_en":"Give the word 'prithi' (earth) first, then say the word 'ruh' (grown);","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੬੮੯।","roman":"Naam tupak ke sabh jeea jaano | yaa mai kachhoo bhed nahee maano | 689 |","meaning_en":"know them all in your heart as names of the tupak (gun); hold that there is no difference in this.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[690],"number_text":"੬੯੦।","page":969,"lines":[{"gurmukhi":"ਬਿਰਛ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਪਦ ਕਹਿ ਜੀਅ ਬਿਚਾਰੋ।","roman":"Birachh sabad ko aadi uchaaro | prisathni pad kahi jeea bichaaro |","meaning_en":"Say the word 'birachh' (tree) first, then say the word 'prisathani' (having a back) and consider it in your heart;","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਹਿ ਅਪਾਰਾ। ਯਾ ਮੈ ਕਛੁ ਨ ਭੇਦ ਨਿਹਾਰਾ। ੬੯੦।","roman":"Naam tupak ke hohi apaaraa | yaa mai kachhu na bhed nihaaraa | 690 |","meaning_en":"the names of the tupak (gun) become countless; see no difference in this.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[691],"number_text":"੬੯੧।","page":969,"lines":[{"gurmukhi":"ਦ੍ਰੁਮਜ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਪਦ ਕਹਿ ਹੀਏ ਬਿਚਾਰੋ।","roman":"Drumaj sabad ko aadi uchaaro | prisathni pad kahi hee'e bichaaro |","meaning_en":"Say the word 'drumaj' (born of trees) first, then say the word 'prisathani' (having a back) and consider it in your heart;","page":969,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਵੈ। ਜਉ ਕੋਊ ਚਤੁਰ ਚਿਤ ਮੈ ਜੋਵੈ। ੬੯੧।","roman":"Sabh hee naam tupak ke hovai | jau ko'oo chatur chit mai jovai | 691 |","meaning_en":"all these become names of the tupak (gun), if any clever one looks into it in his mind.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[692],"number_text":"੬੯੨।","page":969,"lines":[{"gurmukhi":"ਤਰੁ ਪਦ ਮੁਖ ਤੇ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਪਦ ਕੌ ਬਹੁਰਿ ਬਿਚਾਰੋ।","roman":"Taru pad mukh te aadi uchaaro | prisathni pad kau bahuri bichaaro |","meaning_en":"Say the word 'taru' (tree) with your mouth first, then bring in the word 'prisathani' (having a back) after it;","page":969,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਬ ਜੀਅ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੬੯੨।","roman":"Naam tupak ke sab jeea jaano | yaa mai kachhoo bhed nahee maano | 692 |","meaning_en":"know them all in your heart as names of the tupak (gun); hold that there is no difference in this.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[693],"number_text":"੬੯੩।","page":969,"lines":[{"gurmukhi":"ਰੁਖ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਪਦ ਕਹਿ ਬਹੁਰਿ ਬਿਚਾਰੋ।","roman":"Rukh sabad ko aadi uchaaro | prisathni pad kahi bahuri bichaaro |","meaning_en":"Say the word 'rukh' (tree) first, then say the word 'prisathani' (having a back) and consider it;","page":969,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਈ। ਯਾ ਮੈ ਕਹੂੰ ਭੇਦ ਨਹੀ ਕੋਈ। ੬੯੩।","roman":"Sabh hee naam tupak ke hoee | yaa mai kahoon bhed nahee koee | 693 |","meaning_en":"all these become names of the tupak (gun); there is no difference at all in this.","page":969,"meaning_status":"draft"}]},{"type":"verse","number":[694],"number_text":"੬੯੪।","page":970,"lines":[{"gurmukhi":"ਉਤਭੁਜ ਪਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਪਦ ਕਹਿ ਹੀਏ ਬਿਚਾਰੋ।","roman":"Utbhuj pad ko aadi uchaaro | prisathni pad kahi hee'e bichaaro |","meaning_en":"Say the word 'utabhuj' (that which springs from the ground, a plant) first, then say the word 'prisathani' (having a back) and consider it in your heart;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੬੯੪।","roman":"Sabh hee naam tupak ke jaano | yaa mai kachhoo bhed nahee maano | 694 |","meaning_en":"know all these as names of the tupak (gun); hold that there is no difference in this.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[695],"number_text":"੬੯੫।","page":970,"lines":[{"gurmukhi":"ਤਰੁ ਸੁਤ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਬਹੁਰਿ ਪ੍ਰਿਸਠਣੀ ਸਬਦ ਬਿਚਾਰੋ।","roman":"Taru sut sabad ko aadi uchaaro | bahuri prisathnee sabad bichaaro |","meaning_en":"Say the words 'taru sut' (son of the tree) first, then bring in the word 'prisathani';","page":970,"meaning_status":"draft","note":"ਤਰੁ ਸੁਤ: read as wood/timber; uncertain."},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨ ਪਛਾਨੋ। ੬੯੫।","roman":"Sabh hee naam tupak ke jaano | yaa mai kachhoo bhed na pachhaano | 695 |","meaning_en":"know all these as names of the tupak (gun); recognise no difference in this.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[696],"number_text":"੬੯੬।","page":970,"lines":[{"gurmukhi":"ਪਤ੍ਰੀ ਪਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਪ੍ਰਿਸਠਣਿ ਸਬਦ ਸੁ ਬਹੁਰਿ ਪ੍ਰਮਾਨੋ।","roman":"Patree pad ko aadi bakhaano | prisathni sabad su bahuri pramaano |","meaning_en":"Say the word 'patri' (the leafy one, a tree) first, then establish the word 'prisathani' after it;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨਹੁ। ੬੯੬।","roman":"Sabh hee naam tupak ke jaanhu | yaa mai kachhoo bhed nahee maanhu | 696 |","meaning_en":"know all these as names of the tupak (gun); hold that there is no difference in this.","page":970,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":970,"meaning_status":"draft"},{"type":"verse","number":[697],"number_text":"੬੯੭।","page":970,"lines":[{"gurmukhi":"ਧਰਾਧਾਰ ਪਦ ਪ੍ਰਥਮ ਉਚਾਰਨ ਕੀਜੀਐ। ਪ੍ਰਿਸਠਣਿ ਪਦ ਕੋ ਬਹੁਰਿ ਠਉਰ ਤਹ ਦੀਜੀਐ।","roman":"Dharaadhaar pad pratham uchaaran keejeeai | prisathni pad ko bahuri thaur tah deejeeai |","meaning_en":"First say the word 'dharadhar' (support of the earth), then give the word 'prisathani' its place after it;","page":970,"meaning_status":"draft","note":"ਧਰਾਧਾਰ: read as 'support of the earth' (perhaps tree); uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀ ਜਾਨੀਐ। ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕ ਨਹੀ ਮਾਨੀਐ।੬੯੭।","roman":"Sakal tupak ke naam chatur jee jaaneeai | ho yaa ke bheetar bhed naik nahee maaneeai | 697 |","meaning_en":"clever ones, know all these as names of the tupak (gun); hold that there is not the least difference in this.","page":970,"meaning_status":"draft","note":"ਹੋ: metrical filler of the arill, left untranslated."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":970,"meaning_status":"draft"},{"type":"verse","number":[698],"number_text":"੬੯੮।","page":970,"lines":[{"gurmukhi":"ਧਰਾਰਾਜ ਪ੍ਰਥਮੈ ਉਚਰਿ ਪੁਨਿ ਪ੍ਰਿਸਠਨਿ ਪਦ ਦੇਹੁ।","roman":"Dharaaraaj prathmai uchri puni prisathni pad dehu |","meaning_en":"First say 'dhararaj' (king of the earth), then add the word 'prisathani';","page":970,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੬੯੮।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 698 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them in your mind.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[699],"number_text":"੬੯੯।","page":970,"lines":[{"gurmukhi":"ਧਰਾ ਆਦਿ ਸਬਦ ਉਚਰਿ ਕੈ ਨਾਇਕ ਅੰਤ ਉਚਾਰ।","roman":"Dharaa aadi sabad uchri kai naaik ant uchaar |","meaning_en":"First say the word 'dhara' (earth), then at the end say 'naik' (lord);","page":970,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠ ਭਾਖਿ ਬੰਦੂਕ ਕੇ ਲੀਜਹੁ ਨਾਮ ਸੁ ਧਾਰ। ੬੯੯।","roman":"Prisath bhaakhi bandook ke leejhu naam su dhaar | 699 |","meaning_en":"say 'prisath' (back), and take these up with care as names of the banduk (gun).","page":970,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":970,"meaning_status":"draft"},{"type":"verse","number":[700],"number_text":"੭੦੦।","page":970,"lines":[{"gurmukhi":"ਧਰਾ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨਹੁ। ਨਾਇਕ ਸਬਦ ਤਹਾ ਫੁਨਿ ਠਾਨਹੁ।","roman":"Dharaa sabad ko aadi bakhaanhu | naaik sabad tahaa phuni thaanhu |","meaning_en":"Say the word 'dhara' (earth) first, then place the word 'naik' (lord) there;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਪਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਨਾਮ ਤੁਪਕ ਕੈ ਸਭੈ ਬਿਚਰੀਐ। ੭੦੦।","roman":"Prisathni pad ko bahuri uchreeai | naam tupak kai sabhai bichreeai | 700 |","meaning_en":"then say the word 'prisathani'; consider all these as names of the tupak (gun).","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[701],"number_text":"੭੦੧।","page":970,"lines":[{"gurmukhi":"ਧਰਨੀ ਪਦ ਪ੍ਰਥਮੈ ਲਿਖਿ ਡਾਰੋ। ਰਾਵ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਾਰੋ।","roman":"Dharnee pad prathmai likhi daaro | raav sabad tih anti uchaaro |","meaning_en":"Write down the word 'dharani' (earth) first, and say the word 'rav' (king) at its end;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਬਹੁਰਿ ਸਬਦ ਕੋ ਦੀਜੈ। ਨਾਮ ਪਛਾਨ ਤੁਪਕ ਕੋ ਲੀਜੈ। ੭੦੧।","roman":"Prisathni bahuri sabad ko deejai | naam pachhaan tupak ko leejai | 701 |","meaning_en":"then add the word 'prisathani'; recognise it as a name of the tupak (gun).","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[702],"number_text":"੭੦੨।","page":970,"lines":[{"gurmukhi":"ਧਰਨੀਪਤਿ ਪਦ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਸਬਦਹਿ ਬਹੁਰਿ ਸਵਾਰੋ।","roman":"Dharneepti pad aadi uchaaro | prisathni sabadhi bahuri savaaro |","meaning_en":"Say 'dharanipati' (lord of the earth) first, then set the word 'prisathani' after it;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੭੦੨।","roman":"Naam tupak ke sabh jeea jaano | yaa mai kachhoo bhed nahee maano | 702 |","meaning_en":"know them all in your heart as names of the tupak (gun); hold that there is no difference in this.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[703],"number_text":"੭੦੩।","page":970,"lines":[{"gurmukhi":"ਧਰਾਰਾਟ ਪਦ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਪਦ ਕੋ ਬਹੁਰਿ ਸੁ ਧਾਰੋ।","roman":"Dharaaraat pad aadi uchaaro | prisathni pad ko bahuri su dhaaro |","meaning_en":"Say 'dhararat' (sovereign of the earth) first, then place the word 'prisathani' after it;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਜਾਨੋ ਮਨ ਮਾਹੀ। ਯਾ ਮੈ ਭੇਦ ਨੈਕ ਹੂੰ ਨਾਹੀ। ੭੦੩।","roman":"Naam tupak jaano man maahee | yaa mai bhed naik hoon naahee | 703 |","meaning_en":"know it in your mind as a name of the tupak (gun); there is not the least difference in this.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[704],"number_text":"੭੦੪।","page":970,"lines":[{"gurmukhi":"ਧਰਾਰਾਜ ਪੁਨਿ ਆਦਿ ਉਚਾਰੀਐ। ਤਾਹਿ ਪ੍ਰਿਸਠਣੀ ਬਹੁਰਿ ਸੁ ਧਰੀਐ।","roman":"Dharaaraaj puni aadi uchaareeai | taahi prisathnee bahuri su dhareeai |","meaning_en":"Say 'dhararaj' (king of the earth) first, then place 'prisathani' after it;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਵਹਿ। ਜਾ ਕੇ ਸਭ ਗੁਨਿਜਨ ਗੁਨ ਜੋਵਹਿ। ੭੦੪।","roman":"Sabh sree naam tupak ke hovhi | jaa ke sabh gunijan gun jovhi | 704 |","meaning_en":"all these become names of the revered tupak (gun), whose qualities all men of merit consider.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[705],"number_text":"੭੦੫।","page":970,"lines":[{"gurmukhi":"ਧਰਾ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਪ੍ਰਿਸਠਨਿ ਸਬਦ ਸੁ ਅੰਤਿ ਸੁ ਧਾਰੋ।","roman":"Dharaa sabad ko aadi uchaaro | prisathni sabad su anti su dhaaro |","meaning_en":"Say the word 'dhara' (earth) first, and place the word 'prisathani' at the end;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੭੦੫।","roman":"Sakal naam tupak ke jaano | yaa mai kachhoo bhed nahee maano | 705 |","meaning_en":"know all these as names of the tupak (gun); hold that there is no difference in this.","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[706],"number_text":"੭੦੬।","page":970,"lines":[{"gurmukhi":"ਧਰਾ ਸਬਦ ਕੋ ਆਦਿ ਭਨੀਜੈ। ਇੰਦ੍ਰ ਸਬਦ ਤਾ ਪਾਛੇ ਦੀਜੈ।","roman":"Dharaa sabad ko aadi bhaneejai | indr sabad taa paachhe deejai |","meaning_en":"Say the word 'dhara' (earth) first, and put the word 'indra' (lord) after it;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਪਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬੀਚਾਰੋ। ੭੦੬।","roman":"Prisathni pad ko bahuri uchaaro | sakal tupak ke naam beechaaro | 706 |","meaning_en":"then say the word 'prisathani'; consider all these as names of the tupak (gun).","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[707],"number_text":"੭੦੭।","page":970,"lines":[{"gurmukhi":"ਧਰਾ ਸਬਦ ਕੋ ਆਦਿ ਉਚਰੀਐ। ਪਾਲਕ ਸਬਦ ਸੁ ਅੰਤਿ ਬਿਚਰੀਐ।","roman":"Dharaa sabad ko aadi uchreeai | paalak sabad su anti bichreeai |","meaning_en":"Say the word 'dhara' (earth) first, and bring in the word 'palak' (protector) at the end;","page":970,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਪਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੭੦੭।","roman":"Prisathni pad ko bahuri bakhaano | sabh hee naam tupak ke jaano | 707 |","meaning_en":"then say the word 'prisathani'; know all these as names of the tupak (gun).","page":970,"meaning_status":"draft"}]},{"type":"verse","number":[708],"number_text":"੭੦੮।","page":971,"lines":[{"gurmukhi":"ਤਰੁਜ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਨਾਥ ਸਬਦ ਤਿਹ ਅੰਤਿ ਪ੍ਰਮਾਨੋ।","roman":"Taruj sabad ko aadi bakhaano | naath sabad tih anti pramaano |","meaning_en":"Say the word 'taruj' (born of trees) first, and set the word 'nath' (lord) at its end;","page":971,"meaning_status":"draft","note":"ਤਰੁਜ: 'born of trees' (fruit, or wood); uncertain."},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਸਬਦ ਸੁ ਬਹੁਰਿ ਭਨੀਜੈ। ਨਾਮ ਜਾਨ ਤੁਪਕ ਕੋ ਲੀਜੈ। ੭੦੮।","roman":"Prisathni sabad su bahuri bhaneejai | naam jaan tupak ko leejai | 708 |","meaning_en":"then say the word 'prisathani'; know it as a name of the tupak (gun).","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[709],"number_text":"੭੦੯।","page":971,"lines":[{"gurmukhi":"ਦ੍ਰੂਮਜ ਸਬਦ ਕੋ ਆਦਿ ਸੁ ਦੀਜੈ। ਨਾਇਕ ਪਦ ਕੋ ਬਹੁਰਿ ਭਨੀਜੈ।","roman":"Droomaj sabad ko aadi su deejai | naaik pad ko bahuri bhaneejai |","meaning_en":"Give the word 'drumaj' (born of trees) first, then say the word 'naik' (lord);","page":971,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਸਬਦ ਸੁ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਹੀ ਨਾਮ ਤੁਪਕ ਕੇ ਮਾਨਹੁ। ੭੦੯।","roman":"Prisathni sabad su anti bakhaanhu | sabh hee naam tupak ke maanhu | 709 |","meaning_en":"say the word 'prisathani' at the end; accept all these as names of the tupak (gun).","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[710],"number_text":"੭੧੦।","page":971,"lines":[{"gurmukhi":"ਫਲ ਪਦ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Phal pad aadi uchaaran keejai | taa paachhe naaik pad deejai |","meaning_en":"Say the word 'phal' (fruit) first, then put the word 'naik' (lord) after it;","page":971,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਪ੍ਰਿਸਠਨਿ ਤੁਮ ਸਬਦ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੧੦।","roman":"Puni prisathni tum sabad uchaaro | naam tupak ke sakal bichaaro | 710 |","meaning_en":"then say the word 'prisathani'; consider all these as names of the tupak (gun).","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[711],"number_text":"੭੧੧।","page":971,"lines":[{"gurmukhi":"ਤਰੁਜ ਸਬਦ ਕੋ ਆਦਿ ਉਚਰੀਐ। ਰਾਜ ਸਬਦ ਕੋ ਬਹੁਰਿ ਸੁ ਧਰੀਐ।","roman":"Taruj sabad ko aadi uchreeai | raaj sabad ko bahuri su dhareeai |","meaning_en":"Say the word 'taruj' (born of trees) first, then place the word 'raj' (king);","page":971,"meaning_status":"draft","note":"ਤਰੁਜ: 'born of trees' (fruit, or wood); uncertain."},{"gurmukhi":"ਤਾ ਪਾਛੇ ਪ੍ਰਿਸਠਨਿ ਪਦ ਦੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਜਾਨ ਜੀਅ ਲੀਜੈ। ੭੧੧।","roman":"Taa paachhe prisathni pad deejai | naam tuphang jaan jeea leejai | 711 |","meaning_en":"then add the word 'prisathani'; know it in your heart as a name of the tufang (musket).","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[712],"number_text":"੭੧੨।","page":971,"lines":[{"gurmukhi":"ਧਰਨੀਜਾ ਪਦ ਆਦਿ ਭਨਿਜੈ। ਰਾਟ ਸਬਦ ਤਾ ਪਾਛੇ ਦਿਜੈ।","roman":"Dharneejaa pad aadi bhanijai | raat sabad taa paachhe dijai |","meaning_en":"Say the word 'dharanija' (born of the earth) first, and put the word 'rat' (sovereign) after it;","page":971,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਪਦ ਕੋ ਅੰਤਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਸਭ ਭੇਦ ਨ ਮਾਨੋ। ੭੧੨।","roman":"Prisathni pad ko anti bakhaano | naam tupak sabh bhed na maano | 712 |","meaning_en":"say the word 'prisathani' at the end; all are names of the tupak (gun); see no difference among them.","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[713],"number_text":"੭੧੩।","page":971,"lines":[{"gurmukhi":"ਬ੍ਰਿਛਜ ਸਬਦ ਕੋ ਆਦਿ ਭਨੀਜੈ। ਤਾ ਪਾਛੈ ਰਾਜਾ ਪਦ ਦੀਜੈ।","roman":"Brichhaj sabad ko aadi bhaneejai | taa paachhai raajaa pad deejai |","meaning_en":"Say the word 'brichhaj' (born of trees) first, and put the word 'raja' (king) after it;","page":971,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਸਬਦ ਸੁ ਅੰਤਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੧੩।","roman":"Prisathni sabad su anti uchaaro | naam tupak ke sakal bichaaro | 713 |","meaning_en":"say the word 'prisathani' at the end; consider all these as names of the tupak (gun).","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[714],"number_text":"੭੧੪।","page":971,"lines":[{"gurmukhi":"ਤਰੁ ਰੁਹ ਅਨੁਜ ਆਦਿ ਪਦ ਦੀਜੈ। ਨਾਇਕ ਪਦ ਕੋ ਬਹੁਰਿ ਭਨੀਜੈ।","roman":"Taru ruh anuj aadi pad deejai | naaik pad ko bahuri bhaneejai |","meaning_en":"Give the words 'taru ruh anuj' first, then say the word 'naik' (lord);","page":971,"meaning_status":"draft","note":"ਤਰੁ ਰੁਹ ਅਨੁਜ: 'younger brother of what grows as a tree'; reading uncertain."},{"gurmukhi":"ਪ੍ਰਿਸਠਨਿ ਸਬਦ ਅੰਤ ਕੋ ਦੀਨੇ। ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਹਿੰ ਨਵੀਨੇ। ੭੧੪।","roman":"Prisathni sabad ant ko deene | naam tupak ke hohin naveene | 714 |","meaning_en":"with the word 'prisathani' given at the end, new names of the tupak (gun) come about.","page":971,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":971,"meaning_status":"draft"},{"type":"verse","number":[715],"number_text":"੭੧੫।","page":971,"lines":[{"gurmukhi":"ਤਰੁ ਰੁਹ ਪ੍ਰਿਸਠਨਿ ਪ੍ਰਥਮ ਹੀ ਮੁਖ ਤੇ ਕਰੌ ਉਚਾਰ।","roman":"Taru ruh prisathni pratham hee mukh te karau uchaar |","meaning_en":"First speak out with your mouth 'taru ruh prisathani' (backed with what grows as a tree);","page":971,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨਿ ਚਤੁਰ ਨਿਰਧਾਰ। ੭੧੫।","roman":"Naam tupak ke hot hai cheeni chatur nirdhaar | 715 |","meaning_en":"these become names of the tupak (gun); clever ones, recognise them and settle on them.","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[716],"number_text":"੭੧੬।","page":971,"lines":[{"gurmukhi":"ਸੁ ਕਬਿ ਬਕਤ੍ਰ ਤੇ ਕੁੰਦਣੀ ਪ੍ਰਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Su kabi bakatr te kundnee prathmai karo uchaar |","meaning_en":"Good poets, first speak out with your mouth 'kundani' (having a stock);","page":971,"meaning_status":"draft","note":"ਕੁੰਦਣੀ: from kunda, the stock of a gun."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਮਤਿ ਸਵਾਰ। ੭੧੬।","roman":"Naam tupak ke hot hai leejhu sumti savaar | 716 |","meaning_en":"these become names of the tupak (gun); wise-minded ones, take them and polish them.","page":971,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":971,"meaning_status":"draft"},{"type":"verse","number":[717],"number_text":"੭੧੭।","page":971,"lines":[{"gurmukhi":"ਕਾਸਟ ਕੁੰਦਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Kaasat kundnee aadi uchaaran keejeeai |","meaning_en":"Say 'kasat kundani' (with a wooden stock) first;","page":971,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤ ਲੀਜੀਐ।","roman":"Naam tupak ke cheen chatur chit leejeeai |","meaning_en":"clever ones, recognise in your mind these names of the tupak (gun).","page":971,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਿਛਜ ਬਾਸਨੀ ਸਬਦ ਬਕਤ੍ਰ ਤੇ ਭਾਖੀਐ।","roman":"Brichhaj baasnee sabad bakatr te bhaakheeai |","meaning_en":"Speak with your mouth the word 'brichhaj basani' (housed in what is born of trees);","page":971,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਿ ਹ੍ਰਿਦੈ ਮੈ ਰਾਖੀਐ।੭੧੭।","roman":"Ho naam tupak ke jaani hridai mai raakheeai | 717 |","meaning_en":"know it as a name of the tupak (gun) and keep it in your heart.","page":971,"meaning_status":"draft","note":"ਹੋ: metrical filler of the arill, left untranslated."}]},{"type":"verse","number":[718],"number_text":"੭੧੮।","page":971,"lines":[{"gurmukhi":"ਧਰਏਸ ਰਜਾ ਸਬਦ ਸੁ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Dharaes rajaa sabad su anti bakhaaneeai |","meaning_en":"Say 'dharaes' (lord of the earth) and the word 'raja' (king) at the end;","page":971,"meaning_status":"draft","note":"ਧਰਏਸ ਰਜਾ: printed so; ਰਜਾ read as raja; uncertain."},{"gurmukhi":"ਤਾ ਪਾਛੇ ਕੁੰਦਨੀ ਬਹੁਰਿ ਪਦ ਠਾਨੀਐ।","roman":"Taa paachhe kundnee bahuri pad thaaneeai |","meaning_en":"then place the word 'kundani' (having a stock) after it.","page":971,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਕਬਿ ਸਭੈ ਚਿਤ ਮਾਝ ਸੁ ਸਾਚ ਬਿਚਾਰੀਯੋ।","roman":"Su kabi sabhai chit maajh su saach bichaareeyo |","meaning_en":"Good poets, all consider this truly in your minds,","page":971,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਨਿਸੰਕ ਉਚਾਰੀਯੋ।੭੧੮।","roman":"Ho naam tupak ke sakal nisank uchaareeyo | 718 |","meaning_en":"and speak all the names of the tupak (gun) without hesitation.","page":971,"meaning_status":"draft"}]},{"type":"verse","number":[719],"number_text":"੭੧੯।","page":971,"lines":[{"gurmukhi":"ਤਰੁਜ ਬਾਸਨੀ ਆਦਿ ਸੁ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Taruj baasnee aadi su sabad bakhaaneeai |","meaning_en":"Say first the word 'taruj basani' (housed in what is born of trees);","page":971,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਸੁ ਕਬਿ ਮਨ ਮਾਨੀਐ।","roman":"Naam tupak ke sakal su kabi man maaneeai |","meaning_en":"good poets, accept in your minds all these as names of the tupak (gun).","page":971,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਮੈ ਸੰਕ ਨ ਕਛੂ ਹ੍ਰਿਦੈ ਮੈ ਕੀਜੀਐ।","roman":"Yaa mai sank na kachhoo hridai mai keejeeai |","meaning_en":"Have no doubt at all in your heart about this;","page":971,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹਾ ਜਹਾ ਇਹ ਨਾਮ ਚਹੋ ਤਹ ਦੀਜੀਐ।੭੧੯।","roman":"Ho jahaa jahaa ih naam chaho tah deejeeai | 719 |","meaning_en":"wherever you wish, put these names there.","page":971,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":972,"meaning_status":"draft"},{"type":"verse","number":[720],"number_text":"੭੨੦।","page":972,"lines":[{"gurmukhi":"ਭੂਮਿ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਪਦ ਤਿਹ ਪਾਛੇ ਦੈ ਡਾਰੋ।","roman":"Bhoomi sabad ko aadi uchaaro | jaa pad tih paachhe dai daaro |","meaning_en":"Say the word 'bhumi' (earth) first, and put the word 'ja' (born) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੭੨੦।","roman":"Naam tupak ke sabh jeea jaano | yaa mai kachhoo bhed nahee maano | 720 |","meaning_en":"know them all in your heart as names of the tupak (gun); hold that there is no difference in this.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[721],"number_text":"੭੨੧।","page":972,"lines":[{"gurmukhi":"ਪ੍ਰਿਥੀ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਜਾ ਪਦ ਦੈ ਡਾਰੋ।","roman":"Prithee sabad ko aadi uchaaro | taa paachhe jaa pad dai daaro |","meaning_en":"Say the word 'prithi' (earth) first, and put the word 'ja' (born) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਫੰਗ ਜਾਨ ਜੀਯ ਲੀਜੈ। ਚਹੀਐ ਜਹਾ ਤਹੀ ਪਦ ਦੀਜੈ। ੭੨੧।","roman":"Naam tuphang jaan jeey leejai | chaheeai jahaa tahee pad deejai | 721 |","meaning_en":"know it in your heart as a name of the tufang (musket); place the word wherever it is wanted.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[722],"number_text":"੭੨੨।","page":972,"lines":[{"gurmukhi":"ਬਸੁਧਾ ਸਬਦ ਸੁ ਆਦਿ ਬਖਾਨਹੁ। ਤਾ ਪਾਛੇ ਜਾ ਪਦ ਕਹੁ ਠਾਨਹੁ।","roman":"Basudhaa sabad su aadi bakhaanhu | taa paachhe jaa pad kahu thaanhu |","meaning_en":"Say the word 'basudha' (earth) first, and place the word 'ja' (born) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੭੨੨।","roman":"Naam tupak ke sabh jeea jaano | yaa mai kachhoo bhed nahee maano | 722 |","meaning_en":"know them all in your heart as names of the tupak (gun); hold that there is no difference in this.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[723],"number_text":"੭੨੩।","page":972,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਬਸੁੰਧ੍ਰਾ ਸਬਦ ਉਚਰੀਐ। ਤਾ ਪਾਛੇ ਜਾ ਪਦ ਦੈ ਡਰੀਐ।","roman":"Pratham basundhraa sabad uchreeai | taa paachhe jaa pad dai dareeai |","meaning_en":"First say the word 'basundhra' (earth), and put the word 'ja' (born) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭਿ ਜੀਅ ਲਹੀਐ। ਚਹੀਐ ਜਹਾ ਤਹੀ ਪਦ ਕਹੀਐ। ੭੨੩।","roman":"Naam tupak ke sabhi jeea laheeai | chaheeai jahaa tahee pad kaheeai | 723 |","meaning_en":"grasp them all in your heart as names of the tupak (gun); say the word wherever it is wanted.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[724],"number_text":"੭੨੪।","page":972,"lines":[{"gurmukhi":"ਤਰਨੀ ਪਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਤਾ ਪਾਛੇ ਜਾ ਪਦ ਕੋ ਠਾਨੋ।","roman":"Tarnee pad ko aadi bakhaano | taa paachhe jaa pad ko thaano |","meaning_en":"Say the word 'tarani' first, and place the word 'ja' (born) after it;","page":972,"meaning_status":"draft","note":"ਤਰਨੀ: perhaps 'earth' (as in this series) or 'boat'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਹੀ ਲਹੀਐ। ਚਹੀਐ ਜਹਾ ਤਹੀ ਪਦ ਕਹੀਐ। ੭੨੪।","roman":"Naam tupak ke sabh hee laheeai | chaheeai jahaa tahee pad kaheeai | 724 |","meaning_en":"grasp all these as names of the tupak (gun); say the word wherever it is wanted.","page":972,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":972,"meaning_status":"draft"},{"type":"verse","number":[725],"number_text":"੭੨੫।","page":972,"lines":[{"gurmukhi":"ਬਲੀਸ ਆਦਿ ਬਖਾਨ। ਬਾਸਨੀ ਪੁਨਿ ਪਦ ਠਾਨ।","roman":"Balees aadi bakhaan | baasnee puni pad thaan |","meaning_en":"Say 'balis' first, then place the word 'basani' (dwelling);","page":972,"meaning_status":"draft","note":"ਬਲੀਸ: unclear (perhaps 'lord of strength'); unglossed; uncertain."},{"gurmukhi":"ਨਾਮੈ ਤੁਪਕ ਸਭ ਹੋਇ। ਨਹੀ ਭੇਦ ਯਾ ਮਹਿ ਕੋਇ। ੭੨੫।","roman":"Naamai tupak sabh hoi | nahee bhed yaa mahi koi | 725 |","meaning_en":"all become names of the tupak (gun); there is no difference in this.","page":972,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":972,"meaning_status":"draft"},{"type":"verse","number":[726],"number_text":"੭੨੬।","page":972,"lines":[{"gurmukhi":"ਸਿੰਘ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨ। ਤਾ ਪਾਛੇ ਅਰਿ ਸਬਦ ਸੁ ਠਾਨ।","roman":"Singh sabad ko aadi bakhaan | taa paachhe ari sabad su thaan |","meaning_en":"Say the word 'singh' (lion) first, and place the word 'ari' (enemy) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨਹੁ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨਹੁ। ੭੨੬।","roman":"Naam tupak ke sakal pachhaanhu | yaa mai kachhoo bhed nahee maanhu | 726 |","meaning_en":"recognise all these as names of the tupak (gun); hold that there is no difference in this.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[727],"number_text":"੭੨੭।","page":972,"lines":[{"gurmukhi":"ਪੁੰਡਰੀਕ ਪਦ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਅਰਿ ਪਦ ਦੈ ਡਾਰੋ।","roman":"Pundreek pad aadi uchaaro | taa paachhe ari pad dai daaro |","meaning_en":"Say the word 'pundarik' (tiger) first, and put the word 'ari' (enemy) after it;","page":972,"meaning_status":"draft","note":"ਪੁੰਡਰੀਕ: read as 'tiger'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਕੀਜੈ। ੭੨੭।","roman":"Naam tupak ke sabh lahi leejai | yaa mai kachhoo bhed nahee keejai | 727 |","meaning_en":"grasp all these as names of the tupak (gun); make no distinction in this.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[728],"number_text":"੭੨੮।","page":972,"lines":[{"gurmukhi":"ਆਦਿ ਸਬਦ ਹਰ ਜਛ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਅਰਿ ਪਦ ਦੈ ਡਾਰੋ।","roman":"Aadi sabad har jachh uchaaro | taa paachhe ari pad dai daaro |","meaning_en":"Say the words 'har jachh' first, and put the word 'ari' (enemy) after it;","page":972,"meaning_status":"draft","note":"ਹਰ ਜਛ: perhaps 'lion'; unglossed; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਲਹੀਯੋ। ਚਹੀਐ ਨਾਮ ਜਹਾ ਤਹ ਕਹੀਯੋ। ੭੨੮।","roman":"Naam tupak ke sabh jeea laheeyo | chaheeai naam jahaa tah kaheeyo | 728 |","meaning_en":"grasp them all in your heart as names of the tupak (gun); say the name wherever it is wanted.","page":972,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":972,"meaning_status":"draft"},{"type":"verse","number":[729],"number_text":"੭੨੯।","page":972,"lines":[{"gurmukhi":"ਮ੍ਰਿਗਰਾਜ ਆਦਿ ਉਚਾਰ। ਅਰਿ ਸਬਦ ਬਹੁਰਿ ਸੁ ਧਾਰ।","roman":"Mrigraaj aadi uchaar | ari sabad bahuri su dhaar |","meaning_en":"Say 'mrigraj' (king of beasts, the lion) first, then place the word 'ari' (enemy);","page":972,"meaning_status":"draft"},{"gurmukhi":"ਤਊਫੰਗ ਨਾਮ ਪਛਾਨ। ਨਹੀ ਭੇਦ ਯਾ ਮਹਿ ਮਾਨ। ੭੨੯।","roman":"Taoophang naam pachhaan | nahee bhed yaa mahi maan | 729 |","meaning_en":"recognise it as a name of the tufang (musket); hold that there is no difference in this.","page":972,"meaning_status":"draft","note":"ਤਊਫੰਗ: printed so; read as tufang."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":972,"meaning_status":"draft"},{"type":"verse","number":[730],"number_text":"੭੩੦।","page":972,"lines":[{"gurmukhi":"ਆਦਿ ਸਬਦ ਮ੍ਰਿਗਰਾਜ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਰਿਪੁ ਪਦ ਦੈ ਡਾਰੋ।","roman":"Aadi sabad mrigraaj uchaaro | taa paachhe ripu pad dai daaro |","meaning_en":"Say the word 'mrigraj' (king of beasts) first, and put the word 'ripu' (enemy) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਜਾਨੋ। ੭੩੦।","roman":"Naam tupak ke sakal pachhaano | yaa mai kachhoo bhed nahee jaano | 730 |","meaning_en":"recognise all these as names of the tupak (gun); know that there is no difference in this.","page":972,"meaning_status":"draft"}]},{"type":"verse","number":[731],"number_text":"੭੩੧।","page":972,"lines":[{"gurmukhi":"ਪਸੁ ਪਤੇਸ ਪਦ ਪ੍ਰਥਮ ਭਨਿਜੈ। ਤਾ ਪਾਛੈ ਅਰਿ ਪਦ ਕੋ ਦਿਜੈ।","roman":"Pasu pates pad pratham bhanijai | taa paachhai ari pad ko dijai |","meaning_en":"First say the words 'pasu patesh' (lord of the lords of beasts), and give the word 'ari' (enemy) after it;","page":972,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੭੩੧।","roman":"Naam tupak ke sabh jeea jaano | yaa mai kachhoo bhed nahee maano | 731 |","meaning_en":"know them all in your heart as names of the tupak (gun); hold that there is no difference in this.","page":972,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":973,"meaning_status":"draft"},{"type":"verse","number":[732],"number_text":"੭੩੨।","page":973,"lines":[{"gurmukhi":"ਸਕਲ ਪਸੁਨ ਕੇ ਨਾਮ ਲੈ ਸਤ੍ਰੁ ਸਬਦ ਕਹਿ ਅੰਤਿ।","roman":"Sakal pasun ke naam lai satru sabad kahi anti |","meaning_en":"Take the names of all the beasts, and say the word 'satru' (enemy) at the end;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਫੰਗ ਕੇ ਨਿਕਸਤ ਚਲਤ ਅਨੰਤ। ੭੩੨।","roman":"Sabh hee naam tuphang ke niksat chalat anant | 732 |","meaning_en":"all the names of the tufang (musket) go on coming forth without end.","page":973,"meaning_status":"draft","note":"ਨਿਕਸਤ ਚਲਤ ਅਨੰਤ: read as 'go on emerging endlessly'; uncertain."}]},{"type":"verse","number":[733],"number_text":"੭੩੩।","page":973,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਪਦ ਆਦਿ ਬਖਾਨਿ ਕੈ ਪਤਿ ਪਦ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Mrig pad aadi bakhaani kai pati pad bahuri uchaar |","meaning_en":"First say the word 'mrig' (deer), then say the word 'pati' (lord);","page":973,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਫੰਗ ਕੇ ਲੀਜੈ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੭੩੩।","roman":"Ari kahi naam tuphang ke leejai su kabi su dhaar | 733 |","meaning_en":"say 'ari' (enemy), and good poets, take these up with care as names of the tufang (musket).","page":973,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":973,"meaning_status":"draft"},{"type":"verse","number":[734],"number_text":"੭੩੪।","page":973,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਸਬਦ ਆਦਿ ਬਖਾਨ। ਪਾਛੈ ਸੁ ਪਤਿ ਪਦ ਠਾਨ।","roman":"Mrig sabad aadi bakhaan | paachhai su pati pad thaan |","meaning_en":"Say the word 'mrig' (deer) first, and place the word 'pati' (lord) after it;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਸਬਦ ਬਹੁਰਿ ਉਚਾਰ। ਸਭ ਨਾਮ ਤੁਪਕ ਬਿਚਾਰ। ੭੩੪।","roman":"Ripu sabad bahuri uchaar | sabh naam tupak bichaar | 734 |","meaning_en":"then say the word 'ripu' (enemy); consider all these as names of the tupak (gun).","page":973,"meaning_status":"draft"}]},{"type":"verse","number":[735],"number_text":"੭੩੫।","page":973,"lines":[{"gurmukhi":"ਸਿੰਗੀ ਪ੍ਰਿਥਮ ਪਦ ਭਾਖੁ। ਅਰਿ ਸਬਦ ਕਹਿ ਲਖਿ ਰਾਖੁ।","roman":"Singee pritham pad bhaakhu | ari sabad kahi lakhi raakhu |","meaning_en":"Speak the word 'singi' (the horned one, deer) first; say the word 'ari' (enemy) and keep it in view;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਸਬਦ ਬਹੁਰਿ ਬਖਾਨ। ਸਭ ਨਾਮ ਤੁਪਕ ਪਛਾਨ। ੭੩੫।","roman":"Ari sabad bahuri bakhaan | sabh naam tupak pachhaan | 735 |","meaning_en":"then say the word 'ari' (enemy) again; recognise all these as names of the tupak (gun).","page":973,"meaning_status":"draft","note":"Printed so: 'ari' is given in both lines (perhaps the first was meant as 'pati'); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ ਵਡਾ","gurmukhi":"ਛੰਦ ਵਡਾ","roman":"Chhand vadaa","meaning_en":"Chhand Vada.","page":973,"meaning_status":"draft","note":"ਛੰਦ ਵਡਾ: 'the long chhand', as printed."},{"type":"verse","number":[736],"number_text":"੭੩੬।","page":973,"lines":[{"gurmukhi":"ਪਤਿ ਸਬਦ ਆਦਿ ਉਚਾਰਿ ਕੈ ਮ੍ਰਿਗ ਸਬਦ ਬਹੁਰਿ ਬਖਾਨੀਐ।","roman":"Pati sabad aadi uchaari kai mrig sabad bahuri bakhaaneeai |","meaning_en":"First say the word 'pati' (lord), then say the word 'mrig' (deer);","page":973,"meaning_status":"draft","note":"Printed so, with 'pati' before 'mrig'."},{"gurmukhi":"ਅਰਿ ਸਬਦ ਬਹੁਰਿ ਉਚਾਰ ਕੇ ਨਾਮ ਤੁਪਕ ਪਹਿਚਾਨੀਐ।","roman":"Ari sabad bahuri uchaar ke naam tupak pahichaaneeai |","meaning_en":"then say the word 'ari' (enemy), and recognise it as a name of the tupak (gun).","page":973,"meaning_status":"draft"},{"gurmukhi":"ਨਹੀ ਭੇਦ ਯਾ ਮੈ ਨੈਕੁ ਹੈ ਸਭ ਸੁ ਕਬਿ ਮਾਨਹੁ ਚਿਤ ਮੈ।","roman":"Nahee bhed yaa mai naiku hai sabh su kabi maanhu chit mai |","meaning_en":"There is not the least difference in this; good poets, all accept it in your minds;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਜਹ ਜਾਨੀਐ ਤਹ ਦੀਜੀਐ ਪਦ ਅਉਰ ਛੰਦ ਕਬਿਤ ਮੈ। ੭੩੬।","roman":"Jah jaaneeai tah deejeeai pad aur chhand kabit mai | 736 |","meaning_en":"wherever you see fit, put the word into other chhands and kabits (verses).","page":973,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":973,"meaning_status":"draft"},{"type":"verse","number":[737],"number_text":"੭੩੭।","page":973,"lines":[{"gurmukhi":"ਹਰਣ ਸਬਦ ਕੋ ਆਦਿ ਭਣਿਜੈ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਕੋ ਦਿਜੈ।","roman":"Haran sabad ko aadi bhanijai | taa paachhe pati pad ko dijai |","meaning_en":"Say the word 'haran' (deer) first, then put the word 'pati' (lord) after it;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਪਾਛੇ ਅਰਿ ਸਬਦ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੩੭।","roman":"Taa paachhe ari sabad uchaaro | naam tupak ke sakal bichaaro | 737 |","meaning_en":"after that say the word 'ari' (enemy); consider all these as names of the tupak (gun).","page":973,"meaning_status":"draft"}]},{"type":"verse","number":[738],"number_text":"੭੩੮।","page":973,"lines":[{"gurmukhi":"ਸਿੰਗੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਕਹੁ ਦੀਜੈ।","roman":"Singee aadi uchaaran keejai | taa paachhe pati pad kahu deejai |","meaning_en":"Say 'singi' (the horned one, deer) first, then put the word 'pati' (lord) after it;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੭੩੮।","roman":"Satroo sabad kahu bahuri bakhaano | naam tupak ke sakal pachhaano | 738 |","meaning_en":"then say the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":973,"meaning_status":"draft"}]},{"type":"verse","number":[739],"number_text":"੭੩੯।","page":973,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨਾਜਿਨ ਪਦ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਦੈ ਡਾਰੋ।","roman":"Krisnaajin pad aadi uchaaro | taa paachhe pati pad dai daaro |","meaning_en":"Say the word 'krisnajin' (black antelope) first, then put the word 'pati' (lord) after it;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਪਹਿਚਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਨ ਕੋਊ ਜਾਨੋ। ੭੩੯।","roman":"Naam tupak ke sabh pahichaano | yaa mai bhed na ko'oo jaano | 739 |","meaning_en":"recognise all these as names of the tupak (gun); know no difference in this.","page":973,"meaning_status":"draft","note":"Printed so: no word for 'enemy' is given in this verse."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":973,"meaning_status":"draft"},{"type":"verse","number":[740],"number_text":"੭੪੦।","page":973,"lines":[{"gurmukhi":"ਨੈਨੋਤਮ ਪਦ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Nainotam pad bakatr te prathmai karo uchaar |","meaning_en":"First speak out with your mouth the word 'nainotam' (with the finest eyes, the deer);","page":973,"meaning_status":"draft"},{"gurmukhi":"ਪਤਿ ਅਰਿ ਕਹਿ ਕਰ ਤੁਪਕ ਕੇ ਲੀਜੋ ਨਾਮ ਸੁ ਧਾਰ। ੭੪੦।","roman":"Pati ari kahi kar tupak ke leejo naam su dhaar | 740 |","meaning_en":"say 'pati' (lord) and 'ari' (enemy), and take these up with care as names of the tupak (gun).","page":973,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":973,"meaning_status":"draft"},{"type":"verse","number":[741],"number_text":"੭੪੧।","page":973,"lines":[{"gurmukhi":"ਸ੍ਵੈਤਾਸ੍ਵੈਤ ਤਨਿ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਪਤਿ ਸਬਦ ਸਵਾਰੋ।","roman":"Svaitaasvait tani aadi uchaaro | taa paachhe pati sabad savaaro |","meaning_en":"Say 'svetasvet tani' (with a white-and-black body, the antelope) first, then set the word 'pati' (lord) after it;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਉਚਾਰਨ ਕੀਜੈ। ਨਾਮ ਤੁਪਕ ਕੋ ਸਭ ਲਖਿ ਲੀਜੈ। ੭੪੧।","roman":"Ripu pad bahuri uchaaran keejai | naam tupak ko sabh lakhi leejai | 741 |","meaning_en":"then say the word 'ripu' (enemy); recognise all these as names of the tupak (gun).","page":973,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":973,"meaning_status":"draft"},{"type":"verse","number":[742],"number_text":"੭੪੨।","page":973,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Mrigee sabad ko aadi uchaaran keejeeai |","meaning_en":"Say the word 'mrigi' (doe) first;","page":973,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਪਾਛੇ ਨਾਇਕ ਸੁ ਸਬਦ ਕਹੁ ਦੀਜੀਐ।","roman":"Taa paachhe naaik su sabad kahu deejeeai |","meaning_en":"then put the word 'naik' (lord) after it.","page":973,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੀਐ।","roman":"Satroo sabad kahi naam tupak ke jaaneeai |","meaning_en":"Say the word 'satru' (enemy), and know these as names of the tupak (gun);","page":973,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਉਨ ਠਉਰ ਪਦ ਰੁਚੈ ਸੁ ਤਹੀ ਬਖਾਨੀਐ।੭੪੨।","roman":"Ho jaun thaur pad ruchai su tahee bakhaaneeai | 742 |","meaning_en":"say the word in whatever place it suits.","page":973,"meaning_status":"draft"}]},{"type":"verse","number":[743],"number_text":"੭੪੩।","page":974,"lines":[{"gurmukhi":"ਸੇਤ ਅਸਿਤ ਅਜਿਨਾ ਕੇ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Set asit ajinaa ke aadi uchaareeai |","meaning_en":"Say first 'set asit ajina' (with white-and-black skin, the antelope);","page":974,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਪਾਛੇ ਪਤਿ ਸਬਦ ਸੁ ਬਹੁਰਿ ਸੁਧਾਰੀਐ।","roman":"Taa paachhe pati sabad su bahuri sudhaareeai |","meaning_en":"then set the word 'pati' (lord) after it.","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satru sabad ko taa ke anti bakhaaneeai |","meaning_en":"Say the word 'satru' (enemy) at its end,","page":974,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਹੀਯ ਮੈ ਜਾਨੀਐ।੭੪੩।","roman":"Ho sakal tupak ke naam su heey mai jaaneeai | 743 |","meaning_en":"and know all these in your heart as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[744],"number_text":"੭੪੪।","page":974,"lines":[{"gurmukhi":"ਉਦਰ ਸੇਤ ਚਰਮਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Udar set charmaadi uchaaran keejeeai |","meaning_en":"Say first 'udar set charm' (with white-skinned belly, the antelope);","page":974,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਬਹੁਰਿ ਨਾਥ ਪਦ ਦੀਜੀਐ।","roman":"Taa ke paachhe bahuri naath pad deejeeai |","meaning_en":"then put the word 'nath' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਉਚਾਰੀਐ।","roman":"Taa ke paachhe ripu pad bahuri uchaareeai |","meaning_en":"after that say the word 'ripu' (enemy);","page":974,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਹੀ ਚਤੁਰ ਬਿਚਾਰੀਐ।੭੪੪।","roman":"Ho naam tupak ke sabh hee chatur bichaareeai | 744 |","meaning_en":"clever ones, consider all these as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":974,"meaning_status":"draft"},{"type":"verse","number":[745],"number_text":"੭੪੫।","page":974,"lines":[{"gurmukhi":"ਕਿਸਨ ਪਿਸਠ ਚਰਮਾਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Kisan pisath charmaadi uchaaro | taa paachhe naaik pad daaro |","meaning_en":"Say first 'kisan pisath charm' (with black-skinned back, the antelope), then put the word 'naik' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੭੪੫।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sakal pachhaano | 745 |","meaning_en":"then say the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[746],"number_text":"੭੪੬।","page":974,"lines":[{"gurmukhi":"ਚਾਰੁ ਨੇਤ੍ਰ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਪਤਿ ਸਬਦ ਬਿਚਾਰੋ।","roman":"Chaaru netr sabdaadi uchaaro | taa paachhe pati sabad bichaaro |","meaning_en":"Say the words 'charu netra' (fair-eyed, the deer) first, then bring in the word 'pati' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕਹੁ ਬਹੁਰੋ ਦੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲੀਜੈ। ੭੪੬।","roman":"Satru sabad kahu bahuro deejai | naam tuphang cheen chiti leejai | 746 |","meaning_en":"then add the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[747],"number_text":"੭੪੭।","page":974,"lines":[{"gurmukhi":"ਨੈਨੋਤਮ ਪਦ ਆਦਿ ਉਚਾਰੋ। ਨਾਇਕ ਪਦ ਪਾਛੇ ਦੇ ਡਾਰੋ।","roman":"Nainotam pad aadi uchaaro | naaik pad paachhe de daaro |","meaning_en":"Say the word 'nainotam' (with the finest eyes) first, then put the word 'naik' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ੭੪੭।","roman":"Satru sabad kahu bahuri bakhaano | naam tupak ke sabh jeea jaano | 747 |","meaning_en":"then say the word 'satru' (enemy); know all these in your heart as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[748],"number_text":"੭੪੮।","page":974,"lines":[{"gurmukhi":"ਦ੍ਰਿਗੀ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Drigee sabad ko aadi bakhaano | taa paachhe naaik pad thaano |","meaning_en":"Say the word 'drigi' (the eyed one, the deer) first, then place the word 'naik' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕਹੁ ਬਹੁਰੋ ਦੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲੀਜੈ। ੭੪੮।","roman":"Satru sabad kahu bahuro deejai | naam tuphang cheen chiti leejai | 748 |","meaning_en":"then add the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[749],"number_text":"੭੪੯।","page":974,"lines":[{"gurmukhi":"ਚਖੀ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਦੇ ਡਾਰੋ।","roman":"Chakhee sabad ko aadi uchaaro | taa paachhe pati pad de daaro |","meaning_en":"Say the word 'chakhi' (the eyed one, the deer) first, then put the word 'pati' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੭੪੯।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 749 |","meaning_en":"then say the word 'satru' (enemy); know all these as names of the revered tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[750],"number_text":"੭੫੦।","page":974,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਅਧਿਪ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਦੇ ਡਾਰੋ।","roman":"Mrigee adhip ko aadi uchaaro | taa paachhe pati pad de daaro |","meaning_en":"Say 'mrigi adhip' (lord of does) first, then put the word 'pati' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਪਹਿਚਾਨੋ। ੭੫੦।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sabh pahichaano | 750 |","meaning_en":"then say the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[751],"number_text":"੭੫੧।","page":974,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀਰਾਟ ਸਬਦਾਦਿ ਭਨਿਜੈ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਕਹੁ ਦਿਜੈ।","roman":"Mrigeeraat sabdaadi bhanijai | taa paachhe pati pad kahu dijai |","meaning_en":"First say the word 'mrigirat' (sovereign of does), then add the word 'pati' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਧਾਰੋ। ੭੫੧।","roman":"Satroo sabad ko anti uchaaro | naam tupak ke sabh jeea dhaaro | 751 |","meaning_en":"say the word 'satru' (enemy) at the end; hold all these in your heart as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[752],"number_text":"੭੫੨।","page":974,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਇੰਦ੍ਰ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Mrigee indr sabdaadi bakhaano | taa paachhe naaik pad thaano |","meaning_en":"Say the words 'mrigi indra' (lord of does) first, then place the word 'naik' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਪਾਛੇ ਰਿਪੁ ਸਬਦ ਭਨੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲੀਜੈ। ੭੫੨।","roman":"Taa paachhe ripu sabad bhaneejai | naam tuphang cheen chiti leejai | 752 |","meaning_en":"after that say the word 'ripu' (enemy); recognise in your mind these names of the tufang (musket).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[753],"number_text":"੭੫੩।","page":974,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਏਸਰ ਕੋ ਆਦਿ ਉਚਰੀਐ। ਤਾ ਪਾਛੇ ਪਤਿ ਪਦ ਦੇ ਡਰੀਐ।","roman":"Mrigee esar ko aadi uchreeai | taa paachhe pati pad de dareeai |","meaning_en":"Say 'mrigi esar' (lord of does) first, then put the word 'pati' (lord) after it;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਫੰਗ ਸਕਲ ਪਹਿਚਾਨੋ। ੭੫੩।","roman":"Satroo sabad ko anti bakhaano | naam tuphang sakal pahichaano | 753 |","meaning_en":"say the word 'satru' (enemy) at the end; recognise all these as names of the tufang (musket).","page":974,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":974,"meaning_status":"draft"},{"type":"verse","number":[754],"number_text":"੭੫੪।","page":974,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀਰਾਜ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Mrigeeraaj ko aadi uchaaran keejeeai |","meaning_en":"Say 'mrigiraj' (king of does) first;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਨਾਇਕ ਪਦ ਕਹਿ ਦੀਜੀਐ।","roman":"Taa ke paachhe naaik pad kahi deejeeai |","meaning_en":"then put the word 'naik' (lord) after it.","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਯੋ।","roman":"Satru sabad ko taa ke anti bakhaaneeyo |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੈ ਸਕਲ ਚਤੁਰ ਪਹਿਚਾਨੀਯੋ।੭੫੪।","roman":"Ho naam tupak kai sakal chatur pahichaaneeyo | 754 |","meaning_en":"clever ones, recognise all these as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[755],"number_text":"੭੫੫।","page":974,"lines":[{"gurmukhi":"ਮ੍ਰਿਗਿਜ ਸਬਦ ਕੋ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Mrigij sabad ko mukh te aadi bakhaaneeai |","meaning_en":"Say the word 'mrigij' with your mouth first;","page":974,"meaning_status":"draft","note":"ਮ੍ਰਿਗਿਜ: printed so; perhaps 'born of the doe' (fawn) or 'mrigi'; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਨਾਇਕ ਪਦ ਕੋ ਠਾਨੀਐ।","roman":"Taa ke paachhe naaik pad ko thaaneeai |","meaning_en":"then place the word 'naik' (lord) after it.","page":974,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":974,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਹੀ ਚਤੁਰ ਬਿਚਾਰੀਐ।੭੫੫।","roman":"Ho naam tupak ke sabh hee chatur bichaareeai | 755 |","meaning_en":"clever ones, consider all these as names of the tupak (gun).","page":974,"meaning_status":"draft"}]},{"type":"verse","number":[756],"number_text":"੭੫੬।","page":975,"lines":[{"gurmukhi":"ਮੁਖ ਤੇ ਪ੍ਰਥਮ ਮ੍ਰਿਗੀ ਸੁ ਸਬਦ ਕੋ ਭਾਖੀਐ।","roman":"Mukh te pratham mrigee su sabad ko bhaakheeai |","meaning_en":"First speak with your mouth the word 'mrigi' (doe);","page":975,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਨਾਇਕ ਪਦ ਕੋ ਰਾਖੀਐ।","roman":"Taa ke paachhe naaik pad ko raakheeai |","meaning_en":"then place the word 'naik' (lord) after it.","page":975,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਚਤੁਰ ਚਿਤਿ ਧਾਰੀਐ।੭੫੬।","roman":"Ho naam tupak ke sakal chatur chiti dhaareeai | 756 |","meaning_en":"clever ones, keep all these in mind as names of the tupak (gun).","page":975,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":975,"meaning_status":"draft"},{"type":"verse","number":[757],"number_text":"੭੫੭।","page":975,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਅਨੁਜ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Mrigee anuj ko aadi uchaaro | taa paachhe naaik pad daaro |","meaning_en":"Say 'mrigi anuj' first, then put the word 'naik' (lord) after it;","page":975,"meaning_status":"draft","note":"ਮ੍ਰਿਗੀ ਅਨੁਜ: literally 'younger brother of the doe'; reading uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਪ੍ਰਮਾਨਹੁ। ਨਾਮ ਤੁਫੰਗ ਸਕਲ ਜੀਅ ਜਾਨਹੁ। ੭੫੭।","roman":"Satroo sabad ko bahuri pramaanhu | naam tuphang sakal jeea jaanhu | 757 |","meaning_en":"then accept the word 'satru' (enemy); know all these in your heart as names of the tufang (musket).","page":975,"meaning_status":"draft"}]},{"type":"verse","number":[758],"number_text":"੭੫੮।","page":975,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਅਨੁਜ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੈ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Mrigee anuj ko aadi uchaaro | taa paachhai naaik pad daaro |","meaning_en":"Say 'mrigi anuj' first, then put the word 'naik' (lord) after it;","page":975,"meaning_status":"draft","note":"ਮ੍ਰਿਗੀ ਅਨੁਜ: literally 'younger brother of the doe'; reading uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਬਹੁਰੋ ਸੁ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੭੫੮।","roman":"Satroo sabad bahuro su bakhaano | sabh sree naam tupak ke jaano | 758 |","meaning_en":"then say the word 'satru' (enemy); know all these as names of the revered tupak (gun).","page":975,"meaning_status":"draft"}]},{"type":"verse","number":[759],"number_text":"੭੫੯।","page":975,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਅਨੁਜ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਨਾਇਕ ਪਦ ਪਾਛੈ ਦੇ ਡਾਰੋ।","roman":"Mrigee anuj sabdaadi uchaaro | naaik pad paachhai de daaro |","meaning_en":"Say the words 'mrigi anuj' first, then put the word 'naik' (lord) after it;","page":975,"meaning_status":"draft","note":"ਮ੍ਰਿਗੀ ਅਨੁਜ: literally 'younger brother of the doe'; reading uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰ ਬਖਾਨੋ। ਨਾਮ ਤੁਫੰਗ ਸਭੈ ਜੀਅ ਜਾਨੋ। ੭੫੯।","roman":"Satroo sabad ko bahur bakhaano | naam tuphang sabhai jeea jaano | 759 |","meaning_en":"then say the word 'satru' (enemy); know all these in your heart as names of the tufang (musket).","page":975,"meaning_status":"draft"}]},{"type":"verse","number":[760],"number_text":"੭੬੦।","page":975,"lines":[{"gurmukhi":"ਮ੍ਰਿਗੀ ਰਵਣ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Mrigee ravan sabdaadi bhanijai | taa paachhe naaik pad dijai |","meaning_en":"First say the words 'mrigi ravan' (consort of the doe), then add the word 'naik' (lord) after it;","page":975,"meaning_status":"draft","note":"ਰਵਣ: read as 'lover/consort'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੭੬੦।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 760 |","meaning_en":"then say the word 'satru' (enemy); know all these as names of the revered tupak (gun).","page":975,"meaning_status":"draft"}]},{"type":"verse","number":[761],"number_text":"੭੬੧।","page":975,"lines":[{"gurmukhi":"ਮ੍ਰਿਗਜਾਇਕ ਪਦ ਆਦਿ ਬਖਾਨੈ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਠਾਨੈ।","roman":"Mrigjaaik pad aadi bakhaanai | taa paachhe naaik pad thaanai |","meaning_en":"Say the word 'mrigjaik' first, then place the word 'naik' (lord) after it;","page":975,"meaning_status":"draft","note":"ਮ੍ਰਿਗਜਾਇਕ: printed so; reading unclear; unglossed; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਬੰਦੂਕ ਜਾਨ ਜੀਅ ਲਿਜੈ। ੭੬੧।","roman":"Satroo sabad ko bahuri bhanijai | naam bandook jaan jeea lijai | 761 |","meaning_en":"then say the word 'satru' (enemy); know it in your heart as a name of the banduk (gun).","page":975,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":975,"meaning_status":"draft"},{"type":"verse","number":[762],"number_text":"੭੬੨।","page":975,"lines":[{"gurmukhi":"ਆਦਿ ਮ੍ਰਿਗੀਜਾ ਉਚਰਿ ਕੈ ਪਤਿ ਰਿਪੁ ਅੰਤਿ ਉਚਾਰ।","roman":"Aadi mrigeejaa uchri kai pati ripu anti uchaar |","meaning_en":"First say 'mrigija' (born of the doe), then at the end say 'pati' (lord) and 'ripu' (enemy);","page":975,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੭੬੨।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 762 |","meaning_en":"these become names of the tupak (gun); good poets, take them up with care.","page":975,"meaning_status":"draft"}]},{"type":"verse","number":[763],"number_text":"੭੬੩।","page":975,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਚਰ ਆਦਿ ਉਚਾਰ ਕੈ ਪਤਿ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Trinchar aadi uchaar kai pati ari bahuri uchaar |","meaning_en":"First say 'trinchar' (grazer of grass), then say 'pati' (lord) and 'ari' (enemy) after it;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁਘਰ ਸਵਾਰ। ੭੬੩।","roman":"Naam tupak ke hot hai leejhu sughar savaar | 763 |","meaning_en":"these become names of the tupak (gun); skilful ones, take them and polish them.","page":975,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":975,"meaning_status":"draft"},{"type":"verse","number":[764],"number_text":"੭੬੪।","page":975,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਚਰ ਪਦ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Trinchar pad ko aadi uchaaran keejeeai |","meaning_en":"Say the word 'trinchar' (grazer of grass) first;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਨਾਥ ਸਬਦ ਕੋ ਤਾ ਕੈ ਪਾਛੈ ਦੀਜੀਐ।","roman":"Naath sabad ko taa kai paachhai deejeeai |","meaning_en":"then put the word 'nath' (lord) after it.","page":975,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮੁ ਸੁ ਚਤੁਰ ਪਛਾਨੀਐ। ੭੬੪।","roman":"Sakal tupak ke naamu su chatur pachhaaneeai | 764 |","meaning_en":"clever ones, recognise all these as names of the tupak (gun).","page":975,"meaning_status":"draft"}]},{"type":"verse","number":[765],"number_text":"੭੬੫।","page":975,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਭਖ ਪਦ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Trinbhakh pad ko aadi uchaaran keejeeai |","meaning_en":"Say the word 'trinbhakh' (grass-eater) first;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਨਾਇਕ ਪਦ ਕੋ ਤਾ ਕੇ ਪਾਛੇ ਦੀਜੀਐ।","roman":"Naaik pad ko taa ke paachhe deejeeai |","meaning_en":"then put the word 'naik' (lord) after it.","page":975,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੭੬੫।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 765 |","meaning_en":"skilled ones, consider all these as names of the tupak (gun).","page":975,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":975,"meaning_status":"draft"},{"type":"verse","number":[766],"number_text":"੭੬੬।","page":975,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਹਾ ਪਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਤਾ ਪਾਛੈ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Trinhaa pad ko aadi bakhaano | taa paachhai naaik pad thaano |","meaning_en":"Say the word 'trinha' (destroyer of grass) first, then place the word 'naik' (lord) after it;","page":975,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੬੬।","roman":"Satru sabad ko bahuri uchaaro | naam tupak ke sakal bichaaro | 766 |","meaning_en":"then say the word 'satru' (enemy); consider all these as names of the tupak (gun).","page":975,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":976,"meaning_status":"draft"},{"type":"verse","number":[767],"number_text":"੭੬੭।","page":976,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਹਾਤ੍ਰੀ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Trinhaatree ko aadi uchaaran keejeeai |","meaning_en":"Say 'trinhatri' (destroyer of grass) first;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Taa ke paachhe naath sabad ko deejeeai |","meaning_en":"then put the word 'nath' (lord) after it.","page":976,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Taa ke paachhe satroo sabad ko thaaneeai |","meaning_en":"After that place the word 'satru' (enemy);","page":976,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੋ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਜਾਨੀਐ।੭੬੭।","roman":"Ho sakal tupak ko naam chatur chiti jaaneeai | 767 |","meaning_en":"clever ones, know in your mind all these as names of the tupak (gun).","page":976,"meaning_status":"draft"}]},{"type":"verse","number":[768],"number_text":"੭੬੮।","page":976,"lines":[{"gurmukhi":"ਤ੍ਰਿਣ ਭਛੀ ਕੋ ਆਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Trin bhachhee ko aadi bakhaanan keejeeai |","meaning_en":"Say 'trin bhachhi' (grass-eater) first;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਨਾਇਕ ਪਦ ਕੋ ਤਾ ਕੇ ਪਾਛੇ ਦੀਜੀਐ।","roman":"Naaik pad ko taa ke paachhe deejeeai |","meaning_en":"then put the word 'naik' (lord) after it.","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਕਹੀਓ ਬਹੁਰਿ ਸੁਧਾਰਿ ਕੈ।","roman":"Satroo sabad ko kaheeo bahuri sudhaari kai |","meaning_en":"Then say the word 'satru' (enemy) with care,","page":976,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਲੀਜਹੁ ਸਕਲ ਬਿਚਾਰ ਕੈ।੭੬੮।","roman":"Ho naam tupak ke leejhu sakal bichaar kai | 768 |","meaning_en":"and take all these as names of the tupak (gun), with thought.","page":976,"meaning_status":"draft"}]},{"type":"verse","number":[769],"number_text":"੭੬੯।","page":976,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਹਾ ਰਿਪੁ ਕੋ ਆਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Trinhaa ripu ko aadi bakhaanan keejeeai |","meaning_en":"Say 'trinha ripu' (enemy of the grass-destroyer) first;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਨਾਥ ਸਬਦ ਕੋ ਤਾ ਕੇ ਪਾਛੈ ਦੀਜੀਐ।","roman":"Naath sabad ko taa ke paachhai deejeeai |","meaning_en":"then put the word 'nath' (lord) after it.","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਚਤੁਰ ਪਹਿਚਾਨੀਐ।੭੬੯।","roman":"Ho naam tupak ke sakal chatur pahichaaneeai | 769 |","meaning_en":"clever ones, recognise all these as names of the tupak (gun).","page":976,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":976,"meaning_status":"draft"},{"type":"verse","number":[770],"number_text":"੭੭੦।","page":976,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਰਿਪੁ ਆਦਿ ਉਚਾਰਿ ਕੈ ਪਤਿ ਰਿਪੁ ਅੰਤਿ ਉਚਾਰ।","roman":"Trinripu aadi uchaari kai pati ripu anti uchaar |","meaning_en":"First say 'trinripu' (enemy of grass), then at the end say 'pati' (lord) and 'ripu' (enemy);","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਨਾਮ ਤੁਫੰਗ ਕੇ ਲੀਜਹੁ ਸੁਘਰ ਸੁਧਾਰ। ੭੭੦।","roman":"Sabh hee naam tuphang ke leejhu sughar sudhaar | 770 |","meaning_en":"skilful ones, take all these up with care as names of the tufang (musket).","page":976,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":976,"meaning_status":"draft"},{"type":"verse","number":[771],"number_text":"੭੭੧।","page":976,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਰਿਪੁ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Trinripu aadi uchaaran keejai | taa paachhe naaik pad deejai |","meaning_en":"Say 'trinripu' (enemy of grass) first, then put the word 'naik' (lord) after it;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੭੧।","roman":"Satroo sabad ko bahuri uchaaro | naam tupak ke sakal bichaaro | 771 |","meaning_en":"then say the word 'satru' (enemy); consider all these as names of the tupak (gun).","page":976,"meaning_status":"draft"}]},{"type":"verse","number":[772],"number_text":"੭੭੨।","page":976,"lines":[{"gurmukhi":"ਭੂਜਾਂਤਕ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਨਾਇਕ ਤਾ ਪਾਛੇ ਪਦ ਡਾਰੋ।","roman":"Bhoojaantak sabdaadi uchaaro | naaik taa paachhe pad daaro |","meaning_en":"Say the word 'bhujantak' first, then put the word 'naik' (lord) after it;","page":976,"meaning_status":"draft","note":"ਭੂਜਾਂਤਕ: read as bhuj (earth-born, grass/plant) + antak (destroyer); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੭੭੨।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang cheen chiti lijai | 772 |","meaning_en":"then say the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":976,"meaning_status":"draft"}]},{"type":"verse","number":[773],"number_text":"੭੭੩।","page":976,"lines":[{"gurmukhi":"ਪ੍ਰਿਥੀਜ ਅਰਿ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਤਾ ਪਾਛੇ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Pritheej ari sabdaadi uchaaro | taa paachhe naaik pad daaro |","meaning_en":"Say the words 'prithij ari' (enemy of the earth-born) first, then put the word 'naik' (lord) after it;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਪਹਿਚਾਨੋ। ੭੭੩।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sabh pahichaano | 773 |","meaning_en":"then say the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":976,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":976,"meaning_status":"draft"},{"type":"verse","number":[774],"number_text":"੭੭੪।","page":976,"lines":[{"gurmukhi":"ਭੂ ਸੁਤ ਰਿਪੁ ਸਬਦਾਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Bhoo sut ripu sabdaadi bakhaanan keejeeai |","meaning_en":"Say the words 'bhu sut ripu' (enemy of the earth's offspring) first;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਬਹੁਰਿ ਨਾਥ ਪਦ ਦੀਜੀਐ।","roman":"Taa ke paachhe bahuri naath pad deejeeai |","meaning_en":"then put the word 'nath' (lord) after it.","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੭੭੪।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 774 |","meaning_en":"skilled ones, consider all these as names of the tupak (gun).","page":976,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":976,"meaning_status":"draft"},{"type":"verse","number":[775],"number_text":"੭੭੫।","page":976,"lines":[{"gurmukhi":"ਉਰਵਿਜ ਸਬਦ ਸੁ ਆਦਿ ਉਚਾਰੋ। ਰਿਪੁ ਨਾਇਕ ਪਾਛੇ ਪਦ ਡਾਰੋ।","roman":"Urvij sabad su aadi uchaaro | ripu naaik paachhe pad daaro |","meaning_en":"Say the word 'urvij' (born of the earth) first, then put the words 'ripu' (enemy) and 'naik' (lord) after it;","page":976,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੭੭੫।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang cheen chiti lijai | 775 |","meaning_en":"then say the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":976,"meaning_status":"draft"}]},{"type":"verse","number":[776],"number_text":"੭੭੬।","page":977,"lines":[{"gurmukhi":"ਬੈਸੁੰਧਰਜਾ ਸਤ੍ਰੂ ਉਚਾਰੋ। ਨਇਕ ਸਬਦ ਅੰਤਿ ਦੇ ਡਾਰੋ।","roman":"Baisundharjaa satroo uchaaro | naik sabad anti de daaro |","meaning_en":"Say 'baisundharaja' (born of the earth) and 'satru' (enemy), and put the word 'naik' (lord) at the end;","page":977,"meaning_status":"draft","note":"ਨਇਕ: printed so; read as naik."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਨਾਮ ਬੰਦੂਕ ਚਿਤ ਮੈ ਧਰੀਐ। ੭੭੬।","roman":"Satroo sabad ko bahuri uchreeai | naam bandook chit mai dhareeai | 776 |","meaning_en":"then say the word 'satru' (enemy); keep in mind these names of the banduk (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[777],"number_text":"੭੭੭।","page":977,"lines":[{"gurmukhi":"ਧੂਰਿਨ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਜਾ ਰਿਪੁ ਪਦ ਕੋ ਪਾਛੈ ਦੀਜੈ।","roman":"Dhoorin aadi uchaaran keejai | jaa ripu pad ko paachhai deejai |","meaning_en":"Say 'dhurin' (of the dust, the earth) first, and put the words 'ja' (born) and 'ripu' (enemy) after it;","page":977,"meaning_status":"draft","note":"ਧੂਰਿਨ: read as 'earth'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੭੭੭।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sakal pachhaano | 777 |","meaning_en":"then say the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[778],"number_text":"੭੭੮।","page":977,"lines":[{"gurmukhi":"ਦ੍ਵੀਪਨਿ ਆਦਿ ਸਬਦ ਕੋ ਦਿਜੈ। ਜਾ ਪਾਛੇ ਚਰ ਸਬਦ ਭਨਿਜੈ।","roman":"Dveepni aadi sabad ko dijai | jaa paachhe char sabad bhanijai |","meaning_en":"Give the word 'dvipani' (the earth with its islands) first; then say 'ja' (born) and after it the word 'char' (mover);","page":977,"meaning_status":"draft","note":"ਜਾ: read as the word 'ja' (born); it could also be 'after which'. ਚਰ: 'one that moves/grazes'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਸਵਾਰੋ। ੭੭੮।","roman":"Satroo sabad ko bahuri uchaaro | naam tupak ke sakal savaaro | 778 |","meaning_en":"then say the word 'satru' (enemy); so fashion all the names of the tupak (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[779],"number_text":"੭੭੯।","page":977,"lines":[{"gurmukhi":"ਸਿਸਟਨਿ ਪਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਕਹਿ ਚਰ ਪਾਛੇ ਦੇ ਡਾਰੋ।","roman":"Sisatni pad ko aadi uchaaro | jaa kahi char paachhe de daaro |","meaning_en":"Say the word 'sisatani' first; say 'ja' (born) and put 'char' (mover) after it;","page":977,"meaning_status":"draft","note":"ਸਿਸਟਨਿ: perhaps 'the created world, earth' (srishti); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤ ਲਿਜੈ। ੭੭੯।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang cheen chit lijai | 779 |","meaning_en":"then say the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[780],"number_text":"੭੮੦।","page":977,"lines":[{"gurmukhi":"ਧਰਨਿ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਪਦ ਪਾਛੇ ਤਿਹਿ ਡਾਰੋ।","roman":"Dharni sabad ko aadi uchaaro | jaa char pad paachhe tihi daaro |","meaning_en":"Say the word 'dharani' (earth) first, and put the words 'ja' (born) and 'char' (mover) after it;","page":977,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੭੮੦।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 780 |","meaning_en":"then say the word 'satru' (enemy); know all these as names of the revered tupak (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[781],"number_text":"੭੮੧।","page":977,"lines":[{"gurmukhi":"ਧਰਾ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਪਦ ਪਾਛੇ ਤਿਹ ਠਾਨੋ।","roman":"Dharaa sabad ko aadi bakhaano | jaa char pad paachhe tih thaano |","meaning_en":"Say the word 'dhara' (earth) first, and place the words 'ja' (born) and 'char' (mover) after it;","page":977,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਫੰਗ ਸਕਲ ਚਿਤਿ ਧਾਰੋ। ੭੮੧।","roman":"Satroo sabad ko bahuri uchaaro | naam tuphang sakal chiti dhaaro | 781 |","meaning_en":"then say the word 'satru' (enemy); hold all these in mind as names of the tufang (musket).","page":977,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":977,"meaning_status":"draft"},{"type":"verse","number":[782],"number_text":"੭੮੨।","page":977,"lines":[{"gurmukhi":"ਭੂਮਿਜ ਆਦਿ ਉਚਾਰਿ ਕੈ ਚਰ ਪਦ ਬਹੁਰਿ ਉਚਾਰਿ।","roman":"Bhoomij aadi uchaari kai char pad bahuri uchaari |","meaning_en":"First say 'bhumij' (born of the earth), then say the word 'char' (mover);","page":977,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨਾਮ ਤੁਫੰਗ ਕੇ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੭੮੨।","roman":"Ripu kahi naam tuphang ke leejhu su kabi su dhaar | 782 |","meaning_en":"say 'ripu' (enemy), and good poets, take these up with care as names of the tufang (musket).","page":977,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":977,"meaning_status":"draft"},{"type":"verse","number":[783],"number_text":"੭੮੩।","page":977,"lines":[{"gurmukhi":"ਦ੍ਰੂਮਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Droomnee aadi uchaaran keejai | jaa char kahi naaik pad deejai |","meaning_en":"Say 'drumani' (the earth with trees) first; say 'ja' (born) and 'char' (mover), and then add the word 'naik' (lord);","page":977,"meaning_status":"draft","note":"ਦ੍ਰੂਮਨੀ: read as 'having trees', i.e. the earth; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਪਹਿਚਾਨੋ। ੭੮੩।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sabh pahichaano | 783 |","meaning_en":"then say the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[784],"number_text":"੭੮੪।","page":977,"lines":[{"gurmukhi":"ਬ੍ਰਿਛਨਿਜ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਚਰਨਾਇਕ ਪਾਛੇ ਪਦ ਦੀਜੈ।","roman":"Brichhnij aadi uchaaran keejai | charnaaik paachhe pad deejai |","meaning_en":"Say 'brichhanij' first, then add the words 'char' (mover) and 'naik' (lord) after it;","page":977,"meaning_status":"draft","note":"ਬ੍ਰਿਛਨਿਜ: read as 'born of the tree-filled (earth)'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੭੮੪।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang cheen chiti lijai | 784 |","meaning_en":"then say the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[785],"number_text":"੭੮੫।","page":977,"lines":[{"gurmukhi":"ਧਰਏਸਰਣੀ ਆਦਿ ਬਖਾਨੋ। ਤਾ ਪਾਛੇ ਜਾ ਚਰ ਪਦ ਠਾਨੋ।","roman":"Dharaesarnee aadi bakhaano | taa paachhe jaa char pad thaano |","meaning_en":"Say 'dharesarani' first, then place the words 'ja' (born) and 'char' (mover) after it;","page":977,"meaning_status":"draft","note":"ਧਰਏਸਰਣੀ: read as 'the earth, with its lords'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੭੮੫।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 785 |","meaning_en":"then say the word 'satru' (enemy); know all these as names of the revered tupak (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[786],"number_text":"੭੮੬।","page":977,"lines":[{"gurmukhi":"ਧਰਾਰਾਟਨੀ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਨਾਇਕ ਚਰ ਸਬਦ ਬਿਚਾਰੋ।","roman":"Dharaaraatnee aadi uchaaro | jaa naaik char sabad bichaaro |","meaning_en":"Say 'dhararatani' first, then bring in the words 'ja', 'naik' and 'char';","page":977,"meaning_status":"draft","note":"Printed so, in the order ja, naik, char; ਧਰਾਰਾਟਨੀ read as 'the earth, with its sovereigns'; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਮਾਨੋ। ੭੮੬।","roman":"Sabh sree naam tupak ke jaano | yaa mai kachhoo bhed nahee maano | 786 |","meaning_en":"know all these as names of the revered tupak (gun); hold that there is no difference in this.","page":977,"meaning_status":"draft","note":"Printed so: no word for 'enemy' is given in this verse."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":977,"meaning_status":"draft"},{"type":"verse","number":[787],"number_text":"੭੮੭।","page":977,"lines":[{"gurmukhi":"ਬਾਰਿਧਨੀ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Baaridhnee sabdaadi uchaaran keejeeai |","meaning_en":"Say the word 'baridhani' (the earth with its oceans) first;","page":977,"meaning_status":"draft","note":"ਬਾਰਿਧਨੀ: read as 'having oceans', i.e. the earth; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਨਾਇਕ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦੀਜੀਐ।","roman":"Jaa char naaik sabad anti tih deejeeai |","meaning_en":"then put the words 'ja', 'char' and 'naik' at its end.","page":977,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke ant uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":977,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਧਾਰੀਐ।੭੮੭।","roman":"Ho sakal tupak ke naam chatur chiti dhaareeai | 787 |","meaning_en":"clever ones, keep all these in mind as names of the tupak (gun).","page":977,"meaning_status":"draft"}]},{"type":"verse","number":[788],"number_text":"੭੮੮।","page":978,"lines":[{"gurmukhi":"ਸਾਮੁਦ੍ਰਨਿ ਸਬਦਾਦਿ ਉਚਾਰੋ ਜਾਨਿ ਕੈ।","roman":"Saamudrani sabdaadi uchaaro jaani kai |","meaning_en":"Knowingly say the word 'samudrani' (the sea-girt earth) first;","page":978,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਪਦ ਤਾ ਕੇ ਪੁਨਿ ਪਾਛੇ ਠਾਨਿ ਕੈ।","roman":"Jaa char pad taa ke puni paachhe thaani kai |","meaning_en":"then place the words 'ja' (born) and 'char' (mover) after it.","page":978,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":978,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੭੮੮।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 788 |","meaning_en":"skilled ones, consider all these as names of the tupak (gun).","page":978,"meaning_status":"draft"}]},{"type":"verse","number":[789],"number_text":"੭੮੯।","page":978,"lines":[{"gurmukhi":"ਨੀਰਰਾਸਿ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Neerraasi ko aadi uchaaran keejeeai |","meaning_en":"Say 'nirrasi' (the mass of waters, ocean) first;","page":978,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਨਾਇਕ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦੀਜੀਐ।","roman":"Jaa char naaik sabad anti tih deejeeai |","meaning_en":"then put the words 'ja', 'char' and 'naik' at its end.","page":978,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੋ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ko anti bakhaaneeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":978,"meaning_status":"draft","note":"ਤਾ ਕੋ: printed so; read as ਤਾ ਕੇ."},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸਾਚ ਪਹਿਚਾਨੀਐ।੭੮੯।","roman":"Ho sakal tupak ke naam saach pahichaaneeai | 789 |","meaning_en":"recognise all these truly as names of the tupak (gun).","page":978,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":978,"meaning_status":"draft"},{"type":"verse","number":[790],"number_text":"੭੯੦।","page":978,"lines":[{"gurmukhi":"ਨੀਰਾਲਯਨੀ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਨਾਇਕ ਬਹੁਰਿ ਬਿਚਾਰੋ।","roman":"Neeraalaynee aadi uchaaro | jaa char naaik bahuri bichaaro |","meaning_en":"Say 'niralayani' (the earth, abode of waters) first, then bring in the words 'ja', 'char' and 'naik';","page":978,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਦੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲੀਜੈ। ੭੯੦।","roman":"Taa ke anti satroo pad deejai | naam tuphang cheen chiti leejai | 790 |","meaning_en":"put the word 'satru' (enemy) at its end; recognise in your mind these names of the tufang (musket).","page":978,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":978,"meaning_status":"draft"},{"type":"verse","number":[791],"number_text":"੭੯੧।","page":978,"lines":[{"gurmukhi":"ਨੀਰਧਨੀ ਸਬਦਾਦਿ ਉਚਾਰੋ ਜਾਨਿ ਕੈ।","roman":"Neeradhnee sabdaadi uchaaro jaani kai |","meaning_en":"Knowingly say the word 'nirdhani' (the earth with its waters) first;","page":978,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਨਾਇਕ ਪਦ ਕੋ ਪਾਛੇ ਠਾਨਿ ਕੈ।","roman":"Jaa char naaik pad ko paachhe thaani kai |","meaning_en":"then place the words 'ja', 'char' and 'naik' after it.","page":978,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satru sabad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":978,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੭੯੧।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 791 |","meaning_en":"skilled ones, consider all these as names of the tupak (gun).","page":978,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":978,"meaning_status":"draft"},{"type":"verse","number":[792],"number_text":"੭੯੨।","page":978,"lines":[{"gurmukhi":"ਬਾਰਾਲਯਣੀ ਆਦਿ ਕਹਿ ਜਾ ਚਰ ਪਤਿ ਪਦ ਦੇਹੁ।","roman":"Baaraalaynee aadi kahi jaa char pati pad dehu |","meaning_en":"First say 'baralayani' (the earth, abode of waters), then add the words 'ja', 'char' and 'pati' (lord);","page":978,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਪੁਨਿ ਭਾਖੀਐ ਨਾਮ ਤੁਪਕ ਲਖਿ ਲੇਹੁ। ੭੯੨।","roman":"Satroo sabad puni bhaakheeai naam tupak lakhi lehu | 792 |","meaning_en":"then say the word 'satru' (enemy), and recognise these as names of the tupak (gun).","page":978,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":978,"meaning_status":"draft"},{"type":"verse","number":[793],"number_text":"੭੯੩।","page":978,"lines":[{"gurmukhi":"ਜਲ ਰਾਸਨਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Jal raasannee aadi uchaaran keejeeai |","meaning_en":"Say 'jal rasanani' (the earth with its masses of water) first;","page":978,"meaning_status":"draft","note":"ਜਲ ਰਾਸਨਨੀ: printed so; read as from jal-rasi (ocean); uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਨਾਇਕ ਪਦ ਤਿਹ ਪਾਛੇ ਦੀਜੀਐ।","roman":"Jaa char naaik pad tih paachhe deejeeai |","meaning_en":"then put the words 'ja', 'char' and 'naik' after it.","page":978,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਪਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satru pad ko taa ke anti uchaareeai |","meaning_en":"Say the word 'satru' (enemy) at its end;","page":978,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਕਬਿ ਬਿਚਾਰੀਐ। ੭੯੩।","roman":"Ho sakal tupak ke naam su kabi bichaareeai | 793 |","meaning_en":"good poets, consider all these as names of the tupak (gun).","page":978,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":978,"meaning_status":"draft"},{"type":"verse","number":[794],"number_text":"੭੯੪।","page":978,"lines":[{"gurmukhi":"ਕੰਨਿਧਨੀ ਸਬਦਾਦਿ ਭਣਿਜੇ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੇ।","roman":"Kannidhnee sabdaadi bhanije | jaa char kahi naaik pad dije |","meaning_en":"First say the word 'kannidhani'; say 'ja' (born) and 'char' (mover), and then add the word 'naik' (lord);","page":978,"meaning_status":"draft","note":"ਕੰਨਿਧਨੀ: printed so; perhaps 'having the ocean' (kan-nidhi, 'store of waters'); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੯੪।","roman":"Satroo sabad ko anti uchaaro | naam tupak ke sakal bichaaro | 794 |","meaning_en":"say the word 'satru' (enemy) at the end; consider all these as names of the tupak (gun).","page":978,"meaning_status":"draft"}]},{"type":"verse","number":[795],"number_text":"੭੯੫।","page":978,"lines":[{"gurmukhi":"ਅੰਬੁਜਨੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Anbujnee sabdaadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"Say the word 'ambujani' (the earth with lotus-waters) first; say 'ja' (born) and 'char' (mover), and then place the word 'naik' (lord);","page":978,"meaning_status":"draft","note":"ਅੰਬੁਜਨੀ: read as 'having lotuses/waters'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੭੯੫।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang cheen chiti lijai | 795 |","meaning_en":"then say the word 'satru' (enemy); recognise in your mind these names of the tufang (musket).","page":978,"meaning_status":"draft"}]},{"type":"verse","number":[796],"number_text":"੭੯੬।","page":979,"lines":[{"gurmukhi":"ਜਲਨੀ ਆਦਿ ਬਖਾਨਨ ਕੀਜੈ। ਜਾ ਚਰ ਪਤਿ ਪਾਛੈ ਪਦ ਦੀਜੈ।","roman":"Jalnee aadi bakhaanan keejai | jaa char pati paachhai pad deejai |","meaning_en":"Say 'jalani' (the earth with waters) first, then add the words 'ja', 'char' and 'pati' (lord) after it;","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੭੯੬।","roman":"Satroo sabad ko anti bakhaano | naam tupak ke sakal pachhaano | 796 |","meaning_en":"say the word 'satru' (enemy) at the end; recognise all these as names of the tupak (gun).","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[797],"number_text":"੭੯੭।","page":979,"lines":[{"gurmukhi":"ਪਾਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਜਾ ਚਰ ਪਤਿ ਸਬਦਾਂਤਿ ਭਣੀਜੈ।","roman":"Paanini aadi uchaaran keejai | jaa char pati sabdaanti bhaneejai |","meaning_en":"Say 'panini' (the earth with waters) first, and say 'ja', 'char', with the word 'pati' (lord) at the end;","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੭੯੭।","roman":"Satroo sabad ko bahuri uchaaro | naam tupak ke sakal bichaaro | 797 |","meaning_en":"then say the word 'satru' (enemy); consider all these as names of the tupak (gun).","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[798],"number_text":"੭੯੮।","page":979,"lines":[{"gurmukhi":"ਅੰਬੁਜਨੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਪਤਿ ਸਬਦਾਂਤਿ ਕਹਿਜੈ।","roman":"Anbujnee sabdaadi bhanijai | jaa char pati sabdaanti kahijai |","meaning_en":"First say the word 'ambujani' (the earth with lotus-waters), and say 'ja', 'char', with the word 'pati' (lord) at the end;","page":979,"meaning_status":"draft","note":"ਅੰਬੁਜਨੀ: read as 'having lotuses/waters'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਬਹੁਰੋ ਤੁਮ ਠਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਪਹਿਚਾਨੋ। ੭੯੮।","roman":"Satroo sabad bahuro tum thaano | naam tupak ke sabh pahichaano | 798 |","meaning_en":"then place the word 'satru' (enemy); recognise all these as names of the tupak (gun).","page":979,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":979,"meaning_status":"draft"},{"type":"verse","number":[799],"number_text":"੭੯੯।","page":979,"lines":[{"gurmukhi":"ਬਾਰਿਨਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਜਾ ਚਰ ਧਰ ਪਦ ਦੇਹੁ।","roman":"Baarini aadi uchaari kai jaa char dhar pad dehu |","meaning_en":"First say 'barini' (the earth with waters), then add the words 'ja', 'char' and 'dhar' (holder);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਉਚਾਰੁ ਤੁਫੰਗ ਕੇ ਨਾਮ ਚਤੁਰ ਲਖਿ ਲੇਹੁ। ੭੯੯।","roman":"Satroo uchaaru tuphang ke naam chatur lakhi lehu | 799 |","meaning_en":"say 'satru' (enemy); clever ones, recognise these as names of the tufang (musket).","page":979,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":979,"meaning_status":"draft"},{"type":"verse","number":[800],"number_text":"੮੦੦।","page":979,"lines":[{"gurmukhi":"ਬਾਰਿਜਨੀ ਸਬਦਾਦਿ ਉਚਾਰੋ ਜਾਨਿ ਕੈ।","roman":"Baarijnee sabdaadi uchaaro jaani kai |","meaning_en":"Knowingly say first the word 'Barijani' (barij, 'water-born', with -ni);","page":979,"meaning_status":"draft","note":"ਬਾਰਿਜਨੀ: barij = water-born (lotus or cloud); the referent of the compound is not stated; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਪਤਿ ਪਦ ਕੋ ਤਿਹ ਪਾਛੇ ਠਾਨਿ ਕੈ।","roman":"Jaa char pati pad ko tih paachhe thaani kai |","meaning_en":"then put 'ja char' and the word 'pati' (lord) after it;","page":979,"meaning_status":"draft","note":"'ja char': lit. 'born of it, moving', i.e. the creatures that live in what was just named; the riddle then goes to their lord (king) and his enemy (the gun); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰਿ ਕੈ।","roman":"Satroo sabad ko taa ke anti uchaari kai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":979,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਲੇਹੁ ਬਿਚਾਰਿ ਕੈ। ੮੦੦।","roman":"Ho sakal tupak ke naam su lehu bichaari kai | 800 |","meaning_en":"regard all these as names of the gun (tupak).","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[801],"number_text":"੮੦੧।","page":979,"lines":[{"gurmukhi":"ਜਲਨਿਧਨੀ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Jalnidhnee sabdaadi uchaaran keejeeai |","meaning_en":"First say the word 'Jalnidhani' (jalnidhi, 'ocean', with -ni);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰੋ ਦੀਜੀਐ।","roman":"Jaa char kahi naaik pad bahuro deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":979,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੮੦੧।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 801 |","meaning_en":"O skilled one, regard all these as names of the gun (tupak).","page":979,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":979,"meaning_status":"draft"},{"type":"verse","number":[802],"number_text":"੮੦੨।","page":979,"lines":[{"gurmukhi":"ਮੇਘਜਨੀ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Meghajnee sabdaadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say the word 'Meghjani' ('born of clouds', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਜਾਨ ਜੀਅ ਲੀਜੈ। ੮੦੨।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang jaan jeea leejai | 802 |","meaning_en":"then say the word 'shatru' (enemy); know these as names of the gun (tufang) in your heart.","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[803],"number_text":"੮੦੩।","page":979,"lines":[{"gurmukhi":"ਅੰਬੁਦਨੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Anbudnee sabdaadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say the word 'Ambudani' (ambud, 'cloud', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੮੦੩।","roman":"Satroo sabad ko bahuri uchaaro | naam tupak ke sakal bichaaro | 803 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[804],"number_text":"੮੦੪।","page":979,"lines":[{"gurmukhi":"ਹਰਿਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Harinee aadi uchaaran keejai | jaa char kahi naaik pad deejai |","meaning_en":"First say 'Harini' (hari, here probably 'water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":979,"meaning_status":"draft","note":"ਹਰਿਨੀ: hari read here as 'water'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੮੦੪।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sakal pachhaano | 804 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[805],"number_text":"੮੦੫।","page":979,"lines":[{"gurmukhi":"ਬਾਰਿਦਨੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Baaridnee sabdaadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say the word 'Baridani' (barid, 'cloud', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਸਭ ਹੀਏ ਬਿਚਾਰਹੁ। ੮੦੫।","roman":"Satroo sabad ko bahuri uchaarhu | naam tupak sabh hee'e bichaarhu | 805 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak) in your heart.","page":979,"meaning_status":"draft"}]},{"type":"verse","number":[806],"number_text":"੮੦੬।","page":979,"lines":[{"gurmukhi":"ਨਦਿਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Nadinee aadi uchaaran keejai | jaa char kahi naaik pad deejai |","meaning_en":"First say 'Nadini' (nad, 'river', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":979,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ੮੦੬।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sabh jeea jaano | 806 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak) in your heart.","page":979,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":980,"meaning_status":"draft"},{"type":"verse","number":[807],"number_text":"੮੦੭।","page":980,"lines":[{"gurmukhi":"ਨਯਨੀ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Naynee sabad su mukh te aadi uchaareeai |","meaning_en":"First say aloud the word 'Nayani';","page":980,"meaning_status":"draft","note":"ਨਯਨੀ: probably from nai/nadi, 'river'; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਪੁਨਿ ਦੇ ਡਾਰੀਐ।","roman":"Jaa char kahi naaik pad puni de daareeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੈ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa kai anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਜਾਨੀਐ।੮੦੭।","roman":"Ho sakal tupak ke naam chatur chiti jaaneeai | 807 |","meaning_en":"O clever one, know all these as names of the gun (tupak) in your heart.","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[808],"number_text":"੮੦੮।","page":980,"lines":[{"gurmukhi":"ਸਰਤਨਿ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Saratni sabad su mukh te aadi bakhaaneeai |","meaning_en":"First say aloud the word 'Saratani' (sarit, 'river', with -ni);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਪਾਛੇ ਠਾਨੀਐ।","roman":"Jaa char kahi naaik pad paachhe thaaneeai |","meaning_en":"then put 'ja char' and the word 'nayak' (lord) after it;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੮੦੮।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 808 |","meaning_en":"O skilled one, regard all these as names of the gun (tupak).","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[809],"number_text":"੮੦੯।","page":980,"lines":[{"gurmukhi":"ਨਾਦਿਨਿ ਮੁਖ ਤੇ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Naadini mukh te sabad uchaaran keejeeai |","meaning_en":"Say aloud the word 'Nadini' (nad, 'river' or 'roaring', with -ni);","page":980,"meaning_status":"draft","note":"ਨਾਦਿਨਿ: 'river' or 'the roaring one'; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰੋ ਦੀਜੀਐ।","roman":"Jaa char kahi naaik pad bahuro deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੋ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਜਾਨੀਐ।੮੦੯।","roman":"Ho sakal tupak ko naam chatur chiti jaaneeai | 809 |","meaning_en":"O clever one, know all these as names of the gun (tupak) in your heart.","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[810],"number_text":"੮੧੦।","page":980,"lines":[{"gurmukhi":"ਜਲਨੀ ਮੁਖ ਤੇ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Jalnee mukh te aadi uchaaran keejeeai |","meaning_en":"First say aloud 'Jalani' (jal, 'water', with -ni);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਪਾਛੇ ਦੀਜੀਐ।","roman":"Jaa char kahi naaik pad paachhe deejeeai |","meaning_en":"then put 'ja char' and the word 'nayak' (lord) after it;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ।੮੧੦।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 810 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[811],"number_text":"੮੧੧।","page":980,"lines":[{"gurmukhi":"ਆਦਿ ਤਰੰਗਨਿ ਸਬਦ ਉਚਾਰੋ ਜਾਨਿ ਕੈ।","roman":"Aadi tarangni sabad uchaaro jaani kai |","meaning_en":"Knowingly say first the word 'Tarangani' ('full of waves', a river);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰੋ ਠਾਨਿ ਕੈ।","roman":"Jaa char kahi naaik pad bahuro thaani kai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke ant uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ। ੮੧੧।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 811 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[812],"number_text":"੮੧੨।","page":980,"lines":[{"gurmukhi":"ਆਦਿ ਕਰਾਰਨਿ ਸਬਦ ਉਚਾਰੋ ਬਕਤ੍ਰ ਤੇ।","roman":"Aadi karaarni sabad uchaaro bakatr te |","meaning_en":"First say aloud the word 'Kararani' (karar, 'river bank', with -ni);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਉਚਰੋ ਚਿਤ ਤੇ।","roman":"Jaa char kahi naaik pad uchro chit te |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਖਾਨੀਐ।੮੧੨।","roman":"Ho sakal tupak ke naam subudhi bakhaaneeai | 812 |","meaning_en":"O wise one, call all these names of the gun (tupak).","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[813],"number_text":"੮੧੩।","page":980,"lines":[{"gurmukhi":"ਫੇਨਨਨੀ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Phenannee sabdaadi uchaaran keejeeai |","meaning_en":"First say the word 'Phenanani' (phen, 'foam', with -ni);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰੇ ਦੀਜੀਐ।","roman":"Jaa char kahi naaik pad bahure deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪਛਾਨੀਐ।੮੧੩।","roman":"Ho sakal tupak ke naam prabeen pachhaaneeai | 813 |","meaning_en":"O skilled one, recognise all these as names of the gun (tupak).","page":980,"meaning_status":"draft"}]},{"type":"verse","number":[814],"number_text":"੮੧੪।","page":980,"lines":[{"gurmukhi":"ਬ੍ਰਿਛ ਕੰਦਨਿਨਿ ਆਦਿ ਬਖਾਨੋ ਜਾਨਿ ਕੈ।","roman":"Brichh kandnini aadi bakhaano jaani kai |","meaning_en":"Knowingly say first 'Brichh kandanini' ('uprooter of trees', a river);","page":980,"meaning_status":"draft","note":"ਕੰਦਨਿ: read as 'uprooting/destroying'; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨਿ ਕੈ।","roman":"Jaa char kahi naaik pad bahuri pramaani kai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":980,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":980,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਪਹਿਚਾਨੀਐ।੮੧੪।","roman":"Ho sakal tupak ke naam chatur pahichaaneeai | 814 |","meaning_en":"O clever one, recognise all these as names of the gun (tupak).","page":980,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":981,"meaning_status":"draft"},{"type":"verse","number":[815],"number_text":"੮੧੫।","page":981,"lines":[{"gurmukhi":"ਜਲ ਰਸ ਸਨਨੀ ਆਦਿ ਕਹਿ ਜਾ ਚਰ ਪਤਿ ਕਹਿ ਅੰਤਿ।","roman":"Jal ras sannee aadi kahi jaa char pati kahi anti |","meaning_en":"First say 'Jal ras sanani', then 'ja char' and 'pati' (lord) at the end;","page":981,"meaning_status":"draft","note":"ਜਲ ਰਸ ਸਨਨੀ: obscure; 'water' + 'ras' (liquid/juice); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹਿ ਤੁਪਕ ਕੇ ਨਿਕਸਹਿ ਨਾਮ ਅਨੰਤ। ੮੧੫।","roman":"Satroo sabad kahi tupak ke nikashi naam anant | 815 |","meaning_en":"say the word 'shatru' (enemy), and countless names of the gun (tupak) come forth.","page":981,"meaning_status":"draft"}]},{"type":"verse","number":[816],"number_text":"੮੧੬।","page":981,"lines":[{"gurmukhi":"ਕ੍ਰਿਤਅਰਿਨੀ ਪਦ ਆਦਿ ਕਹਿ ਜਾ ਚਰ ਨਾਥ ਉਚਾਰਿ।","roman":"Krita'arinee pad aadi kahi jaa char naath uchaari |","meaning_en":"First say the word 'Kritarini', then say 'ja char' and 'nath' (lord);","page":981,"meaning_status":"draft","note":"ਕ੍ਰਿਤਅਰਿਨੀ: obscure; perhaps 'enemy of what is made' (a river that breaks banks); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਉਚਰਿ ਕਰਿ ਤੁਪਕ ਕੇ ਲੀਜੋ ਨਾਮ ਸੁ ਧਾਰ। ੮੧੬।","roman":"Satroo uchri kari tupak ke leejo naam su dhaar | 816 |","meaning_en":"say 'shatru' (enemy), and take these up as names of the gun (tupak).","page":981,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":981,"meaning_status":"draft"},{"type":"verse","number":[817],"number_text":"੮੧੭।","page":981,"lines":[{"gurmukhi":"ਕ੍ਰਾਰ ਕੰਦਨੀਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Kraar kandneeni aadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say 'Krar kandanini' ('cutter of banks', a river); then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੮੧੭।","roman":"Satroo sabad kahu bahuri bhanijai | naam tuphang cheen chiti lijai | 817 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":981,"meaning_status":"draft"}]},{"type":"verse","number":[818],"number_text":"੮੧੮।","page":981,"lines":[{"gurmukhi":"ਕ੍ਰਾਰ ਆਰਿਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Kraar aarinee aadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say 'Krar arini' ('enemy of banks', a river); then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੮੧੮।","roman":"Satroo sabad kahu bahuri uchaaro | naam tupak ke sakal bichaaro | 818 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":981,"meaning_status":"draft"}]},{"type":"verse","number":[819],"number_text":"੮੧੯।","page":981,"lines":[{"gurmukhi":"ਕਲੁਨਾਸਨਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Kalunaasanni aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Kalunasanani' ('destroyer of sins', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft","note":"ਕਲੁਨਾਸਨ: 'destroyer of sin', an epithet of the Ganga; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅਤਿ ਉਚਰੀਐ। ਨਾਮ ਤੁਪਕ ਸਕਲ ਬਿਚਰੀਐ। ੮੧੯।","roman":"Satroo sabad tih ati uchreeai | naam tupak sakal bichreeai | 819 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":981,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":981,"meaning_status":"draft"},{"type":"verse","number":[820],"number_text":"੮੨੦।","page":981,"lines":[{"gurmukhi":"ਗੰਗਨਿ ਪਦ ਕੋ ਪ੍ਰਥਮ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Gangni pad ko pratham uchaaran keejeeai |","meaning_en":"First say the word 'Gangani' (Ganga, with -ni);","page":981,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰੋ ਦੀਜੀਐ।","roman":"Jaa char kahi naaik pad bahuro deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":981,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪਛਾਨੀਐ।੮੨੦।","roman":"Ho sakal tupak ke naam prabeen pachhaaneeai | 820 |","meaning_en":"O skilled one, recognise all these as names of the gun (tupak).","page":981,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":981,"meaning_status":"draft"},{"type":"verse","number":[821],"number_text":"੮੨੧।","page":981,"lines":[{"gurmukhi":"ਜਨੁਵਨਿ ਪਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Januvni pad ko aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say the word 'Januvani' (Jahnavi, the Ganga, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft","note":"ਜਨੁਵਨਿ: printed so; read as Jahnavi (the Ganga); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੮੨੧।","roman":"Satroo sabad kahu bahuri bhanijai | naam tuphang cheen chiti lijai | 821 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":981,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":981,"meaning_status":"draft"},{"type":"verse","number":[822],"number_text":"੮੨੨।","page":981,"lines":[{"gurmukhi":"ਭਾਗੀਰਥਨੀ ਪਦ ਕੋ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Bhaageerathnee pad ko aadi bakhaaneeai |","meaning_en":"First say the word 'Bhagirathani' (Bhagirathi, the Ganga, with -ni);","page":981,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰੋ ਠਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuro thaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":981,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੮੨੨।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 822 |","meaning_en":"O skilled one, regard all these as names of the gun (tupak).","page":981,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":981,"meaning_status":"draft"},{"type":"verse","number":[823],"number_text":"੮੨੩।","page":981,"lines":[{"gurmukhi":"ਜਟਨਿਨਿ ਪਦ ਕੋ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਧਰੀਐ।","roman":"Jatnini pad ko aadi uchreeai | jaa char kahi naaik pad dhareeai |","meaning_en":"First say the word 'Jatanini' (from jata, matted hair, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":981,"meaning_status":"draft","note":"ਜਟਨਿਨਿ: probably the Ganga, who flows from Shiva's matted hair; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪ੍ਰਮਾਨੋ। ੮੨੩।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sakal pramaano | 823 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":981,"meaning_status":"draft"}]},{"type":"verse","number":[824],"number_text":"੮੨੪।","page":982,"lines":[{"gurmukhi":"ਨਦੀ ਰਾਟਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Nadee raatnini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Nadi ratanini' ('king of rivers', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਜਾਨ ਜੀਅ ਲੀਜੈ। ੮੨੪।","roman":"Satroo sabad kahu bahuri bhaneejai | naam tuphang jaan jeea leejai | 824 |","meaning_en":"then say the word 'shatru' (enemy); know these as names of the gun (tufang) in your heart.","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[825],"number_text":"੮੨੫।","page":982,"lines":[{"gurmukhi":"ਭੀਖਮ ਜਨਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Bheekham jannini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Bhikham jananini' ('mother of Bhishma', i.e. the Ganga, with -ni); then say 'ja char' and add the word 'pati' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਹੀ ਲਹੀਐ। ਯਾ ਮੈ ਕਛੂ ਭੇਦ ਨਹੀ ਕਹੀਐ। ੮੨੫।","roman":"Naam tupak ke sabh hee laheeai | yaa mai kachhoo bhed nahee kaheeai | 825 |","meaning_en":"understand all these as names of the gun (tupak); make no distinction in this at all.","page":982,"meaning_status":"draft","note":"ਭੇਦ: 'difference/distinction' (also 'secret'); i.e. all these are equally names of the gun."}]},{"type":"verse","number":[826],"number_text":"੮੨੬।","page":982,"lines":[{"gurmukhi":"ਨਦੀ ਈਸ੍ਰਨਿਨਿ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਰੀਐ।","roman":"Nadee eesranini aadi uchreeai | jaa char kahi naaik pad dareeai |","meaning_en":"First say 'Nadi isranini' ('lord of rivers', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੮੨੬।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sakal pachhaano | 826 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[827],"number_text":"੮੨੭।","page":982,"lines":[{"gurmukhi":"ਨਦੀ ਰਾਜਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Nadee raajnini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Nadi rajanini' ('king of rivers', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਬਹੁਰੋ ਮੁਖਿ ਭਾਖੁ। ਨਾਮ ਤੁਫੰਗ ਚੀਨਿ ਚਿਤਿ ਰਾਖੁ। ੮੨੭।","roman":"Satroo sabad bahuro mukhi bhaakhu | naam tuphang cheeni chiti raakhu | 827 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[828],"number_text":"੮੨੮।","page":982,"lines":[{"gurmukhi":"ਨਦਿ ਨਾਇਕਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Nadi naaiknini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Nadi nayakanini' ('lord of rivers', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਬਹੁਰੋ ਤਿਹ ਦੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨਿ ਚਿਤਿ ਲੀਜੈ। ੮੨੮।","roman":"Satroo sabad bahuro tih deejai | naam tuphang cheeni chiti leejai | 828 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[829],"number_text":"੮੨੯।","page":982,"lines":[{"gurmukhi":"ਸਰਿਤੇਸ੍ਰਨਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Saritesranini aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Saritesranini' ('lord of rivers', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੮੨੯।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sakal pachhaano | 829 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[830],"number_text":"੮੩੦।","page":982,"lines":[{"gurmukhi":"ਸਰਿਤਾ ਬਰਨਿਨਿ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਰੀਐ।","roman":"Saritaa barnini aadi uchreeai | jaa char kahi naaik pad dareeai |","meaning_en":"First say 'Sarita baranini'; then say 'ja char' and add the word 'nayak' (lord);","page":982,"meaning_status":"draft","note":"ਬਰਨਿਨਿ: 'husband' or 'best' of rivers; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਪਹਿਚਾਨੋ। ੮੩੦।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sabh pahichaano | 830 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[831],"number_text":"੮੩੧।","page":982,"lines":[{"gurmukhi":"ਸਰਿਤੇਦ੍ਰਨਿਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਦੇ ਡਾਰੋ।","roman":"Saritedranini aadi uchaaro | jaa char kahi pati pad de daaro |","meaning_en":"First say 'Saritendranini' ('Indra/king of rivers', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨੋ। ੮੩੧।","roman":"Satroo sabad ko bahuri bakhaano | naam tupak ke sabh jeea jaano | 831 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak) in your heart.","page":982,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":982,"meaning_status":"draft"},{"type":"verse","number":[832],"number_text":"੮੩੨।","page":982,"lines":[{"gurmukhi":"ਸਰਿਤਾ ਨ੍ਰਿਪਨਿਨਿ ਬਕਤ੍ਰ ਤੇ ਪ੍ਰਥਮੈ ਕਰੋ ਉਚਾਰ।","roman":"Saritaa nripnini bakatr te prathmai karo uchaar |","meaning_en":"First say aloud 'Sarita nripanini' ('king of rivers', with -ni);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਪਤਿ ਕਹਿ ਸਤ੍ਰੂ ਕਹਿ ਨਾਮ ਤੁਪਕ ਜੀਅ ਧਾਰ। ੮੩੨।","roman":"Jaa char pati kahi satroo kahi naam tupak jeea dhaar | 832 |","meaning_en":"say 'ja char' and 'pati' (lord), then say 'shatru' (enemy), and hold these in mind as names of the gun (tupak).","page":982,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":982,"meaning_status":"draft"},{"type":"verse","number":[833],"number_text":"੮੩੩।","page":982,"lines":[{"gurmukhi":"ਆਦਿ ਤਰੰਗਨਿ ਰਾਜਨਿ ਸਬਦ ਉਚਾਰੀਐ।","roman":"Aadi tarangni raajni sabad uchaareeai |","meaning_en":"First say the words 'Tarangani rajani' ('king of rivers', with -ni);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਪੁਨਿ ਦੇ ਡਾਰੀਐ।","roman":"Jaa char kahi naaik pad puni de daareeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":982,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪਛਾਨੀਐ।੮੩੩।","roman":"Ho sakal tupak ke naam prabeen pachhaaneeai | 833 |","meaning_en":"O skilled one, recognise all these as names of the gun (tupak).","page":982,"meaning_status":"draft"}]},{"type":"verse","number":[834],"number_text":"੮੩੪।","page":982,"lines":[{"gurmukhi":"ਨਦੀ ਨ੍ਰਿਪਨਿਨੀ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Nadee nripninee mukh te aadi bakhaaneeai |","meaning_en":"First say aloud 'Nadi nripanini' ('king of rivers', with -ni);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":982,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":982,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਧਾਰੀਐ।੮੩੪।","roman":"Ho sakal tupak ke naam chatur chiti dhaareeai | 834 |","meaning_en":"O clever one, hold all these in mind as names of the gun (tupak).","page":982,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":983,"meaning_status":"draft"},{"type":"verse","number":[835],"number_text":"੮੩੫।","page":983,"lines":[{"gurmukhi":"ਆਦਿ ਜਮੁਨਨੀ ਸਬਦ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Aadi jamunnee sabad uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say the word 'Jamunani' (Yamuna, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤ ਲਿਜੈ। ੮੩੫।","roman":"Satroo sabad ko bahuri bhanijai | naam tuphang cheen chit lijai | 835 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[836],"number_text":"੮੩੬।","page":983,"lines":[{"gurmukhi":"ਕਾਲਿੰਦ੍ਰਨਿਨੀ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਰੀਐ।","roman":"Kaalindraninee aadi uchreeai | jaa char kahi naaik pad dareeai |","meaning_en":"First say 'Kalindranini' (Kalindi, the Yamuna, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੩੬।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 836 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[837],"number_text":"੮੩੭।","page":983,"lines":[{"gurmukhi":"ਕਿਸਨ ਬਲਭਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Kisan balbhini aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Kisan balabhini' ('beloved of Krishna', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":983,"meaning_status":"draft","note":"ਕਿਸਨ ਬਲਭਿ: 'Krishna's beloved', here apparently the Yamuna; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੀਐ। ੮੩੭।","roman":"Satroo sabad ko bahuri bakhaaneeai | sabh sree naam tupak ke jaaneeai | 837 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[838],"number_text":"੮੩੮।","page":983,"lines":[{"gurmukhi":"ਬਸੁਦੇਵਜ ਬਲਭਨਨਿ ਭਾਖੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Basudevaj balbhanni bhaakho | jaa char kahi naaik pad raakho |","meaning_en":"Say 'Basudevaj balabhanani' ('beloved of the son of Vasudev', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਏਕ ਨਹੀ ਮਾਨੋ। ੮੩੮।","roman":"Sabh sree naam tupak ke jaano | yaa mai bhed ek nahee maano | 838 |","meaning_en":"know all these as names of the gun (tupak); consider there to be no difference in this at all.","page":983,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":983,"meaning_status":"draft"},{"type":"verse","number":[839],"number_text":"੮੩੯।","page":983,"lines":[{"gurmukhi":"ਸਕਲ ਨਾਮ ਬਸੁਦੇਵ ਕੇ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Sakal naam basudev ke aadi uchaareeai |","meaning_en":"First say any of the names of Vasudev('s son);","page":983,"meaning_status":"draft","note":"ਬਸੁਦੇਵ: Vasudev, here probably meaning Krishna (Vasudeva); uncertain."},{"gurmukhi":"ਜਾ ਬਲਭਨੀ ਤਾ ਪਾਛੇ ਪਦ ਡਾਰੀਐ।","roman":"Jaa balabhnee taa paachhe pad daareeai |","meaning_en":"after it put the word 'balabhani' (beloved, with -ni);","page":983,"meaning_status":"draft","note":"ਜਾ: read as 'after which/whose'; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਰਿਪੁ ਸਬਦ ਬਹੁਰਿ ਤਿਹ ਭਾਖੀਐ।","roman":"Jaa char kahi ripu sabad bahuri tih bhaakheeai |","meaning_en":"then say 'ja char' and then the word 'ripu' (enemy);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚੀਨਿ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਰਾਖੀਐ। ੮੩੯।","roman":"Ho cheeni tupak ke naam chatur chiti raakheeai | 839 |","meaning_en":"O clever one, recognise these as names of the gun (tupak) in your heart.","page":983,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":983,"meaning_status":"draft"},{"type":"verse","number":[840],"number_text":"੮੪੦।","page":983,"lines":[{"gurmukhi":"ਸਿਆਮ ਬਲਭਾ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦੁ ਠਾਨੋ।","roman":"Siaam balbhaa aadi bakhaano | jaa char kahi naaik padu thaano |","meaning_en":"First say 'Siam balabha' ('beloved of Shyam', Krishna); then say 'ja char' and add the word 'nayak' (lord);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੮੪੦।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 840 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[841],"number_text":"੮੪੧।","page":983,"lines":[{"gurmukhi":"ਮੁਸਲੀਧਰ ਬਲਭਾ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Musleedhar balbhaa bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"Say 'Musalidhar balabha' ('beloved of the pestle-bearer'); then say 'ja char' and add the word 'pati' (lord);","page":983,"meaning_status":"draft","note":"ਮੁਸਲੀਧਰ: 'bearer of the pestle', normally Balram; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣੀਜੈ। ਜਾਨ ਨਾਮ ਤੁਪਕ ਕੋ ਲੀਜੈ। ੮੪੧।","roman":"Satroo sabad ko bahuri bhaneejai | jaan naam tupak ko leejai | 841 |","meaning_en":"then say the word 'shatru' (enemy); know these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[842],"number_text":"੮੪੨।","page":983,"lines":[{"gurmukhi":"ਬਾਪੁਰਧਰ ਬਲਭਾ ਪ੍ਰਮਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦਹਿ ਠਾਨੋ।","roman":"Baapurdhar balbhaa pramaano | jaa char kahi pati sabadhi thaano |","meaning_en":"Say 'Bapurdhar balabha' ('beloved of the body-bearer'?); then say 'ja char' and add the word 'pati' (lord);","page":983,"meaning_status":"draft","note":"ਬਾਪੁਰਧਰ: obscure; perhaps 'one who took a (human) body', i.e. Krishna; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਸਬ ਜੀਅ ਨਾਮ ਤੁਪਕ ਕੇ ਧਰੀਐ। ੮੪੨।","roman":"Satroo sabad ko bahuri uchreeai | sab jeea naam tupak ke dhareeai | 842 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[843],"number_text":"੮੪੩।","page":983,"lines":[{"gurmukhi":"ਬੰਸੀਧਰ ਧਰਨਿਨਿ ਪਦ ਦਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਭਣਿਜੈ।","roman":"Banseedhar dharnini pad dijai | jaa char kahi pati sabad bhanijai |","meaning_en":"Put the words 'Bansidhar dharanini' (Bansidhar = 'flute-holder', Krishna); then say 'ja char' and add the word 'pati' (lord);","page":983,"meaning_status":"draft","note":"ਧਰਨਿਨਿ: perhaps 'wife/consort'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਪਹਿਚਾਨੋ। ੮੪੩।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak pahichaano | 843 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[844],"number_text":"੮੪੪।","page":983,"lines":[{"gurmukhi":"ਬਿਸੁਇਸ ਬਲਭਾਦਿ ਪਦ ਦੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਭਣੀਜੈ।","roman":"Bisuis balbhaadi pad deejai | jaa char kahi pati sabad bhaneejai |","meaning_en":"First put 'Bisuis balabha' ('beloved of the lord of the world'); then say 'ja char' and add the word 'pati' (lord);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੪੪।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 844 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[845],"number_text":"੮੪੫।","page":983,"lines":[{"gurmukhi":"ਬਿਸੁਇਸੇਸ੍ਰਣੀ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਪੁਨਿ ਦਿਜੈ।","roman":"Bisuisesranee aadi bhanijai | jaa char kahi pati pad puni dijai |","meaning_en":"First say 'Bisuisesrani' ('of the lord of the world', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":983,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੮੪੫।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 845 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":983,"meaning_status":"draft"}]},{"type":"verse","number":[846],"number_text":"੮੪੬।","page":984,"lines":[{"gurmukhi":"ਜਦੁ ਨਾਇਕ ਨਾਇਕਾ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Jadu naaik naaikaa bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"Say 'Jadu nayak nayaka' ('consort of the lord of the Yadus'); then say 'ja char' and add the word 'pati' (lord);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਦੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲੀਜੈ। ੮੪੬।","roman":"Taa ke anti satroo pad deejai | naam tuphang cheen chiti leejai | 846 |","meaning_en":"add the word 'shatru' (enemy) at the end; recognise these as names of the gun (tufang) in your heart.","page":984,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":984,"meaning_status":"draft"},{"type":"verse","number":[847],"number_text":"੮੪੭।","page":984,"lines":[{"gurmukhi":"ਦੁਆਰਾਵਤੀਸ ਬਲਭਾ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Duaaraavtees balbhaa aadi uchaareeai |","meaning_en":"First say 'Duaravatis balabha' ('beloved of the lord of Dwarka');","page":984,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਨਾਇਕ ਪਦ ਕੋ ਪੁਨਿ ਦੈ ਡਾਰੀਐ।","roman":"Jaa char naaik pad ko puni dai daareeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":984,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪਛਾਨੀਐ।੮੪੭।","roman":"Ho sakal tupak ke naam prabeen pachhaaneeai | 847 |","meaning_en":"O skilled one, recognise all these as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"verse","number":[848],"number_text":"੮੪੮।","page":984,"lines":[{"gurmukhi":"ਜਾਦੋ ਰਾਇ ਬਲਭਾ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Jaado raai balbhaa aadi bakhaaneeai |","meaning_en":"First say 'Jado rai balabha' ('beloved of the king of the Yadavs');","page":984,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Satroo sabad ko taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":984,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਖਿ ਲੀਜੀਐ।੮੪੮।","roman":"Ho sakal tupak ke naam chatur lakhi leejeeai | 848 |","meaning_en":"O clever one, understand all these as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"verse","number":[849],"number_text":"੮੪੯।","page":984,"lines":[{"gurmukhi":"ਦੁਆਰਕੇਂਦ੍ਰ ਬਲਭਿਨਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Duaarkendr balbhini uchaaran keejeeai |","meaning_en":"Say 'Duarkendra balabhini' ('beloved of the lord of Dwarka', with -ni);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਪਾਛੇ ਦੀਜੀਐ।","roman":"Jaa char kahi naaik pad paachhe deejeeai |","meaning_en":"then put 'ja char' and the word 'nayak' (lord) after it;","page":984,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":984,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪਛਾਨੀਐ। ੮੪੯।","roman":"Ho sakal tupak ke naam prabeen pachhaaneeai | 849 |","meaning_en":"O skilled one, recognise all these as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"verse","number":[850],"number_text":"੮੫੦।","page":984,"lines":[{"gurmukhi":"ਦੁਆਰਕੇਸ ਬਲਭਨਿ ਸੁ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Duaarkes balabhni su aadi bakhaaneeai |","meaning_en":"First say 'Duarkes balabhani' ('beloved of the lord of Dwarka', with -ni);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahur pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੌ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kau taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":984,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਧਾਰੀਐ।੮੫੦।","roman":"Ho sakal tupak ke naam chatur chiti dhaareeai | 850 |","meaning_en":"O clever one, hold all these in mind as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":984,"meaning_status":"draft"},{"type":"verse","number":[851],"number_text":"੮੫੧।","page":984,"lines":[{"gurmukhi":"ਦੁਆਰਕੇ ਅਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Duaarke anini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Duarke anini'; then say 'ja char' and add the word 'pati' (lord);","page":984,"meaning_status":"draft","note":"ਦੁਆਰਕੇ ਅਨਿਨਿ: printed so; perhaps 'Duarkesanini' ('of the lord of Dwarka'); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਧਰੀਐ। ੮੫੧।","roman":"Satroo sabad ko bahuri uchreeai | sabh sree naam tupak ke dhareeai | 851 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"verse","number":[852],"number_text":"੮੫੨।","page":984,"lines":[{"gurmukhi":"ਜਦੁਨਾਥਨਨੀ ਆਦਿ ਭਨੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Jadunaathannee aadi bhaneejai | jaa char kahi naaik pad deejai |","meaning_en":"First say 'Jadunathanani' ('lord of the Yadus', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੫੨।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 852 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"verse","number":[853],"number_text":"੮੫੩।","page":984,"lines":[{"gurmukhi":"ਦੁਆਰਵਤੀ ਸਰਨਿਨ ਪਦ ਭਾਖੁ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੁ।","roman":"Duaaravtee sarnin pad bhaakhu | jaa char kahi naaik pad raakhu |","meaning_en":"Say the word 'Duarvati saranin'; then say 'ja char' and add the word 'nayak' (lord);","page":984,"meaning_status":"draft","note":"ਸਰਨਿਨ: perhaps 'lord/refuge' (of Dwarka); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੫੩।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 853 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":984,"meaning_status":"draft"},{"type":"verse","number":[854],"number_text":"੮੫੪।","page":984,"lines":[{"gurmukhi":"ਦੁਆਰਵਤੀ ਨਾਇਕਨਿਨਿ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Duaaravtee naaiknini aadi uchaareeai |","meaning_en":"First say 'Duarvati nayakanini' ('lord of Dwarka', with -ni);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨ ਨਾਇਕ ਪਦ ਡਾਰੀਐ।","roman":"Jaa char kahi kai pun naaik pad daareeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":984,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":984,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪਛਾਨੀਐ।੮੫੪।","roman":"Ho sakal tupak ke naam prabeen pachhaaneeai | 854 |","meaning_en":"O skilled one, recognise all these as names of the gun (tupak).","page":984,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":985,"meaning_status":"draft"},{"type":"verse","number":[855],"number_text":"੮੫੫।","page":985,"lines":[{"gurmukhi":"ਦੁਆਰਕਾ ਧਨਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Duaarkaa dhanni aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Duarka dhanani' ('master of Dwarka', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣੀਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲੀਜੈ। ੮੫੫।","roman":"Satroo sabad ko bahuri bhaneejai | naam tuphang cheen chiti leejai | 855 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[856],"number_text":"੮੫੬।","page":985,"lines":[{"gurmukhi":"ਦੁਆਰਕੇਂਦ੍ਰਨਿਨਿ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਸੁ ਧਰੀਐ।","roman":"Duaarkendranini aadi uchreeai | jaa char kahi pati sabad su dhareeai |","meaning_en":"First say 'Duarkendranini' ('lord of Dwarka', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੇ ਅੰਤਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਮਾਨੋ। ੮੫੬।","roman":"Satroo sabad ke anti bakhaano | sabh sree naam tupak ke maano | 856 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[857],"number_text":"੮੫੭।","page":985,"lines":[{"gurmukhi":"ਦੁਆਰਾਵਤੇਸ੍ਰਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਸੁ ਠਾਨਹੁ।","roman":"Duaaraavtesrani aadi bakhaanhu | jaa char kahi pati sabad su thaanhu |","meaning_en":"First say 'Duaravatesrani' ('lord of Dwarka', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਧਰੀਐ। ੮੫੭।","roman":"Satroo sabad ko bahuri uchreeai | sabh sree naam tupak ke dhareeai | 857 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[858],"number_text":"੮੫੮।","page":985,"lines":[{"gurmukhi":"ਜਦ੍ਵੇਸਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Jadvesni aadi uchaaran keejai | jaa char kahi naaik pad deejai |","meaning_en":"First say 'Jadvesani' ('lord of the Yadus', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਪਹਿਚਾਨੋ। ੮੫੮।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak pahichaano | 858 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[859],"number_text":"੮੫੯।","page":985,"lines":[{"gurmukhi":"ਦੁਆਰਾਵਤੀ ਨਾਇਕਨਿਨਿ ਭਾਖਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਕਹੁ ਰਾਖਹੁ।","roman":"Duaaraavtee naaiknini bhaakhhu | jaa char kahi pati pad kahu raakhhu |","meaning_en":"Say 'Duaravati nayakanini' ('lord of Dwarka', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੮੫੯।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 859 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[860],"number_text":"੮੬੦।","page":985,"lines":[{"gurmukhi":"ਜਗਤੇਸਰਨਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Jagtesarnini aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Jagtesaranini' ('lord of the world', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੬੦।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 860 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":985,"meaning_status":"draft"},{"type":"verse","number":[861],"number_text":"੮੬੧।","page":985,"lines":[{"gurmukhi":"ਅਨਿਕ ਦੁੰਦਭਜਾ ਬਲਭਨਿ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Anik dundabhjaa balabhni aadi bakhaaneeai |","meaning_en":"First say 'Anik dundabhaja balabhani' ('beloved of the son of Anakdundubhi', i.e. of Krishna);","page":985,"meaning_status":"draft","note":"ਅਨਿਕ ਦੁੰਦਭ: Anakdundubhi, a name of Vasudev; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":985,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ।੮੬੧।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 861 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[862],"number_text":"੮੬੨।","page":985,"lines":[{"gurmukhi":"ਹਲੀ ਭ੍ਰਾਤਨਿਨਿ ਆਦਿ ਬਖਾਨਨਿ ਕੀਜੀਐ।","roman":"Halee bhraatnini aadi bakhaanni keejeeai |","meaning_en":"First say 'Hali bhratanini' ('brother of the plough-bearer', Balram's brother Krishna);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":985,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ।੮੬੨।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 862 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":985,"meaning_status":"draft"},{"type":"verse","number":[863],"number_text":"੮੬੩।","page":985,"lines":[{"gurmukhi":"ਬਲਿ ਆਨੁਜਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Bali aanujnini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Bali anujanini' ('younger brother of Bal(ram)', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਫੰਗ ਚੀਨ ਚਿਤਿ ਲਿਜੈ। ੮੬੩।","roman":"Satroo sabad kahu bahuri bhanijai | naam tuphang cheen chiti lijai | 863 |","meaning_en":"then say the word 'shatru' (enemy); recognise these as names of the gun (tufang) in your heart.","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[864],"number_text":"੮੬੪।","page":985,"lines":[{"gurmukhi":"ਬਲਿ ਭਈਅਨਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Bali bhaeeannee aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Bali bhaianani' ('brother of Bal(ram)', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰੋ ਕਹੀਯੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਯੋ। ੮੬੪।","roman":"Satroo sabad ko bahuro kaheeyo | sabh sree naam tupak ke laheeyo | 864 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[865],"number_text":"੮੬੫।","page":985,"lines":[{"gurmukhi":"ਰਉਹਣੇਅ ਭ੍ਰਾਤਨਨਿ ਭਾਖੁ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੁ।","roman":"Rauhnea bhraatanni bhaakhu | jaa char kahi naaik pad raakhu |","meaning_en":"Say 'Rauhaneya bhratanani' ('brother of Rohini's son', Balram); then say 'ja char' and add the word 'nayak' (lord);","page":985,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਹਿ ਲਿਜੈ। ੮੬੫।","roman":"Satroo sabad ko bahuri bhanijai | sabh sree naam tupak lahi lijai | 865 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":985,"meaning_status":"draft"}]},{"type":"verse","number":[866],"number_text":"੮੬੬।","page":986,"lines":[{"gurmukhi":"ਬਲਭਦ੍ਰ ਭ੍ਰਾਤਨਿਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Balbhadr bhraatnini aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Balbhadra bhratanini' ('brother of Balbhadra', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੬੬।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 866 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":986,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":986,"meaning_status":"draft"},{"type":"verse","number":[867],"number_text":"੮੬੭।","page":986,"lines":[{"gurmukhi":"ਪ੍ਰਲੰਬਘਨੁ ਅਨੁਜਨਨੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Pralanbaghnu anujannee aadi bakhaaneeai |","meaning_en":"First say 'Pralambaghanu anujanani' ('younger brother of the slayer of Pralamb', i.e. of Balram);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kahu taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":986,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ।੮੬੭।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 867 |","meaning_en":"O wise one, regard all these as names of the gun (tupak).","page":986,"meaning_status":"draft"}]},{"type":"verse","number":[868],"number_text":"੮੬੮।","page":986,"lines":[{"gurmukhi":"ਕਾਮਪਾਲ ਅਨੁਜਨਿਨੀ ਆਦਿ ਭਨੀਜੀਐ।","roman":"Kaampaal anujninee aadi bhaneejeeai |","meaning_en":"First say 'Kampal anujanini' ('younger brother of Kampal', i.e. of Balram);","page":986,"meaning_status":"draft","note":"ਕਾਮਪਾਲ: taken as a name of Balram; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kahu taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":986,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਮੰਤ੍ਰ ਬਿਚਾਰੀਐ।੮੬੮।","roman":"Ho sakal tupak ke naam su mantr bichaareeai | 868 |","meaning_en":"regard all these as names of the gun (tupak).","page":986,"meaning_status":"draft"}]},{"type":"verse","number":[869],"number_text":"੮੬੯।","page":986,"lines":[{"gurmukhi":"ਹਲ ਆਯੁਧ ਅਨੁਜਨਿਨੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Hal aayudh anujninee aadi bakhaaneeai |","meaning_en":"First say 'Hal ayudh anujanini' ('younger brother of the one whose weapon is the plough', Balram);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਸੁ ਕਬਿ ਕਹਿ ਦੀਜੀਐ।","roman":"Ari pad taa ke anti su kabi kahi deejeeai |","meaning_en":"add the word 'ari' (enemy) at the end;","page":986,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ। ੮੬੯।","roman":"Ho sakal tupak ke naam jaan jeea leejeeai | 869 |","meaning_en":"know all these as names of the gun (tupak) in your heart.","page":986,"meaning_status":"draft"}]},{"type":"verse","number":[870],"number_text":"੮੭੦।","page":986,"lines":[{"gurmukhi":"ਰਿਵਤਿ ਰਵਨ ਅਨੁਜਨਿਨੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Rivti ravan anujninee aadi bakhaaneeai |","meaning_en":"First say 'Rivati ravan anujanini' ('younger brother of Revati's husband', Balram);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਸੁ ਦੀਜੀਐ।","roman":"Satroo sabad ko taa ke anti su deejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":986,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।੮੭੦।","roman":"Ho sakal tupak ke naam jaan jeea leejeeai | 870 |","meaning_en":"know all these as names of the gun (tupak) in your heart.","page":986,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":986,"meaning_status":"draft"},{"type":"verse","number":[871],"number_text":"੮੭੧।","page":986,"lines":[{"gurmukhi":"ਰਾਮ ਅਨੁਜਨਿਨੀ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਦੈ ਡਾਰੋ।","roman":"Raam anujninee aadi uchaaro | jaa char kahi pati pad dai daaro |","meaning_en":"First say 'Ram anujanini' ('younger brother of (Bal)ram', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਪਦ ਜਾਨੋ। ੮੭੧।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak pad jaano | 871 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":986,"meaning_status":"draft"}]},{"type":"verse","number":[872],"number_text":"੮੭੨।","page":986,"lines":[{"gurmukhi":"ਬਲਦੇਵ ਅਨੁਜਨੀ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Baldev anujnee aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Baldev anujani' ('younger brother of Baldev', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੇ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੇ। ੮੭੨।","roman":"Satroo sabad ko bahuri bhanije | naam tupak ke sabh lahi lije | 872 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":986,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":986,"meaning_status":"draft"},{"type":"verse","number":[873],"number_text":"੮੭੩।","page":986,"lines":[{"gurmukhi":"ਪ੍ਰਲੰਬਾਰਿ ਅਨੁਜਨਿਨੀ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Pralanbaari anujninee aadi uchaareeai |","meaning_en":"First say 'Pralambari anujanini' ('younger brother of the enemy of Pralamb', i.e. of Balram);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਪੁਨਿ ਦੇ ਡਾਰੀਐ।","roman":"Jaa char kahi naaik pad puni de daareeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":986,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":986,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਪਹਿਚਾਨੀਐ।੮੭੩।","roman":"Ho sakal tupak ke naam chatur pahichaaneeai | 873 |","meaning_en":"O clever one, recognise all these as names of the gun (tupak).","page":986,"meaning_status":"draft"}]},{"type":"verse","number":[874],"number_text":"੮੭੪।","page":987,"lines":[{"gurmukhi":"ਤ੍ਰਿਣਾਵਰਤ ਅਰਿਨਨਿ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Trinaavrat arinni sabdaadi bakhaaneeai |","meaning_en":"First say the word 'Trinavarat arinani' ('enemy of Trinavart', Krishna);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੇ ਪੁਨਿ ਨਾਇਕ ਪਦ ਠਾਨੀਐ।","roman":"Jaa char kahi ke puni naaik pad thaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":987,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ।੮੭੪।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 874 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[875],"number_text":"੮੭੫।","page":987,"lines":[{"gurmukhi":"ਕੇਸਿਯਾਂਤਕਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Kesiyaantaknini aadi uchaaran keejeeai |","meaning_en":"First say 'Kesiantakanini' ('slayer of Keshi', with -ni);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke ant uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":987,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ। ੮੭੫।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 875 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[876],"number_text":"੮੭੬।","page":987,"lines":[{"gurmukhi":"ਬਕੀਆਂਤਕਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Bakeeaantaknini aadi uchaaran keejeeai |","meaning_en":"First say 'Bakiantakanini' ('slayer of Baki', with -ni);","page":987,"meaning_status":"draft","note":"ਬਕੀ: Bakasur or Putana; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":987,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ।੮੭੬।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 876 |","meaning_en":"O wise one, regard all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[877],"number_text":"੮੭੭।","page":987,"lines":[{"gurmukhi":"ਪਤਿਨਾਗਨਿਨਿ ਆਦਿ ਉਚਾਰੋ ਜਾਨਿ ਕੈ।","roman":"Patinaagnini aadi uchaaro jaani kai |","meaning_en":"Knowingly say first 'Patinaganini' ('lord of the serpent(s)', with -ni);","page":987,"meaning_status":"draft","note":"ਪਤਿਨਾਗ: perhaps Krishna as subduer of the serpent Kali; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਠਾਨਿ ਕੈ।","roman":"Jaa char kahi kai puni naaik pad thaani kai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":987,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪ੍ਰਮਾਨੀਐ।੮੭੭।","roman":"Ho sakal tupak ke naam prabeen pramaaneeai | 877 |","meaning_en":"O skilled one, accept all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[878],"number_text":"੮੭੮।","page":987,"lines":[{"gurmukhi":"ਸਕਟਾਸੁਰ ਹਨਨਿਨ ਸਬਦਾਦਿ ਭਣੀਜੀਐ।","roman":"Saktaasur hannin sabdaadi bhaneejeeai |","meaning_en":"First say the word 'Sakatasur hananin' ('slayer of Shakatasur', with -ni);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਪਾਛੇ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi paachhe naaik pad deejeeai |","meaning_en":"then put 'ja char' and the word 'nayak' (lord) after it;","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":987,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਗਿਆਨ ਪਛਾਨੀਐ।੮੭੮।","roman":"Ho sakal tupak ke naam sugiaan pachhaaneeai | 878 |","meaning_en":"recognise all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":987,"meaning_status":"draft"},{"type":"verse","number":[879],"number_text":"੮੭੯।","page":987,"lines":[{"gurmukhi":"ਮੁਰਅਰਿਨਿਨਿ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Mura'arinini sabdaadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say the word 'Murarinini' ('enemy of Mur', Krishna, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੮੭੯।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 879 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[880],"number_text":"੮੮੦।","page":987,"lines":[{"gurmukhi":"ਨਰਕਾਂਤਕਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Narkaantaknini aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Narakantakanini' ('slayer of Narak', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹਿਜੈ। ੮੮੦।","roman":"Satroo sabad ko bahuri bhanijai | sakal tupak ke naam kahijai | 880 |","meaning_en":"then say the word 'shatru' (enemy); call all these names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[881],"number_text":"੮੮੧।","page":987,"lines":[{"gurmukhi":"ਆਦਿ ਨਰਕਹਾਨਿਨਿ ਪਦ ਭਾਖੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Aadi narakhaanini pad bhaakho | jaa char kahi naaik pad raakho |","meaning_en":"First say the word 'Narakhanini' ('slayer of Narak', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੮੮੧।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 881 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"verse","number":[882],"number_text":"੮੮੨।","page":987,"lines":[{"gurmukhi":"ਸਤ੍ਰੂ ਘਾਇਨਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕਾ ਪਦ ਦਿਜੈ।","roman":"Satroo ghaainni aadi bhanijai | jaa char kahi naaikaa pad dijai |","meaning_en":"First say 'Satru ghainani' ('slayer of enemies', with -ni); then say 'ja char' and add the word 'nayaka' (lord);","page":987,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਪਹਿਚਾਨਹੁ। ੮੮੨।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak pahichaanhu | 882 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":987,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":988,"meaning_status":"draft"},{"type":"verse","number":[883],"number_text":"੮੮੩।","page":988,"lines":[{"gurmukhi":"ਮੁਰ ਮਰਦਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Mur maradnini aadi uchaaran keejeeai |","meaning_en":"First say 'Mur mardanini' ('crusher of Mur', with -ni);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੇ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi ke puni naaik pad deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Satroo sabad ko taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ।੮੮੩।","roman":"Ho sakal tupak ke naam chatur lahi leejeeai | 883 |","meaning_en":"O clever one, understand all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":988,"meaning_status":"draft"},{"type":"verse","number":[884],"number_text":"੮੮੪।","page":988,"lines":[{"gurmukhi":"ਮਧੁ ਸੂਦਨਨਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Madhu soodannini aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Madhu sudananini' ('slayer of Madhu', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੮੮੪।","roman":"Satroo sabad ko bahur bakhaano | sabh sree naam tupak ke jaano | 884 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":988,"meaning_status":"draft"},{"type":"verse","number":[885],"number_text":"੮੮੫।","page":988,"lines":[{"gurmukhi":"ਮਧੁ ਦੁੰਦਨਨੀ ਮੁਖ ਤੇ ਆਦਿ ਭਣਿਜੀਐ।","roman":"Madhu dundannee mukh te aadi bhanijeeai |","meaning_en":"First say aloud 'Madhu dundanani' ('crusher of Madhu', with -ni);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਸਬਦੇਂਦ੍ਰ ਕਹਿਜੀਐ।","roman":"Jaa char kahi kai puni sabdendr kahijeeai |","meaning_en":"then say 'ja char' and add the word 'indra' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪ੍ਰਮਾਨੀਐ।੮੮੫।","roman":"Ho sakal tupak ke naam prabeen pramaaneeai | 885 |","meaning_en":"O skilled one, accept all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"verse","number":[886],"number_text":"੮੮੬।","page":988,"lines":[{"gurmukhi":"ਮਧੁ ਨਾਸਨਨੀ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Madhu naasannee mukh te aadi bakhaaneeai |","meaning_en":"First say aloud 'Madhu nasanani' ('destroyer of Madhu', with -ni);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੇ ਪੁਨਿ ਸਬਦੇਸੁਰ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi ke puni sabdesur pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'isur' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਧਾਰੀਐ।੮੮੬।","roman":"Ho sakal tupak ke naam chatur chiti dhaareeai | 886 |","meaning_en":"O clever one, hold all these in mind as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"verse","number":[887],"number_text":"੮੮੭।","page":988,"lines":[{"gurmukhi":"ਕਾਲਜਮੁਨ ਅਰਿਨਨਿ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Kaalajmun arinni sabdaadi bakhaaneeai |","meaning_en":"First say the word 'Kaljamun arinani' ('enemy of Kalayavan', with -ni);","page":988,"meaning_status":"draft","note":"ਕਾਲਜਮੁਨ: printed so; read as Kalayavan; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਠਾਨੀਐ।","roman":"Jaa char kahi kai puni naaik pad thaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ।੮੮੭।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 887 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"verse","number":[888],"number_text":"੮੮੮।","page":988,"lines":[{"gurmukhi":"ਨਰਕ ਅਰਿਨਨਿ ਮੁਖ ਤੇ ਆਦਿ ਭਣਿਜੀਐ।","roman":"Narak arinni mukh te aadi bhanijeeai |","meaning_en":"First say aloud 'Narak arinani' ('enemy of Narak', with -ni);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦਿਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad dijeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":988,"flags":[{"code":"ੇੈ","reason":"ੇ and ੈ typed on one letter; one covers the other, printed as ੈ"}],"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਛਾਨੀਐ।੮੮੮।","roman":"Ho sakal tupak ke naam subudhi pachhaaneeai | 888 |","meaning_en":"O wise one, recognise all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"verse","number":[889],"number_text":"੮੮੯।","page":988,"lines":[{"gurmukhi":"ਕੰਸਕੇਸ ਕਰਖਨਣੀ ਆਦਿ ਬਖਾਨ ਹੀ।","roman":"Kanskes karkhannee aadi bakhaan hee |","meaning_en":"First say 'Kanskes karkhanani' ('one who dragged Kans by the hair', with -ni);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਠਾਨ ਹੀ।","roman":"Jaa char kahi kai puni naaik pad thaan hee |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ।੮੮੯।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 889 |","meaning_en":"O wise one, regard all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"verse","number":[890],"number_text":"੮੯੦।","page":988,"lines":[{"gurmukhi":"ਬਾਸੁਦਿਵੇਸਨਨਿਨੀ ਆਦਿ ਭਣਿਜੀਐ।","roman":"Baasudivesanninee aadi bhanijeeai |","meaning_en":"First say 'Basudivesananini' ('lord, son of Vasudev', with -ni);","page":988,"meaning_status":"draft","note":"ਬਾਸੁਦਿਵੇਸ: read as Vasudev + 'lord'; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦਿਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad dijeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":988,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":988,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ।੮੯੦।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 890 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":988,"meaning_status":"draft"}]},{"type":"verse","number":[891],"number_text":"੮੯੧।","page":989,"lines":[{"gurmukhi":"ਅਨਕਦੁੰਦਭੇਸਨਿਨਿ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Anakdundbhesnini aadi uchaareeai |","meaning_en":"First say 'Anakdundabhesanini' ('lord, son of Anakdundubhi', with -ni);","page":989,"meaning_status":"draft","note":"ਅਨਕਦੁੰਦਭ: Anakdundubhi, a name of Vasudev; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਡਾਰੀਐ।","roman":"Jaa char kahi kai puni naaik pad daareeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਪਛਾਨੀਐ।੮੯੧।","roman":"Ho sakal tupak ke naam sumantr pachhaaneeai | 891 |","meaning_en":"O good counsellor, recognise all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"verse","number":[892],"number_text":"੮੯੨।","page":989,"lines":[{"gurmukhi":"ਰਸ ਨਰਕਸਨਿਨਿ ਆਦਿ ਸਬਦ ਕੋ ਭਾਖਐ।","roman":"Ras narkasnini aadi sabad ko bhaakha'ai |","meaning_en":"First say the word 'Ras naraksanini';","page":989,"meaning_status":"draft","note":"ਰਸ ਨਰਕਸਨਿਨਿ: obscure; perhaps 'Narakasur's slayer'; printed so; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਰਾਖੀਐ।","roman":"Jaa char kahi kai puni naaik pad raakheeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਧਾਰੀਐ।੮੯੨।","roman":"Ho sakal tupak ke naam chatur chiti dhaareeai | 892 |","meaning_en":"O clever one, hold all these in mind as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"verse","number":[893],"number_text":"੮੯੩।","page":989,"lines":[{"gurmukhi":"ਨਾਰਾਇਨਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Naaraainnee aadi uchaaran keejeeai |","meaning_en":"First say 'Narainani' (Narayan, 'whose dwelling is water', with -ni);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਰਾਜ ਸਬਦ ਪੁਨਿ ਦੀਜੀਐ।","roman":"Jaa char kahi kai raaj sabad puni deejeeai |","meaning_en":"then say 'ja char' and add the word 'raj' (king);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ।੮੯੩।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 893 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"verse","number":[894],"number_text":"੮੯੪।","page":989,"lines":[{"gurmukhi":"ਬਾਰਾਲਯਨਨਿ ਮੁਖਿ ਤੇ ਆਦਿ ਭਣਿਜੀਐ।","roman":"Baaraalyanni mukhi te aadi bhanijeeai |","meaning_en":"First say aloud 'Baralayanani' ('whose dwelling is water', with -ni);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਬਹੁਰਿ ਪਦ ਦਿਜੀਐ।","roman":"Jaa char kahi kai naath bahuri pad dijeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ।੮੯੪।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 894 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"verse","number":[895],"number_text":"੮੯੫।","page":989,"lines":[{"gurmukhi":"ਨੀਰਾਲਯਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Neeraalaynee aadi uchaaran keejeeai |","meaning_en":"First say 'Niralayani' ('whose dwelling is water', with -ni);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਬਹੁਰਿ ਤਿਹ ਦੀਜੀਐ।","roman":"Jaa char kahi pati sabad bahuri tih deejeeai |","meaning_en":"then say 'ja char' and add the word 'pati' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪ੍ਰਮਾਨੀਐ।੮੯੫।","roman":"Ho sakal tupak ke naam prabeen pramaaneeai | 895 |","meaning_en":"O skilled one, accept all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"verse","number":[896],"number_text":"੮੯੬।","page":989,"lines":[{"gurmukhi":"ਨਾਰ ਕੇਤਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Naar ketnini aadi uchaaran keejeeai |","meaning_en":"First say 'Nar ketanini' ('whose home is water', with -ni);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਪੁਨਿ ਨਾਇਕ ਪਦ ਦੀਜੀਐ।","roman":"Jaa char kahi kai puni naaik pad deejeeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੮੯੬।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 896 |","meaning_en":"O skilled one, regard all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"verse","number":[897],"number_text":"੮੯੭।","page":989,"lines":[{"gurmukhi":"ਜਲ ਬਾਸਨਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Jal baasannee aadi uchaaran keejeeai |","meaning_en":"First say 'Jal basanani' ('dweller in water', with -ni);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਪੁਨਿ ਦੀਜੀਐ।","roman":"Jaa char kahi kai naath sabad puni deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kahu taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":989,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ।੮੯੭।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 897 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":989,"meaning_status":"draft"},{"type":"verse","number":[898],"number_text":"੮੯੮।","page":989,"lines":[{"gurmukhi":"ਜਲ ਕੇਤਨਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Jal ketannee aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Jal ketanani' ('whose home is water', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":989,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਖਿ ਲਿਜੈ। ੮੯੮।","roman":"Satroo sabad kah bahuri bhanijai | sabh sree naam tupak lakhi lijai | 898 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":989,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":990,"meaning_status":"draft"},{"type":"verse","number":[899],"number_text":"੮੯੯।","page":990,"lines":[{"gurmukhi":"ਜਲ ਬਾਸਨਨੀ ਆਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Jal baasannee aadi bakhaanan keejeeai |","meaning_en":"First say 'Jal basanani' ('dweller in water', with -ni);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਪੁਨਿ ਦੀਜੀਐ।","roman":"Jaa char kahi kai naath sabad puni deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":990,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪ੍ਰਮਾਨੀਐ।੮੯੯।","roman":"Ho sakal tupak ke naam prabeen pramaaneeai | 899 |","meaning_en":"O skilled one, accept all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":990,"meaning_status":"draft"},{"type":"verse","number":[900],"number_text":"੯੦੦।","page":990,"lines":[{"gurmukhi":"ਜਲ ਧਾਮਨਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Jal dhaamannee aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Jal dhamanani' ('whose abode is water', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਖਿ ਲਿਜੈ। ੯੦੦।","roman":"Satroo kahu bahuri bhanijai | sabh sree naam tupak lakhi lijai | 900 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[901],"number_text":"੯੦੧।","page":990,"lines":[{"gurmukhi":"ਜਲਗ੍ਰਿਹਨਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Jalgrihannee aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Jalgrihanani' ('whose house is water', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਖਿ ਲਿਜੈ। ੯੦੧।","roman":"Satroo sabad kahu bahuri bhanijai | sabh sree naam tupak lakhi lijai | 901 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[902],"number_text":"੯੦੨।","page":990,"lines":[{"gurmukhi":"ਜਲ ਬਾਸਨਨੀ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਧਰੀਐ।","roman":"Jal baasannee aadi uchreeai | jaa char kahi naaik pad dhareeai |","meaning_en":"First say 'Jal basanani' ('dweller in water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਮਾਨਹੁ। ੯੦੨।","roman":"Satroo sabad kahu anti bakhaanhu | sabh sree naam tupak ke maanhu | 902 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[903],"number_text":"੯੦੩।","page":990,"lines":[{"gurmukhi":"ਜਲ ਸੰਕੇਤਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Jal sanketni aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Jal sanketani'; then say 'ja char' and add the word 'pati' (lord);","page":990,"meaning_status":"draft","note":"ਸੰਕੇਤਨਿ: probably for ketan, 'home' (water-dweller); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੦੩।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sabh lahi lijai | 903 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[904],"number_text":"੯੦੪।","page":990,"lines":[{"gurmukhi":"ਬਾਰ ਧਾਮਨੀ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਸਬਦੇਸ ਕਹਿਜੈ।","roman":"Baar dhaamnee aadi bhanijai | jaa char kahi sabdes kahijai |","meaning_en":"First say 'Bar dhamani' ('whose abode is water', with -ni); then say 'ja char' and add the word 'is' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੦੪।","roman":"Satroo sabad kahu bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 904 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[905],"number_text":"੯੦੫।","page":990,"lines":[{"gurmukhi":"ਬਾਰ ਗ੍ਰਿਹਨਨੀ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Baar grihannee aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Bar grihanani' ('whose house is water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੦੫।","roman":"Satroo sabad kahu bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 905 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":990,"meaning_status":"draft"},{"type":"verse","number":[906],"number_text":"੯੦੬।","page":990,"lines":[{"gurmukhi":"ਮੇਘ ਜਨਿਨਿ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Megh janini sabdaadi uchaaran keejeeai |","meaning_en":"First say the word 'Megh janini' ('born of clouds', with -ni);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕਰਿ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Jaa char kahi kari naath sabad ko deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kahu taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":990,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਬਿਚਾਰੀਐ।੯੦੬।","roman":"Ho sakal tupak ke naam prabeen bichaareeai | 906 |","meaning_en":"O skilled one, regard all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":990,"meaning_status":"draft"},{"type":"verse","number":[907],"number_text":"੯੦੭।","page":990,"lines":[{"gurmukhi":"ਸਾਰਸੁਤੀ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Saarsutee sabdaadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say the word 'Sarsuti' (the Saraswati river); then say 'ja char' and add the word 'nayak' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੦੭।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sabh lahi lijai | 907 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[908],"number_text":"੯੦੮।","page":990,"lines":[{"gurmukhi":"ਗੰਗ ਭੇਟਨੀ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Gang bhetnee aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Gang bhetani' ('she who meets the Ganga', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":990,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਕਹਿਜੈ। ੯੦੮।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sakal kahijai | 908 |","meaning_en":"then say the word 'shatru' (enemy); call all these names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[909],"number_text":"੯੦੯।","page":990,"lines":[{"gurmukhi":"ਅਰੁਣਿ ਬਾਰਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨਹੁ।","roman":"Aruni baarnini aadi bakhaanhu | jaa char kahi naaik pad thaanhu |","meaning_en":"First say 'Aruni baranini' ('red water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":990,"meaning_status":"draft","note":"ਅਰੁਣ ... ('red water'): which river is meant is not stated; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰਹੁ। ੯੦੯।","roman":"Satroo sabad ko bahuri uchaarhu | naam tupak ke sakal bichaarhu | 909 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":990,"meaning_status":"draft"}]},{"type":"verse","number":[910],"number_text":"੯੧੦।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਬਾਰਿਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Arun baarinee aadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say 'Arun barini' ('red water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰੋ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਾਰੋ। ੯੧੦।","roman":"Satroo sabad kahu bahuri uchaaro | sakal tupak ke naam bichaaro | 910 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":991,"meaning_status":"draft"},{"type":"verse","number":[911],"number_text":"੯੧੧।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਅੰਬੁਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Arun anbunini aadi uchaaran keejeeai |","meaning_en":"First say 'Arun ambunini' ('red water', with -ni);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Jaa char kahi kai naath sabad ko deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":991,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ।੯੧੧।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 911 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":991,"meaning_status":"draft"},{"type":"verse","number":[912],"number_text":"੯੧੨।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਤਰੰਗਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Arun tarangni aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Arun tarangani' ('red waves', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹਿਜੈ। ੯੧੨।","roman":"Satroo sabad kahu bahuri bhanijai | sakal tupak ke naam kahijai | 912 |","meaning_en":"then say the word 'shatru' (enemy); call all these names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[913],"number_text":"੯੧੩।","page":991,"lines":[{"gurmukhi":"ਆਰਕਤਾ ਜਲਨਿਨਿ ਪਦ ਭਾਖੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Aaraktaa jalnini pad bhaakho | jaa char kahi naaik pad raakho |","meaning_en":"Say the word 'Arakta jalanini' ('red water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਖਿ ਲਿਜੈ। ੯੧੩।","roman":"Satroo sabad kahu bahuri bhanijai | sabh sree naam tupak lakhi lijai | 913 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[914],"number_text":"੯੧੪।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਅੰਬੁਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Arun anbunini aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Arun ambunini' ('red water', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੯੧੪।","roman":"Satroo sabad kahu bahuri uchaaro | naam tupak ke sakal bichaaro | 914 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[915],"number_text":"੯੧੫।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਪਾਨਿਨੀ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Arun paaninee aadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Arun panini' ('red water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਆ ਜਾਨੋ। ੯੧੫।","roman":"Ari pad taa ke anti bakhaano | naam tupak ke sabh jeeaa jaano | 915 |","meaning_en":"add the word 'ari' (enemy) at the end; know all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[916],"number_text":"੯੧੬।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਜਲਨਿਨੀ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Arun jalninee aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Arun jalanini' ('red water', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਖਿ ਲਿਜੈ। ੯੧੬।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sabh lakhi lijai | 916 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[917],"number_text":"੯੧੭।","page":991,"lines":[{"gurmukhi":"ਅਰੁਣ ਨੀਰਨਿਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Arun neernini aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Arun niranini' ('red water', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੧੭।","roman":"Satroo sabad kahu bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 917 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[918],"number_text":"੯੧੮।","page":991,"lines":[{"gurmukhi":"ਸਤਦ੍ਰਵਨਿਨੀ ਪ੍ਰਿਥਮ ਪ੍ਰਕਾਸੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Satdravninee pritham prakaaso | jaa char kahi naaik pad raakho |","meaning_en":"First declare 'Satdravanini' ('flowing in a hundred streams', the Sutlej, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft","note":"ਸਤਦ੍ਰਵ: read as Shatadru, the Sutlej; uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਉਚਰੀਐ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਰੀਐ। ੯੧੮।","roman":"Ari pad taa ke anti uchreeai | sakal tupak ke naam bichreeai | 918 |","meaning_en":"add the word 'ari' (enemy) at the end; regard all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[919],"number_text":"੯੧੯।","page":991,"lines":[{"gurmukhi":"ਸਤ ਪ੍ਰਵਾਹਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨਹੁ।","roman":"Sat pravaahnini aadi bakhaanhu | jaa char kahi naaik pad thaanhu |","meaning_en":"First say 'Sat pravahanini' ('of a hundred currents', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":991,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੯੧੯।","roman":"Satroo sabad kahu bahuri uchaaro | naam tupak ke sakal bichaaro | 919 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"verse","number":[920],"number_text":"੯੨੦।","page":991,"lines":[{"gurmukhi":"ਸਹਸ ਨਾਰਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Sahas naarnini aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say 'Sahas naranini' ('of a thousand waters', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":991,"meaning_status":"draft","note":"ਸਹਸ ਨਾਰ: 'thousand waters/streams'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੇ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੨੦।","roman":"Satroo sabad ke bahuri bhanijai | naam tupak ke sabh lahi lijai | 920 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":991,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":992,"meaning_status":"draft"},{"type":"verse","number":[921],"number_text":"੯੨੧।","page":992,"lines":[{"gurmukhi":"ਸਤ ਦ੍ਰਵਨਨਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Sat dravannini aadi uchaaran keejeeai |","meaning_en":"First say 'Sat dravananini' ('flowing in a hundred streams', with -ni);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਕਹੁ ਦੀਜੀਐ।","roman":"Jaa char kahi kai naath sabad kahu deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਕੋ ਤਾ ਕੇ ਪੁਨਿ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Ripu pad ko taa ke puni anti bakhaaneeai |","meaning_en":"add the word 'ripu' (enemy) at the end;","page":992,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਛਾਨੀਐ।੯੨੧।","roman":"Ho sakal tupak ke naam subudhi pachhaaneeai | 921 |","meaning_en":"O wise one, recognise all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":992,"meaning_status":"draft"},{"type":"verse","number":[922],"number_text":"੯੨੨।","page":992,"lines":[{"gurmukhi":"ਸਤ ਪ੍ਰਵਾਹਨਿਨਿ ਪ੍ਰਥਮ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Sat pravaahnini pratham bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Sat pravahanini' ('of a hundred currents', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੨੨।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sabh lahi lijai | 922 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[923],"number_text":"੯੨੩।","page":992,"lines":[{"gurmukhi":"ਸਤਾ ਗਾਮਿਨੀ ਪ੍ਰਥਮ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Sataa gaaminee pratham bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say 'Sata gamini' ('going in a hundred ways'); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੯੨੩।","roman":"Satroo sabad kahu bahuri bakhaanhu | sakal tupak ke naam pramaanhu | 923 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[924],"number_text":"੯੨੪।","page":992,"lines":[{"gurmukhi":"ਸਤ ਤਰੰਗਨਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Sat taranganni aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Sat taranganani' ('of a hundred waves', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਿ ਸਬਦ ਤਾ ਕੇ ਅਰਿ ਕਹੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਲਹੀਐ। ੯੨੪।","roman":"Anti sabad taa ke ari kaheeai | naam tupak ke sabh jeea laheeai | 924 |","meaning_en":"add the word 'ari' (enemy) at the end; understand all these as names of the gun (tupak) in your heart.","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[925],"number_text":"੯੨੫।","page":992,"lines":[{"gurmukhi":"ਭੂਮਿ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Bhoomi sabad ko aadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say the word 'Bhumi' (earth); then say 'ja char' and add the word 'pati' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬੀਚਾਰਹੁ। ੯੨੫।","roman":"Satroo sabad ko bahuri uchaarhu | naam tupak ke sakal beechaarhu | 925 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[926],"number_text":"੯੨੬।","page":992,"lines":[{"gurmukhi":"ਆਦਿ ਬਿਆਸਨਿਨੀ ਪਦ ਭਾਖੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Aadi biaasninee pad bhaakho | jaa char kahi naaik pad raakho |","meaning_en":"First say the word 'Biasanini' (the Beas, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ੯੨੬।","roman":"Satroo sabad ko bahuri bakhaanhu | sakal tupak ke naam pachhaanhu | 926 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[927],"number_text":"੯੨੭।","page":992,"lines":[{"gurmukhi":"ਬਿਅਹਨਨੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Biahannee sabdaadi bhanijai | jaa char kahi naaik pad dijai |","meaning_en":"First say the word 'Biahanani'; then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft","note":"ਬਿਅਹਨਨੀ: probably the Beas again (Biah); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਾਰਹੁ। ੯੨੭।","roman":"Satroo sabad kahu bahuri uchaarhu | sakal tupak ke naam bichaarhu | 927 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[928],"number_text":"੯੨੮।","page":992,"lines":[{"gurmukhi":"ਪਾਸ ਸਕਤਿਨਨਿ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਧਰੀਐ।","roman":"Paas saktinni aadi uchreeai | jaa char kahi naaik pad dhareeai |","meaning_en":"First say 'Pas saktinani' (pas = noose); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft","note":"ਪਾਸ ਸਕਤਿ: perhaps 'free of the noose' (Vipasha, the Beas); uncertain."},{"gurmukhi":"ਰਿਪੁ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਭਣਿਜੈ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹਿਜੈ। ੯੨੮।","roman":"Ripu pad taa ke anti bhanijai | sakal tupak ke naam kahijai | 928 |","meaning_en":"add the word 'ripu' (enemy) at the end; call all these names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[929],"number_text":"੯੨੯।","page":992,"lines":[{"gurmukhi":"ਪਾਸ ਨਾਸਨਿਨਿ ਆਦਿ ਬਖਨੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਨੀਐ।","roman":"Paas naasnini aadi bakhneeai | jaa char kahi naaik pad thaneeai |","meaning_en":"First say 'Pas nasanini' ('destroyer of the noose', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਰੀਐ। ੯੨੯।","roman":"Satroo sabad ko bahuri uchreeai | sakal tupak ke naam bichreeai | 929 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[930],"number_text":"੯੩੦।","page":992,"lines":[{"gurmukhi":"ਬਰੁਣਾਇਧ ਨਾਸਨਨਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨਹੁ।","roman":"Barunaaidh naasanni bakhaanhu | jaa char kahi naaik pad thaanhu |","meaning_en":"Say 'Barunaidh nasanani' ('destroyer of Varun's weapon', the noose, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹਿਜੈ। ੯੩੦।","roman":"Satroo sabad ko bahuri bhanijai | sakal tupak ke naam kahijai | 930 |","meaning_en":"then say the word 'shatru' (enemy); call all these names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[931],"number_text":"੯੩੧।","page":992,"lines":[{"gurmukhi":"ਜਲਿਸਨ ਆਯੁਧ ਨਾਮ ਕਹੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Jalisan aayudh naam kaheejai | jaa char kahi naaik pad deejai |","meaning_en":"Say the name of the weapon of the lord of water (Varun, i.e. the noose); then say 'ja char' and add the word 'nayak' (lord);","page":992,"meaning_status":"draft","note":"ਜਲਿਸਨ ਆਯੁਧ: 'weapon of the lord of the waters' (Varun's noose); apparently 'destroyer' is to be understood; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੯੩੧।","roman":"Satroo sabad ko bahuri bakhaanhu | sakal tupak ke naam pramaanhu | 931 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":992,"meaning_status":"draft"},{"type":"verse","number":[932],"number_text":"੯੩੨।","page":992,"lines":[{"gurmukhi":"ਸਕਲ ਪਾਸਿ ਲੈ ਨਾਮ ਨਾਸਨਿਨਿ ਭਾਖੀਐ।","roman":"Sakal paasi lai naam naasnini bhaakheeai |","meaning_en":"Take any name of the noose and say 'nasanini' (destroyer, with -ni);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਬਹੁਰਿ ਪਦ ਰਾਖੀਐ।","roman":"Jaa char kahi kai naath bahuri pad raakheeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":992,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":992,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਛਾਨੀਐ।੯੩੨।","roman":"Ho sakal tupak ke naam subudhi pachhaaneeai | 932 |","meaning_en":"O wise one, recognise all these as names of the gun (tupak).","page":992,"meaning_status":"draft"}]},{"type":"verse","number":[933],"number_text":"੯੩੩।","page":993,"lines":[{"gurmukhi":"ਰਾਵਿਨਨੀ ਸਬਦਾਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Raavinnee sabdaadi bakhaanan keejeeai |","meaning_en":"First say the word 'Ravinani' (the Ravi, with -ni);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਪੁਨਿ ਦੀਜੀਐ।","roman":"Jaa char kahi kai naath sabad puni deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":993,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮੁ ਸੁਬੀਰ ਪਛਾਨੀਐ।੯੩੩।","roman":"Ho sakal tupak ke naamu subeer pachhaaneeai | 933 |","meaning_en":"O brave one, recognise all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":993,"meaning_status":"draft"},{"type":"verse","number":[934],"number_text":"੯੩੪।","page":993,"lines":[{"gurmukhi":"ਰਾਵਿਨੀਨਿ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਕਹਿਜੈ।","roman":"Raavineeni sabdaadi bhanijai | jaa char kahi pati sabad kahijai |","meaning_en":"First say the word 'Ravinini' (the Ravi, with -ni); then say 'ja char' and add the word 'pati' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ੯੩੪।","roman":"Satroo sabad kahu bahuri bakhaanhu | sakal tupak ke naam pachhaanhu | 934 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"verse","number":[935],"number_text":"੯੩੫।","page":993,"lines":[{"gurmukhi":"ਚੰਦ੍ਰ ਭਗਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Chandr bhagnini aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Chandra bhaganini' ('sister of the moon', Chandrabhaga, with -ni); then say 'ja char' and add the word 'pati' (lord);","page":993,"meaning_status":"draft","note":"ਚੰਦ੍ਰ ਭਗਨਿ: read as Chandrabhaga, the Chenab; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰਹੁ। ੯੩੫।","roman":"Satroo sabad kahu bahuri uchaarhu | naam tupak ke sakal bichaarhu | 935 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"verse","number":[936],"number_text":"੯੩੬।","page":993,"lines":[{"gurmukhi":"ਸਸਿ ਭਗਨਿਨਿ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Sasi bhagnini sabdaadi bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"First say the word 'Sasi bhaganini' ('sister of the moon', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੩੬।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sabh lahi lijai | 936 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"verse","number":[937],"number_text":"੯੩੭।","page":993,"lines":[{"gurmukhi":"ਚੰਦ੍ਰਨੁਜਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਸੁ ਠਾਨਹੁ।","roman":"Chandranujnini aadi bakhaanhu | jaa char kahi pati sabad su thaanhu |","meaning_en":"First say 'Chandranujanini' ('younger sister of the moon', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰੋ ਧਰੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਰੀਐ। ੯੩੭।","roman":"Satroo sabad kahu bahuro dhareeai | naam tupak ke sakal bichreeai | 937 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":993,"meaning_status":"draft"},{"type":"verse","number":[938],"number_text":"੯੩੮।","page":993,"lines":[{"gurmukhi":"ਸਸਿ ਅਨੁਜਨਿਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Sasi anujninee aadi uchaaran keejeeai |","meaning_en":"First say 'Sasi anujanini' ('younger sister of the moon', with -ni);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Jaa char kahi kai naath sabad ko deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":993,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ।੯੩੮।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 938 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":993,"meaning_status":"draft"},{"type":"verse","number":[939],"number_text":"੯੩੯।","page":993,"lines":[{"gurmukhi":"ਮਯੰਕ ਅਨੁਜਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Mayank anujnini aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Mayank anujanini' ('younger sister of the moon', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੩੯।","roman":"Ari pad anti tavan ke dijai | naam tupak ke sabh lahi lijai | 939 |","meaning_en":"add the word 'ari' (enemy) at the end; understand all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":993,"meaning_status":"draft"},{"type":"verse","number":[940],"number_text":"੯੪੦।","page":993,"lines":[{"gurmukhi":"ਮਯੰਕ ਸਹੋਦਰਨਿਨਿ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Mayank sahodarnini sabdaadi bakhaaneeai |","meaning_en":"First say the word 'Mayank sahodaranini' ('sibling of the moon', with -ni);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕਰਿ ਨਾਥ ਸਬਦ ਕਹੁ ਠਾਨੀਐ।","roman":"Jaa char kahi kari naath sabad kahu thaaneeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":993,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Satroo sabad kahu taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":993,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਕਬਿ ਲਹਿ ਲੀਜੀਐ।੯੪੦।","roman":"Ho sakal tupak ke naam su kabi lahi leejeeai | 940 |","meaning_en":"O good poet, understand all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":993,"meaning_status":"draft"},{"type":"verse","number":[941],"number_text":"੯੪੧।","page":993,"lines":[{"gurmukhi":"ਅਜ ਅਨੁਜਨਨਿਨਿ ਆਦਿ ਕਹਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਭਣਿਜੈ।","roman":"Aj anujannini aadi kahijai | jaa char kahi pati sabad bhanijai |","meaning_en":"First say 'Aj anujananini'; then say 'ja char' and add the word 'pati' (lord);","page":993,"meaning_status":"draft","note":"ਅਜ: here apparently a name of the moon ('younger sister of the moon'); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਅੰਤਿ ਉਚਾਰਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਾਰਹੁ। ੯੪੧।","roman":"Satroo sabad kahu anti uchaarhu | sakal tupak ke naam bichaarhu | 941 |","meaning_en":"add the word 'shatru' (enemy) at the end; regard all these as names of the gun (tupak).","page":993,"meaning_status":"draft"}]},{"type":"verse","number":[942],"number_text":"੯੪੨।","page":994,"lines":[{"gurmukhi":"ਨਿਸਿਸ ਅਨੁਜਨਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦਿ ਪ੍ਰਮਾਨਹੁ।","roman":"Nisis anujannini aadi bakhaanhu | jaa char kahi pati sabdi pramaanhu |","meaning_en":"First say 'Nisis anujananini' ('younger sister of the lord of night', the moon); then say 'ja char' and add the word 'pati' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਰੀਐ। ੯੪੨।","roman":"Satroo sabad ko bahuri uchreeai | sakal tupak ke naam bichreeai | 942 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[943],"number_text":"੯੪੩।","page":994,"lines":[{"gurmukhi":"ਨਿਸਿ ਇਸਰਨਨਿਨਿ ਆਦਿ ਕਹਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਭਣਿਜੈ।","roman":"Nisi isrannini aadi kahijai | jaa char kahi pati sabad bhanijai |","meaning_en":"First say 'Nisi isarananini' ('lord of night', the moon, with -ni); then say 'ja char' and add the word 'pati' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ੯੪੩।","roman":"Satroo sabad kahu bahuri bakhaanhu | sakal tupak ke naam pachhaanhu | 943 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[944],"number_text":"੯੪੪।","page":994,"lines":[{"gurmukhi":"ਰੈਨਾਧਿਪਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Rainaadhipnee aadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say 'Rainadhipani' ('lord of night', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਖਿ ਲਿਜੈ। ੯੪੪।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sabh lakhi lijai | 944 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[945],"number_text":"੯੪੫।","page":994,"lines":[{"gurmukhi":"ਰੈਨ ਰਾਟਨਿਨਿ ਆਦਿ ਉਚਰੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਧਰੀਐ।","roman":"Rain raatnini aadi uchreeai | jaa char kahi naaik pad dhareeai |","meaning_en":"First say 'Rain ratanini' ('king of night', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨਹੁ। ੯੪੫।","roman":"Satroo sabad kahu bahuri bakhaanhu | naam tupak ke sabh jeea jaanhu | 945 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak) in your heart.","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[946],"number_text":"੯੪੬।","page":994,"lines":[{"gurmukhi":"ਰੈਨਰਾਜਨੀ ਆਦਿ ਕਹਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਭਣਿਜੈ।","roman":"Rainraajnee aadi kahijai | jaa char kahi pati sabad bhanijai |","meaning_en":"First say 'Rainrajani' ('king of night', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਕਹੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਲਹੀਐ। ੯੪੬।","roman":"Taa ke anti satroo pad kaheeai | naam tupak ke sabh jeea laheeai | 946 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak) in your heart.","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[947],"number_text":"੯੪੭।","page":994,"lines":[{"gurmukhi":"ਨਿਸ ਨਾਇਕਨਿਨਿ ਆਦਿ ਉਚਰੀਐ। ਸੂਨ ਉਚਰਿ ਚਰ ਪਤਿ ਪਦ ਡਰੀਐ।","roman":"Nis naaiknini aadi uchreeai | soon uchri char pati pad dareeai |","meaning_en":"First say 'Nis nayakanini' ('lord of night', with -ni); say 'sun' (son), then put 'char' and the word 'pati' (lord);","page":994,"meaning_status":"draft","note":"ਸੂਨ ਉਚਰਿ ਚਰ: 'sun char', a variant of 'sut char'; uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੯੪੭।","roman":"Ari pad taa ke anti bakhaanhu | sakal tupak ke naam pramaanhu | 947 |","meaning_en":"add the word 'ari' (enemy) at the end; accept all these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[948],"number_text":"੯੪੮।","page":994,"lines":[{"gurmukhi":"ਨਿਸਿਇਸਨੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Nisi'isnee sabdaadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say the word 'Nisiisani' ('lord of night', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਸੁਕਬਿ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਾਰਹੁ। ੯੪੮।","roman":"Satroo sabad kahu bahuri uchaarhu | sukbi tupak ke naam bichaarhu | 948 |","meaning_en":"then say the word 'shatru' (enemy); O good poet, regard these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[949],"number_text":"੯੪੯।","page":994,"lines":[{"gurmukhi":"ਨਿਸਿ ਪਤਿਨਿਨਿ ਸਬਦਾਦਿ ਉਚਰੀਐ। ਸੁਤ ਚਰ ਅਰਿ ਅੰਤਹਿ ਪਦ ਧਰੀਐ।","roman":"Nisi patinini sabdaadi uchreeai | sut char ari anthi pad dhareeai |","meaning_en":"First say the word 'Nisi patinini' ('lord of night', with -ni); put 'sut char' and the word 'ari' (enemy) at the end;","page":994,"meaning_status":"draft","note":"No word for 'lord' appears in this line; printed so; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਅੰਤਿ ਬਖਾਨਹੁ। ਸੁਕਬਿ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ੯੪੯।","roman":"Satroo sabad kahu anti bakhaanhu | sukbi tupak ke naam pachhaanhu | 949 |","meaning_en":"add the word 'shatru' (enemy) at the end; O good poet, recognise these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[950],"number_text":"੯੫੦।","page":994,"lines":[{"gurmukhi":"ਨਿਸ ਧਨਿਨੀ ਸਬਦਾਦਿ ਕਹਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਅਰਿ ਪਦਹਿ ਭਣਿਜੈ।","roman":"Nis dhaninee sabdaadi kahijai | jaa char kahi ari padhi bhanijai |","meaning_en":"First say the word 'Nis dhanini' ('master of night', with -ni); then say 'ja char' and then the word 'ari' (enemy);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨਹੁ। ੯੫੦।","roman":"Satroo sabad kahu bahuri bakhaanhu | naam tupak ke sabh jeea jaanhu | 950 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak) in your heart.","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[951],"number_text":"੯੫੧।","page":994,"lines":[{"gurmukhi":"ਰੈਨ ਨਾਇਕਨਿ ਆਦਿ ਸੁ ਕਹੀਐ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਦੈ ਰਹੀਐ।","roman":"Rain naaikni aadi su kaheeai | jaa char kahi pati pad dai raheeai |","meaning_en":"First say 'Rain nayakani' ('lord of night', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":994,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਭਾਖਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਖਿ ਰਾਖਹੁ। ੯੫੧।","roman":"Taa ke anti satroo pad bhaakhhu | naam tupak ke sabh lakhi raakhhu | 951 |","meaning_en":"add the word 'shatru' (enemy) at the end; keep all these in mind as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[952],"number_text":"੯੫੨।","page":994,"lines":[{"gurmukhi":"ਨਿਸ ਚਰਨਿਨਿ ਪ੍ਰਥਮੈ ਪਦ ਭਾਖਹੁ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪੁਨਿ ਰਾਖਹੁ।","roman":"Nis charnini prathmai pad bhaakhhu | sut char kahi naaik puni raakhhu |","meaning_en":"First say the word 'Nis charanini' ('night-goer', with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":994,"meaning_status":"draft","note":"ਨਿਸ ਚਰ: 'night-goer', here apparently the moon; uncertain. 'sut char': lit. 'son' + 'moving'; it takes the place of 'ja char' in these verses; exact sense unclear."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ੯੫੨।","roman":"Satroo sabad kahu bahuri bakhaanhu | sakal tupak ke naam pachhaanhu | 952 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[953],"number_text":"੯੫੩।","page":994,"lines":[{"gurmukhi":"ਆਦਿ ਨਿਸਾਚਰਿਨਨਿ ਕਹੁ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Aadi nisaachrinni kahu bhaakho | sut char kahi naaik pad raakho |","meaning_en":"First say 'Nisacharinani' ('night-goer', with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":994,"meaning_status":"draft","note":"ਨਿਸਾਚਰ: 'night-goer', here apparently the moon; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹਿਜੈ। ੯੫੩।","roman":"Satroo sabad kahu bahuri bhanijai | sakal tupak ke naam kahijai | 953 |","meaning_en":"then say the word 'shatru' (enemy); call all these names of the gun (tupak).","page":994,"meaning_status":"draft"}]},{"type":"verse","number":[954],"number_text":"੯੫੪।","page":995,"lines":[{"gurmukhi":"ਰੈਨ ਰਮਨਿ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਕਹਿਜੈ।","roman":"Rain ramni sabdaadi bhanijai | sut char kahi pati sabad kahijai |","meaning_en":"First say the word 'Rain ramani' ('husband of night', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੯੫੪।","roman":"Satroo sabad ko anti bakhaanhu | sakal tupak ke naam pramaanhu | 954 |","meaning_en":"add the word 'shatru' (enemy) at the end; accept all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[955],"number_text":"੯੫੫।","page":995,"lines":[{"gurmukhi":"ਰੈਨ ਰਾਜਨਿਨਿ ਪ੍ਰਥਮ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਪਦਹਿ ਸਵਾਰੋ।","roman":"Rain raajnini pratham uchaaro | sut char kahi pati padhi savaaro |","meaning_en":"First say 'Rain rajanini' ('king of night', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਕਹੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਹੀ ਲਹੀਐ। ੯੫੫।","roman":"Taa ke anti satroo pad kaheeai | naam tupak ke sabh hee laheeai | 955 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[956],"number_text":"੯੫੬।","page":995,"lines":[{"gurmukhi":"ਨਿਸਾਰਵਨਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Nisaaravnini aadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say 'Nisaravanini' ('husband of night', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਾ ਪਾਛੇ ਕਹੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ੯੫੬।","roman":"Satroo sabad taa paachhe kaheeai | sabh sree naam tupak ke laheeai | 956 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[957],"number_text":"੯੫੭।","page":995,"lines":[{"gurmukhi":"ਦਿਨ ਅਰਿ ਰਵਨਿਨਿ ਆਦਿ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਬਿਚਾਰੋ।","roman":"Din ari ravnini aadi uchaaro | sut char kahi pati sabad bichaaro |","meaning_en":"First say 'Din ari ravanini' ('husband of the enemy of day', i.e. of night, with -ni); then say 'sut char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਭਾਖੋ। ਨਾਮ ਤੁਪਕ ਜੂ ਕੇ ਲਖਿ ਰਾਖੋ। ੯੫੭।","roman":"Taa ke anti satroo pad bhaakho | naam tupak joo ke lakhi raakho | 957 |","meaning_en":"add the word 'shatru' (enemy) at the end; keep these in mind as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[958],"number_text":"੯੫੮।","page":995,"lines":[{"gurmukhi":"ਹਰਿਜ ਅਰਿ ਰਵਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Harij ari ravnini aadi bakhaano | sut char kahi pati sabad pramaano |","meaning_en":"First say 'Harij ari ravanini'; then say 'sut char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft","note":"ਹਰਿਜ ਅਰਿ ਰਵਨਿ: perhaps 'husband of the enemy of the sun-born (day)', i.e. of night; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਕਹੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੋ। ੯੫੮।","roman":"Taa ke anti satroo pad kaho | sabh sree naam tupak ke laho | 958 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[959],"number_text":"੯੫੯।","page":995,"lines":[{"gurmukhi":"ਤਿਮ੍ਰਿਯਰਿ ਸੋ ਰਵਨਨਿ ਪਦ ਕਹੀਐ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਗਹੀਐ।","roman":"Timriyri so ravanni pad kaheeai | sut char kahi naaik pad gaheeai |","meaning_en":"Say 'Timriyari' with the word 'ravanani' (husband, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":995,"meaning_status":"draft","note":"ਤਿਮ੍ਰਿਯਰਿ: printed so; meaning of the compound unclear; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਕਹਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੫੯।","roman":"Satroo sabad tih anti kahijai | naam tupak ke sabh lahi lijai | 959 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[960],"number_text":"੯੬੦।","page":995,"lines":[{"gurmukhi":"ਹਰਿਜਰਿ ਰਵਨਿਨਿ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Harijri ravnini aadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say 'Harijari ravanini'; then say 'ja char' and add the word 'nayak' (lord);","page":995,"meaning_status":"draft","note":"ਹਰਿਜਰਿ: read as harij + ari, as in the line above; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਰੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸੁਕਬਿ ਬਿਚਰੀਐ। ੯੬੦।","roman":"Satroo sabad kahu bahuri uchreeai | naam tupak ke sukbi bichreeai | 960 |","meaning_en":"then say the word 'shatru' (enemy); O good poet, regard these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[961],"number_text":"੯੬੧।","page":995,"lines":[{"gurmukhi":"ਰਵਿਜਰਿ ਰਵਨਿਨਿ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Ravijri ravnini aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Ravijari ravanini'; then say 'ja char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft","note":"ਰਵਿਜਰਿ: read as ravij ('sun-born', day) + ari, i.e. night; ravan = husband; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰੋ ਭਾਖਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਖਿ ਰਾਖਹੁ। ੯੬੧।","roman":"Satroo sabad kahu bahuro bhaakhhu | sabh sree naam tupak lakhi raakhhu | 961 |","meaning_en":"then say the word 'shatru' (enemy); keep all these in mind as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[962],"number_text":"੯੬੨।","page":995,"lines":[{"gurmukhi":"ਭਾਨੁਜ ਅਰਿ ਕਹਿ ਰਵਨਿ ਭਨੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Bhaanuj ari kahi ravni bhaneejai | jaa char kahi naaik pad deejai |","meaning_en":"Say 'Bhanuj ari', then say 'ravani' (husband, with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":995,"meaning_status":"draft","note":"ਭਾਨੁਜ ਅਰਿ: 'enemy of the sun-born', taken as night; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੬੨।","roman":"Satroo sabad kahu bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 962 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[963],"number_text":"੯੬੩।","page":995,"lines":[{"gurmukhi":"ਸੂਰਜਰਿ ਰਵਨਿ ਆਦਿ ਪਦ ਕਹੀਐ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਗਹੀਐ।","roman":"Soorajri ravni aadi pad kaheeai | jaa char kahi naaik pad gaheeai |","meaning_en":"First say the word 'Surjari ravani'; then say 'ja char' and add the word 'nayak' (lord);","page":995,"meaning_status":"draft","note":"ਸੂਰਜਰਿ: read as suraj + ari ('enemy of the sun'), i.e. night; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਧਾਰੋ। ੯੬੩।","roman":"Satroo sabad ko bahuri uchaaro | naam tupak ke sabh jeea dhaaro | 963 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[964],"number_text":"੯੬੪।","page":995,"lines":[{"gurmukhi":"ਭਾਨੁਜਾਰਿ ਰਵਨਿਨਿ ਪਦ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਪੁਨਿ ਰਾਖੋ।","roman":"Bhaanujaari ravnini pad bhaakho | sut char kahi pati pad puni raakho |","meaning_en":"Say the word 'Bhanujari ravanini'; then say 'sut char' and add the word 'pati' (lord);","page":995,"meaning_status":"draft","note":"ਭਾਨੁਜਾਰਿ: 'enemy of the sun-born', taken as night; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪ੍ਰਮਾਨਹੁ। ੯੬੪।","roman":"Satroo sabad kahu bahuri bakhaanhu | naam tupak ke sakal pramaanhu | 964 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":995,"meaning_status":"draft"},{"type":"verse","number":[965],"number_text":"੯੬੫।","page":995,"lines":[{"gurmukhi":"ਦਿਨਧੁਜ ਅਰਿ ਰਵਨਿਨਿ ਕੋ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Dindhuj ari ravnini ko aadi uchaareeai |","meaning_en":"First say 'Dindhuj ari ravanini' ('husband of the enemy of the banner of day', with -ni);","page":995,"meaning_status":"draft","note":"ਦਿਨਧੁਜ: 'banner of the day', the sun; uncertain."},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਦੇ ਡਾਰੀਐ।","roman":"Jaa char kahi kai naath sabad de daareeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":995,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":995,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪ੍ਰਮਾਨੀਐ।੯੬੫।","roman":"Ho sakal tupak ke naam prabeen pramaaneeai | 965 |","meaning_en":"O skilled one, accept all these as names of the gun (tupak).","page":995,"meaning_status":"draft"}]},{"type":"verse","number":[966],"number_text":"੯੬੬।","page":996,"lines":[{"gurmukhi":"ਦਿਨਰਾਜਿ ਅਰਿ ਰਵਨਿਨੀ ਸੁ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Dinraaji ari ravninee su aadi bakhaaneeai |","meaning_en":"First say 'Dinraji ari ravanini' ('husband of the enemy of the king of day', with -ni);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੈ ਨਾਥ ਸਬਦ ਪੁਨਿ ਠਾਨੀਐ।","roman":"Jaa char kahi kai naath sabad puni thaaneeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kahu taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":996,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧ ਬਿਚਾਰੀਐ। ੯੬੬।","roman":"Ho sakal tupak ke naam subudh bichaareeai | 966 |","meaning_en":"regard all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":996,"meaning_status":"draft"},{"type":"verse","number":[967],"number_text":"੯੬੭।","page":996,"lines":[{"gurmukhi":"ਦਿਨਿਸ ਅਰਿ ਰਵਨਿਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Dinis ari ravnini aadi uchaaro | jaa char kahi naaik pad daaro |","meaning_en":"First say 'Dinis ari ravanini' ('husband of the enemy of the lord of day', with -ni); then say 'ja char' and add the word 'nayak' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਪੁਨਿ ਕਹਿ ਲੀਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਤੀਜੈ। ੯੬੭।","roman":"Satroo sabad kahu puni kahi leejai | naam tupak ke sakal pateejai | 967 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[968],"number_text":"੯੬੮।","page":996,"lines":[{"gurmukhi":"ਤਮ ਅਰਿ ਜਰਿ ਰਵਨਿਨਿ ਪਦ ਭਾਖੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Tam ari jari ravnini pad bhaakho | jaa char kahi naaik pad raakho |","meaning_en":"Say the word 'Tam ari jari ravanini'; then say 'ja char' and add the word 'nayak' (lord);","page":996,"meaning_status":"draft","note":"ਤਮ ਅਰਿ ਜਰਿ: printed so; perhaps tam-ari ('enemy of darkness', sun) + ja + ari; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਤਿਜੈ। ੯੬੮।","roman":"Satroo sabad tih anti bhanijai | naam tupak ke sakal patijai | 968 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[969],"number_text":"੯੬੯।","page":996,"lines":[{"gurmukhi":"ਚੰਦ੍ਰ ਜੋਨਨੀ ਆਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Chandr jonnee aadi bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"First say 'Chandra jonani'; then say 'ja char' and add the word 'nayak' (lord);","page":996,"meaning_status":"draft","note":"ਜੋਨਨੀ: perhaps 'sister' (born of the same womb as the moon); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਤਿਜੈ। ੯੬੯।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sakal patijai | 969 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[970],"number_text":"੯੭੦।","page":996,"lines":[{"gurmukhi":"ਸਸਿ ਉਪਸਖਿਨੀ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Sasi upaskhinee aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Sasi upsakhini' ('companion of the moon', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੯੭੦।","roman":"Satroo sabad ko bahuri bakhaano | sabh sree naam tupak ke jaano | 970 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[971],"number_text":"੯੭੧।","page":996,"lines":[{"gurmukhi":"ਨਿਸ ਇਸ ਭਗਨੀ ਆਦਿ ਬਖਾਨਹੁ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Nis is bhagnee aadi bakhaanhu | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say 'Nis is bhagani' ('sister of the lord of night', the moon); then say 'ja char' and add the word 'pati' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਤਿਜੈ। ੯੭੧।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sakal patijai | 971 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[972],"number_text":"੯੭੨।","page":996,"lines":[{"gurmukhi":"ਸਸਿ ਭਗਨੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Sasi bhagnee sabdaadi bakhaano | jaa char kahi pati sabad pramaanhu |","meaning_en":"First say the word 'Sasi bhagani' ('sister of the moon'); then say 'ja char' and add the word 'pati' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰਹੁ। ੯੭੨।","roman":"Satroo sabad ko bahuri uchaarhu | naam tupak ke sakal bichaarhu | 972 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[973],"number_text":"੯੭੩।","page":996,"lines":[{"gurmukhi":"ਨਿਸਿਸ ਭਗਾ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਕਹਿਜੈ।","roman":"Nisis bhagaa sabdaadi bhanijai | jaa char kahi pati sabad kahijai |","meaning_en":"First say the word 'Nisis bhaga' ('sister of the lord of night'); then say 'ja char' and add the word 'pati' (lord);","page":996,"meaning_status":"draft","note":"ਭਗਾ: read as 'sister' (bhagini); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੭੩।","roman":"Satroo sabad kahu bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 973 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[974],"number_text":"੯੭੪।","page":996,"lines":[{"gurmukhi":"ਰੈਨ ਰਾਟ ਕਹਿ ਭਗਾ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Rain raat kahi bhagaa bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"Say 'Rain rat' (king of night), then say 'bhaga' (sister); then say 'ja char' and add the word 'pati' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਤਿਜੈ। ੯੭੪।","roman":"Satroo sabad ko anti bhanijai | naam tupak ke sakal patijai | 974 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":996,"meaning_status":"draft"},{"type":"verse","number":[975],"number_text":"੯੭੫।","page":996,"lines":[{"gurmukhi":"ਰੈਨ ਰਾਵਨਿ ਕਹਿ ਭਗਾ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Rain raavni kahi bhagaa sabad bakhaaneeai |","meaning_en":"Say 'Rain ravani' (husband of night), then say the word 'bhaga' (sister);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Jaa char kahi kar naath sabad ko thaaneeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਭਨੀਜੀਐ।","roman":"Satroo sabad ko taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":996,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਹੋ ਤਹ ਦੀਜੀਐ।੯੭੫।","roman":"Ho sakal tupak ke naam chaho tah deejeeai | 975 |","meaning_en":"know all these as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"verse","number":[976],"number_text":"੯੭੬।","page":996,"lines":[{"gurmukhi":"ਰੈਨ ਰਾਜ ਕਹਿ ਭਗਾ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Rain raaj kahi bhagaa bakhaanan keejeeai |","meaning_en":"Say 'Rain raj' (king of night), then say 'bhaga' (sister);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕਰਿ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Jaa char kahi kari naath sabad ko deejeeai |","meaning_en":"then say 'ja char' and add the word 'nath' (lord);","page":996,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":996,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਮਨ ਧਾਰੀਐ।੯੭੬।","roman":"Ho sakal tupak ke naam subudhi man dhaareeai | 976 |","meaning_en":"O wise one, hold all these in mind as names of the gun (tupak).","page":996,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":997,"meaning_status":"draft"},{"type":"verse","number":[977],"number_text":"੯੭੭।","page":997,"lines":[{"gurmukhi":"ਰੈਨ ਰਾਵ ਕਹਿ ਭਗਾ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Rain raav kahi bhagaa bakhaano | jaa char kahi pati sabad pramaano |","meaning_en":"Say 'Rain rav' (king of night), then say 'bhaga' (sister); then say 'ja char' and add the word 'pati' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਜਹ ਚਹੋ ਕਹਿਜੈ। ੯੭੭।","roman":"Satroo sabad tih anti bhanijai | naam tupak jah chaho kahijai | 977 |","meaning_en":"add the word 'shatru' (enemy) at the end; say these names of the gun (tupak) wherever you wish.","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[978],"number_text":"੯੭੮।","page":997,"lines":[{"gurmukhi":"ਦਿਨ ਅਰਿ ਕਹਿ ਭਗ ਸਬਦ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Din ari kahi bhag sabad bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"Say 'Din ari' (enemy of day), then say the word 'bhag' (sister); then say 'ja char' and add the word 'nayak' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਸੁ ਕਹੀਐ। ਨਾਮ ਤੁਪਕ ਉਚਰਹੁ ਜਹ ਚਹੀਐ। ੯੭੮।","roman":"Satroo sabad tih anti su kaheeai | naam tupak ucharhu jah chaheeai | 978 |","meaning_en":"add the word 'shatru' (enemy) at the end; say these names of the gun (tupak) wherever you wish.","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[979],"number_text":"੯੭੯।","page":997,"lines":[{"gurmukhi":"ਤਮਚਰ ਕਹਿ ਭਗ ਸਬਦ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Tamchar kahi bhag sabad bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"Say 'Tamchar' (one who moves in darkness), then say the word 'bhag' (sister); then say 'ja char' and add the word 'nayak' (lord);","page":997,"meaning_status":"draft","note":"ਤਮਚਰ: 'mover in darkness', here apparently the moon; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੯੭੯।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sabh lahi lijai | 979 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[980],"number_text":"੯੮੦।","page":997,"lines":[{"gurmukhi":"ਰੈਣ ਰਾਵਿ ਕਹਿ ਭਗਣਿ ਕਹੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Rain raavi kahi bhagni kaheejai | jaa char kahi naaik pad deejai |","meaning_en":"Say 'Rain ravi' (king of night), then say 'bhagani' (sister); then say 'ja char' and add the word 'nayak' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਾਰਹੁ। ੯੮੦।","roman":"Satroo sabad ko bahuri uchaarhu | sakal tupak ke naam bichaarhu | 980 |","meaning_en":"then say the word 'shatru' (enemy); regard all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[981],"number_text":"੯੮੧।","page":997,"lines":[{"gurmukhi":"ਜਉਨ ਕਰਣ ਕਹਿ ਭਗਣਿ ਬਖਾਨੋ। ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Jaun karan kahi bhagni bakhaano | jaa char kahi naaik pad thaano |","meaning_en":"Say 'Jaun karan', then say 'bhagani' (sister); then say 'ja char' and add the word 'nayak' (lord);","page":997,"meaning_status":"draft","note":"ਜਉਨ ਕਰਣ: obscure; perhaps 'the one with cool rays' (the moon); printed so; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ੯੮੧।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sabh lahi leejai | 981 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[982],"number_text":"੯੮੨।","page":997,"lines":[{"gurmukhi":"ਕਿਰਣ ਧਰਣ ਕਹਿ ਭਗਣਿ ਕਹੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰੀਜੈ।","roman":"Kiran dharan kahi bhagni kaheejai | sut char kahi pati sabad dhareejai |","meaning_en":"Say 'Kiran dharan' (bearer of rays), then say 'bhagani' (sister); then say 'sut char' and add the word 'pati' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਅਨੁਮਾਨਹੁ। ੯੮੨।","roman":"Satroo sabad kahu bahuri bakhaanhu | naam tupak ke sabh anumaanhu | 982 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[983],"number_text":"੯੮੩।","page":997,"lines":[{"gurmukhi":"ਮਯੰਕ ਸਬਦ ਕਹਿ ਭਗਣਿ ਭਣਿਜੈ। ਸਤੁ ਚਰ ਕਹਿ ਪਦ ਨਾਥ ਧਰਿਜੈ।","roman":"Mayank sabad kahi bhagni bhanijai | satu char kahi pad naath dharijai |","meaning_en":"Say the word 'Mayank' (the moon), then say 'bhagani' (sister); then say 'sut char' and add the word 'nath' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਉਚਰੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਸੁ ਧਰੀਐ। ੯੮੩।","roman":"Satroo sabad ko bahuri uchreeai | naam tupak ke sakal su dhareeai | 983 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[984],"number_text":"੯੮੪।","page":997,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਬਾਹਨਿ ਕਹਿ ਭਗਣਿ ਬਖਾਨੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Mrig baahni kahi bhagni bakhaano | sut char kahi pati sabad pramaano |","meaning_en":"Say 'Mrig bahani' (whose mount is the deer, the moon), then say 'bhagani' (sister); then say 'sut char' and add the word 'pati' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਾਰਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਚਿਤਿ ਧਾਰਹੁ। ੯੮੪।","roman":"Satroo sabad tih anti uchaarhu | sabh sree naam tupak chiti dhaarhu | 984 |","meaning_en":"add the word 'shatru' (enemy) at the end; hold all these in mind as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[985],"number_text":"੯੮੫।","page":997,"lines":[{"gurmukhi":"ਹਿਰਣ ਰਾਟ ਕਹਿ ਭਗਣਿ ਉਚਾਰਹੁ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰਹੁ।","roman":"Hiran raat kahi bhagni uchaarhu | sut char kahi naaik pad daarhu |","meaning_en":"Say 'Hiran rat' (king/rider of the deer), then say 'bhagani' (sister); then say 'sut char' and add the word 'nayak' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ੯੮੫।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sakal lahijai | 985 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[986],"number_text":"੯੮੬।","page":997,"lines":[{"gurmukhi":"ਸ੍ਰਿੰਗ ਬਾਹਣੀ ਭਗਾ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Sring baahnee bhagaa bhanijai | jaa char kahi pati sabad dharijai |","meaning_en":"Say 'Sring bahani bhaga' ('sister of the rider of the horned one'); then say 'ja char' and add the word 'pati' (lord);","page":997,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਸ੍ਰਿੰਗ ਬਾਹਣੀ: 'whose mount is horned' (the deer), the moon; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੮੬।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 986 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[987],"number_text":"੯੮੭।","page":997,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਪਤਿਣੀ ਕਹਿ ਭਗਣਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Mrig patinee kahi bhagni bhanijai | jaa char kahi pati sabad dharijai |","meaning_en":"Say 'Mrig patini' (lord of the deer), then say 'bhagani' (sister); then say 'ja char' and add the word 'pati' (lord);","page":997,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੯੮੭।","roman":"Satroo sabad ko bahuri bakhaanhu | sakal tupak ke naam pramaanhu | 987 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"verse","number":[988],"number_text":"੯੮੮।","page":997,"lines":[{"gurmukhi":"ਪ੍ਰਜਾਪਤਿ ਕਹਿ ਭਗਣਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Prajaapti kahi bhagni bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"Say 'Prajapati' (lord of creatures), then say 'bhagani' (sister); then say 'sut char' and add the word 'pati' (lord);","page":997,"meaning_status":"draft","note":"ਪ੍ਰਜਾਪਤਿ: here apparently a name of the moon; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੯੮੮।","roman":"Satroo sabad ko bahuri bakhaanhu | sakal tupak ke naam pramaanhu | 988 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":997,"meaning_status":"draft"},{"type":"verse","number":[989],"number_text":"੯੮੯।","page":997,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਨਾਥ ਭਗਣਣਿ ਭਾਖੁ। ਰਿਪੁ ਨਾਥ ਚਰ ਪਤਿ ਰਾਖੁ।","roman":"Mrig naath bhaganni bhaakhu | ripu naath char pati raakhu |","meaning_en":"Say 'Mrig nath bhaganani' ('sister of the lord of the deer'); put 'ripu nath', 'char' and 'pati';","page":997,"meaning_status":"draft","note":"ਰਿਪੁ ਨਾਥ ਚਰ ਪਤਿ: printed so; the usual order would be '(ja) char' then 'pati'; meaning of 'ripu nath' here unclear; uncertain."},{"gurmukhi":"ਰਿਪੁ ਸਬਦ ਬਹੁਰਿ ਬਖਾਨ। ਸਭ ਨਾਮ ਤੁਪਕ ਪ੍ਰਮਾਨ। ੯੮੯।","roman":"Ripu sabad bahuri bakhaan | sabh naam tupak pramaan | 989 |","meaning_en":"then say the word 'ripu' (enemy); accept all these as names of the gun (tupak).","page":997,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":998,"meaning_status":"draft"},{"type":"verse","number":[990],"number_text":"੯੯੦।","page":998,"lines":[{"gurmukhi":"ਨਦੀ ਰਾਟ ਸੁਤ ਭਗਣਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Nadee raat sut bhagni bhanijai | jaa char kahi pati sabad dharijai |","meaning_en":"Say 'Nadi rat sut bhagani' ('sister of the son of the king of rivers', i.e. of the moon); then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਅਨੁਮਾਨਹੁ। ੯੯੦।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak anumaanhu | 990 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[991],"number_text":"੯੯੧।","page":998,"lines":[{"gurmukhi":"ਸਾਮੁੰਦ੍ਰਜ ਕਹਿ ਭਗਣਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Saamundraj kahi bhagni bhanijai | jaa char kahi pati sabad dharijai |","meaning_en":"Say 'Samundraj' (ocean-born, the moon), then say 'bhagani' (sister); then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਧਾਰੋ। ੯੯੧।","roman":"Satroo sabad tih anti uchaaro | naam tupak ke sabh jeea dhaaro | 991 |","meaning_en":"add the word 'shatru' (enemy) at the end; hold all these in mind as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[992],"number_text":"੯੯੨।","page":998,"lines":[{"gurmukhi":"ਨਦੀ ਰਾਟ ਸੁਤ ਭਗਣਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਦੇ ਡਾਰੋ।","roman":"Nadee raat sut bhagni uchaaro | jaa char kahi pati pad de daaro |","meaning_en":"Say 'Nadi rat sut bhagani' ('sister of the son of the king of rivers'); then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਅਨੁਮਾਨਹੁ। ੯੯੨।","roman":"Satroo sabad kahu bahuri bakhaanhu | sakal tupak ke naam anumaanhu | 992 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[993],"number_text":"੯੯੩।","page":998,"lines":[{"gurmukhi":"ਸਮੁਦ੍ਰਜ ਭਗਣਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Samudraj bhagnini aadi bhanijai | jaa char kahi pati sabad dharijai |","meaning_en":"First say 'Samudraj bhaganini' ('sister of the ocean-born', with -ni); then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੯੩।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak ke jaanhu | 993 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[994],"number_text":"੯੯੪।","page":998,"lines":[{"gurmukhi":"ਮ੍ਰਿਗਜਾ ਭਗਣਿਨਿ ਆਦਿ ਉਚਾਰੋ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਦੇ ਡਾਰੋ।","roman":"Mrigjaa bhagnini aadi uchaaro | jaa char kahi pati pad de daaro |","meaning_en":"First say 'Mrigja bhaganini'; then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft","note":"ਮ੍ਰਿਗਜਾ: printed so; perhaps for mrig-dhuj/mrig-raj, the moon; uncertain."},{"gurmukhi":"ਰਿਪੁ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਅਨੁਮਾਨਹੁ। ੯੯੪।","roman":"Ripu pad taa ke anti bakhaanhu | sakal tupak ke naam anumaanhu | 994 |","meaning_en":"add the word 'ripu' (enemy) at the end; know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[995],"number_text":"੯੯੫।","page":998,"lines":[{"gurmukhi":"ਨਦਿਸਜ ਭਗਣਿ ਆਦਿ ਪਦ ਦੀਜੈ। ਜਾ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰੀਜੈ।","roman":"Nadisaj bhagni aadi pad deejai | jaa char kahi pati sabad dhareejai |","meaning_en":"First put 'Nadisaj bhagani' ('sister of the one born of the lord of rivers'); then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੯੫।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak ke jaanhu | 995 |","meaning_en":"then say the word 'shatru' (enemy); know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[996],"number_text":"੯੯੬।","page":998,"lines":[{"gurmukhi":"ਨਦਿ ਨਾਇਕ ਕਹਿ ਭਗਣਿਨਿ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Nadi naaik kahi bhagnini bhaakho | sut char kahi naaik pad raakho |","meaning_en":"Say 'Nadi nayak' (lord of rivers), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":998,"meaning_status":"draft","note":"Here the 'son' (moon) link appears to be implied; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੋ ਜਾਨੋ। ੯੯੬।","roman":"Satroo sabad tih anti bakhaano | sabh sree naam tupak ko jaano | 996 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[997],"number_text":"੯੯੭।","page":998,"lines":[{"gurmukhi":"ਸਰਿਤਿਸ ਭਗਣਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Saritis bhagnini aadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say 'Saritis bhaganini' ('sister of the lord of rivers', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੯੯੭।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak ke jaanhu | 997 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[998],"number_text":"੯੯੮।","page":998,"lines":[{"gurmukhi":"ਸਰਿਤ ਇੰਦ੍ਰ ਭਗਣਨੀ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Sarit indr bhagannee bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"Say 'Sarit indra bhaganani' ('sister of the Indra of rivers', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਪਹਿਚਾਨਹੁ। ੯੯੮।","roman":"Satroo sabad ko bahuri bakhaanhu | sabh sree naam tupak pahichaanhu | 998 |","meaning_en":"then say the word 'shatru' (enemy); recognise all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":998,"meaning_status":"draft"},{"type":"verse","number":[999],"number_text":"੯੯੯।","page":998,"lines":[{"gurmukhi":"ਨਿਸਸਿਣਿ ਕਹਿ ਭਗਣਿਨਿ ਪਦ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Nissini kahi bhagnini pad aadi bakhaaneeai |","meaning_en":"First say 'Nisasin' (lord of night), then the word 'bhaganini' (sister, with -ni);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi naaik pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'nayak' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਭਨੀਜੀਐ।","roman":"Satroo sabad kahu taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":998,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਕਬਿ ਲਖਿ ਲੀਜੀਐ।੯੯੯।","roman":"Ho sakal tupak ke naam su kabi lakhi leejeeai | 999 |","meaning_en":"O good poet, understand all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[1000],"number_text":"੧੦੦੦।","page":998,"lines":[{"gurmukhi":"ਤਮ ਹਰ ਭਗਣਿਨਿ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Tam har bhagnini mukh te aadi bakhaaneeai |","meaning_en":"First say aloud 'Tam har bhaganini' ('sister of the remover of darkness', with -ni);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਚਰ ਕਹਿ ਕੇ ਪਤਿ ਪਦ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Jaa char kahi ke pati pad bahuri pramaaneeai |","meaning_en":"then say 'ja char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":998,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ।੧੦੦੦।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 1000 |","meaning_en":"O wise one, regard all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[1001],"number_text":"੧੦੦੧।","page":998,"lines":[{"gurmukhi":"ਤਮ ਹਰ ਭਗਣਿਨਿ ਆਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Tam har bhagnini aadi bakhaanan keejeeai |","meaning_en":"First say 'Tam har bhaganini' ('sister of the remover of darkness', with -ni);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕੈ ਪਤਿ ਪਦ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Sut char kahi kai pati pad anti bhaneejeeai |","meaning_en":"then say 'sut char' and add the word 'pati' (lord);","page":998,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਸੁਬੁਧਿ ਕਹੁ।","roman":"Satroo sabad kahu taa ke anti subudhi kahu |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":998,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਅਨੇਕ ਪ੍ਰਬੀਨ ਲਹੁ।੧੦੦੧।","roman":"Ho sakal tupak ke naam anek prabeen lahu | 1001 |","meaning_en":"O skilled one, know all these as names of the gun (tupak).","page":998,"meaning_status":"draft"}]},{"type":"verse","number":[1002],"number_text":"੧੦੦੨।","page":999,"lines":[{"gurmukhi":"ਤਮ ਅਰਿ ਭਗਣਾਣਨਿ ਪਦ ਪ੍ਰਿਥਮ ਕਹੀਜੀਐ।","roman":"Tam ari bhagnaanni pad pritham kaheejeeai |","meaning_en":"First say the word 'Tam ari bhaganani' ('sister of the enemy of darkness', with -ni);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਅੰਤਿ ਤਿਹੁ ਦੀਜੀਐ।","roman":"Sut char kahi pati sabad anti tihu deejeeai |","meaning_en":"then say 'sut char' and add the word 'pati' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":999,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪ੍ਰਮਾਨੀਐ। ੧੦੦੨।","roman":"Ho sakal tupak ke naam subudhi pramaaneeai | 1002 |","meaning_en":"O wise one, accept all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":999,"meaning_status":"draft"},{"type":"verse","number":[1003],"number_text":"੧੦੦੩।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰਰਿ ਭਗਣਣਿ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Timarri bhaganni aadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say 'Timrari bhaganani' ('sister of the enemy of darkness', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨੋ। ਸਕਲ ਤੁਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ੧੦੦੩।","roman":"Satroo sabad tih anti bakhaano | sakal tuk ke naam pachhaano | 1003 |","meaning_en":"add the word 'shatru' (enemy) at the end; recognise all these as names of the gun.","page":999,"meaning_status":"draft","note":"ਤੁਕ: printed so; read as ਤੁਪਕ (gun); uncertain."}]},{"type":"verse","number":[1004],"number_text":"੧੦੦੪।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰ ਨਾਸ ਕਰਿ ਭਗਣਨਿ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Timar naas kari bhaganni bhaakho | sut char kahi naaik pad raakho |","meaning_en":"Say 'Timar nas kari bhaganani' ('sister of the destroyer of darkness', with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੧੦੦੪।","roman":"Satroo sabad ko bahuri bakhaanhu | sakal tupak ke naam pramaanhu | 1004 |","meaning_en":"then say the word 'shatru' (enemy); accept all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"verse","number":[1005],"number_text":"੧੦੦੫।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰ ਰਦਨ ਭਗਣਨੀ ਬਖਾਨੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Timar radan bhagannee bakhaano | sut char kahi naaik pad thaano |","meaning_en":"Say 'Timar radan bhaganani' ('sister of the crusher of darkness', with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣੀਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ੧੦੦੫।","roman":"Satroo sabad kahu bahuri bhaneejai | naam tupak ke sabh lahi leejai | 1005 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"verse","number":[1006],"number_text":"੧੦੦੬।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰ ਉਚਰਿ ਹਾ ਭਗਣ ਬਖਾਨਹੁ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Timar uchri haa bhagan bakhaanhu | sut char kahi pati sabad pramaanhu |","meaning_en":"Say 'Timar' (darkness), then 'ha' (destroyer) and 'bhagan' (sister); then say 'sut char' and add the word 'pati' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਭਣੀਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ੧੦੦੬।","roman":"Satroo sabad tih anti bhaneejai | naam tupak ke sabh lahi leejai | 1006 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"verse","number":[1007],"number_text":"੧੦੦੭।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰ ਨਿਕੰਦਨਿ ਆਦਿ ਉਚਰੀਐ। ਭਗਣਿਨਿ ਸੁਤ ਚਰ ਪੁਨਿ ਪਤਿ ਧਰੀਐ।","roman":"Timar nikandni aadi uchreeai | bhagnini sut char puni pati dhareeai |","meaning_en":"First say 'Timar nikandani' ('destroyer of darkness', with -ni); then put 'bhaganini' (sister, with -ni), 'sut char' and 'pati' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਮਾਨਹੁ। ੧੦੦੭।","roman":"Satroo sabad tih anti bakhaanhu | sakal tupak ke naam pramaanhu | 1007 |","meaning_en":"add the word 'shatru' (enemy) at the end; accept all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"verse","number":[1008],"number_text":"੧੦੦੮।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰਮੰਦ ਭਗਣਿਨੀ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Timarmand bhagninee bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"Say 'Timarmand bhaganini' ('sister of the dimmer of darkness', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":999,"meaning_status":"draft","note":"ਤਿਮਰਮੰਦ: read as 'one who dims darkness'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਅਨੁਮਾਨਹੁ। ੧੦੦੮।","roman":"Satroo sabad tih anti bakhaanhu | sakal tupak ke naam anumaanhu | 1008 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"verse","number":[1009],"number_text":"੧੦੦੯।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰਯਾਂਤ ਕਹਿ ਭਗਣਿਨਿ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Timaryaant kahi bhagnini bhaakho | sut char kahi naaik pad raakho |","meaning_en":"Say 'Timaryant' (ender of darkness), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪ੍ਰਮਾਨਹੁ। ੧੦੦੯।","roman":"Satroo sabad tih anti bakhaanhu | naam tupak ke sakal pramaanhu | 1009 |","meaning_en":"add the word 'shatru' (enemy) at the end; accept all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":999,"meaning_status":"draft"},{"type":"verse","number":[1010],"number_text":"੧੦੧੦।","page":999,"lines":[{"gurmukhi":"ਤਿਮਰ ਨਾਸ ਕਰਿ ਭਗਣਿਨਿ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Timar naas kari bhagnini aadi bakhaaneeai |","meaning_en":"First say 'Timar nas kari bhaganini' ('sister of the destroyer of darkness', with -ni);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਕਹੁ ਠਾਨੀਐ।","roman":"Sut char kahi kar naath sabad kahu thaaneeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਕੋ ਤਾ ਕੇ ਪੁਨਿ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Ripu pad ko taa ke puni anti uchaareeai |","meaning_en":"add the word 'ripu' (enemy) at the end;","page":999,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ। ੧੦੧੦।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 1010 |","meaning_en":"O wise one, regard all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"verse","number":[1011],"number_text":"੧੦੧੧।","page":999,"lines":[{"gurmukhi":"ਉਡਗਰਾਜ ਕਹਿ ਭਗਣਿਨਿ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Udagraaj kahi bhagnini aadi bakhaaneeai |","meaning_en":"First say 'Udagraj' (king of the stars, the moon), then 'bhaganini' (sister, with -ni);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕੇ ਨਾਥ ਸਬਦ ਕਹੁ ਠਾਨੀਐ।","roman":"Sut char kahi ke naath sabad kahu thaaneeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":999,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kahu taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":999,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮੰਤ੍ਰ ਬਿਚਾਰੀਐ। ੧੦੧੧।","roman":"Ho sakal tupak ke naam sumantr bichaareeai | 1011 |","meaning_en":"O good counsellor, regard all these as names of the gun (tupak).","page":999,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1000,"meaning_status":"draft"},{"type":"verse","number":[1012],"number_text":"੧੦੧੨।","page":1000,"lines":[{"gurmukhi":"ਉਡਗਿਸ ਕਹਿ ਭਗਣਿਨੀ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Udgis kahi bhagninee bhanijai | sut char kahi naaik pad dijai |","meaning_en":"Say 'Udagis' (lord of the stars), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਜਾਨਹੁ। ੧੦੧੨।","roman":"Ari pad taa ke anti bakhaanhu | naam tupak ke sabh jeea jaanhu | 1012 |","meaning_en":"add the word 'ari' (enemy) at the end; know all these as names of the gun (tupak) in your heart.","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1013],"number_text":"੧੦੧੩।","page":1000,"lines":[{"gurmukhi":"ਉਡਗ ਨਾਥ ਕਹਿ ਭਗਣਿ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਕਹੁ ਡਾਰੋ।","roman":"Udag naath kahi bhagni uchaaro | sut char kahi pati pad kahu daaro |","meaning_en":"Say 'Udag nath' (lord of the stars), then say 'bhagani' (sister); then say 'sut char' and add the word 'pati' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਜੀਅ ਜਾਨਹੁ। ੧੦੧੩।","roman":"Ripu pad taa ke anti bakhaanhu | sabh sree naam tupak jeea jaanhu | 1013 |","meaning_en":"add the word 'ripu' (enemy) at the end; know all these as names of the gun (tupak) in your heart.","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1014],"number_text":"੧੦੧੪।","page":1000,"lines":[{"gurmukhi":"ਉਡਗ ਨ੍ਰਿਪਤਿ ਕਹਿ ਭਗਣਿਨੀ ਭਣੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Udag nripti kahi bhagninee bhaneejai | sut char kahi naaik pad deejai |","meaning_en":"Say 'Udag nripati' (king of the stars), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੦੧੪।","roman":"Ari pad taa ke anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1014 |","meaning_en":"add the word 'ari' (enemy) at the end; know all these as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1015],"number_text":"੧੦੧੫।","page":1000,"lines":[{"gurmukhi":"ਉਡਗ ਨ੍ਰਿਪਤਿ ਕਹਿ ਭਗਣਿ ਭਣੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Udag nripti kahi bhagni bhaneejai | sut char kahi naaik pad deejai |","meaning_en":"Say 'Udag nripati' (king of the stars), then say 'bhagani' (sister); then say 'sut char' and add the word 'nayak' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੧੦੧੫।","roman":"Satroo sabad tih anti bakhaano | sabh sree naam tupak ke jaano | 1015 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":1000,"meaning_status":"draft"},{"type":"verse","number":[1016],"number_text":"੧੦੧੬।","page":1000,"lines":[{"gurmukhi":"ਉਡਗਏਸ ਭਗਣਿਨਿ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Udgaes bhagnini sabdaadi bakhaaneeai |","meaning_en":"First say the word 'Udagaes bhaganini' ('sister of the lord of the stars', with -ni);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Sut char kahi kar naath sabad ko thaaneeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਜੀਅ ਧਾਰੀਐ। ੧੦੧੬।","roman":"Ho sakal tupak ke naam subudhi jeea dhaareeai | 1016 |","meaning_en":"O wise one, hold all these in mind as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1017],"number_text":"੧੦੧੭।","page":1000,"lines":[{"gurmukhi":"ਉਡਪਤਿ ਭਗਣਿਨਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Udapti bhagnini aadi uchaaran keejeeai |","meaning_en":"First say 'Udpati bhaganini' ('sister of the lord of the stars', with -ni);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Sut char kahi kar naath sabad ko deejeeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪ੍ਰਬੀਨ ਪ੍ਰਮਾਨੀਐ। ੧੦੧੭।","roman":"Ho sakal tupak ke naam prabeen pramaaneeai | 1017 |","meaning_en":"O skilled one, accept all these as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1000,"meaning_status":"draft"},{"type":"verse","number":[1018],"number_text":"੧੦੧੮।","page":1000,"lines":[{"gurmukhi":"ਉਡਗ ਭੂਪਣੀ ਭੂਪਿ ਬਖਾਨੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Udag bhoopnee bhoopi bakhaano | sut char kahi naaik pad thaano |","meaning_en":"Say 'Udag bhupani bhupi' ('sister of the king of the stars'?); then say 'sut char' and add the word 'nayak' (lord);","page":1000,"meaning_status":"draft","note":"ਉਡਗ ਭੂਪਣੀ ਭੂਪਿ: printed so; probably meant as 'Udag bhup bhagani'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੧੦੧੮।","roman":"Satroo sabad kahu bahuri bhanijai | naam tupak ke sabh lahi lijai | 1018 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1019],"number_text":"੧੦੧੯।","page":1000,"lines":[{"gurmukhi":"ਤਾਰਾਪਤਿ ਕਹਿ ਭਗਣਿਨਿ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Taaraapti kahi bhagnini bhaakho | sut char kahi naaik pad raakho |","meaning_en":"Say 'Tarapati' (lord of the stars), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਬਹੁਰਿ ਉਚਾਰਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਜੀਅ ਧਾਰਹੁ। ੧੦੧੯।","roman":"Satroo sabad kahu bahuri uchaarhu | sabh sree naam tupak jeea dhaarhu | 1019 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1020],"number_text":"੧੦੨੦।","page":1000,"lines":[{"gurmukhi":"ਤਾਰੇਸਰ ਕਹਿ ਭਗਣਿ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Taaresar kahi bhagni uchaaro | sut char kahi naaik pad daaro |","meaning_en":"Say 'Taresar' (lord of the stars), then say 'bhagani' (sister); then say 'sut char' and add the word 'nayak' (lord);","page":1000,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੦੨੦।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1020 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"verse","number":[1021],"number_text":"੧੦੨੧।","page":1000,"lines":[{"gurmukhi":"ਤਾਰਾਲਯਇਸ ਭਗਣਿ ਬਖਾਨੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Taaraalyais bhagni bakhaano | sut char kahi pati sabad pramaano |","meaning_en":"Say 'Taralayis bhagani' ('sister of the lord of the home of the stars'); then say 'sut char' and add the word 'pati' (lord);","page":1000,"meaning_status":"draft","note":"ਤਾਰਾਲਯਇਸ: 'lord of the abode of stars', taken as the moon; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਕਹੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ੧੦੨੧।","roman":"Taa ke anti satroo pad kaheeai | sabh sree naam tupak ke laheeai | 1021 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":1000,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":1001,"meaning_status":"draft"},{"type":"verse","number":[1022],"number_text":"੧੦੨੨।","page":1001,"lines":[{"gurmukhi":"ਤਾਰਾ ਗ੍ਰਿਹਣਿਸ ਭਗਣੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Taaraa grihnis bhagnee aadi bakhaaneeai |","meaning_en":"First say 'Tara grihanis bhagani' ('sister of the lord of the house of the stars');","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Sut char kahi kar naath sabad ko thaaneeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਹਿ ਦੀਜੀਐ।","roman":"Satroo sabad kahu taa ke anthi deejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਲਹਿ ਲੀਜੀਐ। ੧੦੨੨।","roman":"Ho sakal tupak ke naam subudhi lahi leejeeai | 1022 |","meaning_en":"O wise one, understand all these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1023],"number_text":"੧੦੨੩।","page":1001,"lines":[{"gurmukhi":"ਉਡਗ ਨਿਕੇਤਿਸ ਭਗਨੀ ਆਦਿ ਭਣੀਜੀਐ।","roman":"Udag niketis bhagnee aadi bhaneejeeai |","meaning_en":"First say 'Udag niketis bhagani' ('sister of the lord of the home of the stars');","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਬਹੁਰਿ ਪਦ ਦੀਜੀਐ।","roman":"Sut char kahi kar naath bahuri pad deejeeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad ko taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ। ੧੦੨੩।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 1023 |","meaning_en":"O wise one, regard all these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1024],"number_text":"੧੦੨੪।","page":1001,"lines":[{"gurmukhi":"ਉਡਗ ਨਾਥ ਭਗਣਿਨੀ ਪ੍ਰਿਥਮ ਪਦ ਭਾਖੀਐ।","roman":"Udag naath bhagninee pritham pad bhaakheeai |","meaning_en":"First say the word 'Udag nath bhaganini' ('sister of the lord of the stars', with -ni);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤੁ ਚਰ ਕਹਿ ਕਰਿ ਨਾਥ ਬਹੁਰਿ ਪਦ ਰਾਖੀਐ।","roman":"Sutu char kahi kari naath bahuri pad raakheeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੈ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad ko taa kai anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਹਿਚਾਨੀਐ। ੧੦੨੪।","roman":"Ho sakal tupak ke naam subudhi pahichaaneeai | 1024 |","meaning_en":"O wise one, recognise all these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1025],"number_text":"੧੦੨੫।","page":1001,"lines":[{"gurmukhi":"ਉਡਗਏਸਰ ਭਗਣਿਨਿ ਸਬਦਾਦਿ ਉਚਾਰੀਐ।","roman":"Udgaesar bhagnini sabdaadi uchaareeai |","meaning_en":"First say the word 'Udagesar bhaganini' ('sister of the lord of the stars', with -ni);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰਿ ਨਾਥ ਸਬਦ ਦੈ ਡਾਰੀਐ।","roman":"Sut char kahi kari naath sabad dai daareeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Satroo sabad kahu taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਕਬਿ ਲਹਿ ਲੀਜੀਐ। ੧੦੨੫।","roman":"Ho sakal tupak ke naam su kabi lahi leejeeai | 1025 |","meaning_en":"O good poet, understand all these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1026],"number_text":"੧੦੨੬।","page":1001,"lines":[{"gurmukhi":"ਉਡਗ ਏਸਰ ਭਗਣਿਨਿ ਸਬਦਾਦਿ ਭਣੀਜੀਐ।","roman":"Udag esar bhagnini sabdaadi bhaneejeeai |","meaning_en":"First say the word 'Udag esar bhaganini' ('sister of the lord of the stars', with -ni);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Sut char kahi kar naath sabad ko deejeeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੋ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad kaho taa ke anti uchaareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਜੀਅ ਧਾਰੀਐ। ੧੦੨੬।","roman":"Ho sakal tupak ke naam subudhi jeea dhaareeai | 1026 |","meaning_en":"O wise one, hold all these in mind as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1001,"meaning_status":"draft"},{"type":"verse","number":[1027],"number_text":"੧੦੨੭।","page":1001,"lines":[{"gurmukhi":"ਉਡਗਾਸ੍ਰੈ ਭਗਣਿਨੀ ਬਖਾਨੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਠਾਨੋ।","roman":"Udgaasrai bhagninee bakhaano | sut char kahi naaik pad thaano |","meaning_en":"Say 'Udagasrai bhaganini' ('sister of the refuge of the stars', with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅਤਿ ਉਚਰੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਜੀਅ ਧਰੀਐ। ੧੦੨੭।","roman":"Satroo sabad tih ati uchreeai | sabh sree naam tupak jeea dhareeai | 1027 |","meaning_en":"then say the word 'shatru' (enemy); hold all these in mind as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1028],"number_text":"੧੦੨੮।","page":1001,"lines":[{"gurmukhi":"ਰਿਖਿਜ ਭਗਣਿਨੀ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Rikhij bhagninee aadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say 'Rikhij bhaganini' ('sister of the sage-born', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":1001,"meaning_status":"draft","note":"ਰਿਖਿਜ: 'born of a sage'; the moon is called son of the sage Atri; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੦੨੮।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1028 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1029],"number_text":"੧੦੨੯।","page":1001,"lines":[{"gurmukhi":"ਮੁਨਿਜ ਭਗਣਿਨੀ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Munij bhagninee aadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say 'Munij bhaganini' ('sister of the sage-born', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":1001,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਹ੍ਰਿਦੈ ਬਿਚਾਰਹੁ। ੧੦੨੯।","roman":"Satroo sabad tih anti uchaarhu | naam tupak ke hridai bichaarhu | 1029 |","meaning_en":"add the word 'shatru' (enemy) at the end; regard these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1030],"number_text":"੧੦੩੦।","page":1001,"lines":[{"gurmukhi":"ਬ੍ਰਿਤਿ ਉਤਮਜ ਭਗਣਿਨੀ ਭਾਖੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੋ।","roman":"Briti utmaj bhagninee bhaakho | sut char kahi naaik pad raakho |","meaning_en":"Say 'Briti utamaj bhaganini'; then say 'sut char' and add the word 'nayak' (lord);","page":1001,"meaning_status":"draft","note":"ਬ੍ਰਿਤਿ ਉਤਮਜ: obscure ('born of one of excellent conduct'?); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਸੁ ਕਹੀਐ। ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮਨ ਲਹੀਐ। ੧੦੩੦।","roman":"Satroo sabad tih anti su kaheeai | sakal tupak ke naaman laheeai | 1030 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":1001,"meaning_status":"draft"}]},{"type":"verse","number":[1031],"number_text":"੧੦੩੧।","page":1002,"lines":[{"gurmukhi":"ਤਪਿਸ ਉਚਰਿ ਭਗਣਿਨੀ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Tapis uchri bhagninee bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"Say 'Tapis' (lord of heat, the sun), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft","note":"ਤਪਿਸ: 'lord of heat', taken as the sun; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਠਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੦੩੧।","roman":"Taa ke anti satroo pad thaanhu | sabh sree naam tupak ke jaanhu | 1031 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1032],"number_text":"੧੦੩੨।","page":1002,"lines":[{"gurmukhi":"ਕਸਿਪ ਸੁਤ ਕਹਿ ਭਗਣਿਨਿ ਭਾਖੀਐ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਰਾਖੀਐ।","roman":"Kasip sut kahi bhagnini bhaakheeai | sut char kahi naaik pad raakheeai |","meaning_en":"Say 'Kasip sut' (son of Kashyap, the sun), then say 'bhaganini' (sister, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":1002,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਰੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਧਰੀਐ। ੧੦੩੨।","roman":"Satroo sabad tih anti uchreeai | naam tupak ke sabh jeea dhareeai | 1032 |","meaning_en":"add the word 'shatru' (enemy) at the end; hold all these in mind as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1033],"number_text":"੧੦੩੩।","page":1002,"lines":[{"gurmukhi":"ਜਵਨ ਕਰਣ ਭਗਣਿਨੀ ਬਖਾਨਹੁ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨਹੁ।","roman":"Javan karan bhagninee bakhaanhu | sut char kahi pati sabad pramaanhu |","meaning_en":"Say 'Javan karan bhaganini'; then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft","note":"ਜਵਨ ਕਰਣ: obscure, as 'ਜਉਨ ਕਰਣ' above; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਦੀਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ੧੦੩੩।","roman":"Taa ke anti satroo pad deejai | naam tupak ke sabh lahi leejai | 1033 |","meaning_en":"add the word 'shatru' (enemy) at the end; understand all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1034],"number_text":"੧੦੩੪।","page":1002,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨਿਨਿ ਆਦਿ ਬਖਾਨਨ ਕੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰੀਜੈ।","roman":"Krisnini aadi bakhaanan keejai | sut char kahi pati sabad dhareejai |","meaning_en":"First say 'Krisanini' ('the dark one', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft","note":"ਕ੍ਰਿਸਨਿ: 'the dark one', probably the Yamuna; uncertain."},{"gurmukhi":"ਰਿਪੁ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਅਨੁਮਾਨਹੁ। ੧੦੩੪।","roman":"Ripu pad taa ke anti bakhaanhu | naam tupak ke sabh anumaanhu | 1034 |","meaning_en":"add the word 'ripu' (enemy) at the end; know all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1035],"number_text":"੧੦੩੫।","page":1002,"lines":[{"gurmukhi":"ਸਿਆਮ ਮੂਰਤਿਨਿਨਿ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Siaam moortinini aadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say 'Siam murtinini' ('dark of form', with -ni); then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਅਨੁਮਾਨਹੁ। ੧੦੩੫।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak anumaanhu | 1035 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1036],"number_text":"੧੦੩੬।","page":1002,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਤਪਤਿਨੀ ਸਬਦ ਉਚਰੀਐ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਧਰੀਐ।","roman":"Pratham taptinee sabad uchreeai | sut char kahi naaik pad dhareeai |","meaning_en":"First say the word 'Taptini' (the Tapti, daughter of the sun, with -ni); then say 'sut char' and add the word 'nayak' (lord);","page":1002,"meaning_status":"draft","note":"ਤਪਤਿਨੀ: read as the Tapti river; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੦੩੬।","roman":"Satroo sabad tih anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1036 |","meaning_en":"add the word 'shatru' (enemy) at the end; know all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1037],"number_text":"੧੦੩੭।","page":1002,"lines":[{"gurmukhi":"ਸੂਰਜ ਪੁਤ੍ਰਿਕਾ ਆਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦਿਜੈ।","roman":"Sooraj putrikaa aadi bhanijai | sut char kahi naaik pad dijai |","meaning_en":"First say 'Suraj putrika' ('daughter of the sun'); then say 'sut char' and add the word 'nayak' (lord);","page":1002,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਾਰਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਜੀਅ ਧਾਰਹੁ। ੧੦੩੭।","roman":"Satroo sabad tih anti uchaarhu | sabh sree naam tupak jeea dhaarhu | 1037 |","meaning_en":"add the word 'shatru' (enemy) at the end; hold all these in mind as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1038],"number_text":"੧੦੩੮।","page":1002,"lines":[{"gurmukhi":"ਸੂਰਜ ਆਤਮਜਾ ਆਦਿ ਭਣੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰੀਜੈ।","roman":"Sooraj aatamjaa aadi bhaneejai | sut char kahi pati sabad dhareejai |","meaning_en":"First say 'Suraj atmaja' ('daughter of the sun'); then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਿਹ ਅੰਤਿ ਉਚਾਰੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰੋ। ੧੦੩੮।","roman":"Satroo sabad tih anti uchaaro | naam tupak ke sakal bichaaro | 1038 |","meaning_en":"add the word 'shatru' (enemy) at the end; regard all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1039],"number_text":"੧੦੩੯।","page":1002,"lines":[{"gurmukhi":"ਆਦਿ ਮਾਨਨੀ ਸਬਦ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਦੇ ਡਾਰੋ।","roman":"Aadi maannee sabad uchaaro | sut char kahi pati pad de daaro |","meaning_en":"First say the word 'Manani' (proud); then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft","note":"ਮਾਨਨੀ ... ਅਹੰਕਾਰਨੀ: words for 'pride'; what they point to (perhaps an army) is not stated; uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਉਚਰੀਐ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਰੀਐ। ੧੦੩੯।","roman":"Ari pad taa ke anti uchreeai | naam tupak ke sakal bichreeai | 1039 |","meaning_en":"add the word 'ari' (enemy) at the end; regard all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1040],"number_text":"੧੦੪੦।","page":1002,"lines":[{"gurmukhi":"ਅਭਿਮਾਨਿਨੀ ਪਦਾਦਿ ਭਣਿਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਧਰਿਜੈ।","roman":"Abhimaaninee padaadi bhanijai | sut char kahi pati sabad dharijai |","meaning_en":"First say the word 'Abhimanini' (proud); then say 'sut char' and add the word 'pati' (lord);","page":1002,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਮਾਨਹੁ। ੧੦੪੦।","roman":"Ari pad taa ke anti bakhaanhu | sabh sree naam tupak ke maanhu | 1040 |","meaning_en":"add the word 'ari' (enemy) at the end; know all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1041],"number_text":"੧੦੪੧।","page":1002,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਸਮਯਣੀ ਸਬਦ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਡਾਰੋ।","roman":"Pratham samaynee sabad uchaaro | sut char kahi naaik pad daaro |","meaning_en":"First say the word 'Samayani'; then say 'sut char' and add the word 'nayak' (lord);","page":1002,"meaning_status":"draft","note":"ਸਮਯਣੀ: obscure; perhaps 'proud' (from smaya); uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਕਹਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੧੦੪੧।","roman":"Satroo sabad ko bahuri kahijai | naam tupak ke sabh lahi lijai | 1041 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"verse","number":[1042],"number_text":"੧੦੪੨।","page":1002,"lines":[{"gurmukhi":"ਗਰਬਿਣਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਨਾਇਕ ਪਦ ਦੀਜੈ।","roman":"Garbini aadi uchaaran keejai | sut char kahi naaik pad deejai |","meaning_en":"First say 'Garbini' (proud); then say 'sut char' and add the word 'nayak' (lord);","page":1002,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰਹੁ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਿਚਾਰਹੁ। ੧੦੪੨।","roman":"Ari pad taa ke anti uchaarhu | naam tupak ke sakal bichaarhu | 1042 |","meaning_en":"add the word 'ari' (enemy) at the end; regard all these as names of the gun (tupak).","page":1002,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":1003,"meaning_status":"draft"},{"type":"verse","number":[1043],"number_text":"੧੦੪੩।","page":1003,"lines":[{"gurmukhi":"ਦ੍ਰਪਨਿਨਿ ਮੁਖ ਤੇ ਸਬਦ ਸੁ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Drapnini mukh te sabad su aadi uchaareeai |","meaning_en":"First say aloud the word 'Drapanini' (proud, with -ni);","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਚਰ ਕਹਿ ਕਰ ਨਾਥ ਸਬਦ ਦੇ ਡਾਰੀਐ।","roman":"Sut char kahi kar naath sabad de daareeai |","meaning_en":"then say 'sut char' and add the word 'nath' (lord);","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਹਿਚਾਨੀਐ। ੧੦੪੩।","roman":"Ho sakal tupak ke naam subudhi pahichaaneeai | 1043 |","meaning_en":"O wise one, recognise all these as names of the gun (tupak).","page":1003,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1003,"meaning_status":"draft"},{"type":"verse","number":[1044],"number_text":"੧੦੪੪।","page":1003,"lines":[{"gurmukhi":"ਅਹੰਕਾਰਨੀ ਆਦਿ ਉਚਾਰੋ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਪਦ ਕਹੁ ਡਾਰੋ।","roman":"Ahankaarnee aadi uchaaro | sut char kahi pati pad kahu daaro |","meaning_en":"First say 'Ahankarani' (full of ego); then say 'sut char' and add the word 'pati' (lord);","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੧੦੪੪।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sabh lahi lijai | 1044 |","meaning_en":"then say the word 'shatru' (enemy); understand all these as names of the gun (tupak).","page":1003,"meaning_status":"draft"}]},{"type":"verse","number":[1045],"number_text":"੧੦੪੫।","page":1003,"lines":[{"gurmukhi":"ਪੀਅਣੀਣਿ ਆਦਿ ਉਚਾਰਣ ਕੀਜੈ। ਸੁਤ ਚਰ ਕਹਿ ਪਤਿ ਸਬਦ ਭਣੀਜੈ।","roman":"Peeaneeni aadi uchaaran keejai | sut char kahi pati sabad bhaneejai |","meaning_en":"First say 'Piaanini'; then say 'sut char' and add the word 'pati' (lord);","page":1003,"meaning_status":"draft","note":"ਪੀਅਣੀਣਿ: obscure; perhaps 'beloved'; uncertain."},{"gurmukhi":"ਰਿਪੁ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਣਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਣਹੁ। ੧੦੪੫।","roman":"Ripu pad taa ke anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1045 |","meaning_en":"add the word 'ripu' (enemy) at the end; know all these as names of the gun (tupak).","page":1003,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1003,"meaning_status":"draft"},{"type":"verse","number":[1046],"number_text":"੧੦੪੬।","page":1003,"lines":[{"gurmukhi":"ਧਿਖਣੀ ਆਦਿ ਬਖਾਨ ਕੈ ਰਿਪੁ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Dhikhnee aadi bakhaan kai ripu pad anti uchaar |","meaning_en":"First say 'Dhikhani' (intellect), and say the word 'ripu' (enemy) at the end;","page":1003,"meaning_status":"draft","note":"ਧਿਖਣੀ: read as dhishana, 'intellect'; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਫੰਗ ਕੇ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੧੦੪੬।","roman":"Sabh sree naam tuphang ke leejhu su kabi su dhaar | 1046 |","meaning_en":"O good poet, hold all these in mind as names of the gun (tufang).","page":1003,"meaning_status":"draft"}]},{"type":"verse","number":[1047],"number_text":"੧੦੪੭।","page":1003,"lines":[{"gurmukhi":"ਮੇਧਣਿ ਆਦਿ ਉਚਾਰਿ ਕੈ ਰਿਪੁ ਪਦ ਕਹੀਐ ਅੰਤਿ।","roman":"Medhni aadi uchaari kai ripu pad kaheeai anti |","meaning_en":"First say 'Medhani' (intellect), and say the word 'ripu' (enemy) at the end;","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਫੰਗ ਕੇ ਨਿਕਸਤ ਚਲੈ ਅਨੰਤ। ੧੦੪੭।","roman":"Sabh sree naam tuphang ke niksat chalai anant | 1047 |","meaning_en":"and countless names of the gun (tufang) keep coming forth.","page":1003,"meaning_status":"draft"}]},{"type":"verse","number":[1048],"number_text":"੧੦੪੮।","page":1003,"lines":[{"gurmukhi":"ਸੇਮੁਖਿਨੀ ਸਬਦਾਦਿ ਕਹਿ ਅਰਿ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Semukhinee sabdaadi kahi ari pad anti bakhaan |","meaning_en":"First say the word 'Semukhini' (intellect), and say the word 'ari' (enemy) at the end;","page":1003,"meaning_status":"draft","note":"ਸੇਮੁਖਿਨੀ: read as semushi, 'intellect'; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਏ ਲਹਿ ਲੀਜੋ ਬੁਧਿਵਾਨ। ੧੦੪੮।","roman":"Sakal tupak ke naam e lahi leejo budhivaan | 1048 |","meaning_en":"understand all these as names of the gun (tupak).","page":1003,"meaning_status":"draft"}]},{"type":"verse","number":[1049],"number_text":"੧੦੪੯।","page":1003,"lines":[{"gurmukhi":"ਆਦਿ ਮਨੀਖਨਿ ਸਬਦ ਕਹਿ ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Aadi maneekhni sabad kahi ripu pad bahuri uchaar |","meaning_en":"First say the word 'Manikhani' (intellect), then say the word 'ripu' (enemy);","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੧੦੪੯।","roman":"Naam tupak ke hot hai leejhu su kabi su dhaar | 1049 |","meaning_en":"O good poet, hold these in mind as names of the gun (tupak).","page":1003,"meaning_status":"draft"}]},{"type":"verse","number":[1050],"number_text":"੧੦੫੦।","page":1003,"lines":[{"gurmukhi":"ਬੁਧਨੀ ਆਦਿ ਬਖਾਨ ਕੈ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Budhnee aadi bakhaan kai anti sabad ari dehu |","meaning_en":"First say 'Budhani' (intellect), and put the word 'ari' (enemy) at the end;","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੧੦੫੦।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 1050 |","meaning_en":"O clever one, recognise these as names of the gun (tupak) in your heart.","page":1003,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1003,"meaning_status":"draft"},{"type":"verse","number":[1051],"number_text":"੧੦੫੧।","page":1003,"lines":[{"gurmukhi":"ਭਾਨੀ ਆਦਿ ਬਖਾਨਨ ਕੀਜੈ। ਰਿਪੁ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਭਣੀਜੈ।","roman":"Bhaanee aadi bakhaanan keejai | ripu pad taa ke anti bhaneejai |","meaning_en":"First say 'Bhani' (radiance); add the word 'ripu' (enemy) at the end;","page":1003,"meaning_status":"draft","note":"ਭਾਨੀ: read as 'radiant one'; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਕਛੂ ਨਹਿ ਮਾਨਹੁ। ੧੦੫੧।","roman":"Sabh sree naam tupak ke jaanhu | yaa mai bhed kachhoo nahi maanhu | 1051 |","meaning_en":"know all these as names of the gun (tupak); consider there to be no difference in this at all.","page":1003,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1003,"meaning_status":"draft"},{"type":"verse","number":[1052],"number_text":"੧੦੫੨।","page":1003,"lines":[{"gurmukhi":"ਆਦਿ ਆਭਾਨੀ ਸਬਦ ਕਹਿ ਰਿਪੁ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Aadi aabhaanee sabad kahi ripu pad anti bakhaan |","meaning_en":"First say the word 'Abhani' (radiance), and say the word 'ripu' (enemy) at the end;","page":1003,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਤੁਪਕ ਕੇ ਲੀਜਹੁ ਸੁ ਕਬਿ ਪਛਾਨ। ੧੦੫੨।","roman":"Naam sakal sree tupak ke leejhu su kabi pachhaan | 1052 |","meaning_en":"O good poet, recognise all these as names of the gun (tupak).","page":1003,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":1004,"meaning_status":"draft"},{"type":"verse","number":[1053],"number_text":"੧੦੫੩।","page":1004,"lines":[{"gurmukhi":"ਆਦਿ ਸੋਭਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi sobhnee sabad uchaaran keejeeai |","meaning_en":"First say the word 'Sobhani' (splendour);","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Satroo sabad ko taa ke anti bhaneejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know all these as names of the gun (tupak) in your heart;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨੀਐ।੧੦੫੩।","roman":"Ho yaa ke bheetar bhed naiku nahee maaneeai | 1053 |","meaning_en":"consider there to be no difference in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1054],"number_text":"੧੦੫੪।","page":1004,"lines":[{"gurmukhi":"ਪ੍ਰਭਾ ਧਰਨਿ ਮੁਖ ਤੇ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Prabhaa dharni mukh te sabdaadi bakhaaneeai |","meaning_en":"First say aloud the word 'Prabha dharani' ('bearer of light');","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti pramaaneeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਉਤਰ ਤੁਪਕ ਕੋ ਨਾਮ ਭਨੀਜੀਐ।","roman":"Taa te utar tupak ko naam bhaneejeeai |","meaning_en":"after that, call it a name of the gun (tupak);","page":1004,"meaning_status":"draft","note":"ਉਤਰ: read as 'after/thereafter'; uncertain."},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਜਾਨ ਨਹੀ ਲੀਜੀਐ।੧੦੫੪।","roman":"Ho yaa ke bheetar bhed jaan nahee leejeeai | 1054 |","meaning_en":"consider there to be no difference in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1055],"number_text":"੧੦੫੫।","page":1004,"lines":[{"gurmukhi":"ਸੁਖਮਨਿ ਪਦ ਕੋ ਮੁਖ ਤੇ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Sukhamni pad ko mukh te aadi uchaareeai |","meaning_en":"First say aloud the word 'Sukhmani';","page":1004,"meaning_status":"draft","note":"ਸੁਖਮਨਿ: perhaps 'peace of mind' or 'subtle intellect'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਹਿ ਡਾਰੀਐ।","roman":"Satroo sabad ko taa ke anthi daareeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"know all these as names of the gun (tupak) in your heart;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੀਐ।੧੦੫੫।","roman":"Ho yaa ke bheetar bhed naiku nahee keejeeai | 1055 |","meaning_en":"make no distinction in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1004,"meaning_status":"draft"},{"type":"verse","number":[1056],"number_text":"੧੦੫੬।","page":1004,"lines":[{"gurmukhi":"ਧੀਮਨਿ ਪਦ ਕੋ ਆਦਿ ਬਖਾਨਹੁ। ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਠਾਨਹੁ।","roman":"Dheemni pad ko aadi bakhaanhu | taa ke anti satroo pad thaanhu |","meaning_en":"First say the word 'Dhimani' (wise, intellect); add the word 'shatru' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਰਬ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੈ। ੧੦੫੬।","roman":"Sarab tupak ke naam laheejai | yaa mai bhed naiku nahee keejai | 1056 |","meaning_en":"understand all these as names of the gun (tupak); make no distinction in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1057],"number_text":"੧੦੫੭।","page":1004,"lines":[{"gurmukhi":"ਆਦਿ ਕ੍ਰਾਂਤਨੀ ਸਬਦ ਉਚਾਰੋ। ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਡਾਰੋ।","roman":"Aadi kraantnee sabad uchaaro | taa ke anti satroo pad daaro |","meaning_en":"First say the word 'Krantani' (radiance); add the word 'shatru' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਯਾ ਕੇ ਬਿਖੈ ਭੇਦ ਨਹੀ ਮਾਨਹੁ। ੧੦੫੭।","roman":"Sabh sree naam tupak ke jaanhu | yaa ke bikhai bhed nahee maanhu | 1057 |","meaning_en":"know all these as names of the gun (tupak); consider there to be no difference in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1058],"number_text":"੧੦੫੮।","page":1004,"lines":[{"gurmukhi":"ਛਬਿਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਰਿਪੁ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Chhabinee aadi uchaaran keejai | ripu pad anti tavan ke deejai |","meaning_en":"First say 'Chhabini' (beauty); add the word 'ripu' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨਹੁ। ਯਾ ਕੇ ਬਿਖੈ ਭੇਦ ਨਹੀ ਮਾਨਹੁ। ੧੦੫੮।","roman":"Naam tupak ke sakal pachhaanhu | yaa ke bikhai bhed nahee maanhu | 1058 |","meaning_en":"recognise all these as names of the gun (tupak); consider there to be no difference in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1059],"number_text":"੧੦੫੯।","page":1004,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਬਾਜਨੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Pritham baajnee sabad bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"First say the word 'Bajani' (having horses); add the word 'ari' (enemy) at the end;","page":1004,"meaning_status":"draft","note":"ਬਾਜਨੀ ... ਦੰਤਿਨੀ: 'having horses/elephants', i.e. an army, whose enemy is the gun; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਚਿਤ ਮੈ ਰੁਚੈ ਤਿਸੀ ਠਾ ਕਹੀਐ। ੧੦੫੯।","roman":"Sabh sree naam tupak ke laheeai | chit mai ruchai tisee thaa kaheeai | 1059 |","meaning_en":"understand all these as names of the gun (tupak); say them at whatever place the mind likes.","page":1004,"meaning_status":"draft","note":"i.e. use these names wherever one wishes (in verse); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":1004,"meaning_status":"draft"},{"type":"verse","number":[1060],"number_text":"੧੦੬੦।","page":1004,"lines":[{"gurmukhi":"ਆਦਿ ਬਾਹਨੀ ਸਬਦ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Aadi baahnee sabad bakhaanan keejeeai |","meaning_en":"First say the word 'Bahani' (army);","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਪਾਛੇ ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਦੀਜੀਐ।","roman":"Taa ke paachhe satroo sabad kahu deejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know all these as names of the gun (tupak) in your heart;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਾਹੀਐ ਜਵਨੈ ਠਵਰ ਸੁ ਤਹਾ ਬਖਾਨੀਐ।੧੦੬੦।","roman":"Ho chaaheeai javnai thavar su tahaa bakhaaneeai | 1060 |","meaning_en":"use them in whatever place you wish.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1061],"number_text":"੧੦੬੧।","page":1004,"lines":[{"gurmukhi":"ਆਦਿ ਤੁਰੰਗਨੀ ਮੁਖ ਤੇ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Aadi turangnee mukh te sabad bakhaaneeai |","meaning_en":"First say aloud the word 'Turangani' (having horses);","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਸੁ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Ari pad taa ke anti su bahuri pramaaneeai |","meaning_en":"add the word 'ari' (enemy) at the end;","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O able one, understand all these as names of the gun (tupak);","page":1004,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੀਐ।੧੦੬੧।","roman":"Ho yaa ke bheetar bhed naiku nahee keejeeai | 1061 |","meaning_en":"make no distinction in this at all.","page":1004,"meaning_status":"draft"}]},{"type":"verse","number":[1062],"number_text":"੧੦੬੨।","page":1005,"lines":[{"gurmukhi":"ਹਯਨੀ ਸਬਦਹਿ ਮੁਖ ਤੇ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Haynee sabadhi mukh te aadi uchaareeai |","meaning_en":"First say aloud the word 'Hayani' (having horses);","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੇ ਅੰਤਿ ਅੰਤਕਰਿ ਪਦ ਕੋ ਡਾਰੀਐ।","roman":"Taa ke anti antakri pad ko daareeai |","meaning_en":"put the word 'antakari' (destroyer) at its end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਜੀਅ ਜਾਨੀਯੋ।","roman":"Sakal tupak ke naam sughar jeea jaaneeyo |","meaning_en":"O able one, know all these as names of the gun (tupak) in your heart;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਦੀਯੋ ਜਹਾ ਤੁਮ ਚਹੋ ਸੁ ਤਹੀ ਬਖਾਨੀਯੋ।੧੦੬੨।","roman":"Ho deeyo jahaa tum chaho su tahee bakhaaneeyo | 1062 |","meaning_en":"put them wherever you wish and say them there.","page":1005,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1005,"meaning_status":"draft"},{"type":"verse","number":[1063],"number_text":"੧੦੬੩।","page":1005,"lines":[{"gurmukhi":"ਸੈਂਧਵਨੀ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਡਾਰੋ।","roman":"Saindhavnee sabdaadi uchaaro | ari pad anti tavan ke daaro |","meaning_en":"First say the word 'Saindhavani' (having Sindhi horses); add the word 'ari' (enemy) at the end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨਹੁ। ੧੦੬੩।","roman":"Sakal tupak ke naam pachhaanhu | yaa mai bhed naiku nahee maanhu | 1063 |","meaning_en":"recognise all these as names of the gun (tupak); consider there to be no difference in this at all.","page":1005,"meaning_status":"draft"}]},{"type":"verse","number":[1064],"number_text":"੧੦੬੪।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਅਰਬਿਨੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Aadi arbinee sabad bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"First say the word 'Arbini' (having Arab horses); add the word 'ari' (enemy) at the end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਜਾਨਹੁ। ੧੦੬੪।","roman":"Sakal tupak ke naam pachhaanhu | yaa mai bhed naiku nahee jaanhu | 1064 |","meaning_en":"recognise all these as names of the gun (tupak); consider there to be no difference in this at all.","page":1005,"meaning_status":"draft"}]},{"type":"verse","number":[1065],"number_text":"੧੦੬੫।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਤੁਰੰਗਨੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤ ਪ੍ਰਮਾਨਹੁ।","roman":"Aadi turangnee sabad bakhaanhu | ari pad taa ke ant pramaanhu |","meaning_en":"First say the word 'Turangani' (having horses); add the word 'ari' (enemy) at the end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਈਐ। ਜਹ ਚਿਤ ਰੁਚੈ ਤਹੀ ਤੇ ਕਹੀਐ। ੧੦੬੫।","roman":"Sabh sree naam tupak ke laeeai | jah chit ruchai tahee te kaheeai | 1065 |","meaning_en":"take all these as names of the gun (tupak); say them wherever the mind likes.","page":1005,"meaning_status":"draft"}]},{"type":"verse","number":[1066],"number_text":"੧੦੬੬।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਘੋਰਨੀ ਸਬਦ ਭਨੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Aadi ghornee sabad bhaneejai | ari pad anti tavan ke deejai |","meaning_en":"First say the word 'Ghorani' (having horses); add the word 'ari' (enemy) at the end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਭੈ ਤੁਪਕ ਕੇ ਨਾਮ ਬਿਚਾਰੋ। ਜਹ ਚਾਹੋ ਤਿਨ ਤਹੀ ਉਚਾਰੋ। ੧੦੬੬।","roman":"Sabhai tupak ke naam bichaaro | jah chaaho tin tahee uchaaro | 1066 |","meaning_en":"regard all these as names of the gun (tupak); say them wherever you wish.","page":1005,"meaning_status":"draft"}]},{"type":"verse","number":[1067],"number_text":"੧੦੬੭।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਹਸਤਿਨੀ ਸਬਦ ਉਚਾਰੋ। ਰਿਪੁ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਡਾਰੋ।","roman":"Aadi hastinee sabad uchaaro | ripu pad anti tavan ke daaro |","meaning_en":"First say the word 'Hastini' (having elephants); add the word 'ripu' (enemy) at the end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਭੈ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹਿਜੈ। ਜਹ ਚਾਹੋ ਤੇ ਤਹੀ ਭਣਿਜੈ। ੧੦੬੭।","roman":"Sabhai tupak ke naam lahijai | jah chaaho te tahee bhanijai | 1067 |","meaning_en":"understand all these as names of the gun (tupak); say them wherever you wish.","page":1005,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":1005,"meaning_status":"draft"},{"type":"verse","number":[1068],"number_text":"੧੦੬੮।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਦੰਤਿਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi dantinee sabad uchaaran keejeeai |","meaning_en":"First say the word 'Dantini' (having tusked elephants);","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦੁ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Satroo sabdu ko anti tavan ke deejeeai |","meaning_en":"add the word 'shatru' (enemy) at the end;","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਛਾਨੀਐ।","roman":"Sakal tupak ke naam subudhi pachhaaneeai |","meaning_en":"O wise one, recognise all these as names of the gun (tupak);","page":1005,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨੀਐ।੧੦੬੮।","roman":"Ho yaa ke bheetar bhed naiku nahee maaneeai | 1068 |","meaning_en":"consider there to be no difference in this at all.","page":1005,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1005,"meaning_status":"draft"},{"type":"verse","number":[1069],"number_text":"੧੦੬੯।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਦੁਰਦਨੀ ਸਬਦ ਬਖਾਨਹੁ। ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਠਾਨਹੁ।","roman":"Aadi duradnee sabad bakhaanhu | taa ke anti satroo pad thaanhu |","meaning_en":"Say the word 'duradni' (army of elephants) first, and place the word 'satru' (enemy) at its end:","page":1005,"meaning_status":"draft","note":"ਦੁਰਦਨੀ: durad 'elephant' + -ni, read as 'army having elephants'; ਤੁਪਕ (tupak) = gun/musket throughout this part."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ਯਾ ਕੇ ਬਿਖੈ ਭੇਦ ਨਹੀ ਕਿਜੈ। ੧੦੬੯।","roman":"Naam tupak ke sakal lahijai | yaa ke bikhai bhed nahee kijai | 1069 |","meaning_en":"take these as all the names of the gun; make no distinction in this.","page":1005,"meaning_status":"draft"}]},{"type":"verse","number":[1070],"number_text":"੧੦੭੦।","page":1005,"lines":[{"gurmukhi":"ਦ੍ਵਿਪਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Dvipnee aadi uchaaran keejai | ari pad anti tavan ke deejai |","meaning_en":"Utter 'dvipni' (army of elephants) first, and put the word 'ari' (enemy) at its end:","page":1005,"meaning_status":"draft","note":"ਦ੍ਵਿਪਨੀ: dvip 'elephant' + -ni; read as 'army of elephants'."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਜਹ ਚਾਹੋ ਤਹ ਹੀ ਤੇ ਕਹੀਐ। ੧੦੭੦।","roman":"Sabh sree naam tupak ke laheeai | jah chaaho tah hee te kaheeai | 1070 |","meaning_en":"know all these as the honoured names of the gun; say them wherever you wish.","page":1005,"meaning_status":"draft"}]},{"type":"verse","number":[1071],"number_text":"੧੦੭੧।","page":1005,"lines":[{"gurmukhi":"ਆਦਿ ਪਦਮਿਨੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Aadi padminee sabad bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"Say the word 'padmini' first, and place the word 'ari' at its end:","page":1005,"meaning_status":"draft","note":"ਪਦਮਿਨੀ: here likely padmi 'elephant' + -ni, 'army of elephants'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹੀਜੈ। ਯਾ ਮੈ ਭੇਦ ਨ ਕਛਹੂ ਕੀਜੈ। ੧੦੭੧।","roman":"Naam tupak ke sakal laheejai | yaa mai bhed na kachhhoo keejai | 1071 |","meaning_en":"take these as all the names of the gun; make no distinction at all in this.","page":1005,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1006,"meaning_status":"draft"},{"type":"verse","number":[1072],"number_text":"੧੦੭੨।","page":1006,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਬਾਰਣੀ ਮੁਖ ਤੇ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Pritham baarnee mukh te sabad bakhaaneeai |","meaning_en":"First utter from the mouth the word 'barani' (army of elephants),","page":1006,"meaning_status":"draft","note":"ਬਾਰਣੀ: baran 'elephant' + -i; read as 'army of elephants'; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅਤਿ ਤਵਨ ਕੋ ਠਾਨੀਐ।","roman":"Satroo sabad ko ati tavan ko thaaneeai |","meaning_en":"and put the word 'satru' at its end.","page":1006,"meaning_status":"draft","note":"ਅਤਿ: printed so; read as ਅੰਤਿ 'at the end'."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਕਬਿ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam su kabi lahi leejeeai |","meaning_en":"O good poet, take these as all the names of the gun;","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੀਐ।੧੦੭੨।","roman":"Ho yaa ke bheetar bhed naiku nahee keejeeai | 1072 |","meaning_en":"make not the slightest distinction in this.","page":1006,"meaning_status":"draft","note":"ਹੋ: metrical filler at the start of the last Aril line; not translated."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1006,"meaning_status":"draft"},{"type":"verse","number":[1073],"number_text":"੧੦੭੩।","page":1006,"lines":[{"gurmukhi":"ਆਦਿ ਬਿਆਲਣੀ ਸਬਦ ਬਖਾਨਹੋ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Aadi biaalnee sabad bakhaanho | ari pad anti tavan ke thaanhu |","meaning_en":"Say the word 'byalani' first, and place the word 'ari' at its end:","page":1006,"meaning_status":"draft","note":"ਬਿਆਲਣੀ: byal 'elephant' (or 'snake') + -ni; read here as 'army of elephants'; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨਹੋ। ੧੦੭੩।","roman":"Sabh sree naam tupak ke jaanhu | yaa mai bhed naiku nahee maanho | 1073 |","meaning_en":"know all these as the honoured names of the gun; accept not the slightest difference in this.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1074],"number_text":"੧੦੭੪।","page":1006,"lines":[{"gurmukhi":"ਇੰਭਣੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Inbhnee aadi uchaaran keejai | ari pad anti tavan ke deejai |","meaning_en":"Utter 'ibhani' (army of elephants) first, and put the word 'ari' at its end:","page":1006,"meaning_status":"draft","note":"ਇੰਭਣੀ: ibh 'elephant' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਵੇ। ਜਾ ਕੋ ਸਕਲ ਸੁ ਕਬਿ ਕੁਲ ਜੋਵੈ। ੧੦੭੪।","roman":"Sabh sree naam tupak ke hove | jaa ko sakal su kabi kul jovai | 1074 |","meaning_en":"these become all the honoured names of the gun, which the whole company of good poets looks upon.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1075],"number_text":"੧੦੭੫।","page":1006,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਕੁੰਭਣੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਜਾਨਹੁ।","roman":"Pratham kunbhnee sabad bakhaanhu | ari pad anti tavan ke jaanhu |","meaning_en":"First say the word 'kumbhani' (army of elephants), and know the word 'ari' to come at its end:","page":1006,"meaning_status":"draft","note":"ਕੁੰਭਣੀ: kumbhi 'elephant' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਨਿਤਪ੍ਰਤਿ ਮੁਖ ਤੇ ਪਾਠ ਕਰੀਜੈ। ੧੦੭੫।","roman":"Sakal tupak ke naam laheejai | nitprati mukh te paath kareejai | 1075 |","meaning_en":"take these as all the names of the gun, and recite them daily with your mouth.","page":1006,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1006,"meaning_status":"draft"},{"type":"verse","number":[1076],"number_text":"੧੦੭੬।","page":1006,"lines":[{"gurmukhi":"ਕੁੰਜਰਣੀ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Kunjarnee sabdaadi uchaaran keejeeai |","meaning_en":"Utter the word 'kunjarani' (army of elephants) first,","page":1006,"meaning_status":"draft","note":"ਕੁੰਜਰਣੀ: kunjar 'elephant' + -ni."},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤ ਬਹੁਰ ਕਹਿ ਦੀਜੀਐ।","roman":"Ari pad taa ke ant bahur kahi deejeeai |","meaning_en":"then say the word 'ari' at its end.","page":1006,"flags":[{"code":"ੰੰ","reason":"same sign typed twice; written once (prints as one)"}],"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam subudhi jeea jaaneeai |","meaning_en":"O wise one, know in your mind these as all the names of the gun;","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨੀਐ।੧੦੭੬।","roman":"Ho yaa ke bheetar bhed naiku nahee maaneeai | 1076 |","meaning_en":"accept not the slightest distinction in this.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1077],"number_text":"੧੦੭੭।","page":1006,"lines":[{"gurmukhi":"ਕਰਿਨੀ ਸਬਦਿ ਸੁ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Karinee sabdi su mukh te aadi bakhaaneeai |","meaning_en":"First utter from the mouth the word 'karini' (army of elephants),","page":1006,"meaning_status":"draft","note":"ਕਰਿਨੀ: kari 'elephant' + -ni."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Satroo sabad ko anti tavan ke thaaneeai |","meaning_en":"and put the word 'satru' at its end.","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਕਬਿ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam su kabi lahi leejeeai |","meaning_en":"O good poet, take these as all the names of the gun;","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਦੀਯੋ ਚਹੋ ਜਿਹ ਠਵਰ ਤਹਾ ਹੀ ਦੀਜੀਐ।੧੦੭੭।","roman":"Ho deeyo chaho jih thavar tahaa hee deejeeai | 1077 |","meaning_en":"wherever you wish to place them, place them there.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1078],"number_text":"੧੦੭੮।","page":1006,"lines":[{"gurmukhi":"ਮਦ੍ਯ ਧਰਨਨੀ ਮੁਖ ਤੇ ਆਦਿ ਭਨੀਜੀਐ।","roman":"Mady dharannee mukh te aadi bhaneejeeai |","meaning_en":"First say from the mouth 'madya-dharanani' (army of those that hold rut-fluid, i.e. elephants),","page":1006,"meaning_status":"draft","note":"ਮਦ੍ਯ ਧਰਨਨੀ: 'holders of mada (musth)' = elephants, + -ni; uncertain."},{"gurmukhi":"ਹੰਤਾ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Hantaa taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'hanta' (slayer) at its end.","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤ ਮੈ ਲਹੋ।","roman":"Sakal tupak ke naam chatur chit mai laho |","meaning_en":"O clever one, take these in your mind as all the names of the gun;","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹ੍ਯੋ ਚਹੋ ਇਨ ਜਹਾ ਤਹਾ ਇਨ ਕੌ ਕਹੋ।੧੦੭੮।","roman":"Ho kahyo chaho in jahaa tahaa in kau kaho | 1078 |","meaning_en":"wherever you wish to say them, say them there.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1079],"number_text":"੧੦੭੯।","page":1006,"lines":[{"gurmukhi":"ਸਿੰਧੁਰਨੀ ਮੁਖ ਤੇ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Sindhurnee mukh te sabdaadi bakhaaneeai |","meaning_en":"Utter from the mouth the word 'sindhurani' (army of elephants) first,","page":1006,"meaning_status":"draft","note":"ਸਿੰਧੁਰਨੀ: sindhur 'elephant' + -ni."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Satroo sabad ko anti tavan ke thaaneeai |","meaning_en":"and put the word 'satru' at its end.","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸ ੁਕਬਿ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam sa kabi jeea jaaneeai |","meaning_en":"O good poet, know in your mind these as all the names of the gun;","page":1006,"meaning_status":"draft","note":"ਸ ੁਕਬਿ: printed so; read as ਸੁ ਕਬਿ."},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕ ਨਹੀ ਮਾਨੀਐ। ੧੦੭੯।","roman":"Ho yaa ke bheetar bhed naik nahee maaneeai | 1079 |","meaning_en":"accept not the slightest distinction in this.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1080],"number_text":"੧੦੮੦।","page":1006,"lines":[{"gurmukhi":"ਅਨਕਪਨੀ ਪਦ ਮੁਖ ਤੇ ਪ੍ਰਿਥਮ ਭਣੀਜੀਐ।","roman":"Ankapnee pad mukh te pritham bhaneejeeai |","meaning_en":"First say from the mouth the word 'anakpani' (army of elephants),","page":1006,"meaning_status":"draft","note":"ਅਨਕਪਨੀ: anekap 'elephant' + -ni; printed ਅਨਕਪ."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Satroo sabad ko anti tavan ke deejeeai |","meaning_en":"and give the word 'satru' at its end.","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1006,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਦਯੋ ਚਹੋ ਜਿਹ ਠਵਰੈ ਤਹੀ ਪ੍ਰਮਾਨੀਐ। ੧੦੮੦।","roman":"Ho dayo chaho jih thavrai tahee pramaaneeai | 1080 |","meaning_en":"wherever you wish to give them, accept them there.","page":1006,"meaning_status":"draft"}]},{"type":"verse","number":[1081],"number_text":"੧੦੮੧।","page":1007,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਗਨੀ ਮੁਖ ਤੇ ਸਬਦ ਉਚਾਰੀਐ।","roman":"Pritham naagnee mukh te sabad uchaareeai |","meaning_en":"First utter from the mouth the word 'nagani' (army of elephants),","page":1007,"meaning_status":"draft","note":"ਨਾਗਨੀ: nag 'elephant' (also 'serpent') + -ni; read here as elephant-army."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਅੰਤਿ ਤਵਨ ਕੇ ਡਾਰੀਐ।","roman":"Satroo sabad kahu anti tavan ke daareeai |","meaning_en":"and put the word 'satru' at its end.","page":1007,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1007,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੀਐ। ੧੦੮੧।","roman":"Ho yaa ke bheetar bhed naiku nahee keejeeai | 1081 |","meaning_en":"make not the slightest distinction in this.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1082],"number_text":"੧੦੮੨।","page":1007,"lines":[{"gurmukhi":"ਹਰਿਨੀ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Harinee sabad su mukh te aadi bakhaaneeai |","meaning_en":"First say from the mouth the word 'harini' (army of elephants),","page":1007,"meaning_status":"draft","note":"ਹਰਿਨੀ: hari here likely 'elephant' + -ni; uncertain (hari has many meanings)."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Satroo sabad ko taa ke anti pramaaneeai |","meaning_en":"and set the word 'satru' at its end.","page":1007,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਅਉ।","roman":"Sabh sree naam tupak ke chatur pachhaaneeau |","meaning_en":"O clever one, recognise these as all the honoured names of the gun,","page":1007,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨੈ ਠਵਰ ਸੁ ਚਹੀਐ ਤਹੀ ਬਖਾਨੀਅਉ। ੧੦੮੨।","roman":"Ho javnai thavar su chaheeai tahee bakhaaneeau | 1082 |","meaning_en":"and speak them in whatever place you want.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1083],"number_text":"੧੦੮੩।","page":1007,"lines":[{"gurmukhi":"ਗਜਨੀ ਸਬਦ ਬਕਤ੍ਰ ਤੇ ਆਦਿ ਭਨੀਜੀਐ।","roman":"Gajnee sabad bakatr te aadi bhaneejeeai |","meaning_en":"First say from the mouth the word 'gajani' (army of elephants),","page":1007,"meaning_status":"draft","note":"ਗਜਨੀ: gaj 'elephant' + -ni."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Satroo sabad ko anti tavan ke deejeeai |","meaning_en":"and give the word 'satru' at its end.","page":1007,"meaning_status":"draft"},{"gurmukhi":"ਚਤੁਰ ਤੁਪਕ ਕੇ ਨਾਮ ਸਕਲ ਲਹਿ ਲੀਜੀਐ।","roman":"Chatur tupak ke naam sakal lahi leejeeai |","meaning_en":"O clever one, take these as all the names of the gun;","page":1007,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੦੮੩।","roman":"Ho jih chaaho tih thavar uchaaran keejeeai | 1083 |","meaning_en":"utter them in whatever place you wish.","page":1007,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1007,"meaning_status":"draft"},{"type":"verse","number":[1084],"number_text":"੧੦੮੪।","page":1007,"lines":[{"gurmukhi":"ਸਾਵਜਨੀ ਸਬਦਾਦਿ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Saavajnee sabdaadi bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"Say the word 'savajani' first, and place the word 'ari' at its end:","page":1007,"meaning_status":"draft","note":"ਸਾਵਜਨੀ: savaj 'wild beast/elephant' + -ni; read as 'army of elephants'; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਜਿਹ ਠਾ ਚਹੋ ਤਹੀ ਤੇ ਕਹੀਐ। ੧੦੮੪।","roman":"Sabh sree naam tupak ke laheeai | jih thaa chaho tahee te kaheeai | 1084 |","meaning_en":"take these as all the honoured names of the gun; say them in whatever place you wish.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1085],"number_text":"੧੦੮੫।","page":1007,"lines":[{"gurmukhi":"ਮਾਤੰਗਨੀ ਪਦਾਦਿ ਭਣਿਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦਿਜੈ।","roman":"Maatangnee padaadi bhanijai | ari pad anti tavan ke dijai |","meaning_en":"Say the word 'matangani' (army of elephants) first, and give the word 'ari' at its end:","page":1007,"meaning_status":"draft","note":"ਮਾਤੰਗਨੀ: matang 'elephant' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਵੈ। ਜਾ ਕੋ ਸਕਲ ਸੁ ਕਬਿ ਮਿਲ ਜੋਵੈ। ੧੦੮੫।","roman":"Sabh sree naam tupak ke hovai | jaa ko sakal su kabi mil jovai | 1085 |","meaning_en":"these become all the honoured names of the gun, which good poets together look upon.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1086],"number_text":"੧੦੮੬।","page":1007,"lines":[{"gurmukhi":"ਆਦਿ ਗਇੰਦਨਿ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Aadi gaindni sabad bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"Say the word 'gayandani' (army of elephants) first, and place the word 'ari' at its end:","page":1007,"meaning_status":"draft","note":"ਗਇੰਦਨਿ: gayand 'great elephant' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਜਵਨੈ ਠਵਰ ਰੁਚੈ ਤਹ ਕਹੀਐ। ੧੦੮੬।","roman":"Sabh sree naam tupak ke laheeai | javnai thavar ruchai tah kaheeai | 1086 |","meaning_en":"take these as all the honoured names of the gun; say them in whatever place you like.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1087],"number_text":"੧੦੮੭।","page":1007,"lines":[{"gurmukhi":"ਦ੍ਰੁਮ ਅਰਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Drum ari aadi uchaaran keejai | ari pad anti tavan ke deejai |","meaning_en":"Utter 'drum-ari' (enemy of trees, i.e. elephant) first, and give the word 'ari' at its end:","page":1007,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਦ੍ਰੁਮ ਅਰਿ: 'enemy of trees' = elephant; presumably understood with -ni (army) before the final ari; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਨ ਕਛੁ ਜੀਅ ਜਾਨੋ। ੧੦੮੭।","roman":"Naam tupak ke sakal pachhaano | yaa mai bhed na kachhu jeea jaano | 1087 |","meaning_en":"recognise these as all the names of the gun; know no difference at all in your mind in this.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1088],"number_text":"੧੦੮੮।","page":1007,"lines":[{"gurmukhi":"ਬ੍ਰਿਛਾਂਤਕਣੀ ਆਦਿ ਉਚਾਰੋ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਡਾਰੋ।","roman":"Brichhaantaknee aadi uchaaro | ari pad anti tavan ke daaro |","meaning_en":"Utter 'brichhantakani' (army of the destroyers of trees, i.e. elephants) first, and put the word 'ari' at its end:","page":1007,"meaning_status":"draft","note":"ਬ੍ਰਿਛਾਂਤਕਣੀ: brichh 'tree' + antak 'ender' = elephant, + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਦਯੋ ਚਹੇ ਜਹ ਠਾ ਤਹ ਕਹੀਐ। ੧੦੮੮।","roman":"Sabh sree naam tupak ke laheeai | dayo chahe jah thaa tah kaheeai | 1088 |","meaning_en":"take these as all the honoured names of the gun; say them in whatever place you wish to give them.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1089],"number_text":"੧੦੮੯।","page":1007,"lines":[{"gurmukhi":"ਫਲਧਰ ਅਰਿਣੀ ਆਦਿ ਕਹੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Phaldhar arinee aadi kaheejai | ari pad anti tavan ke deejai |","meaning_en":"Say 'phaldhar-arini' (army of the enemies of fruit-bearers, i.e. elephants) first, and give the word 'ari' at its end:","page":1007,"meaning_status":"draft","note":"ਫਲਧਰ ਅਰਿਣੀ: 'fruit-bearer' = tree; its enemy = elephant; + -ni = army; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਜਹਾ ਚਹੋ ਤਿਹ ਠਵਰ ਬਖਾਨੋ। ੧੦੮੯।","roman":"Sabh sree naam tupak ke jaano | jahaa chaho tih thavar bakhaano | 1089 |","meaning_en":"know these as all the honoured names of the gun; speak them in whatever place you wish.","page":1007,"meaning_status":"draft"}]},{"type":"verse","number":[1090],"number_text":"੧੦੯੦।","page":1007,"lines":[{"gurmukhi":"ਫਲਦਾਇਕ ਅਰਿਣੀ ਅਹਿ ਉਚਰੀਐ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਡਰੀਐ।","roman":"Phaldaaik arinee ahi uchreeai | ari pad anti tavan ke dareeai |","meaning_en":"Utter 'phaldayak-arini' (army of the enemies of fruit-givers, i.e. elephants) first, and put the word 'ari' at its end:","page":1007,"meaning_status":"draft","note":"ਫਲਦਾਇਕ ਅਰਿਣੀ: 'fruit-giver' = tree; enemy = elephant; -ni = army. ਅਹਿ: printed so, read as ਆਦਿ 'first'; ਡਰੀਐ read as ਡਾਰੀਐ 'put'. Uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਨ ਰੰਚਕ ਮਾਨੋ। ੧੦੯੦।","roman":"Sabh sree naam tupak ke jaano | yaa mai bhed na ranchak maano | 1090 |","meaning_en":"know these as all the honoured names of the gun; accept not the least difference in this.","page":1007,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1008,"meaning_status":"draft"},{"type":"verse","number":[1091],"number_text":"੧੦੯੧।","page":1008,"lines":[{"gurmukhi":"ਧਰਾਧਰਨ ਅਰਿਣੀ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Dharaadhran arinee sabdaadi bakhaaneeai |","meaning_en":"Say first the word 'dharadharan-arini' (army of the enemies of the earth-holders, i.e. trees),","page":1008,"meaning_status":"draft","note":"ਧਰਾਧਰਨ ਅਰਿਣੀ: 'earth-holder' = tree (or mountain); enemy = elephant; -ni = army; uncertain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Satroo sabad ko anti tavan ke thaaneeai |","meaning_en":"and put the word 'satru' at its end.","page":1008,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1008,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਤਿਨ ਚਹੋ ਤਹੀ ਤੇ ਦੀਜੀਐ। ੧੦੯੧।","roman":"Ho javan thavar tin chaho tahee te deejeeai | 1091 |","meaning_en":"wherever you wish them, give them from there.","page":1008,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1008,"meaning_status":"draft"},{"type":"verse","number":[1092],"number_text":"੧੦੯੨।","page":1008,"lines":[{"gurmukhi":"ਧੂਰਿਰਾਟ ਅਰਿਣੀ ਪਦ ਭਾਖੋ। ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਰਾਖੋ।","roman":"Dhooriraat arinee pad bhaakho | taa ke anti satroo pad raakho |","meaning_en":"Say the word 'dhuriraat-arini', and keep the word 'satru' at its end:","page":1008,"meaning_status":"draft","note":"ਧੂਰਿਰਾਟ ਅਰਿਣੀ: dhuriraat obscure, perhaps 'king of the soil' = tree; enemy = elephant; -ni = army; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ਜਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਪ੍ਰਮਾਨੋ। ੧੦੯੨।","roman":"Sabh sree naam tupak ke jaano | jah chaaho tih thavar pramaano | 1092 |","meaning_en":"know these as all the honoured names of the gun; accept them in whatever place you wish.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1093],"number_text":"੧੦੯੩।","page":1008,"lines":[{"gurmukhi":"ਫਲਧ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਡਾਰਹੁ।","roman":"Phaladh sabad ko aadi uchaarhu | ari pad anti tavan ke daarhu |","meaning_en":"Utter the word 'phaladh' (fruit-giver, i.e. tree) first, and put the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਫਲਧ: 'fruit-giver' = tree; the chain to 'gun' seems to omit a step (enemy of tree = elephant, -ni = army); uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਜਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਬਖਾਨਹੁ। ੧੦੯੩।","roman":"Sabh sree naam tupak ke jaanhu | jah chaaho tih thavar bakhaanhu | 1093 |","meaning_en":"know these as all the honoured names of the gun; speak them in whatever place you wish.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1094],"number_text":"੧੦੯੪।","page":1008,"lines":[{"gurmukhi":"ਫਲਿ ਸਬਦ ਕੋ ਆਦਿ ਭਣਿਜੈ। ਅਰਿ ਪਦ ਕਹਿ ਰਿਪੁ ਪਦ ਪੁਨਿ ਦਿਜੈ।","roman":"Phali sabad ko aadi bhanijai | ari pad kahi ripu pad puni dijai |","meaning_en":"Say the word 'phali' (fruit-bearer, i.e. tree) first; say the word 'ari', then give the word 'ripu' (enemy):","page":1008,"meaning_status":"draft","note":"ਫਲਿ: read as 'that which bears fruit' = tree; tree + ari = elephant, (army) + ripu = gun; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਚਹੀਐ ਜਹਾ ਤਹੀ ਤੇ ਕਹੀਐ। ੧੦੯੪।","roman":"Sabh sree naam tupak ke laheeai | chaheeai jahaa tahee te kaheeai | 1094 |","meaning_en":"take these as all the honoured names of the gun; say them wherever they are wanted.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1095],"number_text":"੧੦੯੫।","page":1008,"lines":[{"gurmukhi":"ਤਰੁ ਅਰਿਣੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੋ।","roman":"Taru arinee sabdaadi bakhaano | ari pad anti tavan ke thaano |","meaning_en":"Say first the word 'taru-arini' (army of the enemies of trees, i.e. elephants), and place the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਤਰੁ ਅਰਿਣੀ: taru 'tree' + ari 'enemy' (= elephant) + -ni 'army'."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨਹੁ। ੧੦੯੫।","roman":"Sakal tupak ke naam pachhaano | yaa mai bhed naiku nahee maanhu | 1095 |","meaning_en":"recognise these as all the names of the gun; accept not the slightest difference in this.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1096],"number_text":"੧੦੯੬।","page":1008,"lines":[{"gurmukhi":"ਧਰਿਸ ਅਰਿਣੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦਿਜੈ।","roman":"Dharis arinee sabdaadi bhanijai | ari pad anti tavan ke dijai |","meaning_en":"Say first the word 'dharis-arini', and give the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਧਰਿਸ ਅਰਿਣੀ: dharis perhaps 'lord of the earth' (dhara + is) = tree or king; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਕੇ ਬਿਖੈ ਭੇਦ ਨਹੀ ਜਾਨੋ। ੧੦੯੬।","roman":"Sakal tupak ke naam pachhaano | yaa ke bikhai bhed nahee jaano | 1096 |","meaning_en":"recognise these as all the names of the gun; know no difference in this.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1097],"number_text":"੧੦੯੭।","page":1008,"lines":[{"gurmukhi":"ਬਿਰਛਰਿਣੀ ਸਬਦਾਦਿ ਭਣੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Birachhrinee sabdaadi bhaneejai | ari pad anti tavan ke deejai |","meaning_en":"Say first the word 'birchharini' (army of the enemies of trees), and give the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਬਿਰਛਰਿਣੀ: birchh 'tree' + arini."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਅ ਲਹੀਐ। ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਸੁ ਕਹੀਐ। ੧੦੯੭।","roman":"Naam tupak ke sabh jeea laheeai | jih chaaho tih thavar su kaheeai | 1097 |","meaning_en":"take in your mind all these as names of the gun; say them in whatever place you wish.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1098],"number_text":"੧੦੯੮।","page":1008,"lines":[{"gurmukhi":"ਰਦਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Radnee aadi uchaaran keejai | ari pad anti tavan ke deejai |","meaning_en":"Utter 'radani' (army of tusked ones, i.e. elephants) first, and give the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਰਦਨੀ: rad 'tusk', radi 'tusked one' = elephant, + -ni; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਹਿ ਲੀਜੈ। ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਸੁ ਭਨੀਜੈ। ੧੦੯੮।","roman":"Sabh sree naam tupak lahi leejai | jih chaaho tih thavar su bhaneejai | 1098 |","meaning_en":"take these as all the honoured names of the gun; speak them in whatever place you wish.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1099],"number_text":"੧੦੯੯।","page":1008,"lines":[{"gurmukhi":"ਰਦਨਛੰਦਨੀ ਅਰਿਣੀ ਭਾਖੋ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਰਾਖੋ।","roman":"Radanchhandnee arinee bhaakho | ari pad anti tavan ke raakho |","meaning_en":"Say 'radan-chhandani arini', and keep the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਰਦਨਛੰਦਨੀ ਅਰਿਣੀ: obscure compound built on rad 'tusk'; perhaps 'tusk-bearer' = elephant; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਜਾਨੋ। ੧੦੯੯।","roman":"Sakal tupak ke naam pachhaano | yaa mai bhed naiku nahee jaano | 1099 |","meaning_en":"recognise these as all the names of the gun; know not the slightest difference in this.","page":1008,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1008,"meaning_status":"draft"},{"type":"verse","number":[1100],"number_text":"੧੧੦੦।","page":1008,"lines":[{"gurmukhi":"ਨਾਮ ਸਕਲ ਦੰਤਨ ਕੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Naam sakal dantan ke aadi bakhaaneeai |","meaning_en":"First say all the names of teeth (tusks),","page":1008,"meaning_status":"draft","note":"ਦੰਤਨ: 'teeth/tusks'; the chain is presumably tusk → tusked one (elephant) → army → enemy; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Arinee ari pad anti tavan ke thaaneeai |","meaning_en":"then put the words 'arini' and 'ari' at their end.","page":1008,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1008,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਦੀਯੋ ਚਹੋ ਜਿਹ ਠਵਰ ਤਹਾ ਹੀ ਦੀਜੀਐ। ੧੧੦੦।","roman":"Ho deeyo chaho jih thavar tahaa hee deejeeai | 1100 |","meaning_en":"wherever you wish to place them, place them there.","page":1008,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1008,"meaning_status":"draft"},{"type":"verse","number":[1101],"number_text":"੧੧੦੧।","page":1008,"lines":[{"gurmukhi":"ਨ੍ਰਿਪਣੀ ਆਦਿ ਬਖਾਨਨ ਕੀਜੈ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੈ।","roman":"Nripnee aadi bakhaanan keejai | ari pad anti tavan ke deejai |","meaning_en":"Speak the word 'nripani' (army of kings) first, and give the word 'ari' at its end:","page":1008,"meaning_status":"draft","note":"ਨ੍ਰਿਪਣੀ: nrip 'king' + -ni; read as 'army of kings'."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਕਛੁ ਨਹੀ ਜਾਨੋ। ੧੧੦੧।","roman":"Sakal tupak ke naam pachhaano | yaa mai bhed kachhu nahee jaano | 1101 |","meaning_en":"recognise these as all the names of the gun; know no difference in this.","page":1008,"meaning_status":"draft"}]},{"type":"verse","number":[1102],"number_text":"੧੧੦੨।","page":1009,"lines":[{"gurmukhi":"ਆਦਿ ਭੂਪਨੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Aadi bhoopnee sabad bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"Say the word 'bhupani' (army of kings) first, and place the word 'ari' at its end:","page":1009,"meaning_status":"draft","note":"ਭੂਪਨੀ: bhup 'king' + -ni."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਭਣੀਜੈ। ੧੧੦੨।","roman":"Naam tupak ke sabh lahi leejai | jih chaaho tih thavar bhaneejai | 1102 |","meaning_en":"take all these as names of the gun; speak them in whatever place you wish.","page":1009,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1009,"meaning_status":"draft"},{"type":"verse","number":[1103],"number_text":"੧੧੦੩।","page":1009,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸੁਆਮਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Pritham suaamnee sabad uchaaran keejeeai |","meaning_en":"First utter the word 'suamani' (army of lords),","page":1009,"meaning_status":"draft","note":"ਸੁਆਮਨੀ: suami 'lord, master' + -ni."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Satroo sabad ko anti tavan ke deejeeai |","meaning_en":"and give the word 'satru' at its end.","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨੀਐ। ੧੧੦੩।","roman":"Ho yaa ke bheetar bhed naiku nahee maaneeai | 1103 |","meaning_en":"accept not the slightest distinction in this.","page":1009,"meaning_status":"draft"}]},{"type":"verse","number":[1104],"number_text":"੧੧੦੪।","page":1009,"lines":[{"gurmukhi":"ਆਦਿ ਅਧਿਪਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi adhipnee sabad uchaaran keejeeai |","meaning_en":"Utter the word 'adhipani' (army of rulers) first,","page":1009,"meaning_status":"draft","note":"ਅਧਿਪਨੀ: adhip 'ruler' + -ni."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Satroo sabad ko anti tavan ke deejeeai |","meaning_en":"and give the word 'satru' at its end.","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨੀਐ। ੧੧੦੪।","roman":"Ho yaa ke bheetar bhed naiku nahee maaneeai | 1104 |","meaning_en":"accept not the slightest distinction in this.","page":1009,"meaning_status":"draft"}]},{"type":"verse","number":[1105],"number_text":"੧੧੦੫।","page":1009,"lines":[{"gurmukhi":"ਧਰਦ੍ਰਿੜਨੀ ਮੁਖ ਤੇ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Dhardrirnee mukh te sabdaadi bakhaaneeai |","meaning_en":"Say from the mouth first the word 'dhar-drirhani',","page":1009,"meaning_status":"draft","note":"ਧਰਦ੍ਰਿੜਨੀ: perhaps 'those firm in holding (the earth)' = kings, + -ni = army; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Arinee taa ke anti sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jee leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਘਰ ਚਹੋ ਜਿਹਾ ਠਵਰ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੧੦੫।","roman":"Ho sughar chaho jihaa thavar uchaaran keejeeai | 1105 |","meaning_en":"O skilful one, utter them in whatever place you wish.","page":1009,"meaning_status":"draft"}]},{"type":"verse","number":[1106],"number_text":"੧੧੦੬।","page":1009,"lines":[{"gurmukhi":"ਆਦਿ ਅਧਿਪਨੀ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਭਾਖੀਐ।","roman":"Aadi adhipnee sabad su mukh te bhaakheeai |","meaning_en":"Say from the mouth first the word 'adhipani' (army of rulers),","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Satroo sabad ko anti tavan ke raakheeai |","meaning_en":"and keep the word 'satru' at its end.","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੈ ਚਹੀਐ ਤਹੀ ਪ੍ਰਮਾਨੀਐ। ੧੧੦੬।","roman":"Ho javan thavar mai chaheeai tahee pramaaneeai | 1106 |","meaning_en":"accept them in whatever place you want.","page":1009,"meaning_status":"draft","note":"Repeats the head word of 5.760.0 (ਅਧਿਪਨੀ)."}]},{"type":"verse","number":[1107],"number_text":"੧੧੦੭।","page":1009,"lines":[{"gurmukhi":"ਪਤਿਣੀ ਆਦਿ ਬਖਾਨ ਸਤ੍ਰੂਣੀ ਭਾਖੀਐ।","roman":"Patinee aadi bakhaan satroonee bhaakheeai |","meaning_en":"Say 'patini' (army of lords) first, then say 'satruni';","page":1009,"meaning_status":"draft","note":"ਪਤਿਣੀ: pati 'lord' + -ni; ਸਤ੍ਰੂਣੀ: satru with the -ni ending."},{"gurmukhi":"ਹੋਤ ਤੁਪਕ ਕੇ ਨਾਮ ਹ੍ਰਿਦੈ ਮੈ ਰਾਖੀਐ।","roman":"Hot tupak ke naam hridai mai raakheeai |","meaning_en":"these become names of the gun; keep them in your heart.","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਇਨ ਕੇ ਭੀਤਰ ਭੇਦ ਨ ਨੈਕੁ ਪਛਾਨੀਐ।","roman":"In ke bheetar bhed na naiku pachhaaneeai |","meaning_en":"Recognise not the slightest distinction among them;","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੈ ਚਹੀਐ ਤਹੀ ਪ੍ਰਮਾਨੀਐ। ੧੧੦੭।","roman":"Ho javan thavar mai chaheeai tahee pramaaneeai | 1107 |","meaning_en":"accept them in whatever place you want.","page":1009,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1009,"meaning_status":"draft"},{"type":"verse","number":[1108],"number_text":"੧੧੦੮।","page":1009,"lines":[{"gurmukhi":"ਭੂਪਤਿਣੀ ਸਬਦਾਦਿ ਬਖਾਨੋ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Bhooptinee sabdaadi bakhaano | arinee sabad anti tih thaano |","meaning_en":"Say first the word 'bhupatini' (army of kings), and place the word 'arini' at its end:","page":1009,"meaning_status":"draft","note":"ਭੂਪਤਿਣੀ: bhupati 'king' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਜਵਨੈ ਠਵਰ ਰੁਚੈ ਤਹ ਕਹੀਐ। ੧੧੦੮।","roman":"Sabh sree naam tupak ke laheeai | javnai thavar ruchai tah kaheeai | 1108 |","meaning_en":"take these as all the honoured names of the gun; say them in whatever place you like.","page":1009,"meaning_status":"draft"}]},{"type":"verse","number":[1109],"number_text":"੧੧੦੯।","page":1009,"lines":[{"gurmukhi":"ਆਦਿ ਭੂਪਣੀ ਸਬਦ ਬਖਾਨਹੁ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਹੁ।","roman":"Aadi bhoopnee sabad bakhaanhu | ari pad anti tavan ke thaanhu |","meaning_en":"Say the word 'bhupani' (army of kings) first, and place the word 'ari' at its end:","page":1009,"meaning_status":"draft","note":"Same head word as 5.757.0 (ਭੂਪਨੀ/ਭੂਪਣੀ)."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ਜਿਹ ਠਾ ਰੁਚੈ ਸੁ ਤਹੀ ਪ੍ਰਮਾਨੋ। ੧੧੦੯।","roman":"Naam tupak ke sakal pachhaano | jih thaa ruchai su tahee pramaano | 1109 |","meaning_en":"recognise these as all the names of the gun; accept them in whatever place you like.","page":1009,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1009,"meaning_status":"draft"},{"type":"verse","number":[1110],"number_text":"੧੧੧੦।","page":1009,"lines":[{"gurmukhi":"ਬਧਕਰਣੀ ਮੁਖ ਤੇ ਸਬਦਾਦਿ ਉਚਾਰੀਐ।","roman":"Badhkarnee mukh te sabdaadi uchaareeai |","meaning_en":"Utter from the mouth first the word 'badhkarani' (army of slayers),","page":1009,"meaning_status":"draft","note":"ਬਧਕਰਣੀ: badhkar 'one who slays' + -ni; perhaps 'army of servants/attendants' (read as badh-kar?); uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Arinee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1009,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਰੁਚਿ ਹੋਇ ਤਹੀ ਤੇ ਦੀਜੀਐ। ੧੧੧੦।","roman":"Ho javan thavar ruchi hoi tahee te deejeeai | 1110 |","meaning_en":"give them from whatever place you like.","page":1009,"meaning_status":"draft"}]},{"type":"verse","number":[1111],"number_text":"੧੧੧੧।","page":1010,"lines":[{"gurmukhi":"ਕਿੰਕਰਣੀ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Kinkarnee sabdaadi uchaaran keejeeai |","meaning_en":"Utter first the word 'kinkarani' (army of servants),","page":1010,"meaning_status":"draft","note":"ਕਿੰਕਰਣੀ: kinkar 'servant, attendant' + -ni."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨ ਪ੍ਰਬੀਨ ਚਿਤਿ।","roman":"Sakal tupak ke naam pachhaan prabeen chiti |","meaning_en":"O skilful one, recognise in your mind these as all the names of the gun;","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਿਹ ਚਾਹੋ ਇਹ ਨਾਮ ਦੇਹੁ ਭੀਤਰ ਕਬਿਤ। ੧੧੧੧।","roman":"Ho jih chaaho ih naam dehu bheetar kabit | 1111 |","meaning_en":"put these names into a kabitt wherever you wish.","page":1010,"meaning_status":"draft","note":"ਕਬਿਤ: a poem/verse (kabitt)."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1010,"meaning_status":"draft"},{"type":"verse","number":[1112],"number_text":"੧੧੧੨।","page":1010,"lines":[{"gurmukhi":"ਅਨੁਚਰਨੀ ਸਬਦਾਦਿ ਉਚਰੀਐ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਡਰੀਐ।","roman":"Anucharnee sabdaadi uchreeai | ari pad anti tavan ke dareeai |","meaning_en":"Utter first the word 'anucharani' (army of followers), and put the word 'ari' at its end:","page":1010,"meaning_status":"draft","note":"ਅਨੁਚਰਨੀ: anuchar 'follower' + -ni. ਡਰੀਐ read as ਡਾਰੀਐ 'put'."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਉਚਰੋ ਤਹਾ ਠਵਰ ਜਿਹ ਚਹੀਐ। ੧੧੧੨।","roman":"Sabh sree naam tupak ke laheeai | uchro tahaa thavar jih chaheeai | 1112 |","meaning_en":"take these as all the honoured names of the gun; utter them in whatever place is wanted.","page":1010,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1010,"meaning_status":"draft"},{"type":"verse","number":[1113],"number_text":"੧੧੧੩।","page":1010,"lines":[{"gurmukhi":"ਆਦਿ ਅਨੁਗਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi anugnee sabad uchaaran keejeeai |","meaning_en":"Utter first the word 'anugani' (army of followers),","page":1010,"meaning_status":"draft","note":"ਅਨੁਗਨੀ: anug 'follower' + -ni."},{"gurmukhi":"ਹਨਨੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Hannee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'hanani' (slayer) at its end.","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹ ਜਹ ਸਬਦ ਚਹੀਜੈ ਤਹ ਤਹ ਦੀਜੀਐ। ੧੧੧੩।","roman":"Ho jah jah sabad chaheejai tah tah deejeeai | 1113 |","meaning_en":"wherever the words are wanted, give them there.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1114],"number_text":"੧੧੧੪।","page":1010,"lines":[{"gurmukhi":"ਕਿੰਕਰਣੀ ਮੁਖ ਤੇ ਸਬਦਾਦਿ ਉਚਾਰੀਐ।","roman":"Kinkarnee mukh te sabdaadi uchaareeai |","meaning_en":"Utter from the mouth first the word 'kinkarani' (army of servants),","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Mathnee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'mathani' (destroyer) at its end.","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਜੀਅ ਜਾਨਿ ਲੈ।","roman":"Sakal tupak ke naam sughar jeea jaani lai |","meaning_en":"O skilful one, know in your mind these as all the names of the gun;","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੋ ਚਹੋ ਤਹੀ ਏ ਸਬਦ ਦੈ। ੧੧੧੪।","roman":"Ho javan thavar mo chaho tahee e sabad dai | 1114 |","meaning_en":"wherever you wish, give these words there.","page":1010,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1010,"meaning_status":"draft"},{"type":"verse","number":[1115],"number_text":"੧੧੧੫।","page":1010,"lines":[{"gurmukhi":"ਪ੍ਰਤਨਾ ਆਦਿ ਉਚਾਰਿ ਕੈ ਅਰਿ ਪਦ ਅੰਤਿ ਉਚਾਰ।","roman":"Pratnaa aadi uchaari kai ari pad anti uchaar |","meaning_en":"Utter 'pritna' (army) first and say the word 'ari' at the end;","page":1010,"meaning_status":"draft","note":"ਪ੍ਰਤਨਾ: read as pritna 'army'."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਫੰਗ ਕੇ ਲੀਜੈ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੧੧੧੫।","roman":"Sabh sree naam tuphang ke leejai su kabi su dhaar | 1115 |","meaning_en":"O good poet, take these and set them right as all the honoured names of the tufang (gun).","page":1010,"meaning_status":"draft","note":"ਤੁਫੰਗ: tufang, another word for gun. ਸੁ ਧਾਰ: 'correct, arrange well'; uncertain."}]},{"type":"verse","number":[1116],"number_text":"੧੧੧੬।","page":1010,"lines":[{"gurmukhi":"ਧੁਜਨੀ ਆਦਿ ਬਖਾਨਿ ਕੈ ਅਰਿ ਪਦ ਭਾਖੋ ਅੰਤਿ।","roman":"Dhujnee aadi bakhaani kai ari pad bhaakho anti |","meaning_en":"Say 'dhujni' (army with banners) first and speak the word 'ari' at the end;","page":1010,"meaning_status":"draft","note":"ਧੁਜਨੀ: dhuj 'banner' + -ni = army."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਫੰਗ ਕੇ ਨਿਕਸਤ ਚਲੈ ਅਨੰਤ। ੧੧੧੬।","roman":"Sabh sree naam tuphang ke niksat chalai anant | 1116 |","meaning_en":"countless honoured names of the tufang keep coming forth.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1117],"number_text":"੧੧੧੭।","page":1010,"lines":[{"gurmukhi":"ਆਦਿ ਬਾਹਨੀ ਸਬਦ ਕਹਿ ਅੰਤ ਸਤ੍ਰੂ ਪਦ ਦੀਨ।","roman":"Aadi baahnee sabad kahi ant satroo pad deen |","meaning_en":"Say the word 'bahani' (army) first and give the word 'satru' at the end;","page":1010,"meaning_status":"draft","note":"ਬਾਹਨੀ: vahini 'army'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜੋ ਸਮਝ ਪ੍ਰਬੀਨ। ੧੧੧੭।","roman":"Naam tupak ke hot hai leejo samajh prabeen | 1117 |","meaning_en":"these become names of the gun; O skilful one, understand and take them.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1118],"number_text":"੧੧੧੮।","page":1010,"lines":[{"gurmukhi":"ਕਾਮਿ ਆਦਿ ਸਬਦੋਚਰਿ ਕੈ ਅਰਿ ਪਦ ਅੰਤਿ ਸੁ ਦੇਹੁ।","roman":"Kaami aadi sabdochri kai ari pad anti su dehu |","meaning_en":"Uttering the word 'kami' first, give the word 'ari' at the end;","page":1010,"meaning_status":"draft","note":"ਕਾਮਿ: obscure here; perhaps a word for army (cf. ਚਮੂ 'chamu'), possibly a misprint; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੧੧੧੮।","roman":"Naam tupak ke hot hai cheen chatur chiti lehu | 1118 |","meaning_en":"these become names of the gun; O clever one, recognise them in your mind.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1119],"number_text":"੧੧੧੯।","page":1010,"lines":[{"gurmukhi":"ਕਾਮਿ ਆਦਿ ਸਬਦੋਚਰਿ ਕੈ ਅਰਿ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Kaami aadi sabdochri kai ari pad anti bakhaan |","meaning_en":"Uttering the word 'kami' first, speak the word 'ari' at the end;","page":1010,"meaning_status":"draft","note":"Same head word as 5.779.0 (ਕਾਮਿ); uncertain, perhaps a different army-word was intended."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੧੧੧੯।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 1119 |","meaning_en":"these become names of the gun; O wise one, understand and take them.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1120],"number_text":"੧੧੨੦।","page":1010,"lines":[{"gurmukhi":"ਆਦਿ ਬਿਰੂਥਨਿ ਸਬਦ ਕਹਿ ਅਤਿ ਸਤ੍ਰੂ ਪਦ ਦੀਨ।","roman":"Aadi biroothni sabad kahi ati satroo pad deen |","meaning_en":"Say the word 'baruthani' (army) first and give the word 'satru' at the end;","page":1010,"meaning_status":"draft","note":"ਬਿਰੂਥਨਿ: varuthini 'army'. ਅਤਿ: printed so; read as ਅੰਤਿ 'at the end'."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਪ੍ਰਬੀਨ। ੧੧੨੦।","roman":"Naam tupak ke hot hai leejhu samajh prabeen | 1120 |","meaning_en":"these become names of the gun; O skilful one, understand and take them.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1121],"number_text":"੧੧੨੧।","page":1010,"lines":[{"gurmukhi":"ਸੈਨਾ ਆਦਿ ਬਖਾਨਿ ਕੈ ਅਰਿ ਪਦ ਅੰਤਿ ਬਖਾਨ।","roman":"Sainaa aadi bakhaani kai ari pad anti bakhaan |","meaning_en":"Saying 'saina' (army) first, speak the word 'ari' at the end;","page":1010,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੧੧੨੧।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 1121 |","meaning_en":"these become names of the gun; O wise one, understand and take them.","page":1010,"meaning_status":"draft"}]},{"type":"verse","number":[1122],"number_text":"੧੧੨੨।","page":1010,"lines":[{"gurmukhi":"ਧਨੁਨੀ ਆਦਿ ਬਖਾਨਿ ਕੈ ਅਰਿਣੀ ਅੰਤਿ ਬਖਾਨ।","roman":"Dhanunee aadi bakhaani kai arinee anti bakhaan |","meaning_en":"Saying 'dhanuni' (army of bows) first, speak 'arini' at the end;","page":1010,"meaning_status":"draft","note":"ਧਨੁਨੀ: dhanu 'bow' + -ni; read as 'army with bows' or 'bow-bearing'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹੁ ਸਮਝ ਸੁਜਾਨ। ੧੧੨੨।","roman":"Naam tupak ke hot hai leejhu samajh sujaan | 1122 |","meaning_en":"these become names of the gun; O wise one, understand and take them.","page":1010,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1011,"meaning_status":"draft"},{"type":"verse","number":[1123],"number_text":"੧੧੨੩।","page":1011,"lines":[{"gurmukhi":"ਆਦਿ ਧਨੁਖਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi dhanukhnee sabad uchaaran keejeeai |","meaning_en":"Utter the word 'dhanukhani' (army of bows) first,","page":1011,"meaning_status":"draft","note":"ਧਨੁਖਨੀ: dhanukh 'bow' + -ni."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Satroo sabad ko anti tavan ke deejeeai |","meaning_en":"and give the word 'satru' at its end.","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨ ਨੈਕੁ ਪ੍ਰਮਾਨੀਐ। ੧੧੨੩।","roman":"Ho yaa ke bheetar bhed na naiku pramaaneeai | 1123 |","meaning_en":"accept not the slightest distinction in this.","page":1011,"meaning_status":"draft"}]},{"type":"verse","number":[1124],"number_text":"੧੧੨੪।","page":1011,"lines":[{"gurmukhi":"ਕੋਵੰਡਨੀ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Kovandnee sabad ko aadi uchaareeai |","meaning_en":"Utter the word 'kovandani' (army of bows) first,","page":1011,"meaning_status":"draft","note":"ਕੋਵੰਡਨੀ: kodand 'bow' + -ni."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Arinee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੋ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ko naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1011,"meaning_status":"draft","note":"ਤੁਪਕ ਕੋ: printed so (ਕੋ for ਕੇ)."},{"gurmukhi":"ਹੋ ਜਹਾ ਸਬਦ ਏ ਚਹੋ ਤਹੀ ਤੇ ਦੀਜੀਐ। ੧੧੨੪।","roman":"Ho jahaa sabad e chaho tahee te deejeeai | 1124 |","meaning_en":"wherever you want these words, give them from there.","page":1011,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1011,"meaning_status":"draft"},{"type":"verse","number":[1125],"number_text":"੧੧੨੫।","page":1011,"lines":[{"gurmukhi":"ਇਖੁਆਸਨੀ ਪਦਾਦਿ ਭਨੀਜੈ। ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਤਿਹ ਦੀਜੈ।","roman":"Ikhuaasnee padaadi bhaneejai | arinee anti sabad tih deejai |","meaning_en":"Say first the word 'ikhuasani' (army of bows), and give the word 'arini' at its end:","page":1011,"meaning_status":"draft","note":"ਇਖੁਆਸਨੀ: ikhuas (ishvas) 'bow' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹਿਜਹਿ। ਜਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਭਣਿਜਹਿ। ੧੧੨੫।","roman":"Sakal tupak ke naam lahijhi | jah chaaho tih thavar bhanijhi | 1125 |","meaning_en":"take these as all the names of the gun; speak them in whatever place you wish.","page":1011,"meaning_status":"draft"}]},{"type":"verse","number":[1126],"number_text":"੧੧੨੬।","page":1011,"lines":[{"gurmukhi":"ਕਾਰਮੁਕਨੀ ਸਬਦਾਦਿ ਉਚਰੀਐ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਧਰੀਐ।","roman":"Kaarmuknee sabdaadi uchreeai | arinee sabad anti tih dhareeai |","meaning_en":"Utter first the word 'karmukani' (army of bows), and set the word 'arini' at its end:","page":1011,"meaning_status":"draft","note":"ਕਾਰਮੁਕਨੀ: karmuk 'bow' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਜਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਬਖਾਨੋ। ੧੧੨੬।","roman":"Sakal tupak ke naam pachhaano | jah chaaho tih thavar bakhaano | 1126 |","meaning_en":"recognise these as all the names of the gun; speak them in whatever place you wish.","page":1011,"meaning_status":"draft"}]},{"type":"verse","number":[1127],"number_text":"੧੧੨੭।","page":1011,"lines":[{"gurmukhi":"ਰਿਪੁ ਸੰਤਾਪਨਿ ਆਦਿ ਬਖਾਨੋ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Ripu santaapni aadi bakhaano | arinee sabad anti tih thaano |","meaning_en":"Say first 'ripu-santapani' (that which torments the enemy, i.e. bow), and place the word 'arini' at its end:","page":1011,"meaning_status":"draft","note":"ਰਿਪੁ ਸੰਤਾਪਨਿ: 'tormentor of enemies' = bow (with -ni); uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੈ। ੧੧੨੭।","roman":"Sakal tupak ke naam laheejai | yaa mai bhed naiku nahee keejai | 1127 |","meaning_en":"take these as all the names of the gun; make not the slightest distinction in this.","page":1011,"meaning_status":"draft"}]},{"type":"verse","number":[1128],"number_text":"੧੧੨੮।","page":1011,"lines":[{"gurmukhi":"ਰਿਪੁ ਖੰਡਣਨੀ ਆਦਿ ਭਣਿਜੈ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦਿਜੈ।","roman":"Ripu khandannee aadi bhanijai | arinee sabad anti tih dijai |","meaning_en":"Say first 'ripu-khandanani' (that which cuts down enemies), and give the word 'arini' at its end:","page":1011,"meaning_status":"draft","note":"ਰਿਪੁ ਖੰਡਣਨੀ: 'breaker of enemies' = bow (with -ni); uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਜਹ ਤਹ ਮਿਲਿ ਸੁਘਰੂਚ ਬਖਾਨੋ। ੧੧੨੮।","roman":"Sakal tupak ke naam pachhaano | jah tah mili sughrooch bakhaano | 1128 |","meaning_en":"recognise these as all the names of the gun; O skilful ones, gather and speak them everywhere.","page":1011,"meaning_status":"draft","note":"ਸੁਘਰੂਚ: printed so; read as ਸੁਘਰ (skilful) + ਰੁਚ (as you like)?; uncertain."}]},{"type":"verse","number":[1129],"number_text":"੧੧੨੯।","page":1011,"lines":[{"gurmukhi":"ਦੁਸਟ ਦਾਹਨੀ ਆਦਿ ਭਨੀਜੈ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦੀਜੈ।","roman":"Dusat daahnee aadi bhaneejai | arinee sabad anti tih deejai |","meaning_en":"Say first 'dusht-dahani' (that which burns the wicked), and give the word 'arini' at its end:","page":1011,"meaning_status":"draft","note":"ਦੁਸਟ ਦਾਹਨੀ: 'burner of the wicked' = bow (with -ni); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਤੁਮ ਲਖਿ ਪਾਵਹੁ। ਜਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਬਤਾਵਹੁ। ੧੧੨੯।","roman":"Naam tupak ke tum lakhi paavhu | jah chaaho tih thavar bataavhu | 1129 |","meaning_en":"you will come to know these as names of the gun; tell them in whatever place you wish.","page":1011,"meaning_status":"draft"}]},{"type":"verse","number":[1130],"number_text":"੧੧੩੦।","page":1011,"lines":[{"gurmukhi":"ਰਿਪੁ ਘਾਇਨੀ ਪਦਾਦਿ ਬਖਾਨੋ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Ripu ghaainee padaadi bakhaano | arinee sabad anti tih thaano |","meaning_en":"Say first 'ripu-ghaini' (that which wounds enemies), and place the word 'arini' at its end:","page":1011,"meaning_status":"draft","note":"ਰਿਪੁ ਘਾਇਨੀ: 'striker of enemies' = bow (with -ni); uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹੀਜੈ। ਜਉਨ ਠਵਰ ਚਹੀਐ ਤਹ ਦੀਜੈ। ੧੧੩੦।","roman":"Naam tupak ke sakal laheejai | jaun thavar chaheeai tah deejai | 1130 |","meaning_en":"take these as all the names of the gun; give them in whatever place is wanted.","page":1011,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1011,"meaning_status":"draft"},{"type":"verse","number":[1131],"number_text":"੧੧੩੧।","page":1011,"lines":[{"gurmukhi":"ਆਦਿ ਚਾਪਣੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi chaapnee sabad uchaaran keejeeai |","meaning_en":"Utter the word 'chapani' (army of bows) first,","page":1011,"meaning_status":"draft","note":"ਚਾਪਣੀ: chap 'bow' + -ni."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹਾ ਚਾਹੀਐ ਸਬਦ ਸੁ ਤਹ ਤਹ ਦੀਜੀਐ। ੧੧੩੧।","roman":"Ho jahaa chaaheeai sabad su tah tah deejeeai | 1131 |","meaning_en":"wherever the words are wanted, give them there.","page":1011,"meaning_status":"draft"}]},{"type":"verse","number":[1132],"number_text":"੧੧੩੨।","page":1011,"lines":[{"gurmukhi":"ਪ੍ਰਤੰਚਨੀ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Pratanchnee sabad ko aadi bakhaaneeai |","meaning_en":"Say first the word 'pratanchani' (army of bowstrings),","page":1011,"meaning_status":"draft","note":"ਪ੍ਰਤੰਚਨੀ: pratyancha 'bowstring' + -ni; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Arinee taa ke anti sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1011,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹੋ ਨਿਸੰਕ ਸਭ ਠਉਰ ਨ ਗਨਤੀ ਕੀਜੀਐ। ੧੧੩੨।","roman":"Ho kaho nisank sabh thaur na gantee keejeeai | 1132 |","meaning_en":"say them without hesitation anywhere, and do not count.","page":1011,"meaning_status":"draft","note":"ਨ ਗਨਤੀ ਕੀਜੀਐ: 'do not reckon/hesitate'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਮਲ ਛੰਦ","gurmukhi":"ਰੂਆਮਲ ਛੰਦ","roman":"Rooaamal chhand","meaning_en":"Ruamal metre.","page":1012,"meaning_status":"draft"},{"type":"verse","number":[1133],"number_text":"੧੧੩੩।","page":1012,"lines":[{"gurmukhi":"ਸਤ੍ਰੂ ਭੰਜਣਿ ਆਦਿ ਬਖਾਨ। ਰਿਪੁ ਸਬਦੁ ਬਹੁਰਿ ਪ੍ਰਮਾਨ।","roman":"Satroo bhanjni aadi bakhaan | ripu sabdu bahuri pramaan |","meaning_en":"Say 'satru-bhanjani' (that which breaks enemies) first, then set down the word 'ripu';","page":1012,"meaning_status":"draft","note":"ਸਤ੍ਰੂ ਭੰਜਣਿ: 'breaker of enemies' = bow (with -ni); uncertain."},{"gurmukhi":"ਸਭ ਨਾਮ ਤੁਪਕ ਪਛਾਨ। ਨਹਿ ਭੇਦ ਯਾ ਮਹਿ ਜਾਨ। ੧੧੩੩।","roman":"Sabh naam tupak pachhaan | nahi bhed yaa mahi jaan | 1133 |","meaning_en":"recognise all these as names of the gun; know no difference in this.","page":1012,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1012,"meaning_status":"draft"},{"type":"verse","number":[1134],"number_text":"੧੧੩੪।","page":1012,"lines":[{"gurmukhi":"ਹਰਿ ਸਕਤਣਿ ਪਦ ਆਣਿ ਭਣਿਜੈ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦਿਜੈ।","roman":"Hari sakatni pad aani bhanijai | arinee sabad anti tih dijai |","meaning_en":"Bring in and say the word 'hari-saktani', and give the word 'arini' at its end:","page":1012,"meaning_status":"draft","note":"ਹਰਿ ਸਕਤਣਿ: obscure; perhaps 'Indra's power' = bow (rainbow?); ਆਣਿ 'bringing'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹੀਜੈ। ਜਹੀ ਠਵਰ ਚਹੀਐ ਤਹ ਦੀਜੈ। ੧੧੩੪।","roman":"Naam tupak ke sakal laheejai | jahee thavar chaheeai tah deejai | 1134 |","meaning_en":"take these as all the names of the gun; give them in whatever place is wanted.","page":1012,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1012,"meaning_status":"draft"},{"type":"verse","number":[1135],"number_text":"੧੧੩੫।","page":1012,"lines":[{"gurmukhi":"ਬਿਸਿਖ ਬਰਸਣੀ ਆਦਿ ਉਚਾਰਣ ਕੀਜੀਐ।","roman":"Bisikh barasnee aadi uchaaran keejeeai |","meaning_en":"Utter first 'bisikh-barsani' (that which rains arrows, i.e. bow),","page":1012,"meaning_status":"draft","note":"ਬਿਸਿਖ ਬਰਸਣੀ: 'raining arrows' = bow (with -ni)."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1012,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1012,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਾਬਿ ਕਬਿ ਕੇ ਭੀਤਰ ਸਦਾ ਪ੍ਰਮਾਨੀਐ। ੧੧੩੫।","roman":"Ho kaabi kabi ke bheetar sadaa pramaaneeai | 1135 |","meaning_en":"O poet, always accept them within poetry.","page":1012,"meaning_status":"draft","note":"ਕਾਬਿ ਕਬਿ: read as 'poetry ... O poet'; could also be 'within kabitt and poetry' as in parallel lines; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1012,"meaning_status":"draft"},{"type":"verse","number":[1136],"number_text":"੧੧੩੬।","page":1012,"lines":[{"gurmukhi":"ਬਾਨ ਬਰਖਣੀ ਆਦਿ ਉਚਰੀਐ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਧਰੀਐ।","roman":"Baan barakhnee aadi uchreeai | arinee sabad anti tih dhareeai |","meaning_en":"Utter first 'ban-barkhani' (that which rains arrows), and set the word 'arini' at its end:","page":1012,"meaning_status":"draft","note":"ਬਾਨ ਬਰਖਣੀ: 'raining arrows' = bow (with -ni)."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਭਣੀਜੈ। ੧੧੩੬।","roman":"Sakal tupak ke naam laheejai | jih chaaho tih thavar bhaneejai | 1136 |","meaning_en":"take these as all the names of the gun; speak them in whatever place you wish.","page":1012,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1012,"meaning_status":"draft"},{"type":"verse","number":[1137],"number_text":"੧੧੩੭।","page":1012,"lines":[{"gurmukhi":"ਆਦਿ ਬਾਨਨੀ ਸਬਦਹਿ ਅਭੂਲਿ ਬਖਾਨੀਐ।","roman":"Aadi baannee sabadhi abhooli bakhaaneeai |","meaning_en":"Say first, without forgetting, the word 'banani' (army of arrows),","page":1012,"meaning_status":"draft","note":"ਬਾਨਨੀ: ban 'arrow' + -ni; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Arinee taa ke anti sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1012,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Naam tupak ke sakal jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1012,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹ ਚਾਹੋ ਤਹ ਸਬਦ ਤਹੀ ਤੇ ਦੀਜੀਐ। ੧੧੩੭।","roman":"Ho jah chaaho tah sabad tahee te deejeeai | 1137 |","meaning_en":"wherever you wish the words, give them from there.","page":1012,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1012,"meaning_status":"draft"},{"type":"verse","number":[1138],"number_text":"੧੧੩੮।","page":1012,"lines":[{"gurmukhi":"ਆਦਿ ਪਨਚਨੀ ਸਬਦ ਬਖਾਨੋ। ਮਥਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Aadi panachnee sabad bakhaano | mathnee sabad anti tih thaano |","meaning_en":"Say the word 'panachani' (army of bowstrings) first, and place the word 'mathani' at its end:","page":1012,"meaning_status":"draft","note":"ਪਨਚਨੀ: panach 'bowstring' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਰੁਚਿ ਜੈ ਜਹੀ ਤਹੀ ਤੇ ਕਹੀਐ। ੧੧੩੮।","roman":"Sabh sree naam tupak ke laheeai | ruchi jai jahee tahee te kaheeai | 1138 |","meaning_en":"take these as all the honoured names of the gun; say them wherever you like.","page":1012,"meaning_status":"draft","note":"ਰੁਚਿ ਜੈ: printed so; read as 'as you like'."}]},{"type":"verse","number":[1139],"number_text":"੧੧੩੯।","page":1012,"lines":[{"gurmukhi":"ਕੋਵੰਡਜਨੀ ਆਦਿ ਉਚਰੀਐ। ਮਥਨੀ ਅੰਤਿ ਸਬਦ ਤਿਹ ਧਰੀਐ।","roman":"Kovandajnee aadi uchreeai | mathnee anti sabad tih dhareeai |","meaning_en":"Utter first 'kovandajani' (army of those born of the bow, i.e. arrows), and set 'mathani' at its end:","page":1012,"meaning_status":"draft","note":"ਕੋਵੰਡਜਨੀ: kodand 'bow' + ja 'born' = arrow, + -ni; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਜਹਾ ਰੁਚੈ ਤੇ ਤਹੀ ਬਖਾਨਹੁ। ੧੧੩੯।","roman":"Sabh sree naam tupak ke jaanhu | jahaa ruchai te tahee bakhaanhu | 1139 |","meaning_en":"know these as all the honoured names of the gun; speak them wherever you like.","page":1012,"meaning_status":"draft"}]},{"type":"verse","number":[1140],"number_text":"੧੧੪੦।","page":1012,"lines":[{"gurmukhi":"ਇਖੁਆਸਜਨੀ ਆਦਿ ਭਣੀਜੈ। ਮਥਣੀ ਅੰਤਿ ਸਬਦ ਤਿਹ ਦੀਜੈ।","roman":"Ikhuaasajnee aadi bhaneejai | mathnee anti sabad tih deejai |","meaning_en":"Say first 'ikhuasajani' (army of those born of the bow), and give 'mathani' at its end:","page":1012,"meaning_status":"draft","note":"ਇਖੁਆਸਜਨੀ: ishvas 'bow' + ja 'born' = arrow, + -ni; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹਿਜੈ। ਜਵਨ ਠਵਰ ਚਹੀਐ ਤਹ ਦਿਜੈ। ੧੧੪੦।","roman":"Sakal tupak ke naam lahijai | javan thavar chaheeai tah dijai | 1140 |","meaning_en":"take these as all the names of the gun; give them in whatever place is wanted.","page":1012,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1013,"meaning_status":"draft"},{"type":"verse","number":[1141],"number_text":"੧੧੪੧।","page":1013,"lines":[{"gurmukhi":"ਕਾਰਮੁਕਜਨੀ ਪਦ ਕੋ ਪ੍ਰਿਥਮ ਉਚਾਰੀਐ।","roman":"Kaarmukajnee pad ko pritham uchaareeai |","meaning_en":"Utter first the word 'karmukajani' (army of those born of the bow),","page":1013,"meaning_status":"draft","note":"ਕਾਰਮੁਕਜਨੀ: karmuk 'bow' + ja 'born' = arrow, + -ni; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Arinee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam sughar lahi leejeeai |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਮੈ ਚਹੋ ਤਹਾ ਤੇ ਦੀਜੀਐ। ੧੧੪੧।","roman":"Ho kabit kaabi mai chaho tahaa te deejeeai | 1141 |","meaning_en":"give them wherever you wish in kabitt and poetry.","page":1013,"meaning_status":"draft"}]},{"type":"verse","number":[1142],"number_text":"੧੧੪੨।","page":1013,"lines":[{"gurmukhi":"ਰਿਪੁ ਤਾਪਣੀ ਸਬਦਹਿ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Ripu taapnee sabadhi aadi uchaareeai |","meaning_en":"Utter first the word 'ripu-tapani' (that which torments enemies),","page":1013,"meaning_status":"draft","note":"ਰਿਪੁ ਤਾਪਣੀ: 'tormentor of enemies' (with -ni); uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸੁ ਪਦ ਕੋ ਡਾਰੀਐ।","roman":"Arinee taa ke anti su pad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਛਾਨੀਐ।","roman":"Sakal tupak ke naam subudhi pachhaaneeai |","meaning_en":"O wise one, recognise these as all the names of the gun;","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹਾ ਚਹੋ ਤਹ ਦੇਹੁ ਨ ਸੰਕਾ ਮਾਨੀਐ। ੧੧੪੨।","roman":"Ho jahaa chaho tah dehu na sankaa maaneeai | 1142 |","meaning_en":"give them wherever you wish, and have no doubt.","page":1013,"meaning_status":"draft"}]},{"type":"verse","number":[1143],"number_text":"੧੧੪੩।","page":1013,"lines":[{"gurmukhi":"ਆਦਿ ਚਾਪਣੀ ਮੁਖ ਤੇ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Aadi chaapnee mukh te sabad bakhaaneeai |","meaning_en":"Say from the mouth first the word 'chapani' (army of bows),","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Mathnee taa ke anti sabad ko thaaneeai |","meaning_en":"and place the word 'mathani' at its end.","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam subudhi lahi leejeeai |","meaning_en":"O wise one, take these as all the names of the gun;","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੧੪੩।","roman":"Ho jah chaaho tih thavar uchaaran keejeeai | 1143 |","meaning_en":"utter them in whatever place you wish.","page":1013,"meaning_status":"draft"}]},{"type":"verse","number":[1144],"number_text":"੧੧੪੪।","page":1013,"lines":[{"gurmukhi":"ਪਨਚ ਧਰਨਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Panach dharannee aadi uchaaran keejeeai |","meaning_en":"Utter first 'panach-dharanani' (army of bowstring-bearers),","page":1013,"meaning_status":"draft","note":"ਪਨਚ ਧਰਨਨੀ: 'bearers of the bowstring' = bows/archers, + -ni; uncertain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Mathnee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'mathani' at its end.","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਪਛਾਨੀਐ।","roman":"Sakal tupak ke naam subudhi pachhaaneeai |","meaning_en":"O wise one, recognise these as all the names of the gun;","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਮਾਨੀਐ। ੧੧੪੪।","roman":"Ho yaa ke bheetar bhed naiku nahee maaneeai | 1144 |","meaning_en":"accept not the slightest distinction in this.","page":1013,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1013,"meaning_status":"draft"},{"type":"verse","number":[1145],"number_text":"੧੧੪੫।","page":1013,"lines":[{"gurmukhi":"ਆਦਿ ਸੁਹ੍ਰਿਦਣੀ ਸਬਦ ਬਖਾਨੋ। ਮਥਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Aadi suhridnee sabad bakhaano | mathnee sabad anti tih thaano |","meaning_en":"Say the word 'suhridani' (army of friends) first, and place the word 'mathani' at its end:","page":1013,"flags":[{"code":"0x66","reason":"sihari typed before the previous letter's ਾ; attached to the next consonant - CHECK: the printed sihari stands before a spacing vowel sign, the print is ambiguous"}],"meaning_status":"draft","note":"ਸੁਹ੍ਰਿਦਣੀ: suhrid 'friend' + -ni; uncertain how 'friend' leads to the gun."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਜਿਹ ਠਾ ਰੁਚੈ ਤਹੀ ਤੇ ਕਹੀਐ। ੧੧੪੫।","roman":"Sabh sree naam tupak ke laheeai | jih thaa ruchai tahee te kaheeai | 1145 |","meaning_en":"take these as all the honoured names of the gun; say them in whatever place you like.","page":1013,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1013,"meaning_status":"draft"},{"type":"verse","number":[1146],"number_text":"੧੧੪੬।","page":1013,"lines":[{"gurmukhi":"ਬਲਭਣੀ ਸਬਦਾਦਿ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Balabhnee sabdaadi bakhaanan keejeeai |","meaning_en":"Say first the word 'balabhani' (army of beloved ones),","page":1013,"meaning_status":"draft","note":"ਬਲਭਣੀ: vallabh 'beloved/friend' + -ni; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur chiti jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1013,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨ ਨੈਕੁ ਪ੍ਰਮਾਨੀਐ। ੧੧੪੬।","roman":"Ho yaa ke bheetar bhed na naiku pramaaneeai | 1146 |","meaning_en":"accept not the slightest distinction in this.","page":1013,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1013,"meaning_status":"draft"},{"type":"verse","number":[1147],"number_text":"੧੧੪੭।","page":1013,"lines":[{"gurmukhi":"ਸਾਖਾਇਨਣੀ ਆਦਿ ਉਚਰੀਐ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਧਰੀਐ।","roman":"Saakhaainnee aadi uchreeai | arinee sabad anti tih dhareeai |","meaning_en":"Utter first 'sakhainani', and set the word 'arini' at its end:","page":1013,"meaning_status":"draft","note":"ਸਾਖਾਇਨਣੀ: obscure; perhaps sakha 'friend' + -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ਜਿਹ ਚਹੀਐ ਤਿਹ ਠਵਰ ਭਣਿਜੈ। ੧੧੪੭।","roman":"Naam tupak ke sakal lahijai | jih chaheeai tih thavar bhanijai | 1147 |","meaning_en":"take these as all the names of the gun; speak them in whatever place is wanted.","page":1013,"meaning_status":"draft"}]},{"type":"verse","number":[1148],"number_text":"੧੧੪੮।","page":1013,"lines":[{"gurmukhi":"ਪ੍ਰੀਤਮਣੀ ਪਦ ਆਦਿ ਬਖਾਨੀਐ। ਮਥਣੀ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Preetamnee pad aadi bakhaaneeai | mathnee anti tavan ke thaaneeai |","meaning_en":"Say first the word 'pritamani' (army of dear ones), and place 'mathani' at its end:","page":1013,"meaning_status":"draft","note":"ਪ੍ਰੀਤਮਣੀ: pritam 'beloved' + -ni; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਨੈਕੁ ਨ ਮਿਥਿਆ ਜਾਨੋ। ੧੧੪੮।","roman":"Sakal tupak ke naam pachhaano | yaa mai naiku na mithiaa jaano | 1148 |","meaning_en":"recognise these as all the names of the gun; know not the least falsehood in this.","page":1013,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1014,"meaning_status":"draft"},{"type":"verse","number":[1149],"number_text":"੧੧੪੯।","page":1014,"lines":[{"gurmukhi":"ਆਦਿ ਸੁਜਨਨੀ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi sujannee sabad uchaaran keejeeai |","meaning_en":"Utter first the word 'sujanani' (army of good people),","page":1014,"meaning_status":"draft","note":"ਸੁਜਨਨੀ: sujan 'good person, friend' + -ni; uncertain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Mathnee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'mathani' at its end.","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam subudhi jeea jaaneeai |","meaning_en":"O wise one, know in your mind these as all the names of the gun;","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਤਨਕ ਨਹੀ ਮਾਨੀਐ। ੧੧੪੯।","roman":"Ho yaa ke bheetar bhed tanak nahee maaneeai | 1149 |","meaning_en":"accept not the least distinction in this.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1150],"number_text":"੧੧੫੦।","page":1014,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸੁਹਿਰਦਿਨੀ ਮੁਖ ਤੇ ਸਬਦ ਉਚਾਰੀਐ।","roman":"Pritham suhirdinee mukh te sabad uchaareeai |","meaning_en":"First utter from the mouth the word 'suhirdini' (army of friends),","page":1014,"meaning_status":"draft","note":"ਸੁਹਿਰਦਿਨੀ: suhrid 'friend' + -ni."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਬਹੁਰਿ ਪਦ ਡਾਰੀਐ।","roman":"Arinee taa ke anti bahuri pad daareeai |","meaning_en":"then put the word 'arini' at its end.","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤ ਮਾਝ ਲਹੁ।","roman":"Sakal tupak ke naam chatur chit maajh lahu |","meaning_en":"O clever one, take into your mind these as all the names of the gun;","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਮੈ ਰੁਚੈ ਤਹੀ ਤੇ ਨਾਮ ਕਹੁ। ੧੧੫੦।","roman":"Ho kabit kaabi mai ruchai tahee te naam kahu | 1150 |","meaning_en":"say the names in kabitt and poetry wherever you like.","page":1014,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1014,"meaning_status":"draft"},{"type":"verse","number":[1151],"number_text":"੧੧੫੧।","page":1014,"lines":[{"gurmukhi":"ਮਾਨੁਖਨੀ ਸਬਦਾਦਿ ਭਣੀਜੈ। ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਤਿਹ ਦੀਜੈ।","roman":"Maanukhnee sabdaadi bhaneejai | arinee anti sabad tih deejai |","meaning_en":"Say first the word 'manukhani' (army of men), and give the word 'arini' at its end:","page":1014,"meaning_status":"draft","note":"ਮਾਨੁਖਨੀ: manukh 'man' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਚਹੋ ਜਹਾ ਸਭ ਠਵਰ ਬਖਾਨਹੁ। ੧੧੫੧।","roman":"Sakal tupak ke naam pachhaanhu | chaho jahaa sabh thavar bakhaanhu | 1151 |","meaning_en":"recognise these as all the names of the gun; speak them in every place you wish.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1152],"number_text":"੧੧੫੨।","page":1014,"lines":[{"gurmukhi":"ਆਦਿ ਮਰਤਣੀ ਸਬਦ ਬਖਾਨੋ। ਅੰਤਕ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Aadi maratnee sabad bakhaano | antak sabad anti tih thaano |","meaning_en":"Say the word 'martani' (army of mortals) first, and place the word 'antak' (ender) at its end:","page":1014,"meaning_status":"draft","note":"ਮਰਤਣੀ: martya 'mortal' + -ni."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਭਣੀਜੈ। ੧੧੫੨।","roman":"Naam tupak ke sabh lahi leejai | jih chaaho tih thavar bhaneejai | 1152 |","meaning_en":"take all these as names of the gun; speak them in whatever place you wish.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1153],"number_text":"੧੧੫੩।","page":1014,"lines":[{"gurmukhi":"ਆਦਿ ਮਾਨੁਖਨੀ ਸਬਦ ਬਖਾਨੋ। ਤਾ ਕੇ ਮਥਣੀ ਅੰਤਿ ਸੁ ਠਾਨੋ।","roman":"Aadi maanukhnee sabad bakhaano | taa ke mathnee anti su thaano |","meaning_en":"Say the word 'manukhani' (army of men) first, and place 'mathani' at its end:","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ਜਿਹ ਚਾਹੋ ਤਿਹ ਠਵਰ ਭਣਿਜੈ। ੧੧੫੩।","roman":"Naam tupak ke sabh lahi lijai | jih chaaho tih thavar bhanijai | 1153 |","meaning_en":"take all these as names of the gun; speak them in whatever place you wish.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1154],"number_text":"੧੧੫੪।","page":1014,"lines":[{"gurmukhi":"ਮਾਨਿਖਯਨੀ ਪਦਾਦਿ ਭਣੀਜੈ। ਅੰਤਿ ਸਬਦ ਮਥਣੀ ਤਿਹ ਦੀਜੈ।","roman":"Maanikhaynee padaadi bhaneejai | anti sabad mathnee tih deejai |","meaning_en":"Say first the word 'manikhyani' (army of men), and give the word 'mathani' at its end:","page":1014,"meaning_status":"draft","note":"ਮਾਨਿਖਯਨੀ: variant of manukh 'man' + -ni."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ਰੁਚੈ ਜਹਾ ਤਿਹ ਠਵਰ ਭਣਿਜੈ। ੧੧੫੪।","roman":"Naam tupak ke sakal lahijai | ruchai jahaa tih thavar bhanijai | 1154 |","meaning_en":"take these as all the names of the gun; speak them in whatever place you like.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1155],"number_text":"੧੧੫੫।","page":1014,"lines":[{"gurmukhi":"ਨਰਣੀ ਆਦਿ ਉਚਾਰਣ ਕੀਜੈ। ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਤਿਹ ਦੀਜੈ।","roman":"Narnee aadi uchaaran keejai | arinee anti sabad tih deejai |","meaning_en":"Utter 'narani' (army of men) first, and give the word 'arini' at its end:","page":1014,"meaning_status":"draft","note":"ਨਰਣੀ: nar 'man' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਨ ਨੈਕੁ ਪ੍ਰਮਾਨਹੁ। ੧੧੫੫।","roman":"Sabh sree naam tupak ke jaanhu | yaa mai bhed na naiku pramaanhu | 1155 |","meaning_en":"know these as all the honoured names of the gun; accept not the slightest difference in this.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1156],"number_text":"੧੧੫੬।","page":1014,"lines":[{"gurmukhi":"ਮਾਨਵਨੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਤਾ ਕੇ ਅੰਤਿ ਸਤ੍ਰੂ ਪਦ ਦਿਜੈ।","roman":"Maanavnee sabdaadi bhanijai | taa ke anti satroo pad dijai |","meaning_en":"Say first the word 'manavani' (army of men), and give the word 'satru' at its end:","page":1014,"meaning_status":"draft","note":"ਮਾਨਵਨੀ: manav 'man' + -ni."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹੀਜੈ। ਸਭਾ ਮਧਿ ਬਿਨੁ ਸੰਕ ਕਹੀਜੈ। ੧੧੫੬।","roman":"Naam tupak ke sakal laheejai | sabhaa madhi binu sank kaheejai | 1156 |","meaning_en":"take these as all the names of the gun; say them in an assembly without hesitation.","page":1014,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1014,"meaning_status":"draft"},{"type":"verse","number":[1157],"number_text":"੧੧੫੭।","page":1014,"lines":[{"gurmukhi":"ਪ੍ਰਿਥੀਰਾਟਨੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Pritheeraatnee aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'prithiratani' (army of kings of the earth),","page":1014,"meaning_status":"draft","note":"ਪ੍ਰਿਥੀਰਾਟਨੀ: prithi 'earth' + rat 'king' + -ni."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke ant sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1014,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਇਨ ਕੇ ਕਹਤ ਨ ਸੰਕਾ ਮਨ ਮੈ ਕੀਜੀਐ। ੧੧੫੭।","roman":"Ho in ke kahat na sankaa man mai keejeeai | 1157 |","meaning_en":"in saying them, keep no doubt in the mind.","page":1014,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1014,"meaning_status":"draft"},{"type":"verse","number":[1158],"number_text":"੧੧੫੮।","page":1014,"lines":[{"gurmukhi":"ਛਿਤਣੀਸਣੀ ਪਦਾਦਿ ਭਣਿਜੈ। ਅਰਿਣੀ ਪਦ ਕੋ ਬਹੁਰਿ ਕਹਿਜੈ।","roman":"Chhitneesnee padaadi bhanijai | arinee pad ko bahuri kahijai |","meaning_en":"Say first the word 'chhitanisani' (army of lords of the earth), then say the word 'arini':","page":1014,"meaning_status":"draft","note":"ਛਿਤਣੀਸਣੀ: chhiti 'earth' + is 'lord' + -ni; read as 'lord of the earth' = king, + -ni = army of kings; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਬਖਾਨਹੁ। ਸਕਲ ਸਭਾ ਮੈ ਪ੍ਰਗਟ ਪ੍ਰਮਾਨਹੁ। ੧੧੫੮।","roman":"Naam tupak ke sakal bakhaanhu | sakal sabhaa mai pragat pramaanhu | 1158 |","meaning_en":"speak these as all the names of the gun, and set them forth openly in every assembly.","page":1014,"meaning_status":"draft"}]},{"type":"verse","number":[1159],"number_text":"੧੧੫੯।","page":1015,"lines":[{"gurmukhi":"ਛਤ੍ਰਿਸਣੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਅੰਤਿ ਸਬਦ ਮਥਣੀ ਤਿਹ ਦਿਜੈ।","roman":"Chhatrisnee sabdaadi bhanijai | anti sabad mathnee tih dijai |","meaning_en":"Say first the word 'chhatrisani' (army of lords of the earth), and give the word 'mathani' at its end:","page":1015,"meaning_status":"draft","note":"ਛਤ੍ਰਿਸਣੀ: perhaps chhiti 'earth' + is 'lord' + -ni (or chhatri 'warrior'); uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਨੈਕੁ ਨਹੀ ਜਾਨਹੁ। ੧੧੫੯।","roman":"Sakal tupak ke naam pachhaanhu | yaa mai bhed naiku nahee jaanhu | 1159 |","meaning_en":"recognise these as all the names of the gun; know not the slightest difference in this.","page":1015,"meaning_status":"draft"}]},{"type":"verse","number":[1160],"number_text":"੧੧੬੦।","page":1015,"lines":[{"gurmukhi":"ਛਮਿ ਇਸਣੀ ਸਬਦਾਦਿ ਉਚਾਰੋ। ਮਥਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਡਾਰੋ।","roman":"Chhami isnee sabdaadi uchaaro | mathnee sabad anti tih daaro |","meaning_en":"Utter first the word 'chhami-isani' (army of lords of the earth), and put the word 'mathani' at its end:","page":1015,"meaning_status":"draft","note":"ਛਮਿ ਇਸਣੀ: chhama/kshama 'earth' + is 'lord' + -ni; read as 'lord of the earth' = king, + -ni = army of kings; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੈ। ਸਦਾ ਸੁਨਤ ਬੁਧਿਜਨਨ ਭਣੀਜੈ। ੧੧੬੦।","roman":"Naam tupak ke sabh lahi leejai | sadaa sunat budhijnan bhaneejai | 1160 |","meaning_en":"take all these as names of the gun; always say them in the hearing of the wise.","page":1015,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਮਲ ਛੰਦ","gurmukhi":"ਰੂਆਮਲ ਛੰਦ","roman":"Rooaamal chhand","meaning_en":"Ruamal metre.","page":1015,"meaning_status":"draft"},{"type":"verse","number":[1161],"number_text":"੧੧੬੧।","page":1015,"lines":[{"gurmukhi":"ਧਰਤੀਸਣਿ ਆਦਿ ਬਖਾਨ। ਅਰਿ ਸਬਦ ਅੰਤਿ ਪ੍ਰਮਾਨ।","roman":"Dharteesni aadi bakhaan | ari sabad anti pramaan |","meaning_en":"Say 'dhartisani' (army of lords of the earth) first, and set the word 'ari' at the end;","page":1015,"meaning_status":"draft","note":"ਧਰਤੀਸਣਿ: dharti 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਸਭ ਚੀਨ ਨਾਮ ਤੁਫੰਗ। ਸਭ ਠਵਰ ਭਨਹੁ ਨਿਸੰਗ। ੧੧੬੧।","roman":"Sabh cheen naam tuphang | sabh thavar bhanhu nisang | 1161 |","meaning_en":"recognise all these as names of the tufang (gun); say them everywhere without hesitation.","page":1015,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1015,"meaning_status":"draft"},{"type":"verse","number":[1162],"number_text":"੧੧੬੨।","page":1015,"lines":[{"gurmukhi":"ਸਧਵਲਧਰਿਸਣੀ ਪਦ ਕੋ ਪ੍ਰਿਥਮ ਉਚਾਰੀਐ।","roman":"Sadhavladhrisnee pad ko pritham uchaareeai |","meaning_en":"Utter first the word 'sadhaval-dharisani',","page":1015,"meaning_status":"draft","note":"ਸਧਵਲਧਰਿਸਣੀ: obscure; perhaps 'held by the white one (dhaval, the bull who in legend holds up the earth)' = earth, + is 'lord' + -ni = army of kings; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Arinee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਪੁਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Amit puk ke naam chatur lahi leejeeai |","meaning_en":"O clever one, take these as countless names of the gun;","page":1015,"meaning_status":"draft","note":"ਪੁਕ: printed so; read as ਤੁਪਕ 'gun'."},{"gurmukhi":"ਹੋ ਸਕਲ ਬੁਧਿਜਨ ਸੁਨਤ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੧੬੨।","roman":"Ho sakal budhijan sunat uchaaran keejeeai | 1162 |","meaning_en":"utter them in the hearing of all the wise.","page":1015,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1015,"meaning_status":"draft"},{"type":"verse","number":[1163],"number_text":"੧੧੬੩।","page":1015,"lines":[{"gurmukhi":"ਬ੍ਰਿਖਭ ਧਰਿਸਣੀ ਆਦਿ ਬਖਾਨੋ। ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੋ।","roman":"Brikhabh dharisnee aadi bakhaano | ari pad anti tavan ke thaano |","meaning_en":"Say first the word 'brikhabh-dharisani' (army of lords of what the bull holds up, i.e. the earth), and place the word 'ari' at its end:","page":1015,"meaning_status":"draft","note":"ਬ੍ਰਿਖਭ ਧਰਿਸਣੀ: brikhabh 'bull' (who holds the earth) + dhara + is 'lord' + -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ਸਕਲ ਸਭਾ ਤੇ ਸੁਣਤ ਭਣਿਜੈ। ੧੧੬੩।","roman":"Naam tupak ke sabh lahi lijai | sakal sabhaa te sunat bhanijai | 1163 |","meaning_en":"take all these as names of the gun; speak them in the hearing of the whole assembly.","page":1015,"meaning_status":"draft"}]},{"type":"verse","number":[1164],"number_text":"੧੧੬੪।","page":1015,"lines":[{"gurmukhi":"ਧਾਵਲੇਸਣੀ ਆਦਿ ਬਖਾਨੋ। ਮਥਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਠਾਨੋ।","roman":"Dhaavlesnee aadi bakhaano | mathnee sabad anti tih thaano |","meaning_en":"Say first the word 'dhavalesani', and place the word 'mathani' at its end:","page":1015,"meaning_status":"draft","note":"ਧਾਵਲੇਸਣੀ: dhaval 'white bull' (earth-bearer) + is 'lord' + -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੀਐ। ਸਕਲ ਬੁਧਿਜਨ ਸੁਨਤ ਬਖਾਨੀਐ। ੧੧੬੪।","roman":"Naam tupak ke sakal pachhaaneeai | sakal budhijan sunat bakhaaneeai | 1164 |","meaning_en":"recognise these as all the names of the gun; speak them in the hearing of all the wise.","page":1015,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1015,"meaning_status":"draft"},{"type":"verse","number":[1165],"number_text":"੧੧੬੫।","page":1015,"lines":[{"gurmukhi":"ਆਦਿ ਧਵਲਇਸਣੀ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Aadi dhavlaisnee sabdaadi bakhaaneeai |","meaning_en":"Say first the word 'dhaval-isani',","page":1015,"meaning_status":"draft","note":"ਧਵਲਇਸਣੀ: dhaval 'white bull' + is 'lord' + -ni; uncertain. ਆਦਿ ... ਸਬਦਾਦਿ: 'first' is said twice."},{"gurmukhi":"ਤਾ ਕੇ ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Taa ke arinee anti sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam chatur lahi leejeeai |","meaning_en":"O clever one, take these as all the names of the gun;","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਗੁਨੀਜਨਨ ਕੀ ਸਭਾ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੧੬੫।","roman":"Ho guneejnan kee sabhaa uchaaran keejeeai | 1165 |","meaning_en":"utter them in the assembly of men of merit.","page":1015,"meaning_status":"draft"}]},{"type":"verse","number":[1166],"number_text":"੧੧੬੬।","page":1015,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਬ੍ਰਿਖਭਣੀਇਸਣੀ ਸਬਦ ਉਚਾਰੀਐ।","roman":"Pritham brikhabhneeisnee sabad uchaareeai |","meaning_en":"First utter the word 'brikhabhani-isani',","page":1015,"meaning_status":"draft","note":"ਬ੍ਰਿਖਭਣੀਇਸਣੀ: built on brikhabh 'bull' + is 'lord' + -ni; uncertain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Mathnee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'mathani' at its end.","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚੀਨ ਲੈ ਚਤੁਰ ਚਿਤ।","roman":"Sakal tupak ke naam cheen lai chatur chit |","meaning_en":"O clever one, recognise in your mind these as all the names of the gun;","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਾਬਿ ਕਥਾ ਮੈ ਦੀਜੈ ਅਉ ਭੀਤਰ ਕਬਿਤ। ੧੧੬੬।","roman":"Ho kaabi kathaa mai deejai au bheetar kabit | 1166 |","meaning_en":"give them in tales of poetry and within kabitt.","page":1015,"meaning_status":"draft"}]},{"type":"verse","number":[1167],"number_text":"੧੧੬੭।","page":1015,"lines":[{"gurmukhi":"ਗਾਵਿਸਇਸਣੀ ਅਬਦਹਿ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Gaavisaisnee abadhi aadi uchaareeai |","meaning_en":"Utter first the word 'gavis-isani',","page":1015,"meaning_status":"draft","note":"ਗਾਵਿਸਇਸਣੀ: gav 'cow/bull' + is + is + -ni; uncertain. ਅਬਦਹਿ: printed so; read as ਸਬਦਹਿ 'the word'."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Arinee taa ke anti sabad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam sughar lahi leejeeahi |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1015,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਬੀਚ ਨਿਡਰ ਹੁਇ ਦੀਜੀਅਹਿ। ੧੧੬੭।","roman":"Ho kabit kaabi ke beech nidar hui deejeeahi | 1167 |","meaning_en":"give them fearlessly within kabitt and poetry.","page":1015,"meaning_status":"draft"}]},{"type":"verse","number":[1168],"number_text":"੧੧੬੮।","page":1016,"lines":[{"gurmukhi":"ਭੁਵਿਸਣੀ ਪਦ ਪ੍ਰਿਥਮ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Bhuvisnee pad pritham uchaaran keejeeai |","meaning_en":"Utter first the word 'bhuvisani' (army of lords of the earth),","page":1016,"meaning_status":"draft","note":"ਭੁਵਿਸਣੀ: bhuvi 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕਹੁ ਦੀਜੀਐ।","roman":"Mathnee taa ke anti sabad kahu deejeeai |","meaning_en":"and give the word 'mathani' at its end.","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeey leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੈ ਚਹੀਐ ਤਹ ਤੇ ਦੀਜੀਐ। ੧੧੬੮।","roman":"Ho javan thavar mai chaheeai tah te deejeeai | 1168 |","meaning_en":"give them from whatever place you want.","page":1016,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1016,"meaning_status":"draft"},{"type":"verse","number":[1169],"number_text":"੧੧੬੯।","page":1016,"lines":[{"gurmukhi":"ਉਰਵਿਸਣੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਮਥਣੀ ਅੰਤਿ ਸਬਦ ਤਿਹ ਦਿਜੈ।","roman":"Urvisnee sabdaadi bhanijai | mathnee anti sabad tih dijai |","meaning_en":"Say first the word 'urvisani' (army of lords of the earth), and give the word 'mathani' at its end:","page":1016,"meaning_status":"draft","note":"ਉਰਵਿਸਣੀ: urvi 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹਿਜਹਿ। ਸਰਬ ਠਵਰ ਬਿਨੁ ਸੰਕ ਭਣਿਜਹਿ। ੧੧੬੯।","roman":"Sakal tupak ke naam lahijhi | sarab thavar binu sank bhanijhi | 1169 |","meaning_en":"take these as all the names of the gun; speak them everywhere without hesitation.","page":1016,"meaning_status":"draft"}]},{"type":"verse","number":[1170],"number_text":"੧੧੭੦।","page":1016,"lines":[{"gurmukhi":"ਜਗਤੀਸਣੀ ਪਦਾਦਿ ਬਖਾਨੋ। ਅੰਤਿ ਸਬਦ ਮਥਣੀ ਤਿਹ ਠਾਨੋ।","roman":"Jagteesnee padaadi bakhaano | anti sabad mathnee tih thaano |","meaning_en":"Say first the word 'jagtisani' (army of lords of the world), and place the word 'mathani' at its end:","page":1016,"meaning_status":"draft","note":"ਜਗਤੀਸਣੀ: jagati 'world, earth' + is 'lord' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਯਾ ਮੈ ਭੇਦ ਰਤੀ ਨ ਪ੍ਰਮਾਨਹੁ। ੧੧੭੦।","roman":"Sakal tupak ke naam pachhaanhu | yaa mai bhed ratee na pramaanhu | 1170 |","meaning_en":"recognise these as all the names of the gun; accept not a particle of difference in this.","page":1016,"meaning_status":"draft"}]},{"type":"verse","number":[1171],"number_text":"੧੧੭੧।","page":1016,"lines":[{"gurmukhi":"ਬਸੁਮਤੇਸਣੀ ਆਦਿ ਉਚਰੀਐ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਧਰੀਐ।","roman":"Basumtesnee aadi uchreeai | arinee sabad anti tih dhareeai |","meaning_en":"Utter first 'basumatesani' (army of lords of the earth), and set the word 'arini' at its end:","page":1016,"meaning_status":"draft","note":"ਬਸੁਮਤੇਸਣੀ: vasumati 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭਲਹਿ ਲਿਜਹਿ। ਸਭਨ ਸੁਨਤ ਬਿਨੁ ਸੰਕ ਭਣਿਜਹਿ। ੧੧੭੧।","roman":"Naam tupak ke sabhalhi lijhi | sabhan sunat binu sank bhanijhi | 1171 |","meaning_en":"take all these as names of the gun; speak them without hesitation in everyone's hearing.","page":1016,"meaning_status":"draft","note":"ਸਭਲਹਿ: printed so; read as ਸਭ ਲਹਿ."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1016,"meaning_status":"draft"},{"type":"verse","number":[1172],"number_text":"੧੧੭੨।","page":1016,"lines":[{"gurmukhi":"ਬਸੁਧੇਸਣੀ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Basudhesnee sabad ko aadi uchaareeai |","meaning_en":"Utter first the word 'basudhesani' (army of lords of the earth),","page":1016,"meaning_status":"draft","note":"ਬਸੁਧੇਸਣੀ: vasudha 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਤਾ ਕੇ ਮਥਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Taa ke mathnee anti sabad ko daareeai |","meaning_en":"and put the word 'mathani' at its end.","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤ ਚੀਨ ਲੈ।","roman":"Sakal tupak ke naam chatur chit cheen lai |","meaning_en":"O clever one, recognise in your mind these as all the names of the gun;","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੈ ਚਹੋ ਤਹੀ ਤੇ ਸਬਦ ਦੈ ੧੧੭੨।","roman":"Ho javan thavar mai chaho tahee te sabad dai 1172 |","meaning_en":"wherever you wish, give the words from there.","page":1016,"meaning_status":"draft"}]},{"type":"verse","number":[1173],"number_text":"੧੧੭੩।","page":1016,"lines":[{"gurmukhi":"ਬੇਸੁੰਧੁਰਾਏਸਨੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Besundhuraaesnee aadi bakhaaneeai |","meaning_en":"Say first 'besundhura-esani' (army of lords of the earth),","page":1016,"meaning_status":"draft","note":"ਬੇਸੁੰਧੁਰਾਏਸਨੀ: printed so; read as vasundhara 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Arinee taa ke anti sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨ ਚਤੁਰ ਜੀਅ ਲੀਜੀਅਹਿ।","roman":"Naam tupak ke jaan chatur jeea leejeeahi |","meaning_en":"O clever one, know in your mind these as names of the gun;","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੋ ਚਹੋ ਤਹੀ ਤੇ ਦੀਜੀਅਹਿ। ੧੧੭੩।","roman":"Ho javan thavar mo chaho tahee te deejeeahi | 1173 |","meaning_en":"give them from whatever place you wish.","page":1016,"meaning_status":"draft"}]},{"type":"verse","number":[1174],"number_text":"੧੧੭੪।","page":1016,"lines":[{"gurmukhi":"ਬਸੁਮਤੇਸਣੀ ਪ੍ਰਿਥਮ ਸਬਦ ਕੋ ਭਾਖੀਐ।","roman":"Basumtesnee pritham sabad ko bhaakheeai |","meaning_en":"Say first the word 'basumatesani' (army of lords of the earth),","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਬਹੁਰਿ ਪਦ ਰਾਖੀਐ।","roman":"Arinee taa ke anti bahuri pad raakheeai |","meaning_en":"then keep the word 'arini' at its end.","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਸਕਲ ਜੀਅ ਜਾਨੀਐ।","roman":"Naam tupak ke chatur sakal jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1016,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹਾ ਜਹਾ ਚਹੀਐ ਪਦ ਤਹੀ ਬਖਾਨੀਐ। ੧੧੭੪।","roman":"Ho jahaa jahaa chaheeai pad tahee bakhaaneeai | 1174 |","meaning_en":"speak the words wherever they are wanted.","page":1016,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1016,"meaning_status":"draft"},{"type":"verse","number":[1175],"number_text":"੧੧੭੫।","page":1016,"lines":[{"gurmukhi":"ਸਾਮੁੰਦ੍ਰਣੀ ਏਸਣੀ ਕਹੀਐ। ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਕਹੁ ਗਹੀਐ।","roman":"Saamundranee esnee kaheeai | arinee anti sabad kahu gaheeai |","meaning_en":"Say 'samundrani esani', and take up the word 'arini' at the end:","page":1016,"meaning_status":"draft","note":"ਸਾਮੁੰਦ੍ਰਣੀ ਏਸਣੀ: samundrani 'the sea-girt (earth)' + is 'lord' + -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਲੇਹੁ ਸੁਜਨ ਜਨ। ਅਪਨੇ ਅਪਨੇ ਬੀਚ ਸਕਲ ਮਨਿ। ੧੧੭੫।","roman":"Naam tupak ke lehu sujan jan | apne apne beech sakal mani | 1175 |","meaning_en":"O good people, take these as names of the gun, each of you in your own mind.","page":1016,"meaning_status":"draft"}]},{"type":"verse","number":[1176],"number_text":"੧੧੭੬।","page":1016,"lines":[{"gurmukhi":"ਸਾਮੁੰਦ੍ਰਣੀਏਸਣੀ ਭਾਖੋ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਰਾਖੋ।","roman":"Saamundranee'esnee bhaakho | arinee sabad anti tih raakho |","meaning_en":"Say 'samundrani-esani', and keep the word 'arini' at its end:","page":1016,"meaning_status":"draft","note":"Same compound as 5.860.0, printed joined."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ਸਕਲ ਸੁਕਬਿਜਨ ਸੁਨਤ ਭਣਿਜੈ। ੧੧੭੬।","roman":"Naam tupak ke sakal lahijai | sakal sukbijan sunat bhanijai | 1176 |","meaning_en":"take these as all the names of the gun; speak them in the hearing of all good poets.","page":1016,"meaning_status":"draft"}]},{"type":"verse","number":[1177],"number_text":"੧੧੭੭।","page":1017,"lines":[{"gurmukhi":"ਅਚਲਾਇਸਣੀ ਆਦਿ ਭਣਿਜੈ। ਮਥਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦਿਜੈ।","roman":"Achlaaisnee aadi bhanijai | mathnee sabad anti tih dijai |","meaning_en":"Say first 'achalaisani' (army of lords of the earth), and give the word 'mathani' at its end:","page":1017,"meaning_status":"draft","note":"ਅਚਲਾਇਸਣੀ: achala 'the immovable one' = earth + is 'lord' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਜਵਨ ਠਵਰ ਚਹੀਐ ਹ ਦੀਜੈ। ੧੧੭੭।","roman":"Sakal tupak ke naam laheejai | javan thavar chaheeai ha deejai | 1177 |","meaning_en":"take these as all the names of the gun; give them in whatever place is wanted.","page":1017,"meaning_status":"draft","note":"ਹ ਦੀਜੈ: printed so; read as ਤਹ ਦੀਜੈ."}]},{"type":"verse","number":[1178],"number_text":"੧੧੭੮।","page":1017,"lines":[{"gurmukhi":"ਵਿਪਲੀਸਿਣੀ ਪਦਾਦਿ ਉਚਾਰੋ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਧਾਰੋ।","roman":"Vipleesinee padaadi uchaaro | arinee sabad anti tih dhaaro |","meaning_en":"Utter first the word 'vipalisini' (army of lords of the earth), and set the word 'arini' at its end:","page":1017,"meaning_status":"draft","note":"ਵਿਪਲੀਸਿਣੀ: perhaps vipula 'the vast one' = earth + is + -ni; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਨ ਰੰਚਕ ਜਾਨੋ। ੧੧੭੮।","roman":"Sakal tupak ke naam pachhaano | yaa mai bhed na ranchak jaano | 1178 |","meaning_en":"recognise these as all the names of the gun; know not the least difference in this.","page":1017,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1017,"meaning_status":"draft"},{"type":"verse","number":[1179],"number_text":"੧੧੭੯।","page":1017,"lines":[{"gurmukhi":"ਆਦਿ ਸਾਗਰਾ ਸਬਦ ਬਖਾਨਨ ਕੀਜੀਐ।","roman":"Aadi saagraa sabad bakhaanan keejeeai |","meaning_en":"Say first the word 'sagara' (sea-girt, i.e. the earth),","page":1017,"meaning_status":"draft","note":"ਸਾਗਰਾ: read as 'the sea-girt' = earth; uncertain."},{"gurmukhi":"ਏਸ ਦਰਰਨੀ ਅੰਤਿ ਤਵਨ ਕੋ ਦੀਜੀਐ।","roman":"Es dararnee anti tavan ko deejeeai |","meaning_en":"and give 'es-dararni' (destroyer of the lord) at its end.","page":1017,"meaning_status":"draft","note":"ਏਸ ਦਰਰਨੀ: is 'lord' + dar(a)ni 'destroyer'; the -ni (army) step seems implied; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam sughar lahi leejeeahi |","meaning_en":"O skilful one, take these as all the names of the gun;","page":1017,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਬੀਚ ਚੋ ਤਹ ਦੀਜੀਅਹਿ। ੧੧੭੯।","roman":"Ho kabit kaabi ke beech cho tah deejeeahi | 1179 |","meaning_en":"give them wherever you wish within kabitt and poetry.","page":1017,"meaning_status":"draft","note":"ਚੋ: printed so; read as ਚਹੋ 'you wish'."}]},{"type":"verse","number":[1180],"number_text":"੧੧੮੦।","page":1017,"lines":[{"gurmukhi":"ਮਹਾਅਰਣਵੀ ਸਬਦਹਿ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Mahaa'aranvee sabadhi aadi uchaareeai |","meaning_en":"Utter first the word 'maha-arnavi' (the earth with the great ocean),","page":1017,"meaning_status":"draft","note":"ਮਹਾਅਰਣਵੀ: maha arnav 'great ocean'; with -i, 'the one girt by the great ocean' = earth; uncertain."},{"gurmukhi":"ਪਤਿ ਮਰਦਨਨੀਹ ਅੰਤਿ ਸਬਦ ਕਹੁ ਡਾਰੀਐ।","roman":"Pati mardanneeh anti sabad kahu daareeai |","meaning_en":"and put the words 'pati mardanani' (lord, destroyer) at its end.","page":1017,"meaning_status":"draft","note":"ਪਤਿ ਮਰਦਨਨੀਹ: printed so; read as pati 'lord' + mardani 'crusher'; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਜਾਨ ਜੀਯ ਰਾਖਅਹਿ।","roman":"Naam tupak ke sakal jaan jeey raakha'ahi |","meaning_en":"Know in your mind and keep all these as names of the gun;","page":1017,"meaning_status":"draft","note":"ਰਾਖਅਹਿ: printed so; read as ਰਾਖੀਅਹਿ."},{"gurmukhi":"ਹੋ ਸਕਲ ਸੁਜਨ ਜਨ ਸੁਨਤ ਨਿਡਰ ਹੁਇ ਭਾਖੀਅਹਿ। ੧੧੮੦।","roman":"Ho sakal sujan jan sunat nidar hui bhaakheeahi | 1180 |","meaning_en":"speak them fearlessly in the hearing of all good people.","page":1017,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1017,"meaning_status":"draft"},{"type":"verse","number":[1181],"number_text":"੧੧੮੧।","page":1017,"lines":[{"gurmukhi":"ਆਦਿ ਸਿੰਧੁਣੀ ਸਬਦ ਭਣੀਜੈ। ਪਤਿ ਅਰਦਨੀ ਪਦਾਂਤ ਕਹੀਜੈ।","roman":"Aadi sindhunee sabad bhaneejai | pati aradnee padaant kaheejai |","meaning_en":"Say the word 'sindhuni' (the sea-girt, i.e. earth) first, and say 'pati ardani' (lord, destroyer) at the end:","page":1017,"meaning_status":"draft","note":"ਸਿੰਧੁਣੀ: sindhu 'ocean' + -ni = the sea-girt earth; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੋ। ਸਕਲ ਸੁਜਨ ਜਨ ਸੁਨਤੇ ਕਹੋ। ੧੧੮੧।","roman":"Sabh sree naam tupak ke laho | sakal sujan jan sunte kaho | 1181 |","meaning_en":"take these as all the honoured names of the gun; say them in the hearing of all good people.","page":1017,"meaning_status":"draft"}]},{"type":"verse","number":[1182],"number_text":"੧੧੮੨।","page":1017,"lines":[{"gurmukhi":"ਨੀਰਾਲਯਨੀ ਆਦਿ ਉਚਰੋ। ਨਾਇਕ ਅਰਿਣੀ ਪੁਨਿ ਪਦ ਧਰੋ।","roman":"Neeraalaynee aadi uchro | naaik arinee puni pad dharo |","meaning_en":"Utter first 'niralayani' (the earth, abode of waters), then put the words 'naik arini' (lord, enemy):","page":1017,"meaning_status":"draft","note":"ਨੀਰਾਲਯਨੀ: niralay 'abode of water' = ocean, + -ni = earth; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਰਤੀਕੁ ਨ ਜਾਨੋ। ੧੧੮੨।","roman":"Sakal tupak ke naam pachhaano | yaa mai bhed rateeku na jaano | 1182 |","meaning_en":"recognise these as all the names of the gun; know not a particle of difference in this.","page":1017,"meaning_status":"draft"}]},{"type":"verse","number":[1183],"number_text":"੧੧੮੩।","page":1017,"lines":[{"gurmukhi":"ਆਦਿ ਜਲਾਲਯਣੀ ਪਦ ਦਿਜੈ। ਪਤਿ ਅਰਿਣੀ ਪਦ ਬਹੁਰਿ ਭਣਿਜੈ।","roman":"Aadi jalaalaynee pad dijai | pati arinee pad bahuri bhanijai |","meaning_en":"Give first the word 'jalalayani' (the earth, abode of waters), then say the words 'pati arini' (lord, enemy):","page":1017,"meaning_status":"draft","note":"ਜਲਾਲਯਣੀ: jalalay 'abode of water' = ocean, + -ni = earth; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਸਕਲ ਸੁਜਨ ਜਨ ਸੁਨਤ ਬਖਾਨਹੁ। ੧੧੮੩।","roman":"Sakal tupak ke naam pachhaanhu | sakal sujan jan sunat bakhaanhu | 1183 |","meaning_en":"recognise these as all the names of the gun; speak them in the hearing of all good people.","page":1017,"meaning_status":"draft"}]},{"type":"verse","number":[1184],"number_text":"੧੧੮੪।","page":1017,"lines":[{"gurmukhi":"ਬਾਰਿਧਣੀ ਸਬਦਾਦਿ ਉਚਰੀਐ। ਪਤਿ ਅਰਿ ਅੰਤਿ ਸਬਦ ਕੋ ਧਰੀਐ।","roman":"Baaridhnee sabdaadi uchreeai | pati ari anti sabad ko dhareeai |","meaning_en":"Utter first the word 'baridhani' (the sea-girt, i.e. earth), and set the words 'pati ari' (lord, enemy) at the end:","page":1017,"meaning_status":"draft","note":"ਬਾਰਿਧਣੀ: baridhi 'ocean' + -ni = earth; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹੀਜੈ। ਸਕਲ ਗੁਨਿ ਜਨਨ ਸੁਨਤ ਭਨੀਜੈ। ੧੧੮੪।","roman":"Sakal tupak ke naam kaheejai | sakal guni janan sunat bhaneejai | 1184 |","meaning_en":"say these as all the names of the gun; speak them in the hearing of all men of merit.","page":1017,"meaning_status":"draft"}]},{"type":"verse","number":[1185],"number_text":"੧੧੮੫।","page":1017,"lines":[{"gurmukhi":"ਧਰਾਏਸਣੀ ਆਦਿ ਸਬਦ ਕਹਿ। ਮਥਣੀ ਅੰਤਿ ਤਵਨ ਕੇ ਪਦ ਗਹਿ।","roman":"Dharaaesnee aadi sabad kahi | mathnee anti tavan ke pad gahi |","meaning_en":"Saying the word 'dharaesani' (army of lords of the earth) first, take the word 'mathani' at its end:","page":1017,"meaning_status":"draft","note":"ਧਰਾਏਸਣੀ: dhara 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹਿਜੈ। ਸੰਕ ਛੋਰਿ ਬਿਨ ਸੰਕ ਭਣਿਜੈ। ੧੧੮੫।","roman":"Sakal tupak ke naam lahijai | sank chhori bin sank bhanijai | 1185 |","meaning_en":"take these as all the names of the gun; leave doubt behind and speak them without doubt.","page":1017,"meaning_status":"draft"}]},{"type":"verse","number":[1186],"number_text":"੧੧੮੬।","page":1017,"lines":[{"gurmukhi":"ਲੋਰਭਰੇਸਣੀ ਆਦਿ ਉਚਰੀਐ। ਅੰਤਿ ਸਬਦ ਮਥਣੀ ਕਹੁ ਧਰੀਐ।","roman":"Lorabhresnee aadi uchreeai | anti sabad mathnee kahu dhareeai |","meaning_en":"Utter first 'lorbharesani', and set the word 'mathani' at the end:","page":1017,"meaning_status":"draft","note":"ਲੋਰਭਰੇਸਣੀ: obscure; perhaps a word for the earth + is 'lord' + -ni; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨਹੁ। ਸੰਕ ਛੋਰਿ ਬਿਨੁ ਸੰਕ ਬਖਾਨਹੁ। ੧੧੮੬।","roman":"Sakal tupak ke naam pachhaanhu | sank chhori binu sank bakhaanhu | 1186 |","meaning_en":"recognise these as all the names of the gun; leave doubt behind and speak them without doubt.","page":1017,"meaning_status":"draft"}]},{"type":"verse","number":[1187],"number_text":"੧੧੮੭।","page":1018,"lines":[{"gurmukhi":"ਗੋਰਾ ਆਦਿ ਉਚਾਰਨ ਕੀਜੈ। ਏਸ ਅੰਤਕਣੀ ਅੰਤਿ ਭਣੀਜੈ।","roman":"Goraa aadi uchaaran keejai | es antaknee anti bhaneejai |","meaning_en":"Utter 'gora' (earth) first, and say 'es-antakani' (lord, destroyer) at the end:","page":1018,"meaning_status":"draft","note":"ਗੋਰਾ: read as 'go' = earth; ਏਸ ਅੰਤਕਣੀ: is 'lord' + antak 'ender' with -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ਜਹਾ ਰੁਚੈ ਤਿਹ ਠਵਰ ਪ੍ਰਮਾਨੋ। ੧੧੮੭।","roman":"Naam tupak ke sakal pachhaano | jahaa ruchai tih thavar pramaano | 1187 |","meaning_en":"recognise these as all the names of the gun; accept them in whatever place you like.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1188],"number_text":"੧੧੮੮।","page":1018,"lines":[{"gurmukhi":"ਅਵਨੇਸਣੀ ਪਦਾਦਿ ਕਹੀਜੈ। ਮਥਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦੀਜੈ।","roman":"Avnesnee padaadi kaheejai | mathnee sabad anti tih deejai |","meaning_en":"Say first the word 'avanesani' (army of lords of the earth), and give the word 'mathani' at its end:","page":1018,"meaning_status":"draft","note":"ਅਵਨੇਸਣੀ: avani 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਭੈ ਨਿਵਾਰਿ ਨਿਰਭੈ ਹੁਇ ਕਹੀਐ। ੧੧੮੮।","roman":"Sabh sree naam tupak ke laheeai | bhai nivaari nirbhai hui kaheeai | 1188 |","meaning_en":"take these as all the honoured names of the gun; put away fear and speak them fearlessly.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1189],"number_text":"੧੧੮੯।","page":1018,"lines":[{"gurmukhi":"ਦਿਗਜਨੀ ਸਬਦਾਦਿ ਭਣਿਜੈ। ਏਸਾਰਦਨੀ ਅੰਤਿ ਕਹਿਜੈ।","roman":"Digajnee sabdaadi bhanijai | esaaradnee anti kahijai |","meaning_en":"Say first the word 'digajani' (the earth with the elephants of the quarters), and say 'esardani' (lord, destroyer) at the end:","page":1018,"meaning_status":"draft","note":"ਦਿਗਜਨੀ: dig-gaj 'elephants of the directions' (who bear the earth) + -ni = earth; ਏਸਾਰਦਨੀ: is 'lord' + ardani 'crusher'; uncertain."},{"gurmukhi":"ਸਕਲ ਸੁਨਾਮ ਤੁਪਕ ਕੇ ਚੀਨਹੁ। ਜਹ ਚਾਹੋ ਤਹ ਕਹੋ ਪ੍ਰੀਬਨਹੁ। ੧੧੮੯।","roman":"Sakal sunaam tupak ke cheenhu | jah chaaho tah kaho preebanhu | 1189 |","meaning_en":"recognise all these good names of the gun; O skilful one, say them wherever you wish.","page":1018,"meaning_status":"draft","note":"ਪ੍ਰੀਬਨਹੁ: printed so; read as ਪ੍ਰਬੀਨਹੁ 'O skilful ones'."}]},{"type":"verse","number":[1190],"number_text":"੧੧੯੦।","page":1018,"lines":[{"gurmukhi":"ਕੁੰਭਿਨਾਸਨੀ ਆਦਿ ਉਚਰੀਐ। ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਕਹੁ ਧਰੀਐ।","roman":"Kunbhinaasnee aadi uchreeai | arinee anti sabad kahu dhareeai |","meaning_en":"Utter first 'kumbhi-nasani' (that which destroys elephants), and set the word 'arini' at the end:","page":1018,"meaning_status":"draft","note":"ਕੁੰਭਿਨਾਸਨੀ: 'destroyer of elephants' (a lion), + -ni; how this leads to the gun is unclear; uncertain."},{"gurmukhi":"ਸਭੈ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮਹਿ ਝੂਠ ਨੈਕ ਨਹੀ ਜਾਨੋ। ੧੧੯੦।","roman":"Sabhai tupak ke naam pachhaano | yaa mahi jhooth naik nahee jaano | 1190 |","meaning_en":"recognise all these as names of the gun; know not the least falsehood in this.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1191],"number_text":"੧੧੯੧।","page":1018,"lines":[{"gurmukhi":"ਮਹਿਏਸਣੀ ਪਦਾਦਿ ਭਣਿਜੈ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਸਮਹਿ ਦਿਜੈ।","roman":"Mahiesnee padaadi bhanijai | arinee sabad anti samhi dijai |","meaning_en":"Say first the word 'mahi-esani' (army of lords of the earth), and give the word 'arini' together at its end:","page":1018,"meaning_status":"draft","note":"ਮਹਿਏਸਣੀ: mahi 'earth' + is 'lord' + -ni. ਸਮਹਿ: read as 'together'; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਕਹੀਜੈ। ਜਹ ਹੀ ਚਹੋ ਤਹੀ ਲੈ ਦੀਜੈ। ੧੧੯੧।","roman":"Sakal tupak ke naam kaheejai | jah hee chaho tahee lai deejai | 1191 |","meaning_en":"say these as all the names of the gun; wherever you wish, take them and give them there.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1192],"number_text":"੧੧੯੨।","page":1018,"lines":[{"gurmukhi":"ਮੇਦਣੇਸਣੀ ਆਦਿ ਉਚਰੀਐ। ਘਾਰੀ ਅੰਤਿ ਸਬਦ ਕਹ ਧਰੀਐ।","roman":"Mednesnee aadi uchreeai | ghaaree anti sabad kah dhareeai |","meaning_en":"Utter first 'medanesani' (army of lords of the earth), and set the word 'ghari' at the end:","page":1018,"meaning_status":"draft","note":"ਮੇਦਣੇਸਣੀ: medini 'earth' + is 'lord' + -ni. ਘਾਰੀ: read as 'striker, killer' (cf. ghai); uncertain."},{"gurmukhi":"ਨਾਮ ਸੁਜਾਨ ਤੁਪਕ ਕੇ ਸਭ ਹੀ। ਚਾਹੋ ਜਹਾ ਉਚਰਹੁ ਤਬ ਹੀ। ੧੧੯੨।","roman":"Naam sujaan tupak ke sabh hee | chaaho jahaa ucharhu tab hee | 1192 |","meaning_en":"O wise one, all these are names of the gun; utter them wherever you wish.","page":1018,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1018,"meaning_status":"draft"},{"type":"verse","number":[1193],"number_text":"੧੧੯੩।","page":1018,"lines":[{"gurmukhi":"ਬਸੁੰਧਰੇਸਣੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Basundhresnee aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'basundharesani' (army of lords of the earth),","page":1018,"meaning_status":"draft","note":"ਬਸੁੰਧਰੇਸਣੀ: vasundhara 'earth' + is 'lord' + -ni."},{"gurmukhi":"ਸਬਦ ਦਾਹਨੀ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Sabad daahnee anti tavan ke deejeeai |","meaning_en":"and give the word 'dahani' (burner) at its end.","page":1018,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam jaan jeey leejeeahi |","meaning_en":"Know in your mind these as all the names of the gun;","page":1018,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪ੍ਰਗਟ ਸਭਾ ਕੇ ਮਾਝ ਉਚਾਰਨ ਕੀਜੀਅਹਿ। ੧੧੯੩।","roman":"Ho pragat sabhaa ke maajh uchaaran keejeeahi | 1193 |","meaning_en":"utter them openly in the midst of the assembly.","page":1018,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1018,"meaning_status":"draft"},{"type":"verse","number":[1194],"number_text":"੧੧੯੪।","page":1018,"lines":[{"gurmukhi":"ਸੁੰਧਰੇਸਣੀ ਆਦਿ ਉਚਰੀਐ। ਮਥਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਧਰੀਐ।","roman":"Sundhresnee aadi uchreeai | mathnee anti sabad ko dhareeai |","meaning_en":"Utter first 'sundharesani' (army of lords of the earth), and set the word 'mathani' at the end:","page":1018,"meaning_status":"draft","note":"ਸੁੰਧਰੇਸਣੀ: printed so; read as vasundhara + is + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਅਧਿਕ ਗੁਨਿਜਨਨ ਸੁਨਤ ਭਨੀਜੈ। ੧੧੯੪।","roman":"Sakal tupak ke naam laheejai | adhik gunijnan sunat bhaneejai | 1194 |","meaning_en":"take these as all the names of the gun; speak them in the hearing of many men of merit.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1195],"number_text":"੧੧੯੫।","page":1018,"lines":[{"gurmukhi":"ਨਰਾਧਿਪਣੀ ਆਦਿ ਭਣਿਜੈ। ਮਥਣੀ ਪਦ ਕੋ ਅੰਤਿ ਧਰਿਜੈ।","roman":"Naraadhipnee aadi bhanijai | mathnee pad ko anti dharijai |","meaning_en":"Say first 'naradhipani' (army of kings), and set the word 'mathani' at the end:","page":1018,"meaning_status":"draft","note":"ਨਰਾਧਿਪਣੀ: naradhip 'king' + -ni."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਪ੍ਰਗਟ ਸੁਕਬਿ ਜਨ ਸੁਨਤੇ ਕਹੀਐ। ੧੧੯੫।","roman":"Sabh sree naam tupak ke laheeai | pragat sukbi jan sunte kaheeai | 1195 |","meaning_en":"take these as all the honoured names of the gun; say them openly in the hearing of good poets.","page":1018,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1018,"meaning_status":"draft"},{"type":"verse","number":[1196],"number_text":"੧੧੯੬।","page":1018,"lines":[{"gurmukhi":"ਅੜਿਲ ਮਾਨੁਖੇਸਣੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aril maanukhesnee aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'manukhesani' (army of lords of men),","page":1018,"meaning_status":"draft","note":"ਮਾਨੁਖੇਸਣੀ: manukh 'man' + is 'lord' + -ni. The line begins with ਅੜਿਲ: printed so, the metre name repeated; not translated."},{"gurmukhi":"ਅਤਕਨੀ ਸਬਦਾਦਿ ਤਵਨ ਕੇ ਦੀਜਰੀਐ।","roman":"Ataknee sabdaadi tavan ke deejreeai |","meaning_en":"and give the word 'antakani' (ender) at its end.","page":1018,"meaning_status":"draft","note":"ਅਤਕਨੀ: printed so; read as ਅੰਤਕਨੀ. ਸਬਦਾਦਿ ('first') here must mean 'the word ... at the end'. ਦੀਜਰੀਐ: printed so; read as ਦੀਜੀਐ."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਪਹਿਚਾਨੀਐ।","roman":"Sakal tupak ke naam chatur pahichaaneeai |","meaning_en":"O clever one, recognise these as all the names of the gun;","page":1018,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੰਕਾ ਤਿਆਗ ਉਚਰੀਐ ਸੰਕ ਨ ਮਾਨੀਐ। ੧੧੯੬।","roman":"Ho sankaa tiaag uchreeai sank na maaneeai | 1196 |","meaning_en":"abandon doubt and utter them; hold no doubt.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1197],"number_text":"੧੧੯੭।","page":1018,"lines":[{"gurmukhi":"ਦੇਸਏਸਣੀ ਪਦ ਕੋ ਪ੍ਰਿਥਮ ਬਖਾਨੀਐ।","roman":"Desaesnee pad ko pritham bakhaaneeai |","meaning_en":"Say first the word 'des-esani' (army of lords of lands),","page":1018,"meaning_status":"draft","note":"ਦੇਸਏਸਣੀ: des 'land' + is 'lord' + -ni."},{"gurmukhi":"ਅੰਤਿ ਅਰਦਨੀ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Anti aradnee sabad tavan ke thaaneeai |","meaning_en":"and place the word 'ardani' (crusher) at its end.","page":1018,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam chatur lahi leejeeai |","meaning_en":"O clever one, take these as all the names of the gun;","page":1018,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤੁ ਕਾਬਿ ਕੇ ਬੀਚ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੧੯੭।","roman":"Ho kabitu kaabi ke beech uchaaran keejeeai | 1197 |","meaning_en":"utter them within kabitt and poetry.","page":1018,"meaning_status":"draft"}]},{"type":"verse","number":[1198],"number_text":"੧੧੯੮।","page":1019,"lines":[{"gurmukhi":"ਜਨਪਦੇਸਣੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Janapdesnee aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'janapadesani' (army of lords of the realms),","page":1019,"meaning_status":"draft","note":"ਜਨਪਦੇਸਣੀ: janapad 'country' + is 'lord' + -ni."},{"gurmukhi":"ਅੰਤਿਯੰਤਕਨੀ ਸਬਦ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Antiyantaknee sabad tavan ke deejeeai |","meaning_en":"and give the word 'antakani' (ender) at its end.","page":1019,"meaning_status":"draft","note":"ਅੰਤਿਯੰਤਕਨੀ: read as ਅੰਤਿ 'at the end' + ਅੰਤਕਨੀ 'antakani'; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam jaan jeea leejeeahi |","meaning_en":"Know in your mind these as all the names of the gun;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਹੀਅਹਿ ਠਵਰ ਜਹਾ ਸੁ ਤਹਾ ਤੇ ਦੀਜੀਅਹਿ। ੧੧੯੮।","roman":"Ho chaheeahi thavar jahaa su tahaa te deejeeahi | 1198 |","meaning_en":"give them from whatever place they are wanted.","page":1019,"meaning_status":"draft"}]},{"type":"verse","number":[1199],"number_text":"੧੧੯੯।","page":1019,"lines":[{"gurmukhi":"ਮਾਨਵੇਦ੍ਰਣੀ ਪਦ ਕੋ ਪ੍ਰਿਥਮ ਬਖਾਨੀਐ।","roman":"Maanvedranee pad ko pritham bakhaaneeai |","meaning_en":"Say first the word 'manavendrani' (army of lords of men),","page":1019,"meaning_status":"draft","note":"ਮਾਨਵੇਦ੍ਰਣੀ: manav 'man' + indra 'lord' + -ni."},{"gurmukhi":"ਅੰਤਯੰਤਕਨੀ ਪਦ ਕੋ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Antyantaknee pad ko bahuri pramaaneeai |","meaning_en":"then set down the word 'antakani' at the end.","page":1019,"meaning_status":"draft","note":"ਅੰਤਯੰਤਕਨੀ: read as ਅੰਤਿ 'at the end' + ਅੰਤਕਨੀ 'antakani'; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਤਿਹ ਚਿਤ ਮਹਿ।","roman":"Sakal tupak ke naam jaan tih chit mahi |","meaning_en":"Know these in your mind as all the names of the gun;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਇਸੀ ਕਰ ਮਿਤ ਮਹਿ। ੧੧੯੯।","roman":"Ho bhoot bhavikh bhavaan isee kar mit mahi | 1199 |","meaning_en":"in the past, the future and the present, take them thus as your friend.","page":1019,"meaning_status":"draft","note":"ਭੂਤ ਭਵਿਖ ਭਵਾਨ ... ਮਿਤ ਮਹਿ: obscure; perhaps 'hold them as a friend at all times'; uncertain."}]},{"type":"verse","number":[1200],"number_text":"੧੨੦੦।","page":1019,"lines":[{"gurmukhi":"ਲੋਕਏਦ੍ਰਣੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Lokaedranee aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'lok-endrani' (army of lords of the world),","page":1019,"meaning_status":"draft","note":"ਲੋਕਏਦ੍ਰਣੀ: lok 'world/people' + indra 'lord' + -ni."},{"gurmukhi":"ਤਾ ਕੇ ਹਰਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Taa ke harnee anti sabad ko deejeeai |","meaning_en":"and give the word 'harani' (destroyer) at its end.","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam jaan jeey leejeeahi |","meaning_en":"Know in your mind these as all the names of the gun;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਰੈਨ ਦਿਵਸ ਸਭ ਮੁਖ ਤੇ ਭਾਖ੍ਯੋ ਕੀਜੀਅਹਿ। ੧੨੦੦।","roman":"Ho rain divas sabh mukh te bhaakhyo keejeeahi | 1200 |","meaning_en":"keep speaking them from the mouth night and day.","page":1019,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1019,"meaning_status":"draft"},{"type":"verse","number":[1201],"number_text":"੧੨੦੧।","page":1019,"lines":[{"gurmukhi":"ਲੋਕਰਾਜਨੀ ਆਦਿ ਭਣਿਜੈ। ਅਰਿਣੀ ਸਬਦ ਅੰਤਿ ਤਿਹ ਦਿਜੈ।","roman":"Lokraajnee aadi bhanijai | arinee sabad anti tih dijai |","meaning_en":"Say first 'lokrajani' (army of kings of the world), and give the word 'arini' at its end:","page":1019,"meaning_status":"draft","note":"ਲੋਕਰਾਜਨੀ: lok 'world' + raj 'king' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤਨ ਮਾਠ ਕਹੀਜੈ। ੧੨੦੧।","roman":"Sakal tupak ke naam laheejai | saasatr sinmritan maath kaheejai | 1201 |","meaning_en":"take these as all the names of the gun; say them amid the shastras and smritis.","page":1019,"meaning_status":"draft","note":"ਮਾਠ: printed so; read as ਮਾਝ 'amid' (cf. 5.894.1)."}]},{"type":"verse","number":[1202],"number_text":"੧੨੦੨।","page":1019,"lines":[{"gurmukhi":"ਦੇਸੇਸਨੀ ਰਵਣਨੀ ਭਾਖੋ। ਅੰਤਿ ਅੰਤਕਨੀ ਸਬਦਹਿ ਰਾਖੋ।","roman":"Desesnee ravannee bhaakho | anti antaknee sabadhi raakho |","meaning_en":"Say 'desesani ravanani', and keep the word 'antakani' at the end:","page":1019,"meaning_status":"draft","note":"ਦੇਸੇਸਨੀ ਰਵਣਨੀ: des 'land' + is 'lord' + -ni; ravanani obscure (perhaps 'those who roar' or a misprint); uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਸੁ ਕਬਿਜਨਨ ਕੇ ਸੁਨਤ ਭਨੀਜੈ। ੧੨੦੨।","roman":"Sakal tupak ke naam laheejai | su kabijnan ke sunat bhaneejai | 1202 |","meaning_en":"take these as all the names of the gun; speak them in the hearing of good poets.","page":1019,"meaning_status":"draft"}]},{"type":"verse","number":[1203],"number_text":"੧੨੦੩।","page":1019,"lines":[{"gurmukhi":"ਥਿਰਾ ਭਾਖਿ ਇਸਣੀ ਪੁਨਿ ਭਾਖੋ। ਅੰਤਿ ਅੰਤਕਨੀ ਪਦ ਕਹੁ ਰਾਖੋ।","roman":"Thiraa bhaakhi isnee puni bhaakho | anti antaknee pad kahu raakho |","meaning_en":"Say 'thira' (the steady one, i.e. earth), then say 'isani', and keep the word 'antakani' at the end:","page":1019,"meaning_status":"draft","note":"ਥਿਰਾ: sthira 'the firm one' = earth; ਇਸਣੀ: is 'lord' + -ni."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹਿਜੈ। ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤਨ ਮਾਝ ਭਣਿਜੈ। ੧੨੦੩।","roman":"Sakal tupak ke naam lahijai | saasatr sinmritan maajh bhanijai | 1203 |","meaning_en":"take these as all the names of the gun; speak them amid the shastras and smritis.","page":1019,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1019,"meaning_status":"draft"},{"type":"verse","number":[1204],"number_text":"੧੨੦੪।","page":1019,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਕਾਸਪੀ ਇਸਣੀ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Pritham kaaspee isnee sabad bakhaaneeai |","meaning_en":"First say the words 'kaspi isani' (army of lords of Kashyap's daughter, the earth),","page":1019,"meaning_status":"draft","note":"ਕਾਸਪੀ: Kashyapi, a name of the earth; + is 'lord' + -ni."},{"gurmukhi":"ਅੰਤਯੰਤਕਨੀ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Antyantaknee sabad tavan ke thaaneeai |","meaning_en":"and place the word 'antakani' at its end.","page":1019,"meaning_status":"draft","note":"ਅੰਤਯੰਤਕਨੀ: read as ਅੰਤਿ 'at the end' + ਅੰਤਕਨੀ 'antakani'; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeey leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੰਕਾ ਤਿਆਗਿ ਨਿਸੰਕ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੨੦੪।","roman":"Ho sankaa tiaagi nisank uchaaran keejeeai | 1204 |","meaning_en":"abandon doubt and utter them without doubt.","page":1019,"meaning_status":"draft"}]},{"type":"verse","number":[1205],"number_text":"੧੨੦੫।","page":1019,"lines":[{"gurmukhi":"ਆਦਿ ਨਾਮ ਨਾਗਨ ਕੇ ਪ੍ਰਿਥਮ ਬਖਾਨੀਐ।","roman":"Aadi naam naagan ke pritham bakhaaneeai |","meaning_en":"First say the names of the serpents,","page":1019,"meaning_status":"draft","note":"Here the chain is serpent → father of serpents (Kashyap) → his lord ... ; uncertain."},{"gurmukhi":"ਪਿਤਣੀ ਇਸਣੀ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Pitnee isnee anti tavan ke thaaneeai |","meaning_en":"and place the words 'pitani isani' (father, lord) at their end;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਘਾਤਨੀ ਸਬਦ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Bahuri ghaatnee sabad tavan ke deejeeai |","meaning_en":"then give the word 'ghatani' (slayer) after them;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ। ੧੨੦੫।","roman":"Ho sakal tupak ke naam chatur lahi leejeeai | 1205 |","meaning_en":"O clever one, take these as all the names of the gun.","page":1019,"meaning_status":"draft"}]},{"type":"verse","number":[1206],"number_text":"੧੨੦੬।","page":1019,"lines":[{"gurmukhi":"ਸਰਪ ਤਾਤਣੀ ਇਸਣੀ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Sarap taatnee isnee aadi uchaareeai |","meaning_en":"Utter first 'sarap tatani isani' (lord of the father of serpents),","page":1019,"meaning_status":"draft","note":"ਸਰਪ ਤਾਤਣੀ ਇਸਣੀ: sarap 'serpent' + tat 'father' (Kashyap) ...; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਮਥਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Taa ke mathnee anti sabad ko daareeai |","meaning_en":"and put the word 'mathani' at its end.","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam chatur lahi leejeeai |","meaning_en":"O clever one, take these as all the names of the gun;","page":1019,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਭ ਕਬਿਤਨ ਕੇ ਬਿਖੈ ਨਿਡਰੁ ਹੁਇ ਦੀਜੀਐ। ੧੨੦੬।","roman":"Ho sabh kabitan ke bikhai nidru hui deejeeai | 1206 |","meaning_en":"give them fearlessly in all kabitts.","page":1019,"meaning_status":"draft"}]},{"type":"verse","number":[1207],"number_text":"੧੨੦੭।","page":1020,"lines":[{"gurmukhi":"ਇੰਦਏਂਦ੍ਰਣੀ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Indaendranee aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'ind-endrani' (lord of Indra),","page":1020,"meaning_status":"draft","note":"ਇੰਦਏਂਦ੍ਰਣੀ: indra + indra + -ni; uncertain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Mathnee taa ke anti sabad ko deejeeai |","meaning_en":"and give the word 'mathani' at its end.","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam jaan jeey leejeeahi |","meaning_en":"Know in your mind these as all the names of the gun;","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਮਾਝ ਨਿਡਰ ਹੁਇ ਦੀਜੀਅਹਿ। ੧੨੦੭।","roman":"Ho kabit kaabi ke maajh nidar hui deejeeahi | 1207 |","meaning_en":"give them fearlessly within kabitt and poetry.","page":1020,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1020,"meaning_status":"draft"},{"type":"verse","number":[1208],"number_text":"੧੨੦੮।","page":1020,"lines":[{"gurmukhi":"ਦੇਵਦੇਵਣੀ ਆਦਿ ਉਚਰੀਐ। ਏਸਰਾਂਤਕਨ ਪੁਨਿਪਦ ਧਰੀਐ।","roman":"Devdevnee aadi uchreeai | esraantkan punipad dhareeai |","meaning_en":"Utter first 'devdevani' (of the god of gods, i.e. Indra), then put the word 'esarantakan':","page":1020,"meaning_status":"draft","note":"ਦੇਵਦੇਵਣੀ: devdev 'god of gods' = Indra, + -ni; ਏਸਰਾਂਤਕਨ: is 'lord' + antak 'ender'; ਪੁਨਿਪਦ printed joined. Uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਸੰਕ ਤਿਆਗ ਨਿਰਸੰਕ ਹੁਇ ਕਹੀਐ। ੧੨੦੮।","roman":"Sabh sree naam tupak ke laheeai | sank tiaag nirsank hui kaheeai | 1208 |","meaning_en":"take these as all the honoured names of the gun; abandon doubt and say them without doubt.","page":1020,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1020,"meaning_status":"draft"},{"type":"verse","number":[1209],"number_text":"੧੨੦੯।","page":1020,"lines":[{"gurmukhi":"ਸਕ੍ਰਤਾਤ ਅਰਿਣੀ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Sakrataat arinee sabdaadi bakhaaneeai |","meaning_en":"Say first the words 'sakr-tat arini' (father of Indra ...),","page":1020,"meaning_status":"draft","note":"ਸਕ੍ਰਤਾਤ: sakr 'Indra' + tat 'father' (Kashyap); the chain is uncertain."},{"gurmukhi":"ਮਥਣੀਤਾਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Mathneetaake anti sabad ko thaaneeai |","meaning_en":"and place the word 'mathani' at its end.","page":1020,"meaning_status":"draft","note":"ਮਥਣੀਤਾਕੇ: printed joined; read as ਮਥਣੀ ਤਾ ਕੇ."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਹੀਯੇ ਪਹਿਚਾਨੀਐ।","roman":"Sakal tupak ke naam heeye pahichaaneeai |","meaning_en":"Recognise in your heart these as all the names of the gun;","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਥਾ ਬਾਰਤਾ ਭੀਤਰ ਨਿਡਰ ਬਖਾਨੀਐ। ੧੨੦੯।","roman":"Ho kathaa baartaa bheetar nidar bakhaaneeai | 1209 |","meaning_en":"speak them fearlessly within tales and narratives.","page":1020,"meaning_status":"draft"}]},{"type":"verse","number":[1210],"number_text":"੧੨੧੦।","page":1020,"lines":[{"gurmukhi":"ਸਤਕ੍ਰਿਤੇਸਣੀ ਇਸਣੀ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Satkritesnee isnee aadi uchaareeai |","meaning_en":"Utter first 'satkritesani isani' (lord of Indra ...),","page":1020,"meaning_status":"draft","note":"ਸਤਕ੍ਰਿਤੇਸਣੀ: satkratu 'Indra' + is 'lord' + -ni; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Taa ke arinee anti sabad ko daareeai |","meaning_en":"and put the word 'arini' at its end.","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeey leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਗੁਨਿਜਨਨ ਸੁਨਤ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੨੧੦।","roman":"Ho sakal gunijnan sunat uchaaran keejeeai | 1210 |","meaning_en":"utter them in the hearing of all men of merit.","page":1020,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1020,"meaning_status":"draft"},{"type":"verse","number":[1211],"number_text":"੧੨੧੧।","page":1020,"lines":[{"gurmukhi":"ਸਚੀਪਤਿਸਣੀ ਇਸਣੀ ਭਾਖੋ। ਮਥਣੀ ਸਬਦ ਅੰਤ ਕੋ ਰਾਖੋ।","roman":"Sacheeptisnee isnee bhaakho | mathnee sabad ant ko raakho |","meaning_en":"Say 'sachipatisani isani' (lord of Sachi's husband, Indra ...), and keep the word 'mathani' at the end:","page":1020,"meaning_status":"draft","note":"ਸਚੀਪਤਿਸਣੀ: Sachipati 'husband of Sachi' = Indra, + is + -ni; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਦੇਸ ਦੇਸ ਕਰਿ ਪ੍ਰਗਟ ਭਨੀਜੈ। ੧੨੧੧।","roman":"Sakal tupak ke naam laheejai | des des kari pragat bhaneejai | 1211 |","meaning_en":"take these as all the names of the gun; speak them openly in land after land.","page":1020,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1020,"meaning_status":"draft"},{"type":"verse","number":[1212],"number_text":"੧੨੧੨।","page":1020,"lines":[{"gurmukhi":"ਸਕੰਦ੍ਰਨਤਾਤਣੀ ਏਸਣੀ ਭਾਖੀਐ।","roman":"Sakandrantaatnee esnee bhaakheeai |","meaning_en":"Say 'skandran-tatani esani' (lord of the father of Indra ...),","page":1020,"meaning_status":"draft","note":"ਸਕੰਦ੍ਰਨਤਾਤਣੀ: perhaps sakr/indra 'Indra' + tat 'father' + -ni; uncertain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Mathnee taa ke anti sabad ko raakheeai |","meaning_en":"and keep the word 'mathani' at its end.","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਚਿਤ ਮੈ ਚਤਰ ਪਛਾਨੀਐ।","roman":"Naam tupak ke chit mai chatar pachhaaneeai |","meaning_en":"O clever one, recognise in your mind these as names of the gun;","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਬਿਨਾ ਕਪਟ ਤਿਨ ਲਖੋ ਨ ਕਪਟ ਪ੍ਰਮਾਨੀਐ। ੧੨੧੨।","roman":"Ho binaa kapat tin lakho na kapat pramaaneeai | 1212 |","meaning_en":"know them without deceit, and accept no deceit in them.","page":1020,"meaning_status":"draft"}]},{"type":"verse","number":[1213],"number_text":"੧੨੧੩।","page":1020,"lines":[{"gurmukhi":"ਕਊਸਕੇਸਣੀ ਇਸਣੀ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ।","roman":"Kaooskesnee isnee pritham bakhaani kai |","meaning_en":"Having first said 'kauskesani isani' (lord of Kaushik's lord ...),","page":1020,"meaning_status":"draft","note":"ਕਊਸਕੇਸਣੀ: kaushik, a name of Indra, + is + -ni; uncertain."},{"gurmukhi":"ਮਥਣੀ ਤਾਕੇ ਅਘਤ ਸਬਦ ਕੋ ਠਾਨਿ ਕੈ।","roman":"Mathnee taake aghat sabad ko thaani kai |","meaning_en":"and placed the word 'mathani' at its end,","page":1020,"meaning_status":"draft","note":"ਅਘਤ: printed so; read as ਅੰਤਿ 'at the end'."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਪਹਿਚਾਨੀਐ।","roman":"Sakal tupak ke naam chatur pahichaaneeai |","meaning_en":"O clever one, recognise these as all the names of the gun;","page":1020,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹੇ ਹਮਾਰੇ ਬਚਨ ਸਤਿ ਕਰਿ ਮਾਨੀਐ। ੧੨੧੩।","roman":"Ho kahe hamaare bachan sati kari maaneeai | 1213 |","meaning_en":"accept the words I have spoken as true.","page":1020,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1020,"meaning_status":"draft"},{"type":"verse","number":[1214],"number_text":"੧੨੧੪।","page":1020,"lines":[{"gurmukhi":"ਬਾਸਵੇਸਣੀ ਆਦਿ ਭਣਿਜੈ। ਅੰਤਿ ਸਬਦ ਅਰਿਣੀ ਤਿਹ ਦਿਜੈ।","roman":"Baasvesnee aadi bhanijai | anti sabad arinee tih dijai |","meaning_en":"Say first 'basavesani' (lord of Vasav, Indra ...), and give the word 'arini' at the end:","page":1020,"flags":[{"code":"0x66","reason":"sihari typed before the previous letter's ਾ; attached to the next consonant - CHECK: the printed sihari stands before a spacing vowel sign, the print is ambiguous"}],"meaning_status":"draft","note":"ਬਾਸਵੇਸਣੀ: Vasav 'Indra' + is + -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਜੀਯ ਜਾਨੋ। ਸੰਕ ਤਿਆਗ ਨਿਰਸੰਕ ਬਖਾਨੋ। ੧੨੧੪।","roman":"Naam tupak ke sabh jeey jaano | sank tiaag nirsank bakhaano | 1214 |","meaning_en":"know in your mind all these as names of the gun; abandon doubt and speak them without doubt.","page":1020,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1021,"meaning_status":"draft"},{"type":"verse","number":[1215],"number_text":"੧੨੧੫।","page":1021,"lines":[{"gurmukhi":"ਬਰਹਾ ਇਸਣੀ ਅਰਿਣੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Barhaa isnee arinee aadi bakhaaneeai |","meaning_en":"Say first 'barha isani arini',","page":1021,"meaning_status":"draft","note":"ਬਰਹਾ: obscure; perhaps barhi/barhan 'Indra' or a word for 'ocean'; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁ ਚਿਤ ਮੈ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam su chit mai jaaneeai |","meaning_en":"and know in your mind these as all the names of the gun;","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਸੰਕ ਤਿਆਗਿ ਨਿਰੰਕ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Sank tiaagi nirank uchaaran keejeeai |","meaning_en":"abandon doubt and utter them without doubt;","page":1021,"meaning_status":"draft","note":"ਨਿਰੰਕ: printed so; read as ਨਿਰਸੰਕ 'without doubt'."},{"gurmukhi":"ਹੋ ਸਤਿ ਸੁ ਬਚਨ ਹਮਾਰੇ ਮਾਨੇ ਲੀਜੀਐ। ੧੨੧੫।","roman":"Ho sati su bachan hamaare maane leejeeai | 1215 |","meaning_en":"accept my words as true.","page":1021,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1021,"meaning_status":"draft"},{"type":"verse","number":[1216],"number_text":"੧੨੧੬।","page":1021,"lines":[{"gurmukhi":"ਮਘਵੇਸਰਣੀ ਇਸਰਣੀ ਪ੍ਰਿਥਮੈ ਪਦਹਿ ਉਚਾਰ।","roman":"Maghvesarnee isarnee prithmai padhi uchaar |","meaning_en":"Utter first the words 'maghvesarani isarani',","page":1021,"meaning_status":"draft","note":"ਮਘਵੇਸਰਣੀ ਇਸਰਣੀ: maghva 'Indra' + isar 'lord' + -ni, twice; the closing 'enemy' word is not stated; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈਂ ਲੀਜੈ ਸੁਕਬਿ ਸੁ ਧਾਰ। ੧੨੧੬।","roman":"Naam tupak ke hot hain leejai sukbi su dhaar | 1216 |","meaning_en":"these become names of the gun; O good poet, set them right.","page":1021,"meaning_status":"draft"}]},{"type":"verse","number":[1217],"number_text":"੧੨੧੭।","page":1021,"lines":[{"gurmukhi":"ਮਾਤਲੇਸਣੀ ਏਸਣੀ ਮਥਣੀ ਅੰਤਿ ਉਚਾਰ।","roman":"Maatlesnee esnee mathnee anti uchaar |","meaning_en":"Utter 'mataleesani esani' and 'mathani' at the end;","page":1021,"meaning_status":"draft","note":"ਮਾਤਲੇਸਣੀ: Matali (Indra's charioteer) + is 'lord' (= Indra) + -ni; uncertain."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਤ ਹੈ ਲੀਜਹਿ ਸੁਕਬਿ ਸੁ ਧਾਰ। ੧੨੧੭।","roman":"Naam tupak ke hot hai leejhi sukbi su dhaar | 1217 |","meaning_en":"these become names of the gun; O good poet, set them right.","page":1021,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1021,"meaning_status":"draft"},{"type":"verse","number":[1218],"number_text":"੧੨੧੮।","page":1021,"lines":[{"gurmukhi":"ਜਿਸਨਏਸਣੀ ਆਦਿ ਭਣਿਜੈ। ਇਸਣੀ ਮਥਣੀ ਅੰਤਿ ਕਹਿਜੈ।","roman":"Jisnaesnee aadi bhanijai | isnee mathnee anti kahijai |","meaning_en":"Say first 'jisan-esani' (lord of Jishnu, Indra ...), and say 'isani mathani' at the end:","page":1021,"meaning_status":"draft","note":"ਜਿਸਨਏਸਣੀ: jishnu 'Indra' + is + -ni; uncertain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਦੀਜੈ ਤਵਨ ਠਵਰ ਜਹ ਚਹੀਐ। ੧੨੧੮।","roman":"Sabh sree naam tupak ke laheeai | deejai tavan thavar jah chaheeai | 1218 |","meaning_en":"take these as all the honoured names of the gun; give them in whatever place is wanted.","page":1021,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1021,"meaning_status":"draft"},{"type":"verse","number":[1219],"number_text":"੧੨੧੯।","page":1021,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਪੁਰੰਦਰ ਇਸਣੀ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Pritham purandar isnee sabad bakhaaneeai |","meaning_en":"First say the words 'purandar isani' (Purandar, Indra; lord ...),","page":1021,"meaning_status":"draft","note":"ਪੁਰੰਦਰ: a name of Indra."},{"gurmukhi":"ਇਸਣੀ ਮਥਣੀ ਪਦ ਕੋ ਬਹੁਰਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Isnee mathnee pad ko bahuri pramaaneeai |","meaning_en":"then set down the words 'isani mathani'.","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਜਾਨ ਜੀਯ ਲੀਜੀਅਹਿ।","roman":"Naam tupak ke sakal jaan jeey leejeeahi |","meaning_en":"Know in your mind these as all the names of the gun;","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੰਕ ਤਿਆਗ ਨਿਰਸੰਕ ਉਚਾਰਨ ਕੀਜੀਅਹਿ। ੧੨੧੯।","roman":"Ho sank tiaag nirsank uchaaran keejeeahi | 1219 |","meaning_en":"abandon doubt and utter them without doubt.","page":1021,"meaning_status":"draft"}]},{"type":"verse","number":[1220],"number_text":"੧੨੨੦।","page":1021,"lines":[{"gurmukhi":"ਬਜ੍ਰਧਰਿਸਣੀ ਅਰਿਣੀ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Bajradhrisnee arinee aadi uchaareeai |","meaning_en":"Utter first the words 'bajradharisani arini' (lord of the thunderbolt-holder, Indra ...),","page":1021,"meaning_status":"draft","note":"ਬਜ੍ਰਧਰਿਸਣੀ: bajradhar 'thunderbolt-bearer' = Indra, + is + -ni."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਚਿਤ ਮੈ ਚਤੁਰ ਬਿਚਾਰੀਐ।","roman":"Naam tupak ke chit mai chatur bichaareeai |","meaning_en":"O clever one, consider in your mind these as names of the gun;","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਸੰਕ ਤਯਾਗ ਨਿਰਸੰਕ ਹੁਇ ਸਬਦ ਬਖਾਨੀਐ।","roman":"Sank tayaag nirsank hui sabad bakhaaneeai |","meaning_en":"abandon doubt and speak the words without doubt;","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਿਸੀ ਸੁਕਬਿ ਕੀ ਕਾਨ ਮਨ ਮੈ ਆਨੀਐ। ੧੨੨੦।","roman":"Ho kisee sukbi kee kaan man mai aaneeai | 1220 |","meaning_en":"bring into your mind regard for any good poet.","page":1021,"meaning_status":"draft","note":"ਕਾਨ: 'regard, deference'. Read literally the line has no negative; perhaps 'do not defer to any poet' is intended (cf. the fearless-speaking lines); uncertain."}]},{"type":"verse","number":[1221],"number_text":"੧੨੨੧।","page":1021,"lines":[{"gurmukhi":"ਤੁਰਾਖਾੜ ਪਿਤਣੀ ਇਸਣੀ ਪਦ ਭਾਖੀਐ।","roman":"Turaakhaar pitnee isnee pad bhaakheeai |","meaning_en":"Say the words 'turakhar pitani isani' (Turashat, Indra; father; lord ...),","page":1021,"meaning_status":"draft","note":"ਤੁਰਾਖਾੜ: turashat, a name of Indra; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke anti sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਹੀਯੈ ਪਹਿਚਾਨੀਅਹਿ।","roman":"Sakal tupak ke naam heeyai pahichaaneeahi |","meaning_en":"Recognise in your heart these as all the names of the gun;","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਤੁਰ ਸਭਾ ਕੇ ਬੀਚ ਨਿਸੰਕ ਬਖਾਨੀਅਹਿ। ੧੨੨੧।","roman":"Ho chatur sabhaa ke beech nisank bakhaaneeahi | 1221 |","meaning_en":"speak them without doubt in an assembly of the clever.","page":1021,"meaning_status":"draft"}]},{"type":"verse","number":[1222],"number_text":"੧੨੨੨।","page":1021,"lines":[{"gurmukhi":"ਇੰਦ੍ਰੇਣੀਇੰਦ੍ਰਾਣੀ ਆਦਿ ਬਖਾਨਿ ਕੈ।","roman":"Indreneeindraanee aadi bakhaani kai |","meaning_en":"Having said first 'indreni indrani',","page":1021,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਇੰਦ੍ਰੇਣੀਇੰਦ੍ਰਾਣੀ: printed joined; built on indra 'lord'; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨਿ ਕੈ।","roman":"Arinee taa ke anti sabad ko thaani kai |","meaning_en":"and placed the word 'arini' at its end,","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਯ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeey leejeeai |","meaning_en":"know in your mind these as all the names of the gun;","page":1021,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਬੀਚ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੨੨।","roman":"Ho kabit kaabi ke beech nidar hui deejeeai | 1222 |","meaning_en":"give them fearlessly within kabitt and poetry.","page":1021,"meaning_status":"draft"}]},{"type":"verse","number":[1223],"number_text":"੧੨੨੩।","page":1022,"lines":[{"gurmukhi":"ਉਚਸ੍ਰਿਵਾਇਸ ਏਸ ਏਸਣੀ ਭਾਖੀਐ।","roman":"Uchsrivaais es esnee bhaakheeai |","meaning_en":"Say 'uchsriva-is es esani' (lord of Uchchaihshrava, Indra's horse ...),","page":1022,"meaning_status":"draft","note":"ਉਚਸ੍ਰਿਵਾ: Uchchaihshrava, Indra's horse; its lord = Indra; uncertain chain."},{"gurmukhi":"ਇਸਣੀ ਕਹਿ ਕੈ ਅਰਿਣੀ ਪਦ ਕੋ ਰਾਖੀਐ।","roman":"Isnee kahi kai arinee pad ko raakheeai |","meaning_en":"say 'isani', then keep the word 'arini';","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਅਮਿਤ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam amit jeea jaaneeai |","meaning_en":"know in your mind these as countless names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੰਕ ਤਿਆਗ ਨਿਰਸੰਕ ਹੁਇ ਸਦਾ ਬਖਾਨੀਐ। ੧੨੨੩।","roman":"Ho sank tiaag nirsank hui sadaa bakhaaneeai | 1223 |","meaning_en":"abandon doubt and always speak them without doubt.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1224],"number_text":"੧੨੨੪।","page":1022,"lines":[{"gurmukhi":"ਹਯਣੀ ਇਸਣੀ ਇਸਣੀ ਇਸਣੀ ਭਾਖੀਐ।","roman":"Haynee isnee isnee isnee bhaakheeai |","meaning_en":"Say 'hayani isani isani isani' (of horses; lord, lord, lord),","page":1022,"meaning_status":"draft","note":"ਹਯਣੀ: hay 'horse' + -ni; chain of 'isani' (lord); uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਿਡਰ ਸਭਾ ਕੇ ਮਾਝ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੨੨੪।","roman":"Ho nidar sabhaa ke maajh uchaaran keejeeai | 1224 |","meaning_en":"utter them fearlessly in the midst of the assembly.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1225],"number_text":"੧੨੨੫।","page":1022,"lines":[{"gurmukhi":"ਗਾਜਰਾਜ ਰਾਜਨਨੀ ਪ੍ਰਭਣੀ ਭਾਖੀਐ।","roman":"Gaajraaj raajannee prabhnee bhaakheeai |","meaning_en":"Say 'gajraj rajanani prabhani' (king of elephants; king; lord),","page":1022,"meaning_status":"draft","note":"ਗਾਜਰਾਜ: read as gajraj 'king of elephants' (Airavat, Indra's elephant); uncertain chain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Mathnee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'mathani' at its end.","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨ ਨੈਕੁ ਹੂੰ ਕੀਜੀਐ। ੧੨੨੫।","roman":"Ho yaa ke bheetar bhed na naiku hoon keejeeai | 1225 |","meaning_en":"make not the slightest distinction in this.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1226],"number_text":"੧੨੨੬।","page":1022,"lines":[{"gurmukhi":"ਅਸ੍ਵ ਏਸ ਏਸਣੀ ਇਸਣੀ ਇਸਣਿ ਉਚਾਰੀਐ।","roman":"Asv es esnee isnee isni uchaareeai |","meaning_en":"Utter 'asv es esani isani isani' (horse; lord, lord, lord, lord),","page":1022,"meaning_status":"draft","note":"ਅਸ੍ਵ: 'horse'; chain of 'lord' words; uncertain."},{"gurmukhi":"ਤਾ ਕੇ ਮਥਣੀ ਅੰਤ ਸਬਦ ਕੋ ਡਾਰੀਐ।","roman":"Taa ke mathnee ant sabad ko daareeai |","meaning_en":"and put the word 'mathani' at its end.","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੰਕ ਤਿਆਗਿ ਨਿਰਸੰਕ ਉਚਾਰ੍ਯੋ ਕੀਜੀਐ। ੧੨੨੬।","roman":"Ho sank tiaagi nirsank uchaaryo keejeeai | 1226 |","meaning_en":"abandon doubt and utter them without doubt.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1227],"number_text":"੧੨੨੭।","page":1022,"lines":[{"gurmukhi":"ਬਾਹਰਾਜ ਰਾਜਨਣੀ ਰਾਜਨਿ ਭਾਖੀਐ।","roman":"Baahraaj raajannee raajni bhaakheeai |","meaning_en":"Say 'bahraj rajanani rajani' (king of horses; king; king),","page":1022,"meaning_status":"draft","note":"ਬਾਹਰਾਜ: bah 'horse' + raj 'king'; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਹੀਯੇ ਪਹਿਚਾਨੀਐ।","roman":"Sakal tupak ke naam heeye pahichaaneeai |","meaning_en":"Recognise in your heart these as all the names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਭੀਤਰ ਪ੍ਰਗਟ ਬਖਾਨੀਐ। ੧੨੨੭।","roman":"Ho kabit kaabi ke bheetar pragat bakhaaneeai | 1227 |","meaning_en":"speak them openly within kabitt and poetry.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1228],"number_text":"੧੨੨੮।","page":1022,"lines":[{"gurmukhi":"ਤੁਰੰਗ ਏਸਣੀ ਇਸਣੀ ਪ੍ਰਭਣੀ ਪ੍ਰਿਥਮ ਕਹਿ।","roman":"Turang esnee isnee prabhnee pritham kahi |","meaning_en":"Say first 'turang esani isani prabhani' (horse; lord, lord, master),","page":1022,"meaning_status":"draft","note":"ਤੁਰੰਗ: 'horse'; uncertain chain."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਬਹੁਰਿ ਗਹਿ।","roman":"Satroo sabad ko anti tavan ke bahuri gahi |","meaning_en":"then take the word 'satru' at its end.","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਗੁਨਿਜਨਨ ਸੁਨਤ ਨਿਸੰਕ ਭਣੀਜੀਐ। ੧੨੨੮।","roman":"Ho sakal gunijnan sunat nisank bhaneejeeai | 1228 |","meaning_en":"speak them without doubt in the hearing of all men of merit.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1229],"number_text":"੧੨੨੯।","page":1022,"lines":[{"gurmukhi":"ਆਇਸ ਪਤਿ ਪਿਤਣੀ ਪਦ ਕਹੀਐ।","roman":"Aais pati pitnee pad kaheeai |","meaning_en":"Say the words 'ais pati pitani' ('ais'; lord; father),","page":1022,"meaning_status":"draft","note":"ਆਇਸ: obscure; perhaps a word for horse or for Indra; uncertain. This block has four short lines under the Aril heading."},{"gurmukhi":"ਇਸਣੀ ਅਰਿਣੀ ਸਬਦਹਿ ਲਹੀਐ।","roman":"Isnee arinee sabadhi laheeai |","meaning_en":"take the words 'isani arini';","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਨੀਐ।","roman":"Sabh sree naam tupak ke janeeai |","meaning_en":"know these as all the honoured names of the gun,","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਕਬਿਤ ਕਾਬਿ ਕੇ ਭੀਤਰ ਭਨੀਐ। ੧੨੨੯।","roman":"Kabit kaabi ke bheetar bhaneeai | 1229 |","meaning_en":"and say them within kabitt and poetry.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1230],"number_text":"੧੨੩੦।","page":1022,"lines":[{"gurmukhi":"ਬਾਜਰਾਜ ਕੇ ਸਭ ਹੀ ਨਾਮ ਬਖਾਨਿ ਕੈ।","roman":"Baajraaj ke sabh hee naam bakhaani kai |","meaning_en":"Having said all the names of the king of horses,","page":1022,"meaning_status":"draft","note":"ਬਾਜਰਾਜ: 'king of horses' (Uchchaihshrava); uncertain chain."},{"gurmukhi":"ਪ੍ਰਭਣੀ ਪਿਤਣੀ ਇਸਣੀ ਬਹੁਰਿ ਪਦ ਠਾਨਿ ਕੈ।","roman":"Prabhnee pitnee isnee bahuri pad thaani kai |","meaning_en":"then set down the words 'prabhani pitani isani',","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿਣੀ ਭਾਖਿ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੀਐ।","roman":"Arinee bhaakhi tupak ke naam pachhaaneeai |","meaning_en":"say 'arini' and recognise names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਸਬਦ ਮੈ ਚਹੀਐ ਤਹੀ ਬਖਾਨੀਐ। ੧੨੩੦।","roman":"Ho javan sabad mai chaheeai tahee bakhaaneeai | 1230 |","meaning_en":"speak them in whatever word-setting is wanted.","page":1022,"meaning_status":"draft","note":"ਜਵਨ ਸਬਦ ਮੈ: 'in whatever word/verse'; uncertain."}]},{"type":"verse","number":[1231],"number_text":"੧੨੩੧।","page":1022,"lines":[{"gurmukhi":"ਹਸਤੀ ਏਸ ਪ੍ਰਭ ਪਿਤਣੀ ਗ੍ਰਭਣੀ ਭਾਖੀਐ।","roman":"Hastee es prabh pitnee grabhnee bhaakheeai |","meaning_en":"Say 'hasti es prabh pitani grabhani' (elephant; lord; master; father; ...),","page":1022,"meaning_status":"draft","note":"ਹਸਤੀ: 'elephant'. ਗ੍ਰਭਣੀ: printed so; perhaps for ਪ੍ਰਭਣੀ 'master-ni'; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Naam tupak ke sakal jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1022,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਕਵਿਤ ਮੈ ਚਹੋ ਸੁ ਪਦ ਤਹ ਦੀਜੀਐ। ੧੨੩੧।","roman":"Ho javan kavit mai chaho su pad tah deejeeai | 1231 |","meaning_en":"give the words in whatever kabitt you wish.","page":1022,"meaning_status":"draft"}]},{"type":"verse","number":[1232],"number_text":"੧੨੩੨।","page":1023,"lines":[{"gurmukhi":"ਦੰਤਿ ਰਾਟ ਪ੍ਰਭ ਪਿਤ ਸੁਤਣੀ ਪਦ ਭਾਖਿ ਕੈ।","roman":"Danti raat prabh pit sutnee pad bhaakhi kai |","meaning_en":"Having said the words 'danti-rat prabh pit sutani' (king of tuskers; lord; father; son),","page":1023,"meaning_status":"draft","note":"ਦੰਤਿ ਰਾਟ: 'king of tusked ones' = Airavat; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖਿ ਕੈ।","roman":"Arinee taa ke ant sabad ko raakhi kai |","meaning_en":"and kept the word 'arini' at its end,","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਹੀਐ ਦੀਜੀਐ ਜਹਾ ਨ ਬ੍ਰਿਥਾ ਬਖਾਨੀਐ। ੧੨੩੨।","roman":"Ho chaheeai deejeeai jahaa na brithaa bakhaaneeai | 1232 |","meaning_en":"give them wherever wanted; do not speak them in vain.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1233],"number_text":"੧੨੩੩।","page":1023,"lines":[{"gurmukhi":"ਦੁਰਦ ਰਾਟ ਰਾਟਿਸਣੀ ਇਸਣੀ ਭਾਖੀਐ।","roman":"Durad raat raatisnee isnee bhaakheeai |","meaning_en":"Say 'durad-rat ratisani isani' (king of elephants; king-lord; lord),","page":1023,"meaning_status":"draft","note":"ਦੁਰਦ ਰਾਟ: 'king of elephants'; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਭੀਤਰ ਉਚਰ੍ਯੋ ਕੀਜੀਐ। ੧੨੩੩।","roman":"Ho kabit kaabi ke bheetar uchryo keejeeai | 1233 |","meaning_en":"utter them within kabitt and poetry.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1234],"number_text":"੧੨੩੪।","page":1023,"lines":[{"gurmukhi":"ਦ੍ਵਿਪਿ ਇਸ ਇਸਣੀ ਮਥਣੀ ਆਦਿ ਭਣੀਜੀਐ।","roman":"Dvipi is isnee mathnee aadi bhaneejeeai |","meaning_en":"Say first 'dvipi is isani mathani' (elephant; lord; lord; destroyer),","page":1023,"meaning_status":"draft","note":"ਦ੍ਵਿਪਿ: 'elephant'; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke ant sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਹਿਰਦੇ ਮਹਿ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam hirde mahi jaaneeai |","meaning_en":"Know in your heart these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਹੋ ਸਬਦ ਤੁਮ ਜਹਾ ਨਿਡਰ ਤਹ ਠਾਨੀਐ। ੧੨੩੪।","roman":"Ho chaho sabad tum jahaa nidar tah thaaneeai | 1234 |","meaning_en":"wherever you want the words, place them there fearlessly.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1235],"number_text":"੧੨੩੫।","page":1023,"lines":[{"gurmukhi":"ਪਦਮੀ ਇਸ ਇਸਰਾਟਿਨ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Padmee is israatin aadi bakhaaneeai |","meaning_en":"Say first 'padmi is isratin' (elephant; lord; lord-king),","page":1023,"meaning_status":"draft","note":"ਪਦਮੀ: 'elephant'; ਇਸਰਾਟਿਨ: obscure; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Arinee taa ke ant sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਪਹਿਚਾਨੀਅਹਿ।","roman":"Sakal tupak ke naam chatur pahichaaneeahi |","meaning_en":"O clever one, recognise these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਮਾਝ ਨਿਸੰਕ ਬਖਾਨੀਅਹਿ। ੧੨੩੫।","roman":"Ho kabit kaabi maajh nisank bakhaaneeahi | 1235 |","meaning_en":"speak them without doubt in kabitt and poetry.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1236],"number_text":"੧੨੩੬।","page":1023,"lines":[{"gurmukhi":"ਬਾਰਣੇਂਦ੍ਰ ਏਂਦ੍ਰਣੀ ਇੰਦ੍ਰਣੀ ਆਦਿ ਕਹਿ।","roman":"Baarnendr endranee indranee aadi kahi |","meaning_en":"Say first 'baranendra endrani indrani' (lord of elephants; lord; lord),","page":1023,"meaning_status":"draft","note":"ਬਾਰਣੇਂਦ੍ਰ: baran 'elephant' + indra 'lord'; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਬਹੁਰ ਗਹਿ।","roman":"Arinee taa ke anti sabad ko bahur gahi |","meaning_en":"then take the word 'arini' at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸਤਿ ਕਰ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam sati kar jaaneeai |","meaning_en":"Know truly these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੰਕਾ ਤ੍ਯਾਗਿ ਉਚਾਰ ਨ ਸੰਕਾ ਮਾਨੀਐ। ੧੨੩੬।","roman":"Ho sankaa tyaagi uchaar na sankaa maaneeai | 1236 |","meaning_en":"abandon doubt and utter them; hold no doubt.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1237],"number_text":"੧੨੩੭।","page":1023,"lines":[{"gurmukhi":"ਬ੍ਯਾਲਹ ਪਤਿ ਪਤਣੀ ਪਦ ਪ੍ਰਿਥਮ ਕਹੀਜੀਐ।","roman":"Byaalah pati patnee pad pritham kaheejeeai |","meaning_en":"Say first the words 'byalah pati patani' (elephant; lord; lord),","page":1023,"meaning_status":"draft","note":"ਬ੍ਯਾਲਹ: byal 'elephant' (or 'snake'); uncertain."},{"gurmukhi":"ਅਰਦਨ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Ardan taa ke ant sabad ko deejeeai |","meaning_en":"and give the word 'ardan' (crusher) at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਅਹੁ।","roman":"Amit tupak ke naam chatur jeea jaaneeahu |","meaning_en":"O clever one, know in your mind these as countless names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਵਨ ਠਵਰ ਮੈ ਚਹੀਐ ਤਹੀ ਬਖਾਨੀਅਹੁ। ੧੨੩੭।","roman":"Ho javan thavar mai chaheeai tahee bakhaaneeahu | 1237 |","meaning_en":"speak them in whatever place you want.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1238],"number_text":"੧੨੩੮।","page":1023,"lines":[{"gurmukhi":"ਇੰਭਸੇਸਣੀ ਇਸਣੀ ਇਸਣੀ ਭਾਖੀਐ।","roman":"Inbhsesnee isnee isnee bhaakheeai |","meaning_en":"Say 'ibhsesani isani isani' (lord of elephants; lord; lord),","page":1023,"meaning_status":"draft","note":"ਇੰਭਸੇਸਣੀ: ibh 'elephant' + is + -ni; uncertain chain."},{"gurmukhi":"ਹੰਤ੍ਰੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Hantree taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'hantri' (slayer) at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਮਾਝ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੩੮।","roman":"Ho kabit kaabi ke maajh nidar hui deejeeai | 1238 |","meaning_en":"give them fearlessly in kabitt and poetry.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1239],"number_text":"੧੨੩੯।","page":1023,"lines":[{"gurmukhi":"ਕੁੰਭੀਏਸ ਇਸ ਇਸਣੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Kunbhee'es is isnee aadi bakhaaneeai |","meaning_en":"Say first 'kumbhi-es is isani' (lord of elephants; lord; lord),","page":1023,"meaning_status":"draft","note":"ਕੁੰਭੀਏਸ: kumbhi 'elephant' + is 'lord'; uncertain chain."},{"gurmukhi":"ਇਸਣੀ ਅਰਿਣੀ ਅੰਤ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Isnee arinee ant tavan ke thaaneeai |","meaning_en":"and place the words 'isani arini' at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲੀਜੀਅਹੁ ਜਾਨ ਕਰ।","roman":"Sakal tupak ke naam leejeeahu jaan kar |","meaning_en":"Take and know these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜੋ ਪੂਛੈ ਦੀਜੀਅਹੁ ਤਿਹ ਤੁਰਤ ਬਤਾਇ ਕਰ। ੧੨੩੯।","roman":"Ho jo poochhai deejeeahu tih turat bataai kar | 1239 |","meaning_en":"whoever asks, tell him at once.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1240],"number_text":"੧੨੪੦।","page":1023,"lines":[{"gurmukhi":"ਕੁੰਜਰੇਸ ਇਸ ਪਿਤਣੀ ਪ੍ਰਭਣੀ ਭਾਖੀਐ।","roman":"Kunjres is pitnee prabhnee bhaakheeai |","meaning_en":"Say 'kunjares is pitani prabhani' (lord of elephants; lord; father; master),","page":1023,"meaning_status":"draft","note":"ਕੁੰਜਰੇਸ: kunjar 'elephant' + is 'lord'; uncertain chain."},{"gurmukhi":"ਹੰਤ੍ਰੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Hantree taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'hantri' at its end.","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1023,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਬੀਚ ਨਿਸੰਕ ਭਣੀਜੀਐ। ੧੨੪੦।","roman":"Ho kabit kaabi ke beech nisank bhaneejeeai | 1240 |","meaning_en":"say them without doubt in kabitt and poetry.","page":1023,"meaning_status":"draft"}]},{"type":"verse","number":[1241],"number_text":"੧੨੪੧।","page":1024,"lines":[{"gurmukhi":"ਕਰੀਏਂਦ੍ਰ ਇੰਦ੍ਰਣੀ ਇੰਦ੍ਰਣੀ ਭਾਖੀਐ।","roman":"Karee'endr indranee indranee bhaakheeai |","meaning_en":"Say 'karindra indrani indrani' (lord of elephants; lord; lord),","page":1024,"meaning_status":"draft","note":"ਕਰੀਏਂਦ੍ਰ: kari 'elephant' + indra 'lord'; uncertain chain."},{"gurmukhi":"ਪਤਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Patinee taa ke anti sabad ko raakheeai |","meaning_en":"and keep the word 'patini' at its end;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਲੇਹੁ ਪਛਾਨਿ ਕੈ।","roman":"Ari kahi naam tupak ke lehu pachhaani kai |","meaning_en":"saying 'ari', recognise names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਬੀਚ ਦੀਜੀਅਹੁ ਜਾਨਿ ਕੈ। ੧੨੪੧।","roman":"Ho kabit kaabi ke beech deejeeahu jaani kai | 1241 |","meaning_en":"knowing them, give them in kabitt and poetry.","page":1024,"meaning_status":"draft"}]},{"type":"verse","number":[1242],"number_text":"੧੨੪੨।","page":1024,"lines":[{"gurmukhi":"ਤਰੁ ਅਰਿ ਪ੍ਰਭੁ ਪ੍ਰਭੁ ਪ੍ਰਭਣੀ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Taru ari prabhu prabhu prabhnee aadi bakhaaneeai |","meaning_en":"Say first 'taru-ari prabhu prabhu prabhani' (enemy of trees, i.e. elephant; lord, lord, master),","page":1024,"meaning_status":"draft","note":"ਤਰੁ ਅਰਿ: 'enemy of trees' = elephant; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਸਬਦ ਕੋ ਠਾਨੀਐ।","roman":"Arinee taa ke anti sabad ko thaaneeai |","meaning_en":"and place the word 'arini' at its end.","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹ ਜਹ ਚਹੀਐ ਸਬਦ ਤਹੀ ਤੇ ਦੀਜੀਐ। ੧੨੪੨।","roman":"Ho jah jah chaheeai sabad tahee te deejeeai | 1242 |","meaning_en":"wherever the words are wanted, give them from there.","page":1024,"meaning_status":"draft"}]},{"type":"verse","number":[1243],"number_text":"੧੨੪੩।","page":1024,"lines":[{"gurmukhi":"ਸਉਡਿਸਇਸ ਇਸ ਇਸਣੀ ਆਦਿ ਬਖਾਨਿ ਕੈ।","roman":"Saudisais is isnee aadi bakhaani kai |","meaning_en":"Having said first 'saundis-is is isani' (lord of trunked ones, i.e. elephants; lord; lord),","page":1024,"meaning_status":"draft","note":"ਸਉਡਿਸਇਸ: saundi 'one with a trunk' = elephant + is 'lord'; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਠਾਨਿ ਕੈ।","roman":"Arinee taa ke ant sabad ko thaani kai |","meaning_en":"and placed the word 'arini' at its end,","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"know in your mind these as all the names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਾ ਕੇ ਭੀਤਰ ਭੇਦ ਨੈਕੁ ਨਹੀ ਕੀਜੀਐ। ੧੨੪੩।","roman":"Ho yaa ke bheetar bhed naiku nahee keejeeai | 1243 |","meaning_en":"make not the slightest distinction in this.","page":1024,"meaning_status":"draft"}]},{"type":"verse","number":[1244],"number_text":"੧੨੪੪।","page":1024,"lines":[{"gurmukhi":"ਸਿੰਧੁਰੇਸ ਇਸ ਪਿਤ ਕਹਿ ਪ੍ਰਭਣੀ ਭਾਖੀਐ।","roman":"Sindhures is pit kahi prabhnee bhaakheeai |","meaning_en":"Say 'sindhures is', then 'pit', then 'prabhani' (lord of elephants; lord; father; master),","page":1024,"meaning_status":"draft","note":"ਸਿੰਧੁਰੇਸ: sindhur 'elephant' + is 'lord'; uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਦੋਹਰਨ ਮਾਝ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੪੪।","roman":"Ho kabit dohran maajh nidar hui deejeeai | 1244 |","meaning_en":"give them fearlessly in kabitts and dohras.","page":1024,"meaning_status":"draft"}]},{"type":"verse","number":[1245],"number_text":"੧੨੪੫।","page":1024,"lines":[{"gurmukhi":"ਅਨਕਪੇਂਦ੍ਰ ਇੰਦ੍ਰਣੀ ਇੰਦ੍ਰਣੀ ਭਾਖੀਐ।","roman":"Anakpendr indranee indranee bhaakheeai |","meaning_en":"Say 'anakpendra indrani indrani' (lord of elephants; lord; lord),","page":1024,"meaning_status":"draft","note":"ਅਨਕਪੇਂਦ੍ਰ: anekap 'elephant' + indra 'lord'; uncertain chain."},{"gurmukhi":"ਇਸਣੀ ਅਰਿਣੀ ਅੰਤਿ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Isnee arinee anti sabad ko raakheeai |","meaning_en":"and keep the words 'isani arini' at its end.","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as all the names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁ ਕਬਿ ਸਭਾ ਕੇ ਬੀਚ ਉਚਾਰਨ ਕੀਜੀਐ। ੧੨੪੫।","roman":"Ho su kabi sabhaa ke beech uchaaran keejeeai | 1245 |","meaning_en":"utter them in the assembly of good poets.","page":1024,"meaning_status":"draft"}]},{"type":"verse","number":[1246],"number_text":"੧੨੪੬।","page":1024,"lines":[{"gurmukhi":"ਨਾਗਿਨਾਹਿ ਨਾਹਿ ਇਸਣਿ ਏਸਣੀ ਭਾਖੀਐ।","roman":"Naaginaahi naahi isni esnee bhaakheeai |","meaning_en":"Say 'nagi-nahi nahi isani esani' (lord of elephants; lord; lord; lord),","page":1024,"meaning_status":"draft","note":"ਨਾਗਿਨਾਹਿ ਨਾਹਿ: nag 'elephant' + nah/nath 'lord'; ਇਸਣਿ ਏਸਣੀ: lord-words; uncertain chain."},{"gurmukhi":"ਮਥਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Mathnee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'mathani' at its end.","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪੁਸਤਕ ਪੋਥਨਿ ਮਾਝ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੪੬।","roman":"Ho pustak pothni maajh nisank bakhaaneeai | 1246 |","meaning_en":"speak them without doubt in books and volumes.","page":1024,"meaning_status":"draft"}]},{"type":"verse","number":[1247],"number_text":"੧੨੪੭।","page":1024,"lines":[{"gurmukhi":"ਹਰਿਪਤਿ ਪਤਿ ਪਤਿ ਪਤਿਣੀ ਆਦਿ ਭਣੀਜੀਐ।","roman":"Haripti pati pati patinee aadi bhaneejeeai |","meaning_en":"Say first 'haripati pati pati patini' (lord of elephants; lord, lord, lord),","page":1024,"meaning_status":"draft","note":"ਹਰਿਪਤਿ: hari here perhaps 'elephant' (or 'horse'); uncertain chain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਦੀਜੀਐ।","roman":"Arinee taa ke ant sabad ko deejeeai |","meaning_en":"and give the word 'arini' at its end.","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1024,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਮਾਝ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੪੭।","roman":"Ho kabit kaabi ke maajh nisank bakhaaneeai | 1247 |","meaning_en":"speak them without doubt in kabitt and poetry.","page":1024,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1024,"meaning_status":"draft"},{"type":"verse","number":[1248],"number_text":"੧੨੪੮।","page":1024,"lines":[{"gurmukhi":"ਗਜਪਤਿ ਨ੍ਰਿਪਣੀ ਨ੍ਰਿਪਣਿ ਭਣਿਜੈ। ਨ੍ਰਿਪਣੀ ਅਰਿਣੀ ਪੁਨਿ ਪਦ ਦਿਜੈ।","roman":"Gajapti nripnee nripni bhanijai | nripnee arinee puni pad dijai |","meaning_en":"Say 'gajpati nripani nripani' (lord of elephants; king; king), then give the words 'nripani arini':","page":1024,"meaning_status":"draft","note":"ਗਜਪਤਿ: 'lord of elephants'; ਨ੍ਰਿਪਣੀ 'king' with -ni, repeated; uncertain chain."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਦੋਹਾ ਮਾਝ ਚਉਪਈ ਕਹੀਐ। ੧੨੪੮।","roman":"Sabh sree naam tupak ke laheeai | dohaa maajh chaupaee kaheeai | 1248 |","meaning_en":"take these as all the honoured names of the gun; say them in a dohra or a chaupai.","page":1024,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1025,"meaning_status":"draft"},{"type":"verse","number":[1249],"number_text":"੧੨੪੯।","page":1025,"lines":[{"gurmukhi":"ਸਾਵਜ ਨ੍ਰਿਪ ਨ੍ਰਿਪ ਨ੍ਰਿਪਤਿ ਨ੍ਰਿਪਣਨੀ ਭਾਖੀਐ।","roman":"Saavaj nrip nrip nripti nripannee bhaakheeai |","meaning_en":"Say 'savaj nrip nrip nripati nripanani' (beast; king, king, king, king),","page":1025,"meaning_status":"draft","note":"ਸਾਵਜ: 'wild beast / elephant'; chain of 'king' words; uncertain."},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤ ਸਬਦ ਕੋ ਰਾਖੀਐ।","roman":"Arinee taa ke ant sabad ko raakheeai |","meaning_en":"and keep the word 'arini' at its end.","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Amit tupak ke naam jaan jeea leejeeai |","meaning_en":"Know in your mind these as countless names of the gun;","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਮਾਝ ਉਚਾਰ੍ਯੋ ਕੀਜੀਐ। ੧੨੪੯।","roman":"Ho kabit kaabi ke maajh uchaaryo keejeeai | 1249 |","meaning_en":"utter them in kabitt and poetry.","page":1025,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1025,"meaning_status":"draft"},{"type":"verse","number":[1250],"number_text":"੧੨੫੦।","page":1025,"lines":[{"gurmukhi":"ਆਦਿ ਸਬਦ ਮਾਤੰਗ ਭਣੀਜੈ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਪਦ ਕੋ ਦੀਜੈ।","roman":"Aadi sabad maatang bhaneejai | chaar baar nrip pad ko deejai |","meaning_en":"Say first the word 'matang' (elephant), and give the word 'nrip' (king) four times;","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿਣੀ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੨੫੦।","roman":"Arinee taa ke anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1250 |","meaning_en":"speak the word 'arini' at its end, and know these as all the honoured names of the gun.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1251],"number_text":"੧੨੫੧।","page":1025,"lines":[{"gurmukhi":"ਆਦਿ ਗਯੰਦਨ ਸਬਦ ਉਚਰੀਐ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦਹਿ ਧਰੀਐ।","roman":"Aadi gayandan sabad uchreeai | chaar baar nrip sabadhi dhareeai |","meaning_en":"Utter first the word 'gayandan' (elephants), and set the word 'nrip' four times;","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿਣੀ ਸਬਦ ਬਹੁਰਿ ਤਿਹ ਦਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲਿਜੈ। ੧੨੫੧।","roman":"Arinee sabad bahuri tih dijai | naam tupak ke sabh lahi lijai | 1251 |","meaning_en":"then give the word 'arini' after it, and take all these as names of the gun.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1252],"number_text":"੧੨੫੨।","page":1025,"lines":[{"gurmukhi":"ਬਾਜ ਸਬਦ ਕੋ ਪ੍ਰਿਥਮ ਭਣੀਜੈ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਧਰੀਜੈ।","roman":"Baaj sabad ko pritham bhaneejai | chaar baar nrip sabad dhareejai |","meaning_en":"Say first the word 'baj' (horse), and set the word 'nrip' four times;","page":1025,"meaning_status":"draft","note":"No closing 'enemy' word is stated in this block."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੋ। ਯਾ ਮੈ ਭੇਦ ਰਤੀਕੁ ਨ ਜਾਨੋ। ੧੨੫੨।","roman":"Sakal tupak ke naam pachhaano | yaa mai bhed rateeku na jaano | 1252 |","meaning_en":"recognise these as all the names of the gun; know not a particle of difference in this.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1253],"number_text":"੧੨੫੩।","page":1025,"lines":[{"gurmukhi":"ਬਾਹ ਸਬਦ ਕੋ ਆਦਿ ਉਚਰੀਐ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦਹਿ ਧਰੀਐ।","roman":"Baah sabad ko aadi uchreeai | chaar baar nrip sabadhi dhareeai |","meaning_en":"Utter first the word 'bah' (horse), and set the word 'nrip' four times;","page":1025,"meaning_status":"draft","note":"No closing 'enemy' word is stated in this block."},{"gurmukhi":"ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਚਹੀਐ ਜਿਹ ਠਾ ਤਿਹ ਠਾ ਕਹੀਐ। ੧੨੫੩।","roman":"Sabh sree naam tupak ke laheeai | chaheeai jih thaa tih thaa kaheeai | 1253 |","meaning_en":"take these as all the honoured names of the gun; say them in whatever place is wanted.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1254],"number_text":"੧੨੫੪।","page":1025,"lines":[{"gurmukhi":"ਤੁਰੰਗ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰੋ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਪਦ ਕਹੁ ਡਾਰੋ।","roman":"Turang sabad ko aadi uchaaro | chaar baar nrip pad kahu daaro |","meaning_en":"Utter first the word 'turang' (horse), and put the word 'nrip' four times;","page":1025,"meaning_status":"draft","note":"No closing 'enemy' word is stated in this block."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲਹੀਜੈ। ਰੁਚੈ ਜਹਾ ਤਿਹ ਠਵਰ ਭਣੀਜੈ। ੧੨੫੪।","roman":"Sakal tupak ke naam laheejai | ruchai jahaa tih thavar bhaneejai | 1254 |","meaning_en":"take these as all the names of the gun; speak them in whatever place you like.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1255],"number_text":"੧੨੫੫।","page":1025,"lines":[{"gurmukhi":"ਹੈ ਪਦ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੋ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦਹਿ ਠਾਨੋ।","roman":"Hai pad mukh te aadi bakhaano | chaar baar nrip sabadhi thaano |","meaning_en":"Say first from the mouth the word 'hai' (horse), and place the word 'nrip' four times;","page":1025,"meaning_status":"draft","note":"No closing 'enemy' word is stated in this block."},{"gurmukhi":"ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ਕਬਿਤ ਕਾਬਿ ਕੇ ਮਾਝ ਭਣਿਜੈ। ੧੨੫੫।","roman":"Naam tupak ke sakal lahijai | kabit kaabi ke maajh bhanijai | 1255 |","meaning_en":"take these as all the names of the gun; speak them within kabitt and poetry.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1256],"number_text":"੧੨੫੬।","page":1025,"lines":[{"gurmukhi":"ਥਰੀ ਸਬਦ ਕੋ ਆਦਿ ਭਣਿਜੈ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਕਹਿਜੈ।","roman":"Tharee sabad ko aadi bhanijai | chaar baar nrip sabad kahijai |","meaning_en":"Say first the word 'thari', and say the word 'nrip' four times;","page":1025,"meaning_status":"draft","note":"ਥਰੀ: obscure; perhaps a word for horse (or earth, sthali); uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਪਛਾਨੋ। ੧੨੫੬।","roman":"Ari pad taa ke anti bakhaano | naam tupak ke sakal pachhaano | 1256 |","meaning_en":"speak the word 'ari' at its end, and recognise these as all the names of the gun.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1257],"number_text":"੧੨੫੭।","page":1025,"lines":[{"gurmukhi":"ਦੇਵ ਸਬਦ ਕਹੁ ਆਦਿ ਬਖਾਨਹੁ। ਨ੍ਰਿਪ ਪਦ ਤੀਨ ਬਾਰ ਪੁਨਿ ਠਾਨਹੁ।","roman":"Dev sabad kahu aadi bakhaanhu | nrip pad teen baar puni thaanhu |","meaning_en":"Say first the word 'dev' (god), then place the word 'nrip' three times;","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ੧੨੫੭।","roman":"Satroo sabad ko bahuri bhanijai | naam tupak ke sakal lahijai | 1257 |","meaning_en":"then say the word 'satru', and take these as all the names of the gun.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1258],"number_text":"੧੨੫੮।","page":1025,"lines":[{"gurmukhi":"ਅਮਰ ਸਬਦ ਕਹੁ ਆਦਿ ਉਚਾਰਹੁ। ਨ੍ਰਿਪ ਪਦ ਤੀਨ ਬਾਰ ਪੁਨਿ ਡਾਰਹੁ।","roman":"Amar sabad kahu aadi uchaarhu | nrip pad teen baar puni daarhu |","meaning_en":"Utter first the word 'amar' (immortal, i.e. god), then put the word 'nrip' three times;","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਲੀਜੈ। ਕਬਿਤ ਕਾਬਿ ਕੇ ਭੀਤਰ ਦੀਜੈ। ੧੨੫੮।","roman":"Ari kahi naam tupak ke leejai | kabit kaabi ke bheetar deejai | 1258 |","meaning_en":"saying 'ari', take these as names of the gun, and give them within kabitt and poetry.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1259],"number_text":"੧੨੫੯।","page":1025,"lines":[{"gurmukhi":"ਨ੍ਰਿਜਰ ਸਬਦ ਕੋ ਆਦਿ ਉਚਰੀਐ। ਨ੍ਰਿਪ ਪਦ ਤੀਨ ਬਾਰ ਪੁਨਿ ਧਰੀਐ।","roman":"Nrijar sabad ko aadi uchreeai | nrip pad teen baar puni dhareeai |","meaning_en":"Utter first the word 'nirjar' (ageless one, i.e. god), then set the word 'nrip' three times;","page":1025,"meaning_status":"draft","note":"ਨ੍ਰਿਜਰ: printed so; read as ਨਿਰਜਰ 'nirjar'."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ਸੰਕ ਛਾਡਿ ਨਿਰਸੰਕ ਬਖਾਨਹੁ। ੧੨੫੯।","roman":"Ari kahi naam tupak ke jaanhu | sank chhaadi nirsank bakhaanhu | 1259 |","meaning_en":"saying 'ari', know these as names of the gun; leave doubt and speak them without doubt.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1260],"number_text":"੧੨੬੦।","page":1025,"lines":[{"gurmukhi":"ਬਿਬੁਧ ਸਬਦ ਕੋ ਆਦਿ ਭਣੀਜੈ। ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਧਰੀਜੈ।","roman":"Bibudh sabad ko aadi bhaneejai | teen baar nrip sabad dhareejai |","meaning_en":"Say first the word 'bibudh' (wise one, i.e. god), and set the word 'nrip' three times;","page":1025,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਅਹਿ। ਸੰਕਾ ਤਿਆਗਿ ਸਭਾ ਮੈ ਕਹੀਅਹਿ। ੧੨੬੦।","roman":"Ripu kahi naam tupak ke laheeahi | sankaa tiaagi sabhaa mai kaheeahi | 1260 |","meaning_en":"saying 'ripu', take these as names of the gun; abandon doubt and say them in the assembly.","page":1025,"meaning_status":"draft"}]},{"type":"verse","number":[1261],"number_text":"੧੨੬੧।","page":1026,"lines":[{"gurmukhi":"ਸੁਰ ਪਦ ਆਦਿ ਸਬਦ ਕੋ ਧਾਰੀਐ। ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਪਦ ਕਹੁ ਡਾਰੀਐ।","roman":"Sur pad aadi sabad ko dhaareeai | teen baar nrip pad kahu daareeai |","meaning_en":"Set first the word 'sur' (god), and put the word 'nrip' three times;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੋ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੋ। ੧੨੬੧।","roman":"Ari pad taa ke anti bakhaano | sabh sree naam tupak ke jaano | 1261 |","meaning_en":"speak the word 'ari' at its end, and know these as all the honoured names of the gun.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1262],"number_text":"੧੨੬੨।","page":1026,"lines":[{"gurmukhi":"ਸੁਮਨ ਸਬਦ ਕੋ ਆਦਿ ਬਖਾਨਹੁ। ਤੀਨ ਬਾਰ ਨਾਇਕ ਪਦ ਠਾਨਹੁ।","roman":"Suman sabad ko aadi bakhaanhu | teen baar naaik pad thaanhu |","meaning_en":"Say first the word 'suman' (god), and place the word 'naik' (lord) three times;","page":1026,"meaning_status":"draft","note":"ਸੁਮਨ: here 'god' (suman also means 'flower'); uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਲਹਿਜੈ। ੧੨੬੨।","roman":"Ari pad taa ke anti bhanijai | naam tupak ke sakal lahijai | 1262 |","meaning_en":"say the word 'ari' at its end, and take these as all the names of the gun.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1263],"number_text":"੧੨੬੩।","page":1026,"lines":[{"gurmukhi":"ਆਦਿ ਸਬਦ ਤ੍ਰਿਦਿਵੇਸ ਬਖਾਨੋ। ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਪਦਹਿ ਪ੍ਰਮਾਨੋ।","roman":"Aadi sabad tridives bakhaano | teen baar nrip padhi pramaano |","meaning_en":"Say first the word 'tridives' (lord of heaven), and set down the word 'nrip' three times;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਭਨੀਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਹਿ ਲੀਜੈ। ੧੨੬੩।","roman":"Ari pad taa ke anti bhaneejai | sabh sree naam tupak lahi leejai | 1263 |","meaning_en":"say the word 'ari' at its end, and take these as all the honoured names of the gun.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1264],"number_text":"੧੨੬੪।","page":1026,"lines":[{"gurmukhi":"ਬ੍ਰਿੰਦਾਰਕ ਸਬਦਾਦਿ ਉਚਾਰਹੁ। ਤੀਨ ਬਾਰ ਨਾਇਕ ਪਦ ਡਾਰਹੁ।","roman":"Brindaarak sabdaadi uchaarhu | teen baar naaik pad daarhu |","meaning_en":"Utter first the word 'brindarak' (god), and put the word 'naik' three times;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੋ। ਨਾਮ ਤੁਪਕ ਕੇ ਸਭ ਲਹਿ ਲੀਜੋ। ੧੨੬੪।","roman":"Ari pad anti tavan ke deejo | naam tupak ke sabh lahi leejo | 1264 |","meaning_en":"give the word 'ari' at its end, and take all these as names of the gun.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1265],"number_text":"੧੨੬੫।","page":1026,"lines":[{"gurmukhi":"ਗਤਿ ਬਿਵਾਨ ਸਬਦਾਦਿ ਬਖਾਣਹੁ। ਤੀਨ ਬਾਰ ਪਤਿ ਪਦਿਹਿ ਪ੍ਰਮਾਣਹੁ।","roman":"Gati bivaan sabdaadi bakhaanhu | teen baar pati padihi pramaanhu |","meaning_en":"Say first the words 'gati bivan' (those who move in aerial cars, i.e. gods), and set down the word 'pati' (lord) three times;","page":1026,"meaning_status":"draft","note":"ਗਤਿ ਬਿਵਾਨ: 'moving by vimana' = gods; uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਕਹੀਐ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ੧੨੬੫।","roman":"Ari pad anti tavan ke kaheeai | sabh sree naam tupak ke laheeai | 1265 |","meaning_en":"say the word 'ari' at its end, and take these as all the honoured names of the gun.","page":1026,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1026,"meaning_status":"draft"},{"type":"verse","number":[1266],"number_text":"੧੨੬੬।","page":1026,"lines":[{"gurmukhi":"ਅੰਮ੍ਰਿਤੇਸ ਸਬਦਾਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Anmrites sabdaadi uchaaran keejeeai |","meaning_en":"Utter first the word 'amrites' (lord of nectar),","page":1026,"meaning_status":"draft","note":"ਅੰਮ੍ਰਿਤੇਸ: amrit 'nectar' + is 'lord'; uncertain chain."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Teen baar pati sabad tavan ke deejeeai |","meaning_en":"give the word 'pati' (lord) three times after it,","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਪੁਨਿ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad puni taa ke anti bakhaaneeai |","meaning_en":"then speak the word 'satru' at its end;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ। ੧੨੬੬।","roman":"Ho sakal tupak ke naam chatur jeea jaaneeai | 1266 |","meaning_en":"O clever one, know in your mind these as all the names of the gun.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1267],"number_text":"੧੨੬੭।","page":1026,"lines":[{"gurmukhi":"ਮਧੁ ਪਦ ਮੁਖ ਤੇ ਪ੍ਰਿਥਮੈ ਨੀਕੇ ਭਾਖੀਐ।","roman":"Madhu pad mukh te prithmai neeke bhaakheeai |","meaning_en":"First say well from the mouth the word 'madhu' (nectar),","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Teen baar pati sabad tavan ke raakheeai |","meaning_en":"and keep the word 'pati' three times after it;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਹ ਜਹ ਚਹੀਐ ਸਬਦ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੬੭।","roman":"Ho jah jah chaheeai sabad nisank bakhaaneeai | 1267 |","meaning_en":"speak the words without doubt wherever they are wanted.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1268],"number_text":"੧੨੬੮।","page":1026,"lines":[{"gurmukhi":"ਸੁਧਾ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Sudhaa sabad ko aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'sudha' (nectar),","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਾਰ ਤ੍ਰੈ ਦੀਜੀਐ।","roman":"Nrip pad taa ke anti baar trai deejeeai |","meaning_en":"and give the word 'nrip' three times at its end;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਭਾਖਿ ਤੁਫੰਗ ਨਾਮ ਜੀਅ ਜਾਨੀਐ।","roman":"Ripu pad bhaakhi tuphang naam jeea jaaneeai |","meaning_en":"saying the word 'ripu', know in your mind these as names of the tufang (gun);","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁ ਕਬਿ ਚਉਪਈ ਮਾਝ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੬੮।","roman":"Ho su kabi chaupaee maajh nisank bakhaaneeai | 1268 |","meaning_en":"O good poet, speak them without doubt in a chaupai.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1269],"number_text":"੧੨੬੯।","page":1026,"lines":[{"gurmukhi":"ਸਬਦ ਪਯੂਖ ਸੁ ਮੁਖ ਤੇ ਪ੍ਰਿਥਮ ਉਚਾਰੀਐ।","roman":"Sabad payookh su mukh te pritham uchaareeai |","meaning_en":"Utter well from the mouth first the word 'payukh' (nectar),","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਅੰਤਿ ਤਿਹ ਡਾਰੀਐ।","roman":"Teen baar nrip sabad anti tih daareeai |","meaning_en":"and put the word 'nrip' three times at its end;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਭਾਖਿ ਤੁਪਕ ਨਾਮ ਲਹੀਜੀਐ।","roman":"Ripu pad bhaakhi tupak naam laheejeeai |","meaning_en":"saying the word 'ripu', take these as names of the gun;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁ ਕਬਿ ਦੋਹਰਾ ਮਾਹਿ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੬੯।","roman":"Ho su kabi dohraa maahi nidar hui deejeeai | 1269 |","meaning_en":"O good poet, give them fearlessly in a dohra.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1270],"number_text":"੧੨੭੦।","page":1026,"lines":[{"gurmukhi":"ਅਸੁਦਾ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਆਦਿ ਉਚਾਰਿ ਕੈ।","roman":"Asudaa sabad su mukh te aadi uchaari kai |","meaning_en":"Having uttered well from the mouth first the word 'asuda' (giver of life),","page":1026,"meaning_status":"draft","note":"ਅਸੁਦਾ: asu 'life-breath' + da 'giver' = nectar; uncertain."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਡਾਰਿ ਕੈ।","roman":"Teen baar nrip sabad tavan ke daari kai |","meaning_en":"and put the word 'nrip' three times after it,","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਬਿਚਾਰੀਐ।","roman":"Ripu kahi naam tupak ke chatur bichaareeai |","meaning_en":"saying 'ripu', O clever one, consider these as names of the gun;","page":1026,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਸੋਰਠਾ ਮਾਹਿ ਨਿਸੰਕ ਉਚਾਰੀਐ। ੧੨੭੦।","roman":"Ho chhand sorthaa maahi nisank uchaareeai | 1270 |","meaning_en":"utter them without doubt in the sortha metre.","page":1026,"meaning_status":"draft"}]},{"type":"verse","number":[1271],"number_text":"੧੨੭੧।","page":1027,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਪ੍ਰਾਣਦਾ ਪਦ ਕੋ ਸੁ ਕਬਿ ਬਖਾਨੀਐ।","roman":"Pritham praandaa pad ko su kabi bakhaaneeai |","meaning_en":"O good poet, say first the word 'pranda' (giver of life),","page":1027,"meaning_status":"draft","note":"ਪ੍ਰਾਣਦਾ: 'life-giver' = nectar; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Chaar baar nrip sabad tavan ke thaaneeai |","meaning_en":"and place the word 'nrip' four times after it;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਹ੍ਰਿਦੈ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke hridai pachhaaneeai |","meaning_en":"saying 'ari', recognise in your heart these as names of the gun;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਧਨਿ ਸਵੈਯਾ ਭੀਤਰ ਨਿਡਰ ਬਖਾਨੀਐ। ੧੨੭੧।","roman":"Ho sudhni savaiyaa bheetar nidar bakhaaneeai | 1271 |","meaning_en":"speak them fearlessly within a well-sounding savaiya.","page":1027,"meaning_status":"draft"}]},{"type":"verse","number":[1272],"number_text":"੧੨੭੨।","page":1027,"lines":[{"gurmukhi":"ਜੀਵਦਤ ਪਦ ਪ੍ਰਿਥਮ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Jeevdat pad pritham uchaaran keejeeai |","meaning_en":"Utter first the word 'jivdat' (giver of life),","page":1027,"meaning_status":"draft","note":"ਜੀਵਦਤ: 'giver of life' = nectar; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਲ੍ਰਿਪ ਸਬਦਹਿ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Chaar baar lrip sabadhi anti bhaneejeeai |","meaning_en":"and say the word 'nrip' four times at its end;","page":1027,"meaning_status":"draft","note":"ਲ੍ਰਿਪ: printed so; read as ਨ੍ਰਿਪ 'king'."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਹ੍ਰਿਦੇ ਪਛਾਨ ਲੈ।","roman":"Ari kahi naam tupak ke hride pachhaan lai |","meaning_en":"saying 'ari', recognise in your heart these as names of the gun;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹੀ ਹਮਾਰੀ ਆਜ ਹ੍ਰਿਦੇ ਪਹਿਚਾਨ ਲੈ। ੧੨੭੨।","roman":"Ho kahee hamaaree aaj hride pahichaan lai | 1272 |","meaning_en":"recognise in your heart today what I have said.","page":1027,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1027,"meaning_status":"draft"},{"type":"verse","number":[1273],"number_text":"੧੨੭੩।","page":1027,"lines":[{"gurmukhi":"ਬਪੁਦਾ ਪਦ ਕੋ ਪ੍ਰਿਥਮ ੳਚਾਰਹੁ। ਚਾਰ ਬਾਰ ਨਾਇਕ ਪਦ ਡਾਰਹੁ।","roman":"Bapudaa pad ko pritham uchaarhu | chaar baar naaik pad daarhu |","meaning_en":"Utter first the word 'bapuda' (giver of the body), and put the word 'naik' four times;","page":1027,"meaning_status":"draft","note":"ਬਪੁਦਾ: 'body-giver'; uncertain. ੳਚਾਰਹੁ: printed so; read as ਉਚਾਰਹੁ."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੇ ਬਹੁਰਿ ਭਣਿਜੈ। ਨਾਮ ਤੁਪਕ ਸਭ ਲਹਿ ਲਿਜੈ। ੧੨੭੩।","roman":"Satroo sabad ke bahuri bhanijai | naam tupak sabh lahi lijai | 1273 |","meaning_en":"then say the word 'satru', and take all these as names of the gun.","page":1027,"meaning_status":"draft","note":"ਕੇ: printed so; read as ਕੋ."}]},{"type":"verse","number":[1274],"number_text":"੧੨੭੪।","page":1027,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਦੇਹਦਾ ਸਬਦ ਬਖਾਨੋ। ਚਾਰ ਬਾਰ ਪਤਿ ਸਬਦ ਪ੍ਰਮਾਨੋ।","roman":"Bahuri dehdaa sabad bakhaano | chaar baar pati sabad pramaano |","meaning_en":"Then say the word 'dehda' (giver of the body), and set down the word 'pati' four times;","page":1027,"meaning_status":"draft","note":"ਦੇਹਦਾ: 'body-giver'; uncertain."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਲਹੀਐ। ਝੂਲਾ ਛੰਦ ਬੀਚਿ ਹਸਿ ਕਹੀਐ। ੧੨੭੪।","roman":"Ari kahi naam tupak ke laheeai | jhoolaa chhand beechi hasi kaheeai | 1274 |","meaning_en":"saying 'ari', take these as names of the gun; say them smiling in the jhoola metre.","page":1027,"meaning_status":"draft"}]},{"type":"verse","number":[1275],"number_text":"੧੨੭੫।","page":1027,"lines":[{"gurmukhi":"ਪ੍ਰਾਣਦਤ ਪਦ ਪ੍ਰਿਥਮ ਭਣੀਜੈ। ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਧਰੀਜੈ।","roman":"Praandat pad pritham bhaneejai | chaar baar nrip sabad dhareejai |","meaning_en":"Say first the word 'prandat' (giver of life), and set the word 'nrip' four times;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਹੁ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨਹੁ। ੧੨੭੫।","roman":"Ari pad taa ke anti bakhaanhu | sabh sree naam tupak ke jaanhu | 1275 |","meaning_en":"speak the word 'ari' at its end, and know these as all the honoured names of the gun.","page":1027,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1027,"meaning_status":"draft"},{"type":"verse","number":[1276],"number_text":"੧੨੭੬।","page":1027,"lines":[{"gurmukhi":"ਜਰਾ ਸਬਦ ਕਹੁ ਮੁਖ ਸੋ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Jaraa sabad kahu mukh so aadi bakhaaneeai |","meaning_en":"Say first from the mouth the word 'jara' (old age),","page":1027,"meaning_status":"draft","note":"How 'old age' leads through this chain to the gun is unclear; uncertain."},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨ੍ਰਿਪ ਪਦ ਬਾਰ ਚਾਰ ਫੁਨ ਠਾਨੀਐ।","roman":"Ripu kahi nrip pad baar chaar phun thaaneeai |","meaning_en":"saying 'ripu', then place the word 'nrip' four times;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਿ ਕੈ।","roman":"Satroo sabad ko taa ke anti bakhaani kai |","meaning_en":"having spoken the word 'satru' at its end,","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲੀਜੀਐ ਜਾਨਿ ਕੈ। ੧੨੭੬।","roman":"Ho sakal tupak ke naam leejeeai jaani kai | 1276 |","meaning_en":"know and take these as all the names of the gun.","page":1027,"meaning_status":"draft"}]},{"type":"verse","number":[1277],"number_text":"੧੨੭੭।","page":1027,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਬ੍ਰਿਧਤਾ ਸਬਦ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Pritham bridhtaa sabad uchaaran keejeeai |","meaning_en":"Utter first the word 'bridhta' (old age),","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਭਨੀਜੀਐ।","roman":"Satroo sabad ko taa ke anti bhaneejeeai |","meaning_en":"and say the word 'satru' at its end;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਸਤ੍ਰੁ ਪਦ ਤਿਹ ਉਪਰੰਤਿ ਬਖਾਨੀਐ।","roman":"Bahuri satru pad tih upranti bakhaaneeai |","meaning_en":"then speak the word 'satru' again after that;","page":1027,"meaning_status":"draft","note":"No 'nrip' step is stated in this block."},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤ ਜਾਨੀਐ। ੧੨੭੭।","roman":"Ho sakal tupak ke naam chatur chit jaaneeai | 1277 |","meaning_en":"O clever one, know in your mind these as all the names of the gun.","page":1027,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1027,"meaning_status":"draft"},{"type":"verse","number":[1278],"number_text":"੧੨੭੮।","page":1027,"lines":[{"gurmukhi":"ਜਰਾ ਸਬਦ ਕਹੁ ਆਦਿ ਉਚਰੀਐ। ਹਰਿ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਧਰੀਐ।","roman":"Jaraa sabad kahu aadi uchreeai | hari pad anti tavan ke dhareeai |","meaning_en":"Utter first the word 'jara' (old age), and set the word 'hari' at its end;","page":1027,"meaning_status":"draft","note":"ਹਰਿ here read as 'remover, destroyer' (hari 'one who takes away'); uncertain."},{"gurmukhi":"ਅਰਿ ਪਦ ਮੁਖ ਤੇ ਬਹੁਰਿ ਬਖਾਨੈ। ਨਾਮ ਤੁਪਕ ਕੇ ਹੋਇ ਪ੍ਰਮਾਨੈ। ੧੨੭੮।","roman":"Ari pad mukh te bahuri bakhaanai | naam tupak ke hoi pramaanai | 1278 |","meaning_en":"then say from the mouth the word 'ari'; these become accepted as names of the gun.","page":1027,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1027,"meaning_status":"draft"},{"type":"verse","number":[1279],"number_text":"੧੨੭੯।","page":1027,"lines":[{"gurmukhi":"ਆਲਸ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Aalas sabad su mukh te aadi bakhaaneeai |","meaning_en":"Say well from the mouth first the word 'alas' (sloth),","page":1027,"meaning_status":"draft","note":"How 'sloth' leads through this chain to the gun is unclear; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਸੁ ਹਰਿ ਕਹਿ ਠਾਨੀਐ।","roman":"Chaar baar nrip sabad su hari kahi thaaneeai |","meaning_en":"saying 'hari', place the word 'nrip' four times;","page":1027,"meaning_status":"draft","note":"ਹਰਿ here read as 'remover, destroyer' (hari 'one who takes away'); uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"know in your mind these as all the names of the gun;","page":1027,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਪਾਧੜੀ ਮਾਝ ਨਿਡਰ ਹੋਇ ਦੀਜੀਐ। ੧੨੭੯।","roman":"Ho chhand paadhree maajh nidar hoi deejeeai | 1279 |","meaning_en":"give them fearlessly in the padhari metre.","page":1027,"meaning_status":"draft"}]},{"type":"verse","number":[1280],"number_text":"੧੨੮੦।","page":1028,"lines":[{"gurmukhi":"ਤਰੁਨ ਦੰਤ ਪਦ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Tarun dant pad mukh te aadi bakhaaneeai |","meaning_en":"Say first from the mouth the words 'tarun dant' (teeth of youth),","page":1028,"meaning_status":"draft","note":"ਤਰੁਨ ਦੰਤ: 'young teeth'; chain obscure; uncertain."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨ੍ਰਿਪ ਪਦ ਬਾਰ ਚਾਰ ਪੁਨਿ ਠਾਨੀਐ।","roman":"Ari kahi nrip pad baar chaar puni thaaneeai |","meaning_en":"saying 'ari', then place the word 'nrip' four times;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਹ੍ਰਿਦੈ ਬਖਾਨੀਅਹਿ।","roman":"Ari kahi naam tupak ke hridai bakhaaneeahi |","meaning_en":"saying 'ari', speak these from the heart as names of the gun;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਰੁਆਲਾ ਬਿਖੈ ਨਿਡਰ ਹੁਇ ਠਾਨੀਅਹਿ। ੧੨੮੦।","roman":"Ho chhand ruaalaa bikhai nidar hui thaaneeahi | 1280 |","meaning_en":"set them down fearlessly in the ruala metre.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1281],"number_text":"੧੨੮੧।","page":1028,"lines":[{"gurmukhi":"ਜੋਬਨਾਂਤ ਅੰਤਕ ਪਦ ਪ੍ਰਿਥਮ ਉਚਾਰੀਐ।","roman":"Jobnaant antak pad pritham uchaareeai |","meaning_en":"Utter first the words 'jobanant antak' (ender of youth, destroyer),","page":1028,"meaning_status":"draft","note":"ਜੋਬਨਾਂਤ: 'end of youth' = old age; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਪਰ ਡਾਰੀਐ।","roman":"Chaar baar nrip sabad tavan par daareeai |","meaning_en":"and put the word 'nrip' four times on it;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਚਉਪਈ ਮਾਹਿ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੮੧।","roman":"Ho chhand chaupaee maahi nisank bakhaaneeai | 1281 |","meaning_en":"speak them without doubt in the chaupai metre.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1282],"number_text":"੧੨੮੨।","page":1028,"lines":[{"gurmukhi":"ਤਰੁਨ ਦੰਤ ਅਰਿ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਭਾਖੀਐ।","roman":"Tarun dant ari sabad su mukh te bhaakheeai |","meaning_en":"Say well from the mouth the words 'tarun dant ari',","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਚਤੁਰ ਬਾਰਿ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Chatur baari nrip sabad tavan ke raakheeai |","meaning_en":"and keep the word 'nrip' four times after it;","page":1028,"meaning_status":"draft","note":"ਚਤੁਰ ਬਾਰਿ: 'four times'."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam jaan jeea leejeeai |","meaning_en":"know in your mind these as all the names of the gun;","page":1028,"meaning_status":"draft","note":"No closing 'enemy' word is stated after the ਨ੍ਰਿਪ step in this block."},{"gurmukhi":"ਹੋ ਸੁਧਨਿ ਦੋਹਰਾ ਮਾਹਿ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੮੨।","roman":"Ho sudhni dohraa maahi nidar hui deejeeai | 1282 |","meaning_en":"give them fearlessly in a well-sounding dohra.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1283],"number_text":"੧੨੮੩।","page":1028,"lines":[{"gurmukhi":"ਜੋਬਨਾਰਿ ਅਰਿ ਪਦ ਕੋ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Jobnaari ari pad ko aadi bakhaaneeai |","meaning_en":"Say first the words 'jobanari ari' (enemy of youth, i.e. old age; enemy),","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Chaar baar nrip sabad tavan ke thaaneeai |","meaning_en":"and place the word 'nrip' four times after it;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਤਵਨ ਕੇ ਭਾਖੀਐ।","roman":"Satroo sabad ko anti tavan ke bhaakheeai |","meaning_en":"speak the word 'satru' at its end;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਚਿਤਿ ਰਾਖੀਐ। ੧੨੮੩।","roman":"Ho sakal tupak ke naam chatur chiti raakheeai | 1283 |","meaning_en":"O clever one, keep in your mind these as all the names of the gun.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1284],"number_text":"੧੨੮੪।","page":1028,"lines":[{"gurmukhi":"ਚਤੁਰਥ ਅਵਸਤਾ ਅਰਿ ਪਦ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Chaturath avastaa ari pad aadi bakhaaneeai |","meaning_en":"Say first the words 'chaturath avasta ari' (the fourth stage of life, i.e. old age; enemy),","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਚੁਤਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Chutar baar nrip sabad tavan ke thaaneeai |","meaning_en":"and place the word 'nrip' four times after it;","page":1028,"meaning_status":"draft","note":"ਚੁਤਰ ਬਾਰ: printed so; read as ਚਤੁਰ ਬਾਰ 'four times'."},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਅੰਤਿ ਸੁ ਬਹੁਰਿ ਬਖਾਨਿ ਕੈ।","roman":"Satroo sabad ko anti su bahuri bakhaani kai |","meaning_en":"then having spoken the word 'satru' at the end,","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲੀਜੀਐ ਜਾਨਿ ਕੈ। ੧੨੮੪।","roman":"Ho sakal tupak ke naam leejeeai jaani kai | 1284 |","meaning_en":"know and take these as all the names of the gun.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1285],"number_text":"੧੨੮੫।","page":1028,"lines":[{"gurmukhi":"ਜਮਪਾਸੀ ਕੇ ਨਾਮਨ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Jampaasee ke naaman aadi uchaareeai |","meaning_en":"Utter first the names of Yama's noose,","page":1028,"meaning_status":"draft","note":"ਜਮਪਾਸੀ: read as 'Yama's noose'; may mean 'the noose-holder' (Yama or Varun); uncertain."},{"gurmukhi":"ਹਰਿ ਕਹਿ ਨ੍ਰਿਪ ਪਦ ਬਾਰ ਚਾਰ ਫੁਨਿ ਡਾਰੀਐ।","roman":"Hari kahi nrip pad baar chaar phuni daareeai |","meaning_en":"saying 'hari', then put the word 'nrip' four times;","page":1028,"meaning_status":"draft","note":"ਹਰਿ here read as 'remover, destroyer' (hari 'one who takes away'); uncertain."},{"gurmukhi":"ਸੁ ਕਬਿ ਤੁਪਕ ਕੇ ਨਾਮ ਭਾਖ ਅਰਿ ਲੀਜੀਐ।","roman":"Su kabi tupak ke naam bhaakh ari leejeeai |","meaning_en":"O good poet, saying 'ari', take these as names of the gun;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਧਨਿ ਸਵੈਯਾ ਮਾਝ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੮੫।","roman":"Ho sudhni savaiyaa maajh nidar hui deejeeai | 1285 |","meaning_en":"give them fearlessly in a well-sounding savaiya.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1286],"number_text":"੧੨੮੬।","page":1028,"lines":[{"gurmukhi":"ਅਰਬਲਾਰਿ ਅਰਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Arablaari ari aadi uchaaran keejeeai |","meaning_en":"Utter first the words 'arbalari ari' (enemy of life-span; enemy),","page":1028,"meaning_status":"draft","note":"ਅਰਬਲਾਰਿ: arbal 'life-span' + ari 'enemy' = death/old age; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Chaar baar pati sabad tavan ke deejeeai |","meaning_en":"and give the word 'pati' four times after it;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਜੀਅ ਲੀਜੀਅਹਿ।","roman":"Sakal tupak ke naam jaan jeea leejeeahi |","meaning_en":"know in your mind these as all the names of the gun;","page":1028,"meaning_status":"draft","note":"No closing 'enemy' word is stated after the ਪਤਿ step in this block."},{"gurmukhi":"ਹੋ ਛੰਦ ਕੁੰਡਰੀਆ ਮਾਹਿ ਸੰਕ ਤਜਿ ਦੀਜੀਅਹਿ। ੧੨੮੬।","roman":"Ho chhand kundreeaa maahi sank taji deejeeahi | 1286 |","meaning_en":"leave doubt and give them in the kundaria metre.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1287],"number_text":"੧੨੮੭।","page":1028,"lines":[{"gurmukhi":"ਆਰਜਾਰਿ ਅਰਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aarjaari ari aadi uchaaran keejeeai |","meaning_en":"Utter first the words 'arjari ari' (enemy of life-span; enemy),","page":1028,"meaning_status":"draft","note":"ਆਰਜਾਰਿ: arja 'life-span' + ari; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਪਦ ਕੋ ਬਹੁਰਿ ਭਣੀਜੀਐ।","roman":"Chaar baar nrip pad ko bahuri bhaneejeeai |","meaning_en":"then say the word 'nrip' four times;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਝੂਲਨਾ ਮਾਹਿ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੮੭।","roman":"Ho chhand jhoolnaa maahi nisank bakhaaneeai | 1287 |","meaning_en":"speak them without doubt in the jhoolna metre.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1288],"number_text":"੧੨੮੮।","page":1028,"lines":[{"gurmukhi":"ਦੇਹਬਾਸੀ ਅਰਿ ਹਰਿ ਪਦ ਆਦਿ ਭਨੀਜੀਐ।","roman":"Dehbaasee ari hari pad aadi bhaneejeeai |","meaning_en":"Say first the words 'dehbasi ari hari' (dweller in the body, i.e. life; enemy; destroyer),","page":1028,"meaning_status":"draft","note":"ਦੇਹਬਾਸੀ: 'body-dweller' = the life-breath; ਹਰਿ here read as 'remover, destroyer' (hari 'one who takes away'); uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਸੁ ਬਹੁਰਿ ਕਹੀਜੀਐ।","roman":"Chaar baar nrip sabad su bahuri kaheejeeai |","meaning_en":"then say the word 'nrip' four times;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਬਿਚਾਰੀਐ।","roman":"Ari kahi naam tupak ke chatur bichaareeai |","meaning_en":"saying 'ari', O clever one, consider these as names of the gun;","page":1028,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਅੜਿਲ ਕੇ ਮਾਹਿ ਨਿਡਰ ਕਹਿ ਡਾਰੀਐ। ੧੨੮੮।","roman":"Ho chhand aril ke maahi nidar kahi daareeai | 1288 |","meaning_en":"say them fearlessly in the aril metre.","page":1028,"meaning_status":"draft"}]},{"type":"verse","number":[1289],"number_text":"੧੨੮੯।","page":1029,"lines":[{"gurmukhi":"ਬਪੁਬਾਸੀ ਅਰਿ ਅਰਿ ਸਬਦਾਦਿ ਬਖਾਨੀਐ।","roman":"Bapubaasee ari ari sabdaadi bakhaaneeai |","meaning_en":"Say first the words 'bapubasi ari ari' (dweller in the body; enemy, enemy),","page":1029,"meaning_status":"draft","note":"ਬਪੁਬਾਸੀ: 'body-dweller' = life; uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਐ।","roman":"Chaar baar nrip sabad tavan ke thaaneeai |","meaning_en":"and place the word 'nrip' four times after it;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਚੰਚਰੀਆ ਮਾਹਿ ਨਿਸੰਕ ਪ੍ਰਮਾਨੀਐ। ੧੨੮੯।","roman":"Ho chhand chanchreeaa maahi nisank pramaaneeai | 1289 |","meaning_en":"accept them without doubt in the chanchria metre.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1290],"number_text":"੧੨੯੦।","page":1029,"lines":[{"gurmukhi":"ਤਨਬਾਸੀ ਅਰ ਹਰਿ ਕੋ ਆਦਿ ਬਖਾਨਿ ਕੈ।","roman":"Tanbaasee ar hari ko aadi bakhaani kai |","meaning_en":"Having first said 'tanbasi ar hari' (dweller in the body; and destroyer),","page":1029,"meaning_status":"draft","note":"ਤਨਬਾਸੀ: 'body-dweller' = life; ਅਰ: read as ਅਰਿ 'enemy' or 'and'; ਹਰਿ here read as 'remover, destroyer' (hari 'one who takes away'); uncertain."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨਿ ਨੈ।","roman":"Chaar baar nrip sabad tavan ke thaani nai |","meaning_en":"and placed the word 'nrip' four times after it,","page":1029,"meaning_status":"draft","note":"ਠਾਨਿ ਨੈ: printed so; read as ਠਾਨਿ ਕੈ."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਰਹੁ ਉਚਾਰਨ ਤਹਾ ਜਹਾ ਜੀਅ ਜਾਨੀਐ। ੧੨੯੦।","roman":"Ho karhu uchaaran tahaa jahaa jeea jaaneeai | 1290 |","meaning_en":"utter them wherever your mind thinks fit.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1291],"number_text":"੧੨੯੧।","page":1029,"lines":[{"gurmukhi":"ਅਸੁਰ ਸਬਦ ਕੋ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Asur sabad ko aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'asur' (demon),","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਪਿਤ ਕਹਿ ਨ੍ਰਿਪ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Pit kahi nrip pad anti tavan ke deejeeai |","meaning_en":"saying 'pit' (father), give the word 'nrip' at its end;","page":1029,"meaning_status":"draft","note":"No count is given for ਨ੍ਰਿਪ here."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਿਡਰ ਬਖਾਨੋ ਤਹਾ ਜਹਾ ਜੀਅ ਜਾਨੀਐ। ੧੨੯੧।","roman":"Ho nidar bakhaano tahaa jahaa jeea jaaneeai | 1291 |","meaning_en":"speak them fearlessly wherever your mind thinks fit.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1292],"number_text":"੧੨੯੨।","page":1029,"lines":[{"gurmukhi":"ਰਾਛਸਾਰਿ ਪਦ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਅਹੁ।","roman":"Raachhsaari pad mukh te aadi bakhaaneeahu |","meaning_en":"Say first from the mouth the word 'rachhasari' (enemy of demons, i.e. a god),","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਚਾਰ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨੀਅਹੁ।","roman":"Chaar baar pati sabad tavan ke thaaneeahu |","meaning_en":"and place the word 'pati' four times after it;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਿਤ ਮੈ ਜਾਨ ਲੈ।","roman":"Ari kahi naam tupak ke chit mai jaan lai |","meaning_en":"saying 'ari', know in your mind these as names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜੋ ਪੂਛੈ ਤੁਹਿ ਆਇ ਨਿਸੰਕ ਬਤਾਇ ਦੈ। ੧੨੯੨।","roman":"Ho jo poochhai tuhi aai nisank bataai dai | 1292 |","meaning_en":"whoever comes and asks you, tell him without hesitation.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1293],"number_text":"੧੨੯੩।","page":1029,"lines":[{"gurmukhi":"ਦਾਨਵਾਰਿ ਪਦ ਮੁਖ ਤੇ ਸੁਘਰਿ ਪ੍ਰਿਥਮ ਉਚਰਿ।","roman":"Daanvaari pad mukh te sughri pritham uchri |","meaning_en":"O skilful one, utter first from the mouth the word 'danvari' (enemy of demons),","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਅੰਤਿ ਧਰੁ।","roman":"Chaar baar nrip sabad tavan ke anti dharu |","meaning_en":"and set the word 'nrip' four times at its end;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨ ਲੈ।","roman":"Ari kahi naam tupak ke chatur pachhaan lai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁ ਕਬਿ ਸਭਾ ਕੇ ਮਾਝ ਨਿਡਰ ਹੁਇ ਰਾਖ ਦੈ। ੧੨੯੩।","roman":"Ho su kabi sabhaa ke maajh nidar hui raakh dai | 1293 |","meaning_en":"set them down fearlessly in the assembly of good poets.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1294],"number_text":"੧੨੯੪।","page":1029,"lines":[{"gurmukhi":"ਅਮਰਾਰਦਨ ਅਰਿ ਆਦਿ ਸੁ ਕਬਿ ਉਚਾਰਿ ਕੈ।","roman":"Amraardan ari aadi su kabi uchaari kai |","meaning_en":"O good poet, having uttered first the words 'amarardan ari' (destroyer of the gods; enemy),","page":1029,"meaning_status":"draft","note":"ਅਮਰਾਰਦਨ: amar 'god' + ardan 'destroyer' = demon; uncertain."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਅੰਤਿ ਤਿਹ ਡਾਰਿ ਕੈ।","roman":"Teen baar nrip sabad anti tih daari kai |","meaning_en":"and put the word 'nrip' three times after it,","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਸਕਲ ਸੁਧਾਰ ਲੈ।","roman":"Ari kahi naam tupak ke sakal sudhaar lai |","meaning_en":"saying 'ari', set right all these names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪੜ੍ਯੋ ਚਹਤ ਤਿਹ ਨਰ ਕੋ ਤੁਰਤ ਸਿਖਾਇ ਲੈ। ੧੨੯੪।","roman":"Ho paryo chahat tih nar ko turat sikhaai lai | 1294 |","meaning_en":"teach them at once to the man who wishes to read.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1295],"number_text":"੧੨੯੫।","page":1029,"lines":[{"gurmukhi":"ਸਕ੍ਰ ਸਬਦ ਕਹੁ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Sakr sabad kahu aadi uchaaran keejeeai |","meaning_en":"Utter first the word 'sakr' (Indra),","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਅਰਿ ਕਹਿ ਪਤਿ ਚਾਰ ਬਾਰ ਪਦ ਦੀਜੀਐ।","roman":"Ari ari kahi pati chaar baar pad deejeeai |","meaning_en":"saying 'ari ari', give the word 'pati' four times;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹੁ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨੀਐ।","roman":"Satroo sabad kahu taa ke anti bakhaaneeai |","meaning_en":"speak the word 'satru' at its end;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ। ੧੨੯੫।","roman":"Ho sakal tupak ke naam chatur jeea jaaneeai | 1295 |","meaning_en":"O clever one, know in your mind these as all the names of the gun.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1296],"number_text":"੧੨੯੬।","page":1029,"lines":[{"gurmukhi":"ਸਤ ਕ੍ਰਿਤ ਅਰਿ ਅਰਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Sat krit ari ari aadi uchaaran keejeeai |","meaning_en":"Utter first the words 'sat krit ari ari' (Indra; enemy, enemy),","page":1029,"meaning_status":"draft","note":"ਸਤ ਕ੍ਰਿਤ: satkratu = Indra."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Chaar baar nrip sabad tavan ke deejeeai |","meaning_en":"and give the word 'nrip' four times after it;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕੋ ਤਾ ਕੇ ਅੰਤਿ ਬਖਾਨਿ ਕੈ।","roman":"Satroo sabad ko taa ke anti bakhaani kai |","meaning_en":"having spoken the word 'satru' at its end,","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲੀਜੀਅਹੁ ਜਾਨਿ ਕੈ। ੧੨੯੬।","roman":"Ho sakal tupak ke naam leejeeahu jaani kai | 1296 |","meaning_en":"know and take these as all the names of the gun.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1297],"number_text":"੧੨੯੭।","page":1029,"lines":[{"gurmukhi":"ਸਚੀ ਪਤਿਰਿ ਅਰਿ ਆਦਿ ਸਬਦ ਕਹੁ ਭਾਖੀਐ।","roman":"Sachee patiri ari aadi sabad kahu bhaakheeai |","meaning_en":"Say first the words 'sachi patiri ari' (husband of Sachi, i.e. Indra; enemy; enemy),","page":1029,"meaning_status":"draft","note":"ਪਤਿਰਿ: printed so; read as pati + ari."},{"gurmukhi":"ਚਾਰ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Chaar baar nrip sabad tavan ke raakheeai |","meaning_en":"and keep the word 'nrip' four times after it;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਚਤੁਰ ਪਛਾਨੀਐ।","roman":"Ari kahi naam tupak ke chatur pachhaaneeai |","meaning_en":"saying 'ari', O clever one, recognise these as names of the gun;","page":1029,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਝੂਲਨਾ ਮਾਝ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੯੭।","roman":"Ho chhand jhoolnaa maajh nisank bakhaaneeai | 1297 |","meaning_en":"speak them without doubt in the jhoolna metre.","page":1029,"meaning_status":"draft"}]},{"type":"verse","number":[1298],"number_text":"੧੨੯੮।","page":1030,"lines":[{"gurmukhi":"ਸਕ੍ਰਰਦਨ ਅਰਿ ਰਿਪੁ ਪਦ ਆਦਿ ਬਖਾਨਿ ਕੈ।","roman":"Sakrardan ari ripu pad aadi bakhaani kai |","meaning_en":"Having said first the words 'sakrardan ari ripu' (destroyer of Indra; enemy; enemy),","page":1030,"meaning_status":"draft","note":"ਸਕ੍ਰਰਦਨ: sakr 'Indra' + ardan 'destroyer'."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਪਦ ਕਹੁ ਬਹੁਰਿ ਪ੍ਰਮਾਨਿ ਕੈ।","roman":"Teen baar nrip pad kahu bahuri pramaani kai |","meaning_en":"then set down the word 'nrip' three times,","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਜਾਨੀਐ।","roman":"Satroo sabad kahi naam tupak ke jaaneeai |","meaning_en":"saying the word 'satru', know these as names of the gun;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਝੂਲਾ ਛੰਦਨ ਮਾਝ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੨੯੮।","roman":"Ho jhoolaa chhandan maajh nisank bakhaaneeai | 1298 |","meaning_en":"speak them without doubt in jhoola verses.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1299],"number_text":"੧੨੯੯।","page":1030,"lines":[{"gurmukhi":"ਆਦਿ ਸਬਦ ਪੁਰਹੂਤਰਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Aadi sabad purhootri uchaaran keejeeai |","meaning_en":"Utter first the word 'puruhutari' (enemy of Puruhut, i.e. Indra),","page":1030,"meaning_status":"draft","note":"ਪੁਰਹੂਤਰਿ: puruhut 'Indra' + ari."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਪਿਤਣੀਸ ਅਰਿ ਪਦ ਬਹੁਰਿ ਭਣੀਜੀਐ।","roman":"Ari kahi pitnees ari pad bahuri bhaneejeeai |","meaning_en":"saying 'ari', then say the words 'pitanis ari';","page":1030,"meaning_status":"draft","note":"ਪਿਤਣੀਸ: pit 'father' + is 'lord' with -ni; uncertain."},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਲਹਿ ਲੀਜੀਐ।","roman":"Sakal tupak ke naam chatur lahi leejeeai |","meaning_en":"O clever one, take these as all the names of the gun;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਘਰ ਸੋਰਠਾ ਮਾਝਿ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੨੯੯।","roman":"Ho sughar sorthaa maajhi nidar hui deejeeai | 1299 |","meaning_en":"O skilful one, give them fearlessly in a sortha.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1300],"number_text":"੧੩੦੦।","page":1030,"lines":[{"gurmukhi":"ਬਾਸਵਾਰਿ ਅਰਿ ਆਦਿ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Baasvaari ari aadi uchaaran keejeeai |","meaning_en":"Utter first the words 'basvari ari' (enemy of Vasav, i.e. Indra; enemy),","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਪਿਤਣੀ ਇਸਣੀ ਅਰਿਣੀ ਅੰਤਿ ਭਣੀਜੀਐ।","roman":"Pitnee isnee arinee anti bhaneejeeai |","meaning_en":"and say 'pitani isani arini' at the end;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਚਤੁਰ ਜੀਅ ਜਾਨੀਐ।","roman":"Sakal tupak ke naam chatur jeea jaaneeai |","meaning_en":"O clever one, know in your mind these as all the names of the gun;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਦੋਹਰਾ ਮਾਹਿ ਨਿਸੰਕ ਬਖਾਨੀਐ। ੧੩੦੦।","roman":"Ho chhand dohraa maahi nisank bakhaaneeai | 1300 |","meaning_en":"speak them without doubt in the dohra metre.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1301],"number_text":"੧੩੦੧।","page":1030,"lines":[{"gurmukhi":"ਆਦਿ ਬ੍ਰਿਤਹਾ ਅਰਿ ਅਰਿ ਪਦਹਿ ਪ੍ਰਮਾਨਿ ਕੈ।","roman":"Aadi brithaa ari ari padhi pramaani kai |","meaning_en":"Having set down first the words 'britaha ari ari' (slayer of Vritra, i.e. Indra; enemy, enemy),","page":1030,"meaning_status":"draft","note":"ਬ੍ਰਿਤਹਾ: 'slayer of Vritra' = Indra."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਇਸ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨਿ ਕੈ।","roman":"Teen baar is sabad tavan ke thaani kai |","meaning_en":"and placed the word 'is' (lord) three times after it,","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪੁਨਿ ਠਾਨ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨ ਲੈ।","roman":"Ripu puni thaan tupak ke naam pachhaan lai |","meaning_en":"then place 'ripu', and recognise these as names of the gun;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪੜਿਯੋ ਚਾਹਤ ਜੋ ਨਰ ਤਿਹ ਭੇਦ ਬਤਾਇ ਦੈ। ੧੩੦੧।","roman":"Ho pariyo chaahat jo nar tih bhed bataai dai | 1301 |","meaning_en":"whatever man wishes to read, tell him this secret.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1302],"number_text":"੧੩੦੨।","page":1030,"lines":[{"gurmukhi":"ਮਘਵਾਂਤਕ ਅਰਿ ਆਦਿ ਸਬਦ ਕੋ ਭਾਖੀਐ।","roman":"Maghvaantak ari aadi sabad ko bhaakheeai |","meaning_en":"Say first the words 'maghvantak ari' (destroyer of Maghva, i.e. Indra; enemy),","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਪਦਹਿ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Teen baar nrip padhi tavan ke raakheeai |","meaning_en":"and keep the word 'nrip' three times after it;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਸੁਘਰ ਲਹੀਜੀਐ।","roman":"Ripu kahi naam tupak ke sughar laheejeeai |","meaning_en":"saying 'ripu', O skilful one, take these as names of the gun;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਥਾ ਕੀਰਤਨ ਮਾਝਿ ਨਿਸੰਕ ਭਣੀਜੀਐ। ੧੩੦੨।","roman":"Ho kathaa keertan maajhi nisank bhaneejeeai | 1302 |","meaning_en":"say them without doubt in tales and hymns of praise.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1303],"number_text":"੧੩੦੩।","page":1030,"lines":[{"gurmukhi":"ਮਾਤਲੇਸ੍ਰ ਅਰਿ ਸਬਦਹਿ ਆਦਿ ਬਖਾਨਿ ਕੈ।","roman":"Maatlesr ari sabadhi aadi bakhaani kai |","meaning_en":"Having said first the words 'matalesr ari' (lord of Matali, i.e. Indra; enemy),","page":1030,"meaning_status":"draft","note":"ਮਾਤਲੇਸ੍ਰ: Matali (Indra's charioteer) + isar 'lord' = Indra."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਠਾਨਿ ਕੈ।","roman":"Teen baar nrip sabad tavan ke thaani kai |","meaning_en":"and placed the word 'nrip' three times after it,","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਫੁਨਿ ਤਾ ਕੇ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad phuni taa ke anti uchaareeai |","meaning_en":"then utter the word 'satru' at its end;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮਤ ਸੰਭਾਰੀਐ। ੧੩੦੩।","roman":"Ho sakal tupak ke naam sumat sanbhaareeai | 1303 |","meaning_en":"O wise one, keep in mind all the names of the gun.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1304],"number_text":"੧੩੦੪।","page":1030,"lines":[{"gurmukhi":"ਜਿਸਨਾਂਤਕ ਅੰਤਕ ਸਬਦਾਦਿ ਉਚਾਰੀਐ।","roman":"Jisnaantak antak sabdaadi uchaareeai |","meaning_en":"Utter first the words 'jisnantak antak' (destroyer of Jishnu, i.e. Indra; destroyer),","page":1030,"meaning_status":"draft","note":"ਜਿਸਨਾਂਤਕ: jishnu 'Indra' + antak 'ender'."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਪਦ ਰਾਜ ਤਵਨ ਕੇ ਡਾਰੀਐ।","roman":"Teen baar pad raaj tavan ke daareeai |","meaning_en":"and put the word 'raj' (king) three times after it;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪੁਨਿ ਤਵਨੈ ਅੰਤਿ ਸਬਦ ਕੇ ਦੀਜੀਐ।","roman":"Ari puni tavnai anti sabad ke deejeeai |","meaning_en":"then give the word 'ari' at its end;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਘਰ ਲਹਿ ਲੀਜੀਐ। ੧੩੦੪।","roman":"Ho sakal tupak ke naam sughar lahi leejeeai | 1304 |","meaning_en":"O skilful one, take these as all the names of the gun.","page":1030,"meaning_status":"draft"}]},{"type":"verse","number":[1305],"number_text":"੧੩੦੫।","page":1030,"lines":[{"gurmukhi":"ਪੁਰੰਦ੍ਰਾਰਿ ਅਰਿ ਆਦਿ ਸਬਦ ਕਹੁ ਭਾਖਿ ਕੈ।","roman":"Purandraari ari aadi sabad kahu bhaakhi kai |","meaning_en":"Having said first the words 'purandrari ari' (enemy of Purandar, i.e. Indra; enemy),","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਪਦਹਿ ਅੰਤਿ ਤਿਹ ਰਾਖਿ ਕੈ।","roman":"Teen baar nrip padhi anti tih raakhi kai |","meaning_en":"and kept the word 'nrip' three times at its end,","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਸਤ੍ਰੂ ਪਦ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Bahuri satroo pad anti tavan ke deejeeai |","meaning_en":"then give the word 'satru' at its end;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਘਰ ਤੁਪਕ ਕੇ ਨਾਮ ਸਦਾ ਲਖਿ ਲੀਜੀਐ। ੧੩੦੫।","roman":"Ho sughar tupak ke naam sadaa lakhi leejeeai | 1305 |","meaning_en":"O skilful one, always take these as names of the gun.","page":1030,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1030,"meaning_status":"draft"},{"type":"verse","number":[1306],"number_text":"੧੩੦੬।","page":1030,"lines":[{"gurmukhi":"ਬਜ੍ਰਧਰਰਿ ਅਰਿ ਪਦ ਆਦਿ ਬਖਾਨਹੁ। ਤੀਨ ਬਾਰ ਈਸਰ ਪਦ ਠਾਨਹੁ।","roman":"Bajradharri ari pad aadi bakhaanhu | teen baar eesar pad thaanhu |","meaning_en":"Say first the words 'bajradharari ari' (enemy of the thunderbolt-bearer, Indra; enemy), and place the word 'isar' (lord) three times;","page":1030,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪੁਨਿ ਅੰਤਿ ਬਹੁਰਿ ਤਿਹ ਦੀਜੈ। ਸਭ ਸ੍ਰੀ ਨਾਮ ਤੁਪਕ ਲਹਿ ਲੀਜੈ। ੧੩੦੬।","roman":"Ari puni anti bahuri tih deejai | sabh sree naam tupak lahi leejai | 1306 |","meaning_en":"then give the word 'ari' at its end, and take these as all the honoured names of the gun.","page":1030,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1031,"meaning_status":"draft"},{"type":"verse","number":[1307],"number_text":"੧੩੦੭।","page":1031,"lines":[{"gurmukhi":"ਤੁਰਾਖਾੜ ਅਰਿ ਅਰਿ ਪਦ ਆਦਿ ਉਚਾਰੀਐ।","roman":"Turaakhaar ari ari pad aadi uchaareeai |","meaning_en":"Utter first the words 'turakhar ari ari' (Turashat, Indra; enemy, enemy),","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਪਦਹਿ ਅੰਤਿ ਤਹਿ ਧਾਰੀਐ।","roman":"Teen baar nrip padhi anti tahi dhaareeai |","meaning_en":"and set the word 'nrip' three times at its end;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਬਹੁਰਿ ਪੁਨਿ ਅੰਤਿ ਤਵਨ ਕੇ ਠਾਨਿ ਕੈ।","roman":"Satroo bahuri puni anti tavan ke thaani kai |","meaning_en":"then having placed 'satru' at its end,","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਲੀਜੀਅਹੁ ਜਾਨਿ ਕੈ। ੧੩੦੭।","roman":"Ho sakal tupak ke naam leejeeahu jaani kai | 1307 |","meaning_en":"know and take these as all the names of the gun.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1308],"number_text":"੧੩੦੮।","page":1031,"lines":[{"gurmukhi":"ਰਿਪੁ ਪਾਕਰਿ ਰਿਪੁ ਸਬਦ ਅੰਤਿ ਤਿਹ ਭਾਖੀਐ।","roman":"Ripu paakri ripu sabad anti tih bhaakheeai |","meaning_en":"Say 'ripu pakari' (enemy of Pak's enemy, i.e. of Indra), with the word 'ripu' at its end,","page":1031,"meaning_status":"draft","note":"ਪਾਕਰਿ: Pak-ari 'enemy of the demon Pak' = Indra; uncertain."},{"gurmukhi":"ਨਾਇਕ ਪਦ ਤ੍ਰੈ ਬਾਰ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Naaik pad trai baar tavan ke raakheeai |","meaning_en":"and keep the word 'naik' three times after it;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪੁਨਿ ਤਾ ਕੇ ਅੰਤਿ ਸੁਘਰ ਕਹਿ ਦੀਜੀਐ।","roman":"Ripu puni taa ke anti sughar kahi deejeeai |","meaning_en":"then, O skilful one, say and give 'ripu' at its end;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਮ ਤੁਪਕ ਬਹੁ ਚੀਨ ਉਚਾਰਿਯੋ ਕੀਜੀਐ। ੧੩੦੮।","roman":"Ho naam tupak bahu cheen uchaariyo keejeeai | 1308 |","meaning_en":"recognise the many names of the gun and utter them.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1309],"number_text":"੧੩੦੯।","page":1031,"lines":[{"gurmukhi":"ਇੰਦ੍ਰਾਂਤਕ ਅਰਿ ਆਦਿ ਸਬਦ ਕੋ ਭਾਖੀਐ।","roman":"Indraantak ari aadi sabad ko bhaakheeai |","meaning_en":"Say first the words 'indrantak ari' (destroyer of Indra; enemy),","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਨਾਇਕ ਪਦ ਤ੍ਰੈ ਬਾਰ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Naaik pad trai baar tavan ke raakheeai |","meaning_en":"and keep the word 'naik' three times after it;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਬਹੁਰਿ ਪੁਨਿ ਤਾ ਕੇ ਅੰਤਿ ਧਰੀਜੀਐ।","roman":"Satroo bahuri puni taa ke anti dhareejeeai |","meaning_en":"then set 'satru' at its end;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਜਾਨ ਮਨ ਲੀਜੀਐ। ੧੩੦੯।","roman":"Ho sakal tupak ke naam jaan man leejeeai | 1309 |","meaning_en":"know in your mind these as all the names of the gun.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1310],"number_text":"੧੩੧੦।","page":1031,"lines":[{"gurmukhi":"ਦੇਵ ਸਬਦ ਕੋ ਮੁਖ ਤੇ ਆਦਿ ਬਖਾਨੀਐ।","roman":"Dev sabad ko mukh te aadi bakhaaneeai |","meaning_en":"Say first from the mouth the word 'dev' (god),","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਅਰਦਨ ਕਹਿ ਅਰਦਨ ਪਦ ਅੰਤਿ ਪ੍ਰਮਾਨੀਐ।","roman":"Ardan kahi ardan pad anti pramaaneeai |","meaning_en":"saying 'ardan', set down the word 'ardan' (destroyer) at the end;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਕੇ ਭਾਖੀਐ।","roman":"Teen baar pati sabad tavan ke bhaakheeai |","meaning_en":"say the word 'pati' three times after it;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਮਨ ਲਹਿ ਰਾਖੀਐ। ੧੩੧੦।","roman":"Ho ari kahi naam tupak ke man lahi raakheeai | 1310 |","meaning_en":"saying 'ari', take in your mind and keep these as names of the gun.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1311],"number_text":"੧੩੧੧।","page":1031,"lines":[{"gurmukhi":"ਅਮਰਾ ਅਰਦਨ ਸਬਦ ਸੁ ਮੁਖ ਤੇ ਭਾਖੀਐ।","roman":"Amraa ardan sabad su mukh te bhaakheeai |","meaning_en":"Say well from the mouth the words 'amara ardan' (destroyer of the gods),","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਨਾਇਕ ਪਦ ਤ੍ਰੈ ਬਾਰ ਤਵਨ ਕੇ ਰਾਖੀਐ।","roman":"Naaik pad trai baar tavan ke raakheeai |","meaning_en":"and keep the word 'naik' three times after it;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਸੁਘਰ ਪਛਾਨੀਐ।","roman":"Ripu kahi naam tupak ke sughar pachhaaneeai |","meaning_en":"saying 'ripu', O skilful one, recognise these as names of the gun;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਭੇਦਾਭੇਦ ਕਬਿਤ ਕੇ ਮਾਹਿ ਬਖਾਨੀਐ। ੧੩੧੧।","roman":"Ho bhedaabhed kabit ke maahi bakhaaneeai | 1311 |","meaning_en":"speak them, with their distinctions, within kabitt.","page":1031,"meaning_status":"draft","note":"ਭੇਦਾਭੇਦ: 'distinction and non-distinction'; uncertain."}]},{"type":"verse","number":[1312],"number_text":"੧੩੧੨।","page":1031,"lines":[{"gurmukhi":"ਨਿਰਜਰਾਰਿ ਅਰਦਨ ਪਦ ਪ੍ਰਿਥਮ ਉਚਾਰਿ ਕੈ।","roman":"Nirajraari ardan pad pritham uchaari kai |","meaning_en":"Having uttered first the words 'nirjarari ardan' (enemy of the gods; destroyer),","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਡਾਰਿ ਕੈ।","roman":"Teen baar nrip sabad tavan ke daari kai |","meaning_en":"and put the word 'nrip' three times after it,","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਸੁਘਰ ਲਹੀਜੀਐ।","roman":"Ari kahi naam tupak ke sughar laheejeeai |","meaning_en":"saying 'ari', O skilful one, take these as names of the gun;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਅੜਿਲ ਛੰਦ ਕੇ ਮਾਹਿ ਨਿਡਰ ਹੁਇ ਦੀਜੀਐ। ੧੩੧੨।","roman":"Ho aril chhand ke maahi nidar hui deejeeai | 1312 |","meaning_en":"give them fearlessly in the aril metre.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1313],"number_text":"੧੩੧੩।","page":1031,"lines":[{"gurmukhi":"ਬਿਬੁਧਾਂਤਕ ਅੰਤਕ ਸਬਦਾਦਿ ਉਚਾਰ ਕਰ।","roman":"Bibudhaantak antak sabdaadi uchaar kar |","meaning_en":"Having uttered first the words 'bibudhantak antak' (destroyer of the gods; destroyer),","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਨ੍ਰਿਪ ਸਬਦ ਤਵਨ ਕੇ ਡਾਰ ਕਰ।","roman":"Teen baar nrip sabad tavan ke daar kar |","meaning_en":"and put the word 'nrip' three times after it,","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਕਹਿ ਨਾਮ ਤੁਪਕ ਕੇ ਸੁਘਰ ਬਿਚਾਰੀਐ।","roman":"Ripu kahi naam tupak ke sughar bichaareeai |","meaning_en":"saying 'ripu', O skilful one, consider these as names of the gun;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਰੁਆਲਾ ਮਾਝ ਨਿਸੰਕ ਉਚਾਰੀਐ। ੧੩੧੩।","roman":"Ho chhand ruaalaa maajh nisank uchaareeai | 1313 |","meaning_en":"utter them without doubt in the ruala metre.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1314],"number_text":"੧੩੧੪।","page":1031,"lines":[{"gurmukhi":"ਸੁਪਰਬਾਣ ਪਰ ਅਰਿ ਪਦ ਪ੍ਰਿਥਮ ਭਣੀਜੀਐ।","roman":"Suparbaan par ari pad pritham bhaneejeeai |","meaning_en":"Say first the words 'suparban par ari' (enemy of the gods),","page":1031,"meaning_status":"draft","note":"ਸੁਪਰਬਾਣ: suparvan 'god'; ਪਰ: obscure (perhaps 'upon/after'); uncertain."},{"gurmukhi":"ਤੀਨ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਪਰ ਦੀਜੀਐ।","roman":"Teen baar pati sabad tavan par deejeeai |","meaning_en":"and give the word 'pati' three times after it;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਭਾਖ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੀਅਹੁ।","roman":"Ari pad bhaakh tupak ke naam pachhaaneeahu |","meaning_en":"saying the word 'ari', recognise these as names of the gun;","page":1031,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਛੰਦ ਚੰਚਰੀਆ ਮਾਝ ਨਿਡਰ ਹੁਐ ਠਾਨੀਅਹੁ। ੧੩੧੪।","roman":"Ho chhand chanchreeaa maajh nidar huai thaaneeahu | 1314 |","meaning_en":"set them down fearlessly in the chanchria metre.","page":1031,"meaning_status":"draft"}]},{"type":"verse","number":[1315],"number_text":"੧੩੧੫।","page":1032,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸਬਦ ਤ੍ਰਿਦਵੇਸ ਉਚਾਰਨ ਕੀਜੀਐ।","roman":"Pritham sabad tridves uchaaran keejeeai |","meaning_en":"Utter first the word 'tridves' (lord of heaven, i.e. Indra),","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਅਰਿ ਕਹਿ ਨ੍ਰਿਪ ਪਦ ਤ੍ਰੈ ਵਾਰ ਭਣੀਜੀਐ।","roman":"Ari ari kahi nrip pad trai vaar bhaneejeeai |","meaning_en":"saying 'ari ari', say the word 'nrip' three times;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਾ ਕੇ ਪੁਨਿ ਅੰਤਿ ਉਚਾਰੀਐ।","roman":"Satroo sabad taa ke puni anti uchaareeai |","meaning_en":"then utter the word 'satru' at its end;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਬੁਧਿ ਬਿਚਾਰੀਐ। ੧੩੧੫।","roman":"Ho sakal tupak ke naam subudhi bichaareeai | 1315 |","meaning_en":"O wise one, consider these as all the names of the gun.","page":1032,"meaning_status":"draft"}]},{"type":"verse","number":[1316],"number_text":"੧੩੧੬।","page":1032,"lines":[{"gurmukhi":"ਬ੍ਰਿੰਦਾਰਕ ਅਰਿ ਅਰਿ ਸਬਦਾਦਿ ਉਚਾਰਜੈ।","roman":"Brindaarak ari ari sabdaadi uchaarjai |","meaning_en":"Utter first the words 'brindarak ari ari' (god; enemy, enemy),","page":1032,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਤੀਨ ਬਾਰ ਪਤਿ ਸਬਦ ਤਵਨ ਕੇ ਡਾਰਜੈ।","roman":"Teen baar pati sabad tavan ke daarjai |","meaning_en":"and put the word 'pati' three times after it;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੂ ਸਬਦ ਤਾ ਕੇ ਪੁਨਿ ਅੰਤਿ ਭਨੀਜੀਐ।","roman":"Satroo sabad taa ke puni anti bhaneejeeai |","meaning_en":"then say the word 'satru' at its end;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮਤਿ ਲਹਿ ਲੀਜੀਐ। ੧੩੧੬।","roman":"Ho sakal tupak ke naam sumti lahi leejeeai | 1316 |","meaning_en":"O wise one, take these as all the names of the gun.","page":1032,"meaning_status":"draft"}]},{"type":"verse","number":[1317],"number_text":"੧੩੧੭।","page":1032,"lines":[{"gurmukhi":"ਸਭ ਬਿਵਾਨ ਕੇ ਨਾਮ ਭਾਖਿ ਗਤਿ ਭਾਖੀਐ।","roman":"Sabh bivaan ke naam bhaakhi gati bhaakheeai |","meaning_en":"Having said all the names of 'bivan' (aerial car), say 'gati' (one who moves),","page":1032,"meaning_status":"draft","note":"'those who move in aerial cars' = gods."},{"gurmukhi":"ਅਰਿ ਅਰਿ ਕਹਿ ਨ੍ਰਿਪ ਚਾਰ ਬਾਰ ਪਦ ਰਾਖੀਐ।","roman":"Ari ari kahi nrip chaar baar pad raakheeai |","meaning_en":"saying 'ari ari', keep the word 'nrip' four times;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰ ਸਤ੍ਰੂ ਪੁਨਿ ਅੰਤਿ ਤਵਨ ਕੇ ਦੀਜੀਐ।","roman":"Bahur satroo puni anti tavan ke deejeeai |","meaning_en":"then give 'satru' at its end;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਕਲ ਤੁਪਕ ਕੇ ਨਾਮ ਸੁਮਤਿ ਲਹਿ ਲੀਜੀਐ। ੧੩੧੭।","roman":"Ho sakal tupak ke naam sumti lahi leejeeai | 1317 |","meaning_en":"O wise one, take these as all the names of the gun.","page":1032,"meaning_status":"draft"}]},{"type":"verse","number":[1318],"number_text":"੧੩੧੮।","page":1032,"lines":[{"gurmukhi":"ਆਦਿ ਅਗਨਿ ਜਿਵ ਪਦ ਕੋ ਸੁ ਪੁਨਿ ਬਖਾਨੀਐ।","roman":"Aadi agni jiv pad ko su puni bakhaaneeai |","meaning_en":"Say first the words 'agni jiv' (those who live by fire, i.e. gods),","page":1032,"flags":[{"code":"0x66","reason":"sihari typed before the previous letter's ੁ; attached to the next consonant"}],"meaning_status":"draft","note":"ਅਗਨਿ ਜਿਵ: perhaps 'those whose mouth is fire (agni-jihva)' = gods; uncertain."},{"gurmukhi":"ਅਰਿ ਅਰਿ ਕਹਿ ਨ੍ਰਿਪ ਚਾਰ ਬਾਰ ਪੁਨਿ ਠਾਨੀਐ।","roman":"Ari ari kahi nrip chaar baar puni thaaneeai |","meaning_en":"saying 'ari ari', then place the word 'nrip' four times;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਭਾਖਿ ਤੁਪਕ ਕੇ ਨਾਮ ਪਛਾਨੀਐ।","roman":"Ripu pad bhaakhi tupak ke naam pachhaaneeai |","meaning_en":"saying the word 'ripu', recognise these as names of the gun;","page":1032,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਿਤ ਕਾਬਿ ਕੇ ਮਾਝਿ ਨਿਸੰਕ ਪ੍ਰਮਾਨੀਐ। ੧੩੧੮।","roman":"Ho kabit kaabi ke maajhi nisank pramaaneeai | 1318 |","meaning_en":"accept them without doubt in kabitt and poetry.","page":1032,"meaning_status":"draft"}]}],"ending":null});
